const L5R4E=
{"clans":[{"id":"badger","nome":"Badger"},{"id":"bat","nome":"Bat"},{"id":"boar","nome":"Boar"},{"id":"crab","nome":"Crab"},{"id":"crane","nome":"Crane"},{"id":"dragon","nome":"Dragon"},{"id":"dragonfly","nome":"Dragonfly"},{"id":"falcon","nome":"Falcon"},{"id":"fox","nome":"Fox"},{"id":"hare","nome":"Hare"},{"id":"imperial","nome":"Imperial"},{"id":"lion","nome":"Lion"},{"id":"mantis","nome":"Mantis"},{"id":"monkey","nome":"Monkey"},{"id":"monks","nome":"Monks"},{"id":"oriole","nome":"Oriole"},{"id":"ox","nome":"Ox"},{"id":"phoenix","nome":"Phoenix"},{"id":"ronin","nome":"Ronin"},{"id":"scorpion","nome":"Scorpion"},{"id":"snake","nome":"Snake"},{"id":"sparrow","nome":"Sparrow"},{"id":"spider","nome":"Spider"},{"id":"tiger","nome":"Tiger"},{"id":"tortoise","nome":"Tortoise"},{"id":"unicorn","nome":"Unicorn"}],"familias":[{"id":"badger_ichiro","clanId":"badger","nome":"Ichiro","traco":"strength"},{"id":"bat_komori","clanId":"bat","nome":"Komori","traco":"intelligence"},{"id":"boar_heichi","clanId":"boar","nome":"Heichi","traco":"willpower"},{"id":"crab_hida","clanId":"crab","nome":"Hida","traco":"strength"},{"id":"crab_hiruma","clanId":"crab","nome":"Hiruma","traco":"agility"},{"id":"crab_kaiu","clanId":"crab","nome":"Kaiu","traco":"intelligence"},{"id":"crab_kuni","clanId":"crab","nome":"Kuni","traco":"intelligence"},{"id":"crab_toritaka","clanId":"crab","nome":"Toritaka","traco":"perception"},{"id":"crab_yasuki","clanId":"crab","nome":"Yasuki","traco":"awareness"},{"id":"crane_asahina","clanId":"crane","nome":"Asahina","traco":"intelligence"},{"id":"crane_daidoji","clanId":"crane","nome":"Daidoji","traco":"stamina"},{"id":"crane_doji","clanId":"crane","nome":"Doji","traco":"awareness"},{"id":"crane_kakita","clanId":"crane","nome":"Kakita","traco":"agility"},{"id":"dragon_kitsuki","clanId":"dragon","nome":"Kitsuki","traco":"awareness"},{"id":"dragon_mirumoto","clanId":"dragon","nome":"Mirumoto","traco":"agility"},{"id":"dragon_tamori","clanId":"dragon","nome":"Tamori","traco":"willpower"},{"id":"dragon_togashi","clanId":"dragon","nome":"Togashi","traco":"reflexes"},{"id":"dragon_hitomi","clanId":"dragon","nome":"Hitomi","traco":"strength"},{"id":"dragon_hoshi","clanId":"dragon","nome":"Hoshi","traco":"void"},{"id":"dragonfly_tonbo","clanId":"dragonfly","nome":"Tonbo","traco":"awareness"},{"id":"falcon_toritaka","clanId":"falcon","nome":"Toritaka","traco":"perception"},{"id":"fox_kitsune","clanId":"fox","nome":"Kitsune","traco":"willpower"},{"id":"hare_ujina","clanId":"hare","nome":"Ujina","traco":"agility"},{"id":"hare_usagi","clanId":"hare","nome":"Usagi","traco":"awareness"},{"id":"imperial_miya","clanId":"imperial","nome":"Miya","traco":"reflexes"},{"id":"imperial_otomo","clanId":"imperial","nome":"Otomo","traco":"intelligence"},{"id":"imperial_seppun","clanId":"imperial","nome":"Seppun","traco":"agility"},{"id":"imperial_hantei","clanId":"imperial","nome":"Hantei","traco":"void"},{"id":"imperial_toturi","clanId":"imperial","nome":"Toturi","traco":"willpower"},{"id":"imperial_nasu","clanId":"imperial","nome":"Nasu","traco":"awareness"},{"id":"lion_akodo","clanId":"lion","nome":"Akodo","traco":"agility"},{"id":"lion_ikoma","clanId":"lion","nome":"Ikoma","traco":"awareness"},{"id":"lion_kitsu","clanId":"lion","nome":"Kitsu","traco":"intelligence"},{"id":"lion_matsu","clanId":"lion","nome":"Matsu","traco":"strength"},{"id":"mantis_kitsune","clanId":"mantis","nome":"Kitsune","traco":"awareness"},{"id":"mantis_moshi","clanId":"mantis","nome":"Moshi","traco":"intelligence"},{"id":"mantis_tsuruchi","clanId":"mantis","nome":"Tsuruchi","traco":"perception"},{"id":"mantis_yoritomo","clanId":"mantis","nome":"Yoritomo","traco":"stamina"},{"id":"monkey_toku","clanId":"monkey","nome":"Toku","traco":"stamina"},{"id":"monkey_fuzake","clanId":"monkey","nome":"Fuzake","traco":"perception"},{"id":"monks_four_temples","clanId":"monks","nome":"Four Temples","traco":"void"},{"id":"monks_order_of_heroes","clanId":"monks","nome":"Order of Heroes","traco":"void"},{"id":"monks_the_temple_of_osanowo","clanId":"monks","nome":"The Temple of Osano-Wo","traco":"void"},{"id":"monks_the_shrine_of_the_seven_thunders","clanId":"monks","nome":"The Shrine Of The Seven Thunders","traco":"void"},{"id":"monks_the_temple_of_kaimetsu_uo","clanId":"monks","nome":"The Temple Of Kaimetsu-Uo","traco":"void"},{"id":"monks_the_temples_of_the_thousand_fortunes","clanId":"monks","nome":"The Temples of the Thousand Fortunes","traco":"void"},{"id":"oriole_tsi","clanId":"oriole","nome":"Tsi","traco":"strength"},{"id":"ox_morito","clanId":"ox","nome":"Morito","traco":"stamina"},{"id":"phoenix_agasha","clanId":"phoenix","nome":"Agasha","traco":"perception"},{"id":"phoenix_asako","clanId":"phoenix","nome":"Asako","traco":"awareness"},{"id":"phoenix_isawa","clanId":"phoenix","nome":"Isawa","traco":"willpower"},{"id":"phoenix_shiba","clanId":"phoenix","nome":"Shiba","traco":"perception"},{"id":"scorpion_bayushi","clanId":"scorpion","nome":"Bayushi","traco":"agility"},{"id":"scorpion_shosuro","clanId":"scorpion","nome":"Shosuro","traco":"awareness"},{"id":"scorpion_soshi","clanId":"scorpion","nome":"Soshi","traco":"intelligence"},{"id":"scorpion_yogo","clanId":"scorpion","nome":"Yogo","traco":"willpower"},{"id":"snake_chuda","clanId":"snake","nome":"Chuda","traco":"strength"},{"id":"sparrow_suzume","clanId":"sparrow","nome":"Suzume","traco":"awareness"},{"id":"spider_chuda","clanId":"spider","nome":"Chuda","traco":"intelligence"},{"id":"spider_daigotsu","clanId":"spider","nome":"Daigotsu","traco":"stamina"},{"id":"spider_goju","clanId":"spider","nome":"Goju","traco":"agility"},{"id":"spider_spider_monks","clanId":"spider","nome":"Spider Monks","traco":"reflexes"},{"id":"tortoise_kasuga","clanId":"tortoise","nome":"Kasuga","traco":"perception"},{"id":"unicorn_horiuchi","clanId":"unicorn","nome":"Horiuchi","traco":"willpower"},{"id":"unicorn_ide","clanId":"unicorn","nome":"Ide","traco":"perception"},{"id":"unicorn_iuchi","clanId":"unicorn","nome":"Iuchi","traco":"intelligence"},{"id":"unicorn_moto","clanId":"unicorn","nome":"Moto","traco":"agility"},{"id":"unicorn_shinjo","clanId":"unicorn","nome":"Shinjo","traco":"reflexes"},{"id":"unicorn_utaku","clanId":"unicorn","nome":"Utaku","traco":"stamina"}],"escolas":[{"id":"badger_ichiro_bushi_school","clanId":"badger","nome":"Ichiro Bushi School","traco":"strength","honra":"3.5","tags":["bushi","badger_bushi"],"pericias":[{"id":"athletics","rank":1,"enfase":""},{"id":"commerce","rank":1,"enfase":""},{"id":"defense","rank":1,"enfase":""},{"id":"heavy_weapons","rank":1,"enfase":""},{"id":"jiujutsu","rank":1,"enfase":""},{"id":"kenjutsu","rank":1,"enfase":"Katana"}],"tecnicas":[{"id":"badger_transcend_the_mountain","nome":"Transcend The Mountain","rank":1,"descricao":"The bushi of the Badger Clan live and train in the rugged territory of the Great Wall of the North, and revere strength as the ultimate measure of any warrior's capabilities - the power of a warrior's fists can still be relied on when all else fails. You may re-roll any Skill roll or Trait roll which uses Strength, but you must keep the result of the second roll. You suffer no movement or combat penalties for Moderate terrain, and only half the normal penalty for Difficult terrain."},{"id":"badger_strength_of_the_badger","nome":"Strength Of The Badger","rank":2,"descricao":"With practice, the Badger learn to call upon their strength to crush their opponents. A number of times per session equal to your Strength Rank, you may re-roll a damage roll, keeping the better of the two results."},{"id":"badger_crushing_blow","nome":"Crushing Blow","rank":3,"descricao":"Experienced Badger learn to deliver blows of truly fearsome power, with weapons or even their bare hands, which can pulverize flesh even through the protection of armor. You may ignore the effects of armor on an opponent's Armor TN. Your unarmed attacks may ignore 1 Rank of your target's Reduction."},{"id":"badger_crashing_stones","nome":"Crashing Stones","rank":4,"descricao":"Ichiro samurai are taught to strike with the speed of the deadly avalanche. Your attacks with Samurai weapons or unarmed strikes are considered Simple Actions."},{"id":"badger_return_the_strike","nome":"Return The Strike","rank":5,"descricao":"The final lesson taught in Badger Clan dojo is that the most effective blows in combat are not the swiftest, but the hardest struck. At the start of a skirmish, before Initiative is rolled, you may choose to lower your Initiative total by 20 for the duration of the skirmish. In exchange, you add your Strength Rank in unkept dice to both your attack and your damage rolls for the first two rounds of that combat."}]},{"id":"bat_komori_shugenja_school","clanId":"bat","nome":"Komori Shugenja School","traco":"awareness","honra":"4.5","tags":["shugenja","bat_shugenja"],"pericias":[{"id":"calligraphy","rank":1,"enfase":"Cipher"},{"id":"lore_theology","rank":1,"enfase":""},{"id":"meditation","rank":1,"enfase":""},{"id":"spellcraft","rank":1,"enfase":""},{"id":"tea_ceremony","rank":1,"enfase":""}],"tecnicas":[{"id":"bat_the_kamis_whispers","nome":"The Kami's Whispers","rank":1,"descricao":"The Komori practice the rituals of the koumori spirits from whom their founder is descended, and ferry messages from one to another via the kami. You may expend one spell slot to send a whispered message to another individual known to you. This message must be no longer in length than thirty seconds per School Rank, and may be delivered a maximum distance equal to your School Rank x 100 miles."}]},{"id":"boar_heichi_bushi_school","clanId":"boar","nome":"Heichi Bushi School","traco":"strength","honra":"3","tags":["bushi","boar_bushi"],"pericias":[{"id":"athletics","rank":1,"enfase":""},{"id":"defense","rank":1,"enfase":""},{"id":"hunting","rank":1,"enfase":""},{"id":"intimidation","rank":1,"enfase":""},{"id":"kenjutsu","rank":1,"enfase":""},{"id":"spears","rank":1,"enfase":"Mai Chong"}],"tecnicas":[{"id":"boar_the_charge_of_the_boar","nome":"The Charge Of The Boar","rank":1,"descricao":"The attack of a boar can come from nowhere, with little warning. If you are in the Full Attack stance, you may ready a medium weapon or a spear as a Free Action. When wielding a spear in combat, you gain a damage bonus of +0k1."},{"id":"boar_the_strength_of_the_opposition","nome":"The Strength Of The Opposition","rank":2,"descricao":"The Boar school specializes in using spears, especially the Mai Chong, to snare an opponent's clothing and armor, rendering them helpless. You may call two Raises to Entangle an opponent with a Mai Chong, or three Raises to Entangle them with another spear-class weapon."},{"id":"boar_the_speed_of_the_boar","nome":"The Speed Of The Boar","rank":3,"descricao":"The Boar bushi learns to strike with the relentless speed of his namesake animal. You may attack as a Simple Action when wielding a spear."},{"id":"boar_the_anger_of_the_boar","nome":"The Anger Of The Boar","rank":4,"descricao":"Much like their namesake, Boar bushi keep fighting even when critically injured. You may spend a Void point during the Reactions segment to reduce your Wound TN penalty by one Wound Rank (the wounds still exist, you simply feel less pain from them). This effect lasts the remainder of the skirmish."},{"id":"boar_beyond_the_mountains","nome":"Beyond The Mountains","rank":5,"descricao":"At this rank the Boar has learned to control his warrior's fury and unleash it at the most unexpected times, even when he appears to be completely defensive. If you are in the Full Defense Stance, you may make one normal attack with a spear or a Samurai-keyword weapon as a Free Action, ingoring the restriction of the Full Defense Stance. This attack gains a bonus of +2k0 to the attack roll."}]},{"id":"crab_hida_bushi_school","clanId":"crab","nome":"Hida Bushi School","traco":"stamina","honra":"3.5","tags":["bushi","crab_bushi"],"pericias":[{"id":"athletics","rank":1,"enfase":""},{"id":"defense","rank":1,"enfase":""},{"id":"heavy_weapons","rank":1,"enfase":"Tetsubo"},{"id":"intimidation","rank":1,"enfase":""},{"id":"kenjutsu","rank":1,"enfase":""},{"id":"lore_shadowlands","rank":1,"enfase":""}],"tecnicas":[{"id":"crab_the_way_of_the_crab","nome":"The Way Of The Crab","rank":1,"descricao":"The Hida bushi is the epitome of 'heavy infantry,' able to endure harsh blows and deliver crushing attacks in return. You may ignore TN penalties for wearing heavy armor for all skills except Stealth. When using a Heavy Weapon, you gain a bonus of +1k0 to the total of all damage rolls."},{"id":"crab_the_mountain_does_not_move","nome":"The Mountain Does Not Move","rank":2,"descricao":"The Hida bushi is famous for extraordinary tenacity, weathering wounds that would kill normal men. You gain Reduction equal to your Earth Ring."},{"id":"crab_two_pincers_one_mind","nome":"Two Pincers, One Mind","rank":3,"descricao":"A Hida bushi is relentless. You may make attacks as a Simple Action instead of a Complex Action while using Heavy Weapons or weapons with the Samurai keyword."},{"id":"crab_devastating_blow","nome":"Devastating Blow","rank":4,"descricao":"A Hida stops at nothing to destroy his enemies once his anger is roused. Once per encounter, when wielding a Heavy Weapon you may make a calculated strike against the enemy. Lower the enemy's Reduction by 4 for this attack. If this attack succeeds, you Daze the target. The target may recover from this Conditional Effect by making a successful Earth Ring Roll versus a TN equal to your damage roll during the Reaction Stage of each Round. The TN decreases by 5 each time the target fails the roll."},{"id":"crab_the_mountain_does_not_fall","nome":"The Mountain Does Not Fall","rank":5,"descricao":"Nothing can stop a Hida warrior from fulfilling his duty, not even the threat of death. You may spend a Void Point during the Reaction Stage. During your next Turn, you may take actions as if you were in the Healthy Wound Rank. You ignore the Dazed, Fatigued, and Stunned Conditional Effects. The benefits of this Technique last until the next Reactions Stage."}]},{"id":"crab_kuni_shugenja_school","clanId":"crab","nome":"Kuni Shugenja School","traco":"willpower","honra":"2.5","tags":["shugenja","crab_shugenja"],"pericias":[{"id":"calligraphy","rank":1,"enfase":"Cipher"},{"id":"defense","rank":1,"enfase":""},{"id":"lore_shadowlands","rank":2,"enfase":""},{"id":"lore_theology","rank":1,"enfase":""},{"id":"spellcraft","rank":1,"enfase":""}],"tecnicas":[{"id":"crab_gaze_into_shadow","nome":"Gaze Into Shadow","rank":1,"descricao":"The Kuni have carefully studied many of the most sinister opponents imaginable, and have learned how to combat them. You gain a bonus of +1k0 to the total of all Spell Casting Rolls when the target is any non-human creature, and any spell that inflicts damage inflicts an additional +1k1 damage when used against a target who possesses the Shadowlands Taint. You also gain a Free Raise on any spell with the Jade keyword."}]},{"id":"crab_yasuki_courtier_school","clanId":"crab","nome":"Yasuki Courtier School","traco":"perception","honra":"2.5","tags":["courtier","crab_courtier"],"pericias":[{"id":"commerce","rank":1,"enfase":"Appraisal"},{"id":"courtier","rank":1,"enfase":""},{"id":"defense","rank":1,"enfase":""},{"id":"etiquette","rank":1,"enfase":""},{"id":"intimidation","rank":1,"enfase":""},{"id":"sincerity","rank":1,"enfase":"Deceit"}],"tecnicas":[{"id":"crab_the_way_of_the_carp","nome":"The Way Of The Carp","rank":1,"descricao":"The Yasuki are masters of commerce and practice it far more openly than other samurai families; they do not consider it to be a breach of etiquette to engage in open commerce. You gain a Free Raise when using the Commerce skill, and you do not lose Honor or Glory for using the Commerce skill even in public. Also, Yasuki are taught from youth to be adept at sizing up their potential customers. When speaking with someone you may make a Contested Roll of your Commerce/Perception against their Etiquette/Awareness to discern some material object or service they want or desire."},{"id":"crab_do_as_we_say","nome":"Do As We Say","rank":2,"descricao":"The flip side of Yasuki commerce is Yasuki pushiness. The Yasuki are renowned for both their glib tongues and their high-pressure sales tactics, pressuring and deceiving their customers and allies into doing what they want. A number of times per session equal to your School Rank, you may re-roll a failed Sincerity or Intimidation Skill roll. You must keep the results of the second roll."},{"id":"crab_treasures_of_the_carp","nome":"Treasures Of The Carp","rank":3,"descricao":"Your contracts in the merchant and commercial circles of Rokugan make it possible for you to acquire almost anything you might need to satisfy a customer. You may roll Commerce/Awareness at TN 20 to locate a rare or useful item, subject to GM discretion, for someone else. You may track down higher-quality or rarer items by calling Raises."},{"id":"crab_wiles_of_the_carp","nome":"Wiles Of The Carp","rank":4,"descricao":"As ruthless merchants, the Yasuki are also skilled at seeing through the deceptions and blandishments of others. Anyone making a Social Skill Roll for the purpose of lying to you or deceiving you has their TN increased by an amount equal to 5 times your School Rank."},{"id":"crab_what_is_yours_is_mine","nome":"What Is Yours Is Mine","rank":5,"descricao":"The ultimate skill of the Yasuki is to influence others by offering them what they want the most. If you known of a material item someone needs, and arrange for them to get it, you gain a bonus of +5k0 to any Contested Social Rolls you make against that person for the next 24 hours."}]},{"id":"crab_hiruma_bushi_school","clanId":"crab","nome":"Hiruma Bushi School","traco":"willpower","honra":"4.5","tags":["bushi","crab_bushi"],"pericias":[{"id":"athletics","rank":1,"enfase":""},{"id":"hunting","rank":1,"enfase":""},{"id":"kenjutsu","rank":1,"enfase":"Katana"},{"id":"kyujutsu","rank":1,"enfase":""},{"id":"lore_shadowlands","rank":1,"enfase":""},{"id":"stealth","rank":1,"enfase":""}],"tecnicas":[{"id":"crab_torchs_flame_flickers","nome":"Torch's Flame Flickers","rank":1,"descricao":"The Hiruma learns to focus his trikes even while protecting himself, perfecting the penetrating quality of his blow without sacrificing his defense. While you assume the Attack Stance, you gain a bonus of +1k0 to the total of all attack rolls. You are skilled at survival and can make all food, water, and jade rations last twice as long for a number of people equal to your Hunting Skill Rank."},{"id":"crab_wolfs_little_lesson","nome":"Wolf's Little Lesson","rank":2,"descricao":"Hiruma learn to dash in and out in a single motion. While you assume the Attack Stance, you add 5 to your Armor TN every time you hit with a melee weapon. This bonus may stack a number of times equal to your School Rank and lasts unti the end of the skirmish."},{"id":"crab_hummingbird_wings","nome":"Hummingbird Wings","rank":3,"descricao":"The Hiruma know how the hummingbird can move in any direction and apply this truism to battle. Once per Round you may activate this Technique when an opponent targets you with an attack. You gain a bonus of double your School Rank to your Armor TN for that attack. This stacks with any other Armor TN bonuses you gain from other means (Such as spending a Void Point)."},{"id":"crab_shark_smells_blood","nome":"Shark Smells Blood","rank":4,"descricao":"Against a weakened opponent, a Hiruma is a terrible foe indeed. You may make attacks as a Simple Action instead of a Complex Action when using a weapon with the Samurai keyword."},{"id":"crab_daylight_wastes_no_movement","nome":"Daylight Wastes No Movement","rank":5,"descricao":"The Hiruma learns to use no more energy than is precisely needed to kill his opponent. If you deliver more Wounds than necessary to kill your target, you may apply the exess Woudns to the next target you hit. This Technique does not activate two attacks in a row. The carry-over effect does not last beyond the end of the current skirmish."}]},{"id":"crab_toritaka_bushi_school","clanId":"crab","nome":"Toritaka Bushi School","traco":"strength","honra":"5.5","tags":["bushi","crab_bushi"],"pericias":[{"id":"animal_handling","rank":1,"enfase":"Falcons"},{"id":"hunting","rank":2,"enfase":""},{"id":"kenjutsu","rank":1,"enfase":""},{"id":"lore_spirit_realms","rank":1,"enfase":""},{"id":"spears","rank":1,"enfase":""}],"tecnicas":[{"id":"crab_the_falcons_eyes","nome":"The Falcon's Eyes","rank":1,"descricao":"A Toritaka must be aware of his surroundings at all times, for his enemies can appear anywhere. You add +1k0 to all Skill and raw Trait rolls involving the Perception Trait. Additionally, when striking a creature from another Spirit Realm (including oni from Jigoku and hungry dead from Gaki-do), you add +1k0 to all damage rolls."},{"id":"crab_the_falcon_takes_flight","nome":"The Falcon Takes Flight","rank":2,"descricao":"Through his training, the Toritaka can sense the emanations of nearby spirits as they cross over into the mortal realm. You may attempt to detect the presence of any creatures from other Spirit Realms by making a Perception Trait Roll against a TN equal to the creature's Air Ring x 5."},{"id":"crab_the_falcons_wings","nome":"The Falcon's Wings","rank":3,"descricao":"The Toritaka strikes with precision, constantly keeping his enemies at bay. You may make attacks as a Simple Action instead of a Complex Action while wielding a spear or a weapon with the Samurai keyword."},{"id":"crab_vigilant_and_strong","nome":"Vigilant And Strong","rank":4,"descricao":"Monsters may have tricks to confuse their enemies, but the Toritaka learns to see the truth through the fog. You may spend a Void Point to negate any darkness or blinding penalties. This effect lasts until the Reactions Phase two Rounds later."},{"id":"crab_claws_of_the_falcon","nome":"Claws Of The Falcon","rank":5,"descricao":"Nothing will stop the Toritaka's attack from hitting its target. Your attacks ignore up to 5 points of your opponent's Reduction (if he has any). Against creatures from other Spirit Realms, you may spend a Void Point as a Free Action to reduce the creature's Reduction by 10 for one Round."}]},{"id":"crab_ob_hiruma_scout_school","clanId":"crab","nome":"Hiruma Scout School","traco":"reflexes","honra":"4.5","tags":["bushi","crab_bushi"],"pericias":[{"id":"athletics","rank":1,"enfase":""},{"id":"hunting","rank":1,"enfase":""},{"id":"kenjutsu","rank":1,"enfase":""},{"id":"kyujutsu","rank":1,"enfase":""},{"id":"lore_shadowlands","rank":1,"enfase":""},{"id":"stealth","rank":1,"enfase":"Sneaking"}],"tecnicas":[{"id":"crab_dance_the_razors_edge","nome":"Dance the Razor's Edge","rank":1,"descricao":"The Hiruma scouts learn the ways of the Shadowlands intimately, and are taught to rely on speed and stealth to survive, function, and escape in that most inhospitable of environments. You may add your Stealth Skill rank to the total of your Initiative rolls (unless caught by surprise or otherwise unaware). You can make all food, water, and jade rations last twice as long as normal for a number of people equal to your Hunting Skill Rank. While in the Shadowlands, you gain +1k0 to Stealth rolls and always know the direction of the Empire and roughly how far away it is."},{"id":"crab_run_like_the_wind","nome":"Run Like the Wind","rank":2,"descricao":"The Hiruma practice speed, evasion, and endurance in order to evade their enemies and deliver their scouting reports. You may make Free and Simple Move actions while in the Full Defense stance. You can run at high speed for a number of hours equal to your Stamina + School Rank, after which you are Exhausted until you have one hour's rest."},{"id":"crab_veil_of_the_spirits","nome":"Veil of the Spirits","rank":3,"descricao":"At this Rank, the Hiruma has perfected his skills with stealth to the point where they become almost supernatural. As long as you do not move and have some form of cover, concealment, or camouflage available (GM's discretion), you may spend a Void Point to make yourself all but invisible - in mechanical terms, this adds a number of kept dice to your Stealth roll equal to your School Rank. This effect lasts until you move or make a noise."},{"id":"crab_harness_the_wind","nome":"Harness the Wind","rank":4,"descricao":"The Hiruma has now learned to strike as swiftly as he runs. You may make attacks as a Simple Action instead of a Complex Action when using any samurai weapons, knife, or bow. You may also attack as a Simple Action regardless of weapon when fighting any Shadowlands creature or other known Tainted nonhuman (such as zombies or gaki)."},{"id":"crab_strike_of_the_stalker","nome":"Strike of the Stalker","rank":5,"descricao":"The Hiruma Scouts strike their opponents from hiding, delivering vicious blows that get past all defenses. If you are striking a surprised or unaware foe, your Raises are not limited by your Void,a nd you can ignore 10 points of Reduction (from any source)."}]},{"id":"crab_defender_of_the_wall","clanId":"crab","nome":"Defender of the Wall","traco":"","honra":"","tags":["bushi","crab_bushi","advanced","crab_advanced"],"pericias":[],"tecnicas":[{"id":"crab_the_flames_of_purity","nome":"The Flames Of Purity","rank":1,"descricao":"The Defender of the Wall is ready to repel any unnatural assaults with the conviction of a pure soul. Creatures with the Shadowlands Taint may not reroll 10's on attack or damage rolls against you."},{"id":"crab_hidas_strength","nome":"Hida's Strength","rank":2,"descricao":"The Defender of the Wall is an impregnable fortress, even without wearing his armor. You gain Reduction 8. This stacks with any other Techiques or armor which grant you Reduction."},{"id":"crab_the_crab_are_the_wall","nome":"The Crab Are The Wall","rank":3,"descricao":"The Defender of the Wall will let nothing stop him short of death. Once per round, you may immediately negate one Condition on yourself (other than Mounted or Grappled)."}]},{"id":"crane_kakita_bushi_school","clanId":"crane","nome":"Kakita Bushi School","traco":"reflexes","honra":"6.5","tags":["bushi","crane_bushi"],"pericias":[{"id":"etiquette","rank":1,"enfase":""},{"id":"iaijutsu","rank":1,"enfase":"Focus"},{"id":"kenjutsu","rank":1,"enfase":""},{"id":"kyujutsu","rank":1,"enfase":""},{"id":"sincerity","rank":1,"enfase":""},{"id":"tea_ceremony","rank":1,"enfase":""}],"tecnicas":[{"id":"crane_the_way_of_the_crane","nome":"The Way Of The Crane","rank":1,"descricao":"The study of the sword demonstrates the many ways in which the art of Kakita's technique can be applied. You add twice your Iaijutsu Skill to all Initiative rolls. You gain a bonus of +1k1 plus your School Rank to the total of all attack and Focus rolls while assuming the Center Stance. This bonus also applies during the Combat Round following one in which you assume the Center Stance."},{"id":"crane_speed_of_lightning","nome":"Speed Of Lightning","rank":2,"descricao":"Enemies who are slow or weak of spirit are doomed to failure. You gain a bonus of +2k0 to the total of all attack rolls against those with lower Initiative than your own."},{"id":"crane_first_and_last_strike","nome":"First And Last Strike","rank":3,"descricao":"A Kakita Bushi is feared throughout the Empire as a follower of the oldesta nd most venerated dueling tradition in the Empire. You may Strike first in a duel if you win the Iaijutsu/Void roll by a difference of 3 or higher. You gain a Free Raise on your Strike for each additional margin of 3 instead of 5."},{"id":"crane_one_strike_two_cuts","nome":"One Strike, Two Cuts","rank":4,"descricao":"With one pure strike, the advanced student of Kakita's technique cuts his opponent twice. You may make attacks as a Simple Action instead of a Complex Action while using weapons with the Samurai keyword."},{"id":"crane_strike_with_no_thought","nome":"Strike With No Thought","rank":5,"descricao":"A true student of Kakita requires no thought before the perfect strike, depending entirely on instinct. You may take one Simple Action per Turn while assuming the Center Stance. You gain the benefits of Center Stance while you assume the stance instead of the following Turn, and you may remain in the Center Stance as many consecutive Turns as desired. The Simple Action you take can be a Move Action (bypassing the normal restriction of the Center Stance)."}]},{"id":"crane_asahina_shugenja_school","clanId":"crane","nome":"Asahina Shugenja School","traco":"awareness","honra":"6.5","tags":["shugenja","crane_shugenja"],"pericias":[{"id":"calligraphy","rank":1,"enfase":"Cipher"},{"id":"etiquette","rank":1,"enfase":""},{"id":"lore_theology","rank":1,"enfase":""},{"id":"meditation","rank":1,"enfase":""},{"id":"spellcraft","rank":1,"enfase":""}],"tecnicas":[{"id":"crane_the_souls_grace","nome":"The Soul's Grace","rank":1,"descricao":"The Asahina have harnessed the power of the kami for art, not war. You may spend a Void Point to reduce the total of all opponents' damage rolls inflicted within 20' of you by 0k1 for a number of rounds equal to your School Rank. (Using this technique again before its duration expires \"resets\" the duration but does not increase the damage penalty.) You also gain a Free Raise on any spell with the Defense keyword. Spells: Sense, Commune, Summon, 3 Air, 2 Water, and 1 Earth"}]},{"id":"crane_doji_courtier_school","clanId":"crane","nome":"Doji Courtier School","traco":"awareness","honra":"6.5","tags":["courtier","crane_courtier"],"pericias":[{"id":"calligraphy","rank":1,"enfase":""},{"id":"courtier","rank":1,"enfase":"Manipulation"},{"id":"etiquette","rank":1,"enfase":"Courtesy"},{"id":"perform_storytelling","rank":1,"enfase":""},{"id":"sincerity","rank":1,"enfase":""},{"id":"tea_ceremony","rank":1,"enfase":""}],"tecnicas":[{"id":"crane_the_soul_of_honor","nome":"The Soul Of Honor","rank":1,"descricao":"Apprentice Doji courtiers are taught to rely on their Honor when dealing with others, infusing their every word and gesture with the power of their purity, and to build networks of allies by discerning what others need and fulfilling those needs. So long as you maintain your Honor Rank at 6.0 or better, you gain a Free Raise on all Courtier, Sincerity, and Etiquette rolls. Also, by conversing with another person for a few minutes, you can make a Contested Roll of Courtier (Manipulation) / Awareness against the target's Etiquette (Courtesy) / Awareness to learn whether they are in need of any favors or assistance (such as needing travel papers to reach another province, for example)."},{"id":"crane_speaking_in_silence","nome":"Speaking In Silence","rank":2,"descricao":"At this Rank the Doji learns Cadence, the art of communicating through subtle gestures and body language. This gives them a huge advantage in the courts by allowing them to share information while their rivals are none the wiser. You can roll Courtier / Intelligence at TN 15 to communicate simple ideas and instructions (things like \"distract them,\" \"this favors us,\" or \"Intercept that person\") with any other Crane who is trained in the Doji Courtier School or who has at least 5 Ranks in the Courtier Skill. More complex ideas can be conveyed with Raises, although there is an upper limit (set by the GM) on how complicated Cadence can become."},{"id":"crane_the_perfect_gift","nome":"The Perfect Gift","rank":3,"descricao":"The Doji build their networks of alliances through selflessness, offering others what they need so that in the future the Doji may rely on their assistance. Any time you are in court or in an urban area, you can roll Courtier / Awareness at TN 20 to come up with a suitable gift or a helpful political favor for someone else. By calling Raises on this roll, you can acquire a rarer or more potent gift or favor. If such a gift or favor is accepted, you may immediately take that person as an Ally with 1-point Devotion, without XP cost (subject to the GM's permission)."},{"id":"crane_voice_of_honor","nome":"Voice Of Honor","rank":4,"descricao":"At this Rank the Doji has learned the art of political maneuvering, making his positions and arguments appear synonymous with Honor, forcing anyone who disagrees with him to take a dishonorable position. In any debate or arguement, you may make a Contested Roll of Courtier (Manipulation) / Awareness against the target's Etiquette (Courtesy) / Awareness. If you win the roll, the opponent is forced to concede that his position conflicts with the demands of Honor and Bushido, and if he persists in that position he will commit a breach of etiquette. (It is the GM's discretion, based on the circumstances, as to whether it is a minor or major breach.)"},{"id":"crane_the_gift_of_the_lady","nome":"The Gift Of The Lady","rank":5,"descricao":"The final training of the Doji teaches them the art of influencing the emotions of others, making friends and allies out of almost anyone - even bitter enemies. By conversing with someone for a few minutes, you may make a Contested Roll of Courtier (Manipulation) / Awareness against the target's Etiquette (Courtesy) / Willpower. If the target is an Ally, you gain a bonus of +5k0 to the total of this roll. With a success, you shift the target's emotions in a favorable direction, persuading them to listen to your advice and counsel. The GM is the final arbiter but in general, the target will go along with anything you suggest which does not conflict with his basic loyalties."}]},{"id":"crane_daidoji_iron_warriors","clanId":"crane","nome":"Daidoji Iron Warriors","traco":"agility","honra":"6.5","tags":["bushi","crane_bushi"],"pericias":[{"id":"battle","rank":1,"enfase":""},{"id":"defense","rank":2,"enfase":""},{"id":"iaijutsu","rank":1,"enfase":""},{"id":"kenjutsu","rank":1,"enfase":"Katana"},{"id":"kyujutsu","rank":1,"enfase":""}],"tecnicas":[{"id":"crane_the_force_of_honor","nome":"The Force Of Honor","rank":1,"descricao":"The Iron Warrior serves as the shield of his clan, defending the honor and homes of the Crane. You gain a bonus of your Honor Rank (rounded down) minus 4 to your Wounds at each Wound Rank, to a minimum bonus of one. (Thus at Honor Rank 6.5, you gain a bonus of 2 Wounds to each Wound Rank.) Additionally, you gain a bonus of +1k0 to the total of all attack rolls while in the Attack Stance."},{"id":"crane_the_shield_of_faith","nome":"The Shield Of Faith","rank":2,"descricao":"The Iron Warrior truly believes that his work serves a higher purpose. When you perform the Guard Maneuver, the benefits last for an additional Round. Additionally, the Armor TN bonus of the Guard Maneuver is increased by 5. (This bonus applies to both your Armor TN and your target's Armor TN - thus, you suffer not TN penalty when Guarding, and your target gains a bonus of +15 to his Armor TN instead of +10.)"},{"id":"crane_strike_beneath_the_veil","nome":"Strike Beneath The Veil","rank":3,"descricao":"The Daidoji is an intractable foe, devastating to face under any circumstances. You may make melee attacks as a Simple Action instead of a Complex Action while in the Attack Stance."},{"id":"crane_vigilance_of_mind","nome":"Vigilance Of Mind","rank":4,"descricao":"The Iron Warrior is always on the lookout for dangers. You may spend a Void Point during the Reactions Stage to target an opponent who has attempted to strike at either you or the target of your Guard Maneuver during the Round. You gain a bonus of +2k1 to the total of all attack and damge rolls against that opponent during the next Round."},{"id":"crane_to_tread_on_the_sword","nome":"To Tread On The Sword","rank":5,"descricao":"When the Iron Warrior fights to protect his charge, he will continue on long after others would perish. You may spend two Void Points as a Free Action when someone declares an action against the target of your Guard Maneuver. You become the target of the action instead (if it would be a legal action - GM's discretion in questionable instances). You also gain one Free Action that you may use immediately for the sole purpose of moving toward the target of your Guard Maneuver. If you cannot reach your target, this Technique has no effect."}]},{"id":"crane_kenshinzen","clanId":"crane","nome":"Kenshinzen","traco":"","honra":"","tags":["bushi","crane_bushi","advanced","crane_advanced"],"pericias":[],"tecnicas":[{"id":"crane_drawing_the_void","nome":"Drawing The Void","rank":1,"descricao":"The Kenshinzen remains still on the battlefield while the chaos of battle rages around him. If you are in the Center Stance, you add an additional +10 to your Armor TN."},{"id":"crane_kakitas_strength","nome":"Kakita's Strength","rank":2,"descricao":"The Kenshinzen can sense the moments between heartbeats, allowing him to strike at the exact moment needed. When making an Assessment or Focus roll as part of an Iajutsu duel, your dice explode on a 9 as well as a 10."},{"id":"crane_a_single_moment","nome":"A Single Moment","rank":3,"descricao":"The Kenshinzen's will to defeat his enemy exudes out of him, paralyzing his enemies. If you make only one attack this Turn, an opponent you hit is Stunned until the beginning of your next Turn."}]},{"id":"dragon_mirumoto_bushi_school","clanId":"dragon","nome":"Mirumoto Bushi School","traco":"stamina","honra":"4.5","tags":["bushi","dragon_bushi"],"pericias":[{"id":"defense","rank":1,"enfase":""},{"id":"iaijutsu","rank":1,"enfase":""},{"id":"kenjutsu","rank":1,"enfase":"Katana"},{"id":"lore_shugenja","rank":1,"enfase":""},{"id":"lore_theology","rank":1,"enfase":""},{"id":"meditation","rank":1,"enfase":""}],"tecnicas":[{"id":"dragon_way_of_the_dragon","nome":"Way Of The Dragon","rank":1,"descricao":"Initiates of the Mirumoto Bushi School must master the basic principles of Niten, the two-sword technique founded by Mirumoto himself. When wielding a katana in your main hand and a wakizashi in your off hand, you suffer no penalties of any kind for dual wielding, and you gain a bonus of your School Rank to your Armor TN (This is cumulative with the normal bonus for wielding two weapons). Additionally, when you are targeted with a spell, you may raise or lower the TN of that spell's Spellcasting Roll by 5."},{"id":"dragon_the_calm_in_midst_of_thunder","nome":"The Calm In Midst Of Thunder","rank":2,"descricao":"In addition to their focus on the art of kenjutsu, the Mirumoto study the art of the duel as well in order to properly face their traditional opponents among the Kakita. While you assume the Center Stance, you gain a bonus to the total of your Iaijutsu rolls equal to your Kenjutsu Skill Rank."},{"id":"dragon_strong_and_swift","nome":"Strong And Swift","rank":3,"descricao":"As the exploration of Niten continues, the student learns to overwhelm opponents with a flurry of blows while maintaining a superior defense. Attacking is a Simple Action for you while you use weapons with the Samurai keyword."},{"id":"dragon_furious_retaliation","nome":"Furious Retaliation","rank":4,"descricao":"Once an opponent presents himself as a threat, the Mirumoto will stop at nothing to defeat him to defend the honor of the family's teachings. During the Reactions Stage of Combat, you may choose one opponent who made or attempted an attack against you this Round. During your next Turn, you gain a bonus of +3k0 to all attack rolls against that target."},{"id":"dragon_heart_of_the_dragon","nome":"Heart Of The Dragon","rank":5,"descricao":"Masters of the Mirumoto Bushi School seem to strike from everywhere at once. If you attack twice in the same Turn while you are wielding a katana in your main hand and a wakizashi in your off hand, you may make one additional attack with your off hand as a Free Action."}]},{"id":"dragon_tamori_shugenja_school","clanId":"dragon","nome":"Tamori Shugenja School","traco":"stamina","honra":"4.5","tags":["shugenja","dragon_shugenja"],"pericias":[{"id":"athletics","rank":1,"enfase":""},{"id":"calligraphy","rank":1,"enfase":"Cipher"},{"id":"defense","rank":1,"enfase":""},{"id":"divination","rank":1,"enfase":""},{"id":"lore_theology","rank":1,"enfase":""},{"id":"medicine","rank":1,"enfase":""},{"id":"spellcraft","rank":1,"enfase":""}],"tecnicas":[{"id":"dragon_flesh_of_the_elements","nome":"Flesh of the Elements","rank":1,"descricao":"The Tamori have learned to distill the essence of magic and contain it within concoctions or objects for later use. You may expend one spell slot to store a spell you know that has an Area of effect \"one target person\" or \"one target creature\" in a potion, to be activated later. This stored spell may be activated instantly by anyone holding the potion by expending a Simple Action to drink it or a Complex Action to throw it (depending upon the spell's target), using Athletics (Throwing) / Agility. Spells stored in this manner may be stored indefinitely, but count against your spell slots per day for each day that they continue to await activation. Creating a potion in this manner requires a number of hours equal to the stored spell's Mastery Level. You also gain a Free Raise on any spell with the Craft keyword. Spells: Sense, Commune, Summon, 3 Earth, 2 Fire, and 1 Water"}]},{"id":"dragon_kitsuki_investigator_school","clanId":"dragon","nome":"Kitsuki Investigator School","traco":"perception","honra":"5.5","tags":["courtier","dragon_courtier"],"pericias":[{"id":"courtier","rank":1,"enfase":""},{"id":"etiquette","rank":1,"enfase":"Courtesy"},{"id":"investigation","rank":1,"enfase":"Interrogation"},{"id":"kenjutsu","rank":1,"enfase":""},{"id":"meditation","rank":1,"enfase":""},{"id":"sincerity","rank":1,"enfase":""}],"tecnicas":[{"id":"dragon_kitsukis_method","nome":"Kitsuki's Method","rank":1,"descricao":"The Kitsuki are masters of investigation and perception, noticing the most minute and telling details with merely a glance. You gain a Free Raise on all your Investigation Skill Rolls. However, while the Kitsuki are trained for investigation and diplomacy, unlike other courtiers they do not wholly neglect the ways of the warrior. In a skirmish, you add your Perception Trait Rank to your Armor TN."},{"id":"dragon_wisdom_the_wind_brings","nome":"Wisdom The Wind Brings","rank":2,"descricao":"The Kitsuki skill at noticing small details makes it very difficult to deceive them. Anyone making a Social Skill Roll for the purpose of lying to you or otherwise deceiving you, or making a Feint or Disarm Maneuver against you in a skirmish, must add +5 to their TN for each of your Kitsuki Investigator School Ranks."},{"id":"dragon_know_the_rhythm_of_the_heart","nome":"Know The Rhythm Of The Heart","rank":3,"descricao":"The Kitsuki study a secret methodology known as Ichi Miru, or \"first look,\" which allows them to size up another person in almost a single glance. After speaking with someone for a few moments, you can roll Investigation (Notice) / Perception against a TN of their Intelligence x 5. A success grants you a true and accurate, if simple, picture of their personality and motivations. For example, you might perceive that a boisterous ronin is actually a calculating man who is trying to put on the picture of being a rude, simple fellow."},{"id":"dragon_finding_the_path","nome":"Finding The Path","rank":4,"descricao":"The Kitsuki has learned the art of uncovering and tracking others' social connections and networks of alliances. By conversing with someone for a few minutes, you can make a Contested Roll of your Investigation (Interrogation) / Intelligence against their Etiquette (Courtesy) / Intelligence to identify one of their allies or enemies. Each successful Raise you make on this roll will identify another of their allies or enemies (you choose whether you learn an ally or an enemy - the GM chooses which specific person is revealed). This technique can be used against each specific person once per day."},{"id":"dragon_the_eyes_betray_the_heart","nome":"The Eyes Betray The Heart","rank":5,"descricao":"Kitsuki's method allows its master practitioners to see through even the most practiced falsehoods and tricks. At this rank, any knowing attempt to lie to you (as opposed to unwittingly passing on false information) will almost certainly fail. You automatically make a Contested Roll of your Investigation (Interrogation) / Perception against the liar's Sincerity (Deceit) / Willpower, whether or not you suspect them of lying. Further, if you already known someone is lying to you, you gain a bonus of +5k0 on this Contested Roll, and my call Raises on the roll in an attempt to make them inadvertently give away more information than they intended (GM's choice what information they reveal)."}]},{"id":"dragon_togashi_tattooed_order","clanId":"dragon","nome":"Togashi Tattooed Order","traco":"void","honra":"4.5","tags":["monk","dragon_monk"],"pericias":[{"id":"athletics","rank":1,"enfase":""},{"id":"craft_tattooing","rank":1,"enfase":""},{"id":"defense","rank":1,"enfase":""},{"id":"jiujutsu","rank":1,"enfase":""},{"id":"meditation","rank":1,"enfase":""}],"tecnicas":[{"id":"dragon_blood_of_the_kami","nome":"Blood Of The Kami","rank":1,"descricao":"The blood of the Kami is barely diluted in the ruling line of the Togashi order, and the brothers chosen to serve the Dragon as Togashi vassals receive the mystical blood of a god in the form of unique tattoos. You gain two Tattoos at this rank."},{"id":"dragon_body_of_stone","nome":"Body Of Stone","rank":2,"descricao":"Master of the body is the first essential step of a monk's journey toward enlightenment, and martial arts are the perfect tool to bring the body and spirit into harmony. You gain a bonus of +1k1 to the total of all unarmed attack and damage rolls."},{"id":"dragon_blessing_of_the_kami","nome":"Blessing Of The Kami","rank":3,"descricao":"As an ise zumi continues his journey of self-discovery, accumulating new experiences along the way, he will eventually be judged worth of additional insight in the form of new tattoos. You gain two additional Tattoos."},{"id":"dragon_will_of_stone","nome":"Will Of Stone","rank":4,"descricao":"Perfect mastery of the flesh is an indication that a soul's journey is nearing its end. You may make unarmed attacks as a Simple Action rather than a Complex Action."},{"id":"dragon_touch_of_the_kami","nome":"Touch Of The Kami","rank":5,"descricao":"Insight into the true nature of the universe is the reward for a soul that seeks true mastery of the spirit. You gain two additional Tattoos."}]},{"id":"dragon_ob_hoshi_tsurui_zumi","clanId":"dragon","nome":"Hoshi Tsurui Zumi","traco":"void","honra":"4.5","tags":["monk","dragon_monk"],"pericias":[{"id":"athletics","rank":1,"enfase":""},{"id":"defense","rank":1,"enfase":""},{"id":"etiquette","rank":1,"enfase":""},{"id":"jiujutsu","rank":1,"enfase":""},{"id":"meditation","rank":1,"enfase":"Void"}],"tecnicas":[]},{"id":"dragon_ob_hitomi_kikage_zumi","clanId":"dragon","nome":"Hitomi Kikage Zumi","traco":"reflexes","honra":"4.5","tags":["monk","dragon_monk"],"pericias":[{"id":"athletics","rank":1,"enfase":""},{"id":"defense","rank":1,"enfase":""},{"id":"jiujutsu","rank":1,"enfase":""},{"id":"meditation","rank":1,"enfase":""}],"tecnicas":[]},{"id":"dragon_swordsmasters","clanId":"dragon","nome":"Swordsmasters","traco":"","honra":"","tags":["bushi","dragon_bushi","advanced","dragon_advanced"],"pericias":[],"tecnicas":[{"id":"dragon_the_silence_of_two_strikes","nome":"The Silence Of Two Strikes","rank":1,"descricao":"The Swordmaster's connection to his blades is nearly supernatural, allowing him to tune out the rest of the world. While wielding a katana in your main hand and a wakizashi in your offhand, you may spend Void Points twice per Turn."},{"id":"dragon_mirumotos_strength","nome":"Mirumoto's Strength","rank":2,"descricao":"The Swordmaster feels the calm of the world when he stands before his opponent. In an iaijutsu duel, you always gain a +1k1 bonus to your Focus roll as though you had beaten your opponent with the Assessment roll, regardless of the roll's actual result. (Your opponent can still gain the +1k1 bonus for having a higher Assessment roll, but this does not impact your bonus.)"},{"id":"dragon_harmony_and_precision","nome":"Harmony And Precision","rank":3,"descricao":"The Swordmaster fells an opponent with each swing of the blade, striking exactly where he needs to devastate his enemies. While wielding a katana in your main hand and a wakizashi in your off hand, you may ignore your opponents Reduction (if any)."}]},{"id":"dragon_tamori_master_of_the_mountains","clanId":"dragon","nome":"Tamori Master Of The Mountains","traco":"","honra":"","tags":["shugenja","dragon_shugenja","advanced","dragon_advanced"],"pericias":[],"tecnicas":[{"id":"dragon_integration_of_the_gods","nome":"Integration Of The Gods","rank":1,"descricao":"The Master of the Mountain knows flexibility is the only way to survive in the harsh wilderness of the mountains. When casting a spell, you may choose to spend 2 spell slots of another Ring rather than a single spell slot of the appropriate Ring. (This cannot be the Ring of the opposing Element from the spell's Element, e.g. Air/Earth, Fire/Water.) For example, this means that you may spend 2 Earth spell slots to cast a Fire spell instead of a single Fire spell slot."},{"id":"dragon_inner_fortitude","nome":"Inner Fortitude","rank":2,"descricao":"The Master of the Mountain draws power from within his own body as well as teh Elements outside. Your Shugenja School Rank increases by one. Additionally, you may spend a spell slot as a Free Action to gain Reduction 2 and +10 to your Armor TN. This effect lasts for a number of Rounds equal to your Earth Ring, ending during the Reactions Stage of the final Round. You may choose to end the effect early as a Free Action. For the purposes of casting spells, your School Rank is increased by 1. While this effect is active, you find it more difficult to tap into the Elements around you. You must call one Raise to no effect every time you cast a spell."},{"id":"dragon_power_in_need","nome":"Power In Need","rank":3,"descricao":"The Master of the Mountain can coax power out of the most contrary kami by confronting them with his own strength and willpower. As a Simple Action you may spend a Void Point and a spell slot from any Ring. Choose a spell keyword. You gain a bonus of +4k1 to the total of all Spell Casting Rolls while casting spells with that keyword. This effect lasts until the end of the encounter (in combat) or for an hour (outside of combat)."}]},{"id":"dragonfly_tonbo_shugenja_school","clanId":"dragonfly","nome":"Tonbo Shugenja School","traco":"perception","honra":"4.5","tags":["shugenja","dragonfly_shugenja"],"pericias":[{"id":"calligraphy","rank":1,"enfase":""},{"id":"courtier","rank":1,"enfase":""},{"id":"etiquette","rank":1,"enfase":""},{"id":"meditation","rank":1,"enfase":"Void Recovery"},{"id":"sincerity","rank":1,"enfase":""},{"id":"spellcraft","rank":1,"enfase":""}],"tecnicas":[{"id":"dragonfly_guided_by_fate","nome":"Guided By Fate","rank":1,"descricao":"The Tonbo are adept at court as well as the ways of the shugenja, serving as they have as the Dragon Clan's intermediaries almost since their creation. The kami's whispers can be powerful tools in court. You may expend one spell slot to gain a bonus of +1k0 on one Social Skill Roll. You may never spend more spell slots than your School Rank to augment a single roll. You gain a Free Raise on any spell with the Divination keyword."}]},{"id":"falcon_toritaka_bushi_school","clanId":"falcon","nome":"Toritaka Bushi School","traco":"strength","honra":"5.5","tags":["bushi","falcon_bushi"],"pericias":[{"id":"animal_handling","rank":1,"enfase":"Falcons"},{"id":"hunting","rank":2,"enfase":""},{"id":"kenjutsu","rank":1,"enfase":""},{"id":"lore_spirit_realms","rank":1,"enfase":""},{"id":"spears","rank":1,"enfase":""}],"tecnicas":[{"id":"falcon_the_falcons_eyes","nome":"The Falcon's Eyes","rank":1,"descricao":"A Toritaka must be aware of his surroundings at all times, for his enemies can appear anywhere. You add +1k0 to all Skill and raw Trait rolls involving the Perception Trait. Additionally, when striking a creature from another Spirit Realm (including oni from Jigoku and hungry dead from Gaki-do), you add +1k0 to all damage rolls."},{"id":"falcon_the_falcon_takes_flight","nome":"The Falcon Takes Flight","rank":2,"descricao":"Through his training, the Toritaka can sense the emanations of nearby spirits as they cross over into the mortal realm. You may attempt to detect the presence of any creatures from other Spirit Realms by making a Perception Trait Roll against a TN equal to the creature's Air Ring x 5."},{"id":"falcon_the_falcons_wings","nome":"The Falcon's Wings","rank":3,"descricao":"The Toritaka strikes with precision, constantly keeping his enemies at bay. You may make attacks as a Simple Action instead of a Complex Action while wielding a spear or a weapon with the Samurai keyword."},{"id":"falcon_vigilant_and_strong","nome":"Vigilant And Strong","rank":4,"descricao":"Monsters may have tricks to confuse their enemies, but the Toritaka learns to see the truth through the fog. You may spend a Void Point to negate any darkness or blinding penalties. This effect lasts until the Reactions Phase two Rounds later."},{"id":"falcon_claws_of_the_falcon","nome":"Claws Of The Falcon","rank":5,"descricao":"Nothing will stop the Toritaka's attack from hitting its target. Your attacks ignore up to 5 points of your opponent's Reduction (if he has any). Against creatures from other Spirit Realms, you may spend a Void Point as a Free Action to reduce the creature's Reduction by 10 for one Round."}]},{"id":"fox_kitsune_shugenja_school","clanId":"fox","nome":"Kitsune Shugenja School","traco":"stamina","honra":"4.5","tags":["shugenja","fox_shugenja"],"pericias":[{"id":"calligraphy","rank":1,"enfase":""},{"id":"defense","rank":1,"enfase":""},{"id":"hunting","rank":1,"enfase":""},{"id":"medicine","rank":1,"enfase":"Herbalism"},{"id":"meditation","rank":1,"enfase":""},{"id":"spellcraft","rank":1,"enfase":""}],"tecnicas":[{"id":"fox_essence_of_chikushudo","nome":"Essence Of Chikushudo","rank":1,"descricao":"None in the Empire are closer to the ways of nature than the simple Kitsune who make the wilderness their home. You may use the Sense, Commune, and summon basic spells to affect the animal spirits of Chikushudo as well as kami (using Summon results in the appearance of a single animal spirit rather than a set amount of the elemental material). Animal spirits tend to be more direct than kami, and perceive things differently, but have just as little sense of why man does what he does. You gain a Free Raise on any nonSpells: Sense, Commune, Summon, 3 Earth, 2 Water, and 1 Fire"}]},{"id":"hare_usagi_bushi_school","clanId":"hare","nome":"Usagi Bushi School","traco":"reflexes","honra":"4","tags":["bushi","hare_bushi"],"pericias":[{"id":"athletics","rank":1,"enfase":"Running"},{"id":"defense","rank":1,"enfase":""},{"id":"hunting","rank":1,"enfase":""},{"id":"jiujutsu","rank":1,"enfase":""},{"id":"kenjutsu","rank":1,"enfase":""},{"id":"lore_maho","rank":1,"enfase":""}],"tecnicas":[{"id":"hare_speed_of_the_hare","nome":"Speed Of The Hare","rank":1,"descricao":"The Hare are known for fighting with a speed and agility reminiscent of the animal for which their clan is named. In any situation where you have room to dodge, jump, and otherwise maneuver (GM's discretion), you may add your Athletics Skill Rank to your Armor TN except when in the Full Attack or Center stance. Your Water Ring is considered 1 higher for purposes of how far you can move with Move actions."},{"id":"hare_leap_of_the_hare","nome":"Leap Of The Hare","rank":2,"descricao":"The Hare bushi has learned to strike with a devastating springing attack that catches many opponents off guard. If you are in the Full Attack stance, you can leap forward and attack an opponent up to 15' away without taking a Move Action. All of your attacks on this turn must target that opponent."},{"id":"hare_swift_as_lightning","nome":"Swift As Lightning","rank":3,"descricao":"The speed and flexibility of the Hare allows him to strike with fearsome rapidity. Your attacks with unarmed strikes, knives, or Samurai-keyword weapons are considered Simple Actions."},{"id":"hare_kick_of_the_hare","nome":"Kick Of The Hare","rank":4,"descricao":"The Hare has learned not only how to strike with speed, but also how to dodge and avoid his foes at the same time. You may now perform your Rank Two Techniques while in the Attack stance instead of the Full Attack stance. If you perform the technique in the Full Attack stance, you may make your second attack of the Round against another opponent within 15' of the first opponent."},{"id":"hare_reichins_style","nome":"Reichin's Style","rank":5,"descricao":"The final lesson of the Hare school is a whirling flurry of leaps, feints, and attacks that come at the opponent from all directions, confusing and disorienting him. You may perform the Feint Maneuver for only 1 Raise, and your damage bonus from a successful Feint is not limited to your Insight Rank x 5."}]},{"id":"hare_usagi_bushi_school_after_clan_war","clanId":"hare","nome":"Usagi Bushi School (After Clan War)","traco":"reflexes","honra":"4","tags":["bushi","hare_bushi"],"pericias":[{"id":"athletics","rank":1,"enfase":"Running"},{"id":"defense","rank":1,"enfase":""},{"id":"hunting","rank":1,"enfase":""},{"id":"jiujutsu","rank":1,"enfase":""},{"id":"kenjutsu","rank":1,"enfase":""},{"id":"lore_kolat","rank":1,"enfase":""}],"tecnicas":[{"id":"hare_speed_of_the_hare","nome":"Speed Of The Hare","rank":1,"descricao":"The Hare are known for fighting with a speed and agility reminiscent of the animal for which their clan is named. In any situation where you have room to dodge, jump, and otherwise maneuver (GM's discretion), you may add your Athletics Skill Rank to your Armor TN except when in the Full Attack or Center stance. Your Water Ring is considered 1 higher for purposes of how far you can move with Move actions."},{"id":"hare_leap_of_the_hare","nome":"Leap Of The Hare","rank":2,"descricao":"The Hare bushi has learned to strike with a devastating springing attack that catches many opponents off guard. If you are in the Full Attack stance, you can leap forward and attack an opponent up to 15' away without taking a Move Action. All of your attacks on this turn must target that opponent."},{"id":"hare_swift_as_lightning","nome":"Swift As Lightning","rank":3,"descricao":"The speed and flexibility of the Hare allows him to strike with fearsome rapidity. Your attacks with unarmed strikes, knives, or Samurai-keyword weapons are considered Simple Actions."},{"id":"hare_kick_of_the_hare","nome":"Kick Of The Hare","rank":4,"descricao":"The Hare has learned not only how to strike with speed, but also how to dodge and avoid his foes at the same time. You may now perform your Rank Two Techniques while in the Attack stance instead of the Full Attack stance. If you perform the technique in the Full Attack stance, you may make your second attack of the Round against another opponent within 15' of the first opponent."},{"id":"hare_reichins_style","nome":"Reichin's Style","rank":5,"descricao":"The final lesson of the Hare school is a whirling flurry of leaps, feints, and attacks that come at the opponent from all directions, confusing and disorienting him. You may perform the Feint Maneuver for only 1 Raise, and your damage bonus from a successful Feint is not limited to your Insight Rank x 5."}]},{"id":"imperial_seppun_guardsman_school","clanId":"imperial","nome":"Seppun Guardsman School","traco":"perception","honra":"6.5","tags":["bushi","imperial_bushi"],"pericias":[{"id":"battle","rank":1,"enfase":""},{"id":"defense","rank":1,"enfase":""},{"id":"etiquette","rank":1,"enfase":""},{"id":"iaijutsu","rank":1,"enfase":""},{"id":"kenjutsu","rank":1,"enfase":"Katana"},{"id":"kyujutsu","rank":1,"enfase":""}],"tecnicas":[{"id":"imperial_never_in_darkness","nome":"Never In Darkness","rank":1,"descricao":"The Seppun are taught to be unswerving in their Honor, and nothing can draw them away from their duty. Any time you are rolling to resist a Social Skill roll which could tempt or lead you away from your duty - such as Temptation, Intimidation, or even Courtier - you roll additional unkept dice equal to your School Rank. You gain a +1k1 bonus any time you are making an Investigation roll to detect an ambush or surprise attack."},{"id":"imperial_the_clouds_part","nome":"The Clouds Part","rank":2,"descricao":"The Seppun's blows are infused with his dedication to the Emperor's cause. At the start of your Turn, you may spend a Void Point to add your Honor Rank to the total of your attack and damage rolls until your Next Turn."},{"id":"imperial_suns_light_reveals","nome":"Sun'S Light Reveals","rank":3,"descricao":"The Seppun's dedication now allows him to see through all manner of deceptions, even magical ones. At any time you may choose to spend a Void point as a Free Action to roll Investigation (Notice) / Perception at TN 25. With a success, you immediately see through all disguises and illusions around you, whether normal or magical in nature. If you are in the presence of the Emperor, his immediate family, or a major Imperial Official (Chancellor, Shogun, etc) you do not need to spend a Void Point to activate this Technique. Once you have pierced a specific disguise/illusion, it no longer has any effect on you (although a new disguise or illusion you encounter later will function normally)."},{"id":"imperial_speed_of_heaven","nome":"Speed Of Heaven","rank":4,"descricao":"The power of Heaven infuses the Seppun's arm, allowing him to strike with greater speed. You may now attack as a Simple Action when using weapons with the Samurai keyword."},{"id":"imperial_heaven_never_falls","nome":"Heaven Never Falls","rank":5,"descricao":"The true Seppun bodyguard is never caught off-guard, and can protect his charge even when surprised or disabled. Any time you are within 20' of a person you are guarding, you may spend a Void Point to leap in front of a blow or spell which is targeting your charge. The damage is automatically applied to you instead of your charge. If you are still standing (not Down or Out) after this damage, you may immediately take an extra Simple Action, which may be used for any purpose including an attack. This Technique can be used even if your character is Blinded, Prone, Stunned, Dazed, Entangled, or at the Down Wound Rank (but not Grappled or at the Out Wound Rank)."}]},{"id":"imperial_seppun_shugenja_school","clanId":"imperial","nome":"Seppun Shugenja School","traco":"intelligence","honra":"6.5","tags":["shugenja","imperial_shugenja"],"pericias":[{"id":"calligraphy","rank":1,"enfase":""},{"id":"defense","rank":1,"enfase":""},{"id":"etiquette","rank":1,"enfase":""},{"id":"investigation","rank":1,"enfase":"Notice"},{"id":"lore_theology","rank":1,"enfase":""},{"id":"meditation","rank":1,"enfase":""}],"tecnicas":[{"id":"imperial_in_defense_of_the_throne","nome":"In Defense of the Throne","rank":1,"descricao":"The Hidden Guard exist only to defend their Emperor, and are terrible opponents for any who might pose a danger to the sanctity of the Son of Heaven. You gain a Free Raise on any spell cast to protect the life, personal belongings, family, or reputation of the Emperor, as long as the action taken would not cause you to lose Honor. This includes members of the Imperial families (though not yourself). You also gain a Free Raise on any spells known only to the Imperial families. Spells: Sense, Commune, Summon, 3 Fire, 2 Water, and 1 Air"}]},{"id":"imperial_otomo_courtier_school","clanId":"imperial","nome":"Otomo Courtier School","traco":"awareness","honra":"5.5","tags":["courtier","imperial_courtier"],"pericias":[{"id":"courtier","rank":1,"enfase":"Manipulation"},{"id":"defense","rank":1,"enfase":""},{"id":"etiquette","rank":1,"enfase":""},{"id":"intimidation","rank":1,"enfase":"Control"},{"id":"investigation","rank":1,"enfase":""},{"id":"sincerity","rank":1,"enfase":""}],"tecnicas":[{"id":"imperial_the_voice_of_heaven","nome":"The Voice Of Heaven","rank":1,"descricao":"The Otomo believe that nothing done in the name of the Emperor and Imperial authority can ever be truly dishonorable. Their appointed role within the Empire is to spread conflict between the clans so they cannot unite against Imperial power, and the Otomo do this without hesitation. You do not lose Honor for using the Intimidation (Control) Skill. Any time you are in conversation with someone from one of the clans (Great or Minor), you may make a Contested Roll of your Courtier (Manipulation) / Awareness against their Etiquette (Courtesy) / Awareness to provoke a disagreement or argument between them and someone from another clan or faction of your choice."},{"id":"imperial_destiny_has_no_secrets","nome":"Destiny Has No Secrets","rank":2,"descricao":"The Otmo have information networks that rival those of the Scorpion, and can call on them in almost any part of the Empire. If you have the opportunity to seek out your contacts, you may spend a Void Point to roll Courtier / Awareness at TN 25 to learn one piece of critically useful information (chosen by the GM)."},{"id":"imperial_my_masters_voice","nome":"My Master'S Voice","rank":3,"descricao":"The Otomo speak with the direct authority of the Emperor, and the more experienced among them have mastered the art of \"obiesaseru\", using the authority of the Son of Heaven to stun their foes. You may only use this Technique against honorable samurai (Honor Rank 1.0 or better) who revere the Emperor - criminals, bandits, the Lost, and nonhumans are immune to its effects. To use obiesaseru, you must take a Complex Action to pause, gather your willpoewr, and shout an appropriate command (typically something like, \"Stop in the name of the Emperor!\"). You make a Contested Social Skill roll of Intimidation (Control) / Willpower against the target's Etiquette (Courtesy) / Willpower. (If the target sincerely believes he is acting honorably, he gains a Free Raise to his roll.) If you win the roll, on his next Turn the target may not move, attack, cast spells, or perform any other action that would directly obstruct or threaten you or your immediate friends/allies (GM's discretion as to who is considered your ally). He may, however, attack others who are not your allies, and regardless he can always use the Defense and full Defense Postures."},{"id":"imperial_the_emperors_protection","nome":"The Emperor'S Protection","rank":4,"descricao":"As a favored servant of Imperial power, the Otomo is under special protection , and can easily crush those foolish enough to disagree with him in public. Any time you are in an argument or debate with another person, you may spend a Void Point to make a Contested Roll of your Courtier (Manipulation) / Awareness against their Etiquette (Courtesy) / Awareness. If you win the roll, they must either agree with your position or immediately lose 5 points of Honor."},{"id":"imperial_the_virtues_of_command","nome":"The Virtues Of Command","rank":5,"descricao":"The Otomo is now able to bring the full power of Imperial authority to bear on those who displease him. When making an Contested Social Roll against someone who reveres Imperial authority, you may gain a +5k0 bonus on your roll."}]},{"id":"imperial_miya_herald_school","clanId":"imperial","nome":"Miya Herald School","traco":"awareness","honra":"6.5","tags":["courtier","imperial_courtier"],"pericias":[{"id":"courtier","rank":1,"enfase":"Rhetoric"},{"id":"defense","rank":1,"enfase":""},{"id":"etiquette","rank":1,"enfase":"Courtesy"},{"id":"horsemanship","rank":1,"enfase":""},{"id":"lore_heraldry","rank":1,"enfase":""},{"id":"sincerity","rank":1,"enfase":""}],"tecnicas":[{"id":"imperial_voice_of_the_emperor","nome":"Voice Of The Emperor","rank":1,"descricao":"The Miya learn the ways of the Empire, so they can spread the word of the Emperor far and wide, and the art of non-aggression, so their words will be heard by all who respect the Emperor. While inside the borders of the Empire, you may spend a Void Point to gain the Way of the Land Advantage for the province you currently occupy - this effect lasts until you next sleep. Also, any Rokugani who reveres the Emperor and who knowingly and deliberately attacks you will automatically lose a number of points of Honor equal to twice your School Rank."},{"id":"imperial_eyes_of_the_emperor","nome":"Eyes Of The Emperor","rank":2,"descricao":"The Miya serve as peacekeepers as well as messengers, brokering treaties between warring factions in the Empire, and learn to remain impartial under the most intense pressure. You may add your Honor Rank to all Etiquette (Courtesy) skill rolls made to resist others' attempts to influence you."},{"id":"imperial_hand_of_the_emperor","nome":"Hand Of The Emperor","rank":3,"descricao":"The Miya's aura of peacefulness and non-aggression has now reached the point where it becomes difficult for honorable foes to attack him at all. At the start of a skirmish, or during the Reactions Step of any later round in a skirmish, you may spend a Void Point as a Free Action to prevent any Rokugani who reveres the Emperor from being able to harm you before the next Reactions step. (They can still attempt to capture or restrain you in a non-damaging way.) This Technique only takes effect as long as the Miya is not participating in the skirmish or in a duel."},{"id":"imperial_blessings_of_the_emperor","nome":"Blessings Of The Emperor","rank":4,"descricao":"At this rank, the Miya have developed a personality strong enough to impose their demand for peace on the more violent individuals around them, in what is essentially a specialized form of the Otomo technique of obiesaseru. This may be done a number of times per session equal to your School Rank, but you may only use this Technique against honorable samurai (Honor Rank 1.0 or better) who revere the Emperor - criminals, bandits, the Lost, and nonhumans are immune to its effects. To use this Technique, you take a Complex Action to step forward and forcefully demand an end to violence. (\"This brawling will cease, in the name of the Emperor!\") You make a Contested Roll of your Courtier (Rhetoric) / Awareness against the Etiquette (Courtesy) / Willpower of all affected person within hearing. All individuals who lose the roll must immediately cease all aggressive action, and cannot attack or cast offensive spells until they take damage or you give them permission to fight. (They can still use defensive abilities and the Defense and Full Defense stances.) The effect lasts for one minute, and the Technique can be used on the same targets again if it is resisted or expires. This Techniques affects both enemies and allies."},{"id":"imperial_glory_of_the_emperor","nome":"Glory Of The Emperor","rank":5,"descricao":"The Herald is now a true master of non-aggression and diplomacy. When rolling with the Courtier or Etiquette skills against a target with at least Honor 1.0, you may add a +5k0 bonus to the roll."}]},{"id":"lion_akodo_bushi_school","clanId":"lion","nome":"Akodo Bushi School","traco":"perception","honra":"6.5","tags":["bushi","lion_bushi"],"pericias":[{"id":"battle","rank":1,"enfase":"Mass Combat"},{"id":"defense","rank":1,"enfase":""},{"id":"kenjutsu","rank":1,"enfase":""},{"id":"kyujutsu","rank":1,"enfase":""},{"id":"lore_history","rank":1,"enfase":""},{"id":"sincerity","rank":1,"enfase":""}],"tecnicas":[{"id":"lion_the_way_of_the_lion","nome":"The Way Of The Lion","rank":1,"descricao":"Bushi of the Akodo School hone their fury until it is as precise as a blade. You may either ignore the portion of an opponent's Armor TN derived from Armor, or gain a Free Raise when attacking. (You do not ignore Reduction from the Armor when choosing the first option.) Also, you gain a bonus of +1k0 to the total of all attack rolls on your first melee attack against an opponent in a skirmish, or against any opponent who has declared a Raise on an attack against you since your last turn. You add only a total of 1k0 for an enemy who Raises against you, no matter how many times they actually Raised."},{"id":"lion_strength_of_purity","nome":"Strength Of Purity","rank":2,"descricao":"Akodo-trained warriors are known for their dedication to bushido, and take a fierce satisfaction in defeating dishonorable foes. During a skirmish you may add your Honor Rank to the total of any single roll during your Turn. You may not increase damage rolls in this fashion, nor can you do this while assuming the Center Stance."},{"id":"lion_strength_of_my_ancestors","nome":"Strength Of My Ancestors","rank":3,"descricao":"The Akodo bushi attacks twice, once for himself and once for his ancestor. You may make attacks as a Simple Action instead of a Complex Action while using weapons with the Samurai keyword."},{"id":"lion_triumph_before_battle","nome":"Triumph Before Battle","rank":4,"descricao":"No foe is beyond the reach of the devoted Lion warrior. Once per skirmish, you may designate an opponent durin the Reactions Stage. You may ignore any Armor TN bonuses your target receives from his Stance during the next Round."},{"id":"lion_akodos_final_lesson","nome":"Akodo's Final Lesson","rank":5,"descricao":"Mastery of the Akodo Bushi School imparts an unshakable faith in victory. When you make Raises on any Bugei Skill Roll, if you meet or exceed the original TN (before Raises) but fail to meet the Raised TN, you still succeed without the benefits of Raises."}]},{"id":"lion_kitsu_shugenja_school","clanId":"lion","nome":"Kitsu Shugenja School","traco":"perception","honra":"6.5","tags":["shugenja","lion_shugenja"],"pericias":[{"id":"battle","rank":1,"enfase":""},{"id":"calligraphy","rank":1,"enfase":"Cipher"},{"id":"etiquette","rank":1,"enfase":""},{"id":"lore_history","rank":1,"enfase":""},{"id":"lore_theology","rank":1,"enfase":""},{"id":"spellcraft","rank":1,"enfase":""}],"tecnicas":[{"id":"lion_eyes_of_the_ancestors","nome":"Eyes of the Ancestors","rank":1,"descricao":"The Kitsu are descended from mystical creatures, and as such are able to reach across the veil between worlds and speak with their ancestors. You may make a Spell Casting Roll (as though casting a Water Spell) against a target's Willpower x 5. If successful, you learn all Spiritual Advantages or Disadvantages that individual possesses. By spending a Void Point, you may negate any one Spiritual Advantage an opponent possesses for a number of minutes equal to your School Rank. You also gain a Free Raise on any spell with the Battle keyword. Spells: Sense, Commune, Summon, 3 Water, 2 Air, and 1 Earth"}]},{"id":"lion_ikoma_bard_school","clanId":"lion","nome":"Ikoma Bard School","traco":"intelligence","honra":"6.5","tags":["courtier","lion_courtier"],"pericias":[{"id":"courtier","rank":1,"enfase":""},{"id":"etiquette","rank":1,"enfase":""},{"id":"lore_history","rank":1,"enfase":"Lion Clan"},{"id":"perform_storytelling","rank":1,"enfase":""},{"id":"sincerity","rank":1,"enfase":"Honesty"}],"tecnicas":[{"id":"lion_the_herald_of_glory","nome":"The Herald Of Glory","rank":1,"descricao":"The Ikoma are historians and storytellers, tasked with recording the glorious deeds of others for posterity, ensuring that courageous and honorable accomplishments are never forgotten. You gain the Precise Memory Advantage for no cost in Experience Points (if you already have Percise Memory, you are refunded that many Experience Points). You may use the Perform: Storytelling skill to engage in public bragging on behalf of another person. If you can cite heroic or noble actions by that person and successfully roll Perform: Storytelling / Awareness at TN 20, that person whill gain a number of points of Glory equal to your School Rank. This may be done a number of times per person per month equal to your School Rank."},{"id":"lion_the_heart_of_the_lion","nome":"The Heart Of The Lion","rank":2,"descricao":"The Ikoma are tasked with conveying the emotions which the rest of the Clan keeps bottled away in stoic rectitude. You do not lose Honor or Glory for displaying emotion in public, so long as you do so on behalf of another Lion or for an honorable cause greater than yourself (such as your clan, the Empire, or the Code of Bushido). At the same time, your understanding of both honor and emotion strengthens your own soul against temptation. Anyone attempting to sway your emotions through the use of the Intimidation or Temptation skills must add +5 to their TN for each of your School Ranks."},{"id":"lion_the_voice_of_the_ancestors","nome":"The Voice Of The Ancestors","rank":3,"descricao":"The Ikoma act as Battle-Criers for the Lion, inspiring their soldiers on the battlefield with tales of the heroic deeds of their ancestors. Prior to a battle or skirmish, you may inspire your allies by speaking for a few minutes and rolling Perform: Oratory / Awareness at a TN equal to 15 + 5 per person you are inspiring. Targets who are not members of the Lion Clan increase the TN by 5 for each such person. With a successful roll, each person you inspired may add their Honor Rank to the total of any one Skill Roll during that battle or skirmish. (If this benefit is not used by the end of the battle, it is lost.)"},{"id":"lion_the_strength_of_tradition","nome":"The Strength Of Tradition","rank":4,"descricao":"The Ikoma's steadfast encouragement call on the examples of noble ancestors to infuse their allies with a strength they did not know they had. A number of times per session equal to your School Rank, as a Simple Action, you may verbally encourage an ally with a tale of great deeds from the past, rolling Perform: Storytelling / Awareness at TN 25. With a success, the next time during the same day that the chosen ally fails a roll, he may re-roll it, adding your Honor Rank in unkept dice to his roll. However, if he fails this second roll, you lose 2 points of Honor."},{"id":"lion_every_lion_is_your_brother","nome":"Every Lion Is Your Brother","rank":5,"descricao":"The Ikoma's understanding of Bushido, history, emotion, and human nature empowers them in court, filling their arguments with the ringing power of generations of noble Lion, and calling on the precedents of a thousand years and more to support their cause. Five times per session, when you are making a Contested Social Roll against an opponent, you may cite historical precedent to support your views and roll additional unkept dice equal to your Rank in Perform: Storytelling. (In situations where citing history seems inappropriate or strange, the GM has the final say on whether this Technique may be used.)"}]},{"id":"lion_matsu_berserker_school","clanId":"lion","nome":"Matsu Berserker School","traco":"strength","honra":"6.5","tags":["bushi","lion_bushi"],"pericias":[{"id":"battle","rank":1,"enfase":""},{"id":"jiujutsu","rank":1,"enfase":""},{"id":"kenjutsu","rank":1,"enfase":"Katana"},{"id":"kyujutsu","rank":1,"enfase":""},{"id":"lore_history","rank":1,"enfase":""}],"tecnicas":[{"id":"lion_the_lions_roar","nome":"The Lion's Roar","rank":1,"descricao":"Warriors of the Matsu School respect their Akodo cousins' leadership skills, but they know that a furious attack often simply overwhelms an enemy. You add your Honor Rank to all damage rolls. Whenever you assume the Full Attack Stance, you may move an additional 5 feet per Turn in addition to the bonus your receive from the Stance. (This does not allow you to move farther than your maximum move per Turn.)"},{"id":"lion_matsus_fury","nome":"Matsu's Fury","rank":2,"descricao":"The target of a Matsu's fury has little hope of victory. When you assume the Full Attack Stance, choose an opponent within 30'. If you successfully hit him this Turn, the target is frozen with fear and cannot take Move Actions to move from his current position. During the Reactions Stage, an affected opponent may attempt a Willpower roll against a TN equal to the amount of damage dealt from your latest attack to negate the effects of this Technique (the opponent does not suffer penalties from his Wound Rank for this roll). If he fails, the effects of this Technique end during the next Reactions Stage (the second after he was struck). Enemies who are immune to Fear cannot be affected by this Technique."},{"id":"lion_the_lions_charge","nome":"The Lion's Charge","rank":3,"descricao":"When a Lion strikes, he grants the gift of final rest to all who stand against him. You may make melee attacks as a Simple Action instead of a Complex Action."},{"id":"lion_matsus_courage","nome":"Matsu's Courage","rank":4,"descricao":"Death means nothing in the face of the loss of honor, and no Matsu will yield while he yet draws breath. You ignore TN penalties from Wounded Levels equal to your Honor Rank, or twice your Honor Rank while in the Full Attack Stance."},{"id":"lion_the_lions_victory","nome":"The Lion's Victory","rank":5,"descricao":"The death of an opponent is the only measure of victory for a Matsu. Once per encounter after you roll damage for an attack, you may spend a Void Point as a Free Action to activate this Technique. You rend the opponent, ripping open his wounds and dealing grievous injury to him. All of the dice you choose to keep explode, re-rolling and adding the result to your damage total."}]},{"id":"lion_the_lions_pride","clanId":"lion","nome":"The Lion's Pride","traco":"","honra":"","tags":["bushi","lion_bushi","advanced","lion_advanced"],"pericias":[],"tecnicas":[{"id":"lion_the_fury_of_matsu","nome":"The Fury Of Matsu","rank":1,"descricao":"The Lion's Pride bushi's attacks leave no room for counterattack, serving as the perfect defense. You may add +10 to your Armor TN while in the Full Attack Stance."},{"id":"lion_paragon_of_honor","nome":"Paragon Of Honor","rank":2,"descricao":"The Lion's Pride warrior knows that her devotion to her personal honor is its own reward. Opponents with lower Honor Rank within 30' may not reroll 10's. Opponents may ignore this effect for the encounter by spending 2 Void Points during the Reactions Stage of any Combat Round."},{"id":"lion_matsus_technique","nome":"Matsu's Technique","rank":3,"descricao":"Even in the middle of her attacks, the Lion's Pride bushi is ready to counter any feeble attempts to strike her. When an opponent declares a melee attack against you, if you have not taken your Turn this Round, you may immediately spend a Void Point to take a Simple Action to make an attack against that Opponent. This attack resolves before your opponent's attack. If you use this Technique, you may only perform one Simple Action during your Turn this Round. (You may take Free Actions as normal.) You may use this Technique while in the Full Attack Stance."}]},{"id":"mantis_yoritomo_bushi_school","clanId":"mantis","nome":"Yoritomo Bushi School","traco":"strength","honra":"3.5","tags":["bushi","mantis_bushi"],"pericias":[{"id":"commerce","rank":1,"enfase":""},{"id":"defense","rank":1,"enfase":""},{"id":"jiujutsu","rank":1,"enfase":"Improvised Weapons"},{"id":"kenjutsu","rank":1,"enfase":""},{"id":"knives","rank":1,"enfase":"Kama"},{"id":"sailing","rank":1,"enfase":""}],"tecnicas":[{"id":"mantis_the_way_of_the_mantis","nome":"The Way Of The Mantis","rank":1,"descricao":"Mantis bushi learn to fight on the pitching decks of ships and to use anything within reach as a weapon. You suffer no penalties to movement or attacks for rough or uneven terrain. You do not lose Glory or Honor when using improvised weapons, or weapons with the Peasant keyword, in combat. You suffer no penalties for fighting with a Small or Medium weapon in your off-hand if that weapon has the Peasant keyword. finally, you gain a bonus of +1k0 to all attack rolls."},{"id":"mantis_voice_of_the_storm","nome":"Voice Of The Storm","rank":2,"descricao":"Your wild, unfettered attacks disorient your opponent and opens holes in his defenses. Every time you hit an opponent in melee, his Armor TN is reduced by 5. This penalty only applies to your attacks, and lasts for 2 Rounds. This Technique is cumulative (a number of times equal to your School Rank), and the duration resets with each application."},{"id":"mantis_strike_of_the_mantis","nome":"Strike Of The Mantis","rank":3,"descricao":"A Yoritomo strikes as swiftly as the storm. You may make attacks as a Simple Action instead of a Complex Action while using weapons with the Samurai or Peasant keyword."},{"id":"mantis_the_rolling_wave","nome":"The Rolling Wave","rank":4,"descricao":"The Yoritomo Bushi reacts with the flow of combat, deftly dodging blows while reaching his target. If you move at least 5 feet, you gain a bonus of +10 to your Armor TN until your next Turn. You may sacrifice this bonus during your Turn before you roll any attack to gain two Free Raises that may only be used to perform the Knockdown Maneuver."},{"id":"mantis_hand_of_osanowo","nome":"Hand Of Osano-Wo","rank":5,"descricao":"The Yoritomo Bushi strikes with brutal force, digging his weapons deep into his target. You may choose to activate this Technique by spending a Void Point as a Free Action. You keep an additional number of damage dice equal to your Strength. If these attacks hit a Prone target, you gain a bonus of +0k2 to the total of your damage rolls against that target."}]},{"id":"mantis_moshi_shugenja_school","clanId":"mantis","nome":"Moshi Shugenja School","traco":"awareness","honra":"4.5","tags":["shugenja","mantis_shugenja"],"pericias":[{"id":"calligraphy","rank":1,"enfase":"Cipher"},{"id":"divination","rank":1,"enfase":""},{"id":"lore_theology","rank":1,"enfase":""},{"id":"meditation","rank":1,"enfase":""},{"id":"spellcraft","rank":1,"enfase":""}],"tecnicas":[{"id":"mantis_favor_of_the_sun","nome":"Favor of the Sun","rank":1,"descricao":"No family has been more reverent of the various incarnations of the Sun throughout their history, and their piety has granted them great favor with the Heavens. During the day, you gain an additional Affinity for Fire spells. This benefit is lost at night. You also gain a Free Raise on any spell with the Thunder keyword. Spells: Sense, Commune, Summon, 3 Air and 3 Fire spells"}]},{"id":"mantis_yoritomo_courtier_school","clanId":"mantis","nome":"Yoritomo Courtier School","traco":"willpower","honra":"2.5","tags":["courtier","mantis_courtier"],"pericias":[{"id":"commerce","rank":1,"enfase":"Appraisal"},{"id":"courtier","rank":1,"enfase":""},{"id":"defense","rank":1,"enfase":""},{"id":"etiquette","rank":1,"enfase":""},{"id":"intimidation","rank":1,"enfase":"Control"},{"id":"sincerity","rank":1,"enfase":""}],"tecnicas":[{"id":"mantis_duty_before_honor","nome":"Duty Before Honor","rank":1,"descricao":"Like the Yasuki, the Mantis Courtiers are merchants as well as diplomats, and they cultivate a personal style built around intimidation rather than friendship. Futhermore, they spend much of their lives outside of the courts dealing with some of the more unsavory characters in Rokugan. You do not lose Glory or Honor for using the Commerce Skill in public, and you do not lose Honor for using the Intimidation (Control) skill. Any time you are making Social Skill Rolls against ronin, bandits, gang members, mercenaries, pirates, and other lawless types, you gain a number of Free Raises equal to your School Rank."},{"id":"mantis_storm_heart","nome":"Storm Heart","rank":2,"descricao":"When the time comes to act in courts, the Yoritomo eschew the eloquent words of the Doji or the subtle gibes of the Scorpion in favor of straightforward bullying, browbeating friend and foe alike into accepting their position. When you use the Intimidation (Control) Skill, your Willpower is considered to be one Rank higher. When you use the Intimidation (Control) skill against a samurai with lower Status Rank than you, your Willpower is considered two Ranks higher instead."},{"id":"mantis_command_the_winds","nome":"Command The Winds","rank":3,"descricao":"The Mantis are taught to put the force of their boorish and aggressive behavior behind their words in court, making it difficult to tell whether they are lying or telling the truth. A number of times per session equal to your School rank, if you have failed a Sincerity Social Skill Roll, you may re-roll it as an Intimidation (Control) Social Skill Roll instead. You must take the result of the Intimidation roll."},{"id":"mantis_will_of_the_storm","nome":"Will Of The Storm","rank":4,"descricao":"An experienced Mantis has learned to shatter and demoralize his opponents in court with his mere presence. When initiating a conversation with someone, you may make a Contested roll of your Intimidation (Control) / Willpower against his Etiquette (Courtesy) / Willpower. If you win the roll, he cannot spend any Void points against you for the next hour. Also, during that time he suffers a -3k0 penalty to all Social Rolls made against you. (This Technique cannot be used again until its effect expires.)"},{"id":"mantis_strength_in_all_things","nome":"Strength In All Things","rank":5,"descricao":"At this Rank the Mantis courtier's iron willpower and threatening nature have reached perfection, allowing him to overcome all foes and to laugh in th eface of threats that would make even a Hida bushi turn pale. Any time you are attempting to use the Intimidation skill against someone else, or are rolling to resist an Intimidation or Temptation Skill roll or a Fear effect, you gain a bonus of +5k0 to the roll."}]},{"id":"mantis_tsuruchi_archer_school","clanId":"mantis","nome":"Tsuruchi Archer School","traco":"reflexes","honra":"3.5","tags":["bushi","mantis_bushi"],"pericias":[{"id":"athletics","rank":1,"enfase":""},{"id":"defense","rank":1,"enfase":""},{"id":"hunting","rank":1,"enfase":""},{"id":"investigation","rank":1,"enfase":""},{"id":"kyujutsu","rank":2,"enfase":"Yumi"}],"tecnicas":[{"id":"mantis_always_be_ready","nome":"Always Be Ready","rank":1,"descricao":"The Tsuruchi Archer must be prepared to fight against his foes with little warning. You gain a bonus of +1k0 to the total of all attack rolls using a bow. Additionally, you gain a bonus of +3 to your Initiative Score."},{"id":"mantis_the_arrow_knows_the_way","nome":"The Arrow Knows The Way","rank":2,"descricao":"A Tsuruchi must not aim, but simply allow the arrow to follow its own path. You gain one Free Raise that can only be used to make the Called Shot Maneuver. Additionally, you gain a bonus of +2k0 to the total of all damage rolls while using a bow."},{"id":"mantis_the_wasps_sting","nome":"The Wasp's Sting","rank":3,"descricao":"Tsuruchi's technique teaches its students uncanny speed. You may make attacks as a Simple Action instead of a Complex Action when using a bow."},{"id":"mantis_flight_of_nomind","nome":"Flight Of No-Mind","rank":4,"descricao":"The true archer does not concern himself with the arrow, but exists only to loose it. Once per skirmish, you may spend a Void Point as a Complex Action to shoot an arrow that knows exactly where it must go. This attack ignores all effects of armor, as well as any penalties from Wound Ranks or visibility. You may make Raises but you cannot perform the Extra Attack Maneuver for this attack. You may not shoot a target that is further than your bow's normal range with this Technique."},{"id":"mantis_tsuruchis_eye","nome":"Tsuruchi's Eye","rank":5,"descricao":"The final lesson of Tsuruchi is that there is nothing that cannot be felled by a single arrow. You may make a ranged attack as a Complex Action to gain a bonus of +4k1 to the total of both attack and damage rolls. You may not use this Technique in conjunction with Flight of No-Mind."}]},{"id":"mantis_kitsune_shugenja_school","clanId":"mantis","nome":"Kitsune Shugenja School","traco":"stamina","honra":"4.5","tags":["shugenja","mantis_shugenja"],"pericias":[{"id":"calligraphy","rank":1,"enfase":""},{"id":"defense","rank":1,"enfase":""},{"id":"hunting","rank":1,"enfase":""},{"id":"medicine","rank":1,"enfase":"Herbalism"},{"id":"meditation","rank":1,"enfase":""},{"id":"spellcraft","rank":1,"enfase":""}],"tecnicas":[{"id":"mantis_essence_of_chikushudo","nome":"Essence Of Chikushudo","rank":1,"descricao":"None in the Empire are closer to the ways of nature than the simple Kitsune who make the wilderness their home. You may use the Sense, Commune, and summon basic spells to affect the animal spirits of Chikushudo as well as kami (using Summon results in the appearance of a single animal spirit rather than a set amount of the elemental material). Animal spirits tend to be more direct than kami, and perceive things differently, but have just as little sense of why man does what he does. You gain a Free Raise on any nonSpells: Sense, Commune, Summon, 3 Earth, 2 Water, and 1 Fire"}]},{"id":"mantis_storm_riders","clanId":"mantis","nome":"Storm Riders","traco":"","honra":"","tags":["shugenja","mantis_shugenja","advanced","mantis_advanced"],"pericias":[],"tecnicas":[{"id":"mantis_strength_of_suitengu","nome":"Strength Of Suitengu","rank":1,"descricao":"The Storm Riders are at home on the seas, navigating with an ease envied by all who see them. Your Shugenja School Rank is considered one higher for purposes of casting Water spells. You may spend a Void Point to release a lightning bolt from your hands as a Complex Action. This bolt strikes one target within a range of 10' x our Water Ring. It rolls and keeps a number of damage dice equal to your Air Ring. You may expend spell slots to increase the damage of this bolt by +1k0 per spell slot expended, up to a maximum of your Storm Rider Rank."},{"id":"mantis_the_raging_ocean","nome":"The Raging Ocean","rank":2,"descricao":"The Storm Rider's connection to the ocean allows him to extend beyond his limits. Your Shugenja School Rank increases by one. You Water Ring is considered 2 ranks higher for purposes of determining the number of spells you may cast per day."},{"id":"mantis_child_of_osanowo","nome":"Child Of Osano-Wo","rank":3,"descricao":"The Storm Riders are the descendants of the Fortune of Fire and Thunder, and their blessings protect them from his domain. Your Shugenja School Rank is considered 1 higher for the purpose of casting Water spells. You may spend A Void Point as a Free Action to gain immunity to all spells possessing the Thunder keyword for 3 rounds. This ability only affects spells of Mastery Level 3 and lower."}]},{"id":"monkey_toku_bushi_school","clanId":"monkey","nome":"Toku Bushi School","traco":"willpower","honra":"5.5","tags":["bushi","monkey_bushi"],"pericias":[{"id":"athletics","rank":1,"enfase":""},{"id":"defense","rank":1,"enfase":""},{"id":"hunting","rank":1,"enfase":""},{"id":"investigation","rank":1,"enfase":"Search"},{"id":"kenjutsu","rank":1,"enfase":""},{"id":"lore_history","rank":1,"enfase":""}],"tecnicas":[{"id":"monkey_tokus_lesson","nome":"Toku's Lesson","rank":1,"descricao":"A Monkey Bushi will prevail, even in the face of the most difficult odds. You add +1k0 to all Skill Rolls with a TN of 25 or higher. (This includes attack rolls.) Additionally, all your Wound Penalties are reduced by an amount equal to your Willpower plus double your School Rank."},{"id":"monkey_the_strength_of_one_man","nome":"The Strength Of One Man","rank":2,"descricao":"As a member of a very small Minor Clan, the Toku bushi is accustomed to fighting against the odds. While facing multiple opponents or an enemy with a higher Insight Rank, you add +1k1 to your attack and damage rolls."},{"id":"monkey_courage_above_all","nome":"Courage Above All","rank":3,"descricao":"The Toku bushi calls on the courage of his Clan's founder to speed his own attacks. You may make melee attacks as a Simple Action instead of a Complex Action."},{"id":"monkey_forge_your_own_fate","nome":"Forge Your Own Fate","rank":4,"descricao":"The Toku Bushi learns to dodge the worst of any attack. You may spend a Void Point when suffering Wounds to force your opponent to drop his two highest dice from his damage roll, even if this would reduce the total amount of kept dice. This cannot reduce the damage roll to less than 1k1."},{"id":"monkey_fortune_favors_the_mortal_man","nome":"Fortune Favors The Mortal Man","rank":5,"descricao":"The Toku bushi earns his good blessings with his own sheer tenacity. Once per Round, you may spend a Void Point to reroll any roll. You add +2k1 to the new roll. You may choose to keep the new roll or your original roll."}]},{"id":"monks_four_temples_monk_school","clanId":"monks","nome":"Four Temples Monk School","traco":"awareness","honra":"6.5","tags":["monk","monks_monk","brotherhood","monks_brotherhood"],"pericias":[{"id":"courtier","rank":1,"enfase":""},{"id":"etiquette","rank":1,"enfase":""},{"id":"jiujutsu","rank":1,"enfase":""},{"id":"lore_theology","rank":1,"enfase":"Shintao"},{"id":"meditation","rank":1,"enfase":""}],"tecnicas":[{"id":"monks_soul_of_civility","nome":"Soul of Civility","rank":1,"descricao":"Brothers of the Four Temples are accustomed to interacting with extremely important visitors and receiving invitations to influential courts. When you spend a Void Point to augment a High Skill Roll or a Social Skill Roll, you gain +2k2 instead of the normal +1k1."}]},{"id":"monks_order_of_heroes_monk_school","clanId":"monks","nome":"Order of Heroes Monk School","traco":"perception","honra":"4.5","tags":["monk","monks_monk","brotherhood","monks_brotherhood"],"pericias":[{"id":"athletics","rank":1,"enfase":""},{"id":"defense","rank":1,"enfase":""},{"id":"jiujutsu","rank":1,"enfase":""},{"id":"lore_theology","rank":1,"enfase":"*any"},{"id":"meditation","rank":1,"enfase":""}],"tecnicas":[{"id":"monks_destinys_hand","nome":"Destiny's Hand","rank":1,"descricao":"The Order’s esoteric methods allow for the passage of chi from a monk to another without diffi culty. You may spend a Void Point as a Free Action to confer a bonus of +1k1 to any one roll this round by an ally who has not yet taken his Turn. You may not enhance a roll that cannot normally benefi t from Void Points (such as a damage roll, for instance)."}]},{"id":"shine_of_the_seven_thunders_monk_school","clanId":"monks","nome":"The Shrine Of The Seven Thunders Monk","traco":"stamina","honra":"4.5","tags":["monk","monks_monk","brotherhood","monks_brotherhood"],"pericias":[{"id":"athletics","rank":1,"enfase":""},{"id":"jiujutsu","rank":1,"enfase":""},{"id":"lore_theology","rank":1,"enfase":"Shintao"},{"id":"meditation","rank":1,"enfase":""}],"tecnicas":[{"id":"monks_walk_with_the_prophet","nome":"Walk with the Prophet","rank":1,"descricao":"Brothers of this shrine emphasize training in one element over all others. All three of your initial Kiho must be selected from the same element. Your Insight Rank is considered one higher for the purposes of meeting the Mastery Level of Kiho from this element."}]},{"id":"temple_of_the_kaimetsu_uo_monk_school","clanId":"monks","nome":"The Temple Of Kaimetsu-Uo","traco":"willpower","honra":"4.5","tags":["monk","monks_monk","brotherhood","monks_brotherhood"],"pericias":[{"id":"defense","rank":1,"enfase":""},{"id":"jiujutsu","rank":1,"enfase":""},{"id":"lore_theology","rank":1,"enfase":"Fortunes"},{"id":"meditation","rank":1,"enfase":""}],"tecnicas":[{"id":"monks_the_path_of_purity","nome":"The Path of Purity","rank":1,"descricao":"Your soul dwells in a place of wisdom and serenity, and your ire is diffi cult to arouse under any circumstances. When making a Contested Social Skill Roll initiated by your opponent, you may use any Ring in place of the normal Trait used (typically Awareness) for the purposes of that roll."}]},{"id":"monks_the_temple_of_osanowo_monk_school","clanId":"monks","nome":"The Temple of Osano-Wo Monk School","traco":"strength","honra":"4.5","tags":["monk","monks_monk","brotherhood","monks_brotherhood"],"pericias":[{"id":"battle","rank":1,"enfase":""},{"id":"jiujutsu","rank":2,"enfase":""},{"id":"lore_theology","rank":1,"enfase":"Fortunes"},{"id":"meditation","rank":1,"enfase":""}],"tecnicas":[{"id":"monks_the_hand_of_thunder","nome":"The Hand of Thunder","rank":1,"descricao":"The emphasis of the Thunderer’s monks on the purity of unarmed combat is obvious to all who encounter them. You gain a +0k1 bonus to all damage rolls stemming from unarmed attacks. This effect is cumulative with any other effects that allow you to roll or keep additional dice on unarmed damage."}]},{"id":"monks_the_temples_of_the_thousand_fortunes_monk_school","clanId":"monks","nome":"The Temples of the Thousand Fortunes Monk School","traco":"agility","honra":"4.5","tags":["monk","monks_monk","brotherhood","monks_brotherhood"],"pericias":[{"id":"jiujutsu","rank":1,"enfase":""},{"id":"lore_history","rank":1,"enfase":""},{"id":"lore_theology","rank":1,"enfase":"Fortunes"},{"id":"meditation","rank":1,"enfase":""}],"tecnicas":[{"id":"monks_the_thousand_forms","nome":"The Thousand Forms","rank":1,"descricao":"There is no limit to the variety of blessings bestowed upon the loyal members of the Brotherhood by their divine patrons. You begin the game knowing four Kiho, rather than the normal three possessed by all Brotherhood monk characters. These do not count against the additional Kiho you can purchase with Experience Points (which you may do as normal)."}]},{"id":"oriole_tsi_smith_school","clanId":"oriole","nome":"Tsi Smith School","traco":"intelligence","honra":"4.5","tags":["smith","oriole_smith"],"pericias":[{"id":"commerce","rank":1,"enfase":""},{"id":"defense","rank":1,"enfase":""}],"tecnicas":[{"id":"oriole_tools_of_the_fortunes","nome":"Tools of the Fortunes","rank":1,"descricao":"The Tsi Smith dedicates his life to reaching perfection in the heat of the furnace. All Craft Skills are considered School Skills for you for the purpose of effects that target School Skills. Whenever you make a Craft Skill Roll, you gain one point of Glory for succeeding, and one additional point for every increment of 5 by which you exceed the TN. This effect only applies to rolls made against a TN equal to 10 plus your School Rank x 5 or higher."},{"id":"oriole_tsi_xings_guos_blessing","nome":"Tsi Xings Guo's Blessing","rank":2,"descricao":"The Oriole smith seeks to emulate the works of the Fortune of Steel. When wielding or using one of your own creations (such as a weapon in battle or wearing an elaborate kimono in court), you gain a bonus of +2k1 for Void Points spent on relevant Skill Rolls, rather than the usual +1k1. Additionally, when an item you created is given as a gift among members of the samurai caste, both you and the gift-giver gain Glory equal to your School Rank."},{"id":"oriole_a_crafters_dedication","nome":"A Crafter's Dedication","rank":3,"descricao":"A Tsi Smith knows the worth of everything he creates, years after it has left his forge. When crafting, the price of the object you are creating is reduced by half for the purposes of determining how long it takes to create the object in question. When someone in your presence is using an item you created, you may take a Complex Action to grant them a bonus of +xk1, where X is your School Rank, on the relevant Skill Roll (for example, Kenjutsu for a katana, Defense for armor, or Etiquette for a kimono)."},{"id":"oriole_exhaustive_knowledge","nome":"Exhaustive Knowledge","rank":4,"descricao":"All members of the Tsi smiths are expected to test their own creations for weight, balance, and effectiveness. You may spend a Void Point as a Free Action to allow you to make any attacks with a weapon you created as Simple Actions rather than Complex Actions. This effect lasts for a number of Rounds equal to your School Rank."},{"id":"oriole_starfilled_steel","nome":"Star-Filled Steel","rank":5,"descricao":"Oriole-made items are rivaled only by the masterful items of the Kaiu Forge. Once per day upon the completion of crafting a weapon, you may spend all your Void Points in order to create a Sacred Weapon (as per the Advantage). this weapon is known as a Tsi Weapon (e.g., a Tsi Blade, Tsi Tetsubo, etc.), and may possess one of the following qualities: Balanced (the wielder gains a bonus of +1k0 on attack rolls made with this weapon), Swift (The wielder gains a bonus of +5 to his Initiative Score while wielding the weapon, or Unbreakable (the weapon may not be broken). At the GM's option, a truly gifted Tsi smith may also be able to make a weapon Radiant (treat the weapon as jade for purposes of harming Invulnerable creatures)."}]},{"id":"ox_morito_bushi_school","clanId":"ox","nome":"Morito Bushi School","traco":"agility","honra":"3.5","tags":["bushi","ox_bushi"],"pericias":[{"id":"defense","rank":1,"enfase":""},{"id":"horsemanship","rank":1,"enfase":""},{"id":"hunting","rank":1,"enfase":"Tracking"},{"id":"kenjutsu","rank":1,"enfase":""},{"id":"lore_kolat","rank":1,"enfase":""},{"id":"lore_underworld","rank":1,"enfase":""}],"tecnicas":[{"id":"ox_legacy_of_the_four_winds","nome":"Legacy Of The Four Winds","rank":1,"descricao":"The Ox warrior fights as one with his horse. At the beginning of combat, you may add +1k0 to your Initiative if you are Mounted. Additionally, you may add +1k0 to attack rolls while mounted."},{"id":"ox_the_wind_blows_many_ways","nome":"The Wind Blows Many Ways","rank":2,"descricao":"A Morito bushi becomes adept in all facets of war. At the beginning of combat, you may declare a number of Bugei Skills equal to your School Rank. You add +1k0 to all rolls involving the chosen Skills."},{"id":"ox_thunder_and_fury","nome":"Thunder And Fury","rank":3,"descricao":"The Morito bushi strikes with the speed of his charging horse. You may make attacks as a Simple Action instead of a Complex Action while Mounted."},{"id":"ox_the_blade_upon_the_wind","nome":"The Blade Upon The Wind","rank":4,"descricao":"The Morito bushi can rush forward, moving faster than any of his foes can anticipate. Once per skirmish, you may spend a Void Point as a Free Action to set your Initative Score equal to that of another participant in the battle. This may be either an ally or opponent. However, after you use this Technique, your Initiative Score is reduced by 5 during the Reactions Stage of each Round until the end of the encounter. You may only have one Turn per Round, even if your Initiative Score drops below your current Initiative Score."},{"id":"ox_fast_and_furious","nome":"Fast And Furious","rank":5,"descricao":"The Morito bushi rides into battle, trampling those who cannot escape his path. while you are attacking an opponent with lower Initiative, you add +2k2 to all attacks and damage rolls."}]},{"id":"phoenix_shiba_bushi_school","clanId":"phoenix","nome":"Shiba Bushi School","traco":"agility","honra":"5.5","tags":["bushi","phoenix_bushi"],"pericias":[{"id":"defense","rank":1,"enfase":""},{"id":"kenjutsu","rank":1,"enfase":""},{"id":"kyujutsu","rank":1,"enfase":""},{"id":"lore_theology","rank":1,"enfase":""},{"id":"meditation","rank":1,"enfase":"Void Recovery"},{"id":"spears","rank":1,"enfase":""}],"tecnicas":[{"id":"phoenix_the_way_of_the_phoenix","nome":"The Way Of The Phoenix","rank":1,"descricao":"Shiba bushi move through battle as the Void moves through all the elements. When spending a Void Point to gain +1k1 on a roll, you may choose to spend 2 Void Points (to gain +2k2) on the roll instead. You may Guard as a Free Action; however, if you do so, your target only adds +5 to his Armor TN instead of +10."},{"id":"phoenix_dancing_with_the_elements","nome":"Dancing With The Elements","rank":2,"descricao":"Shiba bushi become attuned to the shugenja they protect, aiding their spells and deterring those of their enemies. When you assume your Stance for the Round, you may choose a target within 30'. Whenever your target casts or is the target of a spell, you may choose to increase or decrease the TN of the spell by 5. Additionally, whenever you are the target of a spell, you may immediately choose to increase or decrease the TN of the spell by 5."},{"id":"phoenix_one_with_the_void","nome":"One With The Void","rank":3,"descricao":"In battle, the Shiba can find his place in the world. This Technique automatically activates during the Reaction Stafe of Combat if another character spent a Void Point during this Combat Round. You regain a Void Point. This Void Point may exceed your maximum, but all excess Void Points are lost after combat resolves. You do not learn anything regarding the source of the Void Point or how it was originally spent. this Technique only activates twice per skirmish."},{"id":"phoenix_move_with_the_world","nome":"Move With The World","rank":4,"descricao":"Serenity brings certainty, and certainty brings speed. You may make attacks as a Simple Action instead of a Complex Action with using Polearms, Spears, or weapons with the Samurai keyword."},{"id":"phoenix_touch_of_the_void","nome":"Touch Of The Void","rank":5,"descricao":"Masters of the Shiba style can draw back the veil and allow the universe to act through them. For every Void Point you spend, you gain the effects of spending two, when applicable. Additionally, you may now spend Void Pionts on enhancements twice in one Turn."}]},{"id":"phoenix_isawa_shugenja_school","clanId":"phoenix","nome":"Isawa Shugenja School","traco":"intelligence","honra":"4.5","tags":["shugenja","phoenix_shugenja"],"pericias":[{"id":"calligraphy","rank":1,"enfase":"Cipher"},{"id":"lore_theology","rank":1,"enfase":""},{"id":"medicine","rank":1,"enfase":""},{"id":"meditation","rank":1,"enfase":""},{"id":"spellcraft","rank":1,"enfase":""}],"tecnicas":[{"id":"phoenix_isawas_gift","nome":"Isawa's Gift","rank":1,"descricao":"There are no greater masters of the shugenja tradition than those among the Isawa. You gain a Free Raise on all Spell Casting Rolls for spells of the element which you chose as your Affinity. Spells: Sense, Commune, Summon, 3 spells of any one element, 2 spells of any other element, 1 spell of a third element, and 1 spell of a fourth element."}]},{"id":"phoenix_asako_loremaster_school","clanId":"phoenix","nome":"Asako Loremaster School","traco":"intelligence","honra":"6.5","tags":["courtier","phoenix_courtier"],"pericias":[{"id":"courtier","rank":1,"enfase":""},{"id":"etiquette","rank":1,"enfase":"Courtesy"},{"id":"lore_history","rank":1,"enfase":""},{"id":"lore_theology","rank":1,"enfase":"Fortunes"},{"id":"meditation","rank":1,"enfase":""},{"id":"sincerity","rank":1,"enfase":""}],"tecnicas":[{"id":"phoenix_temple_of_the_soul","nome":"Temple Of The Soul","rank":1,"descricao":"The Asako are historians and scholars, and their studies are broader than those of any others in the Empire. They pride themselves on the depth of their knowledge in all fields of intellectual endeavor. They also share the Phoenix devotion to peace and civility, relying on genteel discourse to resolve problems. You gain a Free Raise on any Skill Roll with a Lore Skill. Any time you spend a Void Point on an Etiquette Skill Roll, you gain a bonus of +3k1 to the total of the roll instead of the normal +1k1."},{"id":"phoenix_from_the_ashes","nome":"From The Ashes","rank":2,"descricao":"The Asako Loremasters' in-depty study of historical events allows them to detect subtle patterns in behavior in every court, patterns invisible to their more worldly rivals from the other Clans. After spending at least one day observing the events in a particular court, you can roll Lore: History / Perception at TN 20 to gain a bonus +2k0 to the total of all your Social Skill Rolls for the next two days, so long as your remain in that court. (This Technique's effect can be re-activated with another skill roll when it expires - it is not necessary to spend additional days observing so long as you remain in the same court.)"},{"id":"phoenix_voice_of_the_universe","nome":"Voice Of The Universe","rank":3,"descricao":"As the Asako's training progresses, his recall of obscure historical facts allows him to provide useful contemporary advice to his allies. You may spend an hour conversing with a friend or ally and then roll Lore: History / Intelligence at TN 25. With a success, that ally may add your Lore: History Skill Rank to the total of any Social Skill Rolls he makes within the next twenty-four hours. You may Raise twice to affect one (and only one) additional ally, provided that ally also participates in the conversation. (This Technique cannot be used on the same person again until its effect expires.)"},{"id":"phoenix_invincible_mind","nome":"Invincible Mind","rank":4,"descricao":"The enlightened and educated Asako can see through the games, tricks, and deceits of the material world. Any time you fail a Contested Social Skill Roll to resist someoen trying to influence your emotions, opinions, or behavior (such as with the Courtier, Temptation, or Intimidation skills), you may re-roll using Intelligence as the Trait for the second roll in place of whichever Trait was originally required. You must keep the result of the second roll. This Technique cannot be used to resist Fear."},{"id":"phoenix_wisdom_of_the_ages","nome":"Wisdom Of The Ages","rank":5,"descricao":"At this rank, the Asako truly demonstrate that the wisdom of the Phoenix is eternal. Any time you are rolling a Lore Skill, including for your other School Techniques, you gain a +5k0 bonus to the total of the roll."}]},{"id":"phoenix_agasha_shugenja_school","clanId":"phoenix","nome":"Agasha Shugenja School","traco":"intelligence","honra":"4.5","tags":["shugenja","phoenix_shugenja"],"pericias":[{"id":"calligraphy","rank":1,"enfase":"Cipher"},{"id":"defense","rank":1,"enfase":""},{"id":"etiquette","rank":1,"enfase":""},{"id":"lore_theology","rank":1,"enfase":""},{"id":"spellcraft","rank":1,"enfase":""}],"tecnicas":[{"id":"phoenix_elements_of_all_thing","nome":"Elements of All Thing","rank":1,"descricao":"The Agasha understand the interactions of the elements more so than perhaps any other family. When casting a spell, you may spend a Void Point to use a different Ring of your choosing rather than the appropriate Ring for that spell. this spell uses a spell slot for the Ring used to actuall cast the spell. You also gain a Free Raise on any spell with the Craft keyword."}]},{"id":"ronin_disciples_of_sun_tao","clanId":"ronin","nome":"Disciples of Sun Tao","traco":"reflexes","honra":"4.5","tags":["bushi","ronin","ronin_bushi"],"pericias":[{"id":"athletics","rank":1,"enfase":""},{"id":"defense","rank":1,"enfase":""},{"id":"hunting","rank":1,"enfase":""},{"id":"iaijutsu","rank":1,"enfase":""},{"id":"kenjutsu","rank":1,"enfase":""}],"tecnicas":[{"id":"ronin_gaze_of_sun_tao","nome":"Gaze of Sun Tao","rank":1,"descricao":"Students of Sun Tao understand the relationship between honor and skill. You may add your Honor Rank to the total of all Iaijutsu Skill Rolls."}]},{"id":"ronin_forest_killers","clanId":"ronin","nome":"Forest Killers","traco":"agility","honra":"1.5","tags":["bushi","ronin","ronin_bushi"],"pericias":[{"id":"athletics","rank":1,"enfase":""},{"id":"defense","rank":1,"enfase":""},{"id":"hunting","rank":1,"enfase":""},{"id":"kenjutsu","rank":1,"enfase":""},{"id":"kyujutsu","rank":1,"enfase":""},{"id":"stealth","rank":1,"enfase":""}],"tecnicas":[{"id":"ronin_strength_of_the_forest","nome":"Strength Of The Forest","rank":1,"descricao":"The Forest Killers are a formidable group who recruit only the toughest and most durable of warriors to join their band. You gain additional Wounds per Wound Rank equal to your Stamina. You may also add your Stamina to the total of all damage rolls resulting from melee attacks."}]},{"id":"ronin_tawagotos_army","clanId":"ronin","nome":"Tawagoto's Army","traco":"agility","honra":"4.5","tags":["bushi","ronin","ronin_bushi"],"pericias":[{"id":"battle","rank":1,"enfase":""},{"id":"defense","rank":1,"enfase":""},{"id":"etiquette","rank":1,"enfase":""},{"id":"investigation","rank":1,"enfase":""},{"id":"kenjutsu","rank":1,"enfase":""},{"id":"spears","rank":1,"enfase":""}],"tecnicas":[{"id":"ronin_the_peoples_will","nome":"The People's Will","rank":1,"descricao":"Those who are guided by honor carry the strength of the Empire’s people in their actions. When you spend a Void Point to add a bonus of +1k1 to any Skill or Trait Roll, you may also add your Honor Rank to the total of that roll."}]},{"id":"ronin_tengokus_justice","clanId":"ronin","nome":"Tengoku's Justice","traco":"strength","honra":"4.5","tags":["bushi","ronin","ronin_bushi"],"pericias":[],"tecnicas":[{"id":"ronin_heavens_curse","nome":"Heaven's Curse","rank":1,"descricao":"The sheer ruthless, murderous nature of the Tengoku’s Justice fighting style could rival even that of the Forest Killers. Whenever you surprise an opponent in a skirmish, you may double your Strength for the purposes of determining how many damage dice you roll on that attack."}]},{"id":"ronin_the_tessen","clanId":"ronin","nome":"The Tessen","traco":"stamina","honra":"3.5","tags":["bushi","ronin","ronin_bushi"],"pericias":[{"id":"battle","rank":1,"enfase":""},{"id":"defense","rank":1,"enfase":""},{"id":"investigation","rank":1,"enfase":""},{"id":"jiujutsu","rank":1,"enfase":""},{"id":"war_fan","rank":1,"enfase":""}],"tecnicas":[{"id":"ronin_folds_of_the_iron_fan","nome":"Folds Of The Iron Fan","rank":1,"descricao":"Few in Rokugan have mastered the facets of the iron fan with the same fluency as the Tessen. When wielding a war fan in your off hand, you suffer no penalties for attacks made with that hand. You also add your rank in War Fans to the total of your Armor TN at all times while wielding a war fan."}]},{"id":"scorpion_bayushi_bushi_school","clanId":"scorpion","nome":"Bayushi Bushi School","traco":"intelligence","honra":"2.5","tags":["bushi","scorpion_bushi"],"pericias":[{"id":"courtier","rank":1,"enfase":"Manipulation"},{"id":"defense","rank":1,"enfase":""},{"id":"etiquette","rank":1,"enfase":""},{"id":"iaijutsu","rank":1,"enfase":""},{"id":"kenjutsu","rank":1,"enfase":""},{"id":"sincerity","rank":1,"enfase":""}],"tecnicas":[{"id":"scorpion_the_way_of_the_scorpion","nome":"The Way Of The Scorpion","rank":1,"descricao":"Scorpion bushi always seem to get the jump on opponents. You gain a bonus +1k1 to your Initiative Rolls. You also gain a bonus of +5 to your Armor TN against any opponent with lower Initiative."},{"id":"scorpion_pincers_and_tail","nome":"Pincers And Tail","rank":2,"descricao":"The infamous Scorpion feint has been the demise of many foolhardly samurai. You may make the Feint Maneuver for one Raise instead of two."},{"id":"scorpion_strike_at_the_tail","nome":"Strike At The Tail","rank":3,"descricao":"Scorpion bushi strive to keep their enemies off guard, stopping their attacks and slowing them down. When you assume a Stance at the start of your Turn, you may choose a target within 30'. If you successfully hit him during your Turn, the target is Fatigued as if he had gone without rest for 24 hours. During the Reaction Stage, an affected opponent may attempt an Earth Ring roll against a TN of 25 to negate the effects of this Technique. If he fails, the effects of this Technique end during the next Reactions Stage (the second Reactions Stage after he was struck)."},{"id":"scorpion_strike_from_above_strike_from_below","nome":"Strike From Above, Strike From Below","rank":4,"descricao":"The swiftness of the Scorpion allows him to cut down foes before they realize they have been attacked. You may make melee attacks as a Simple Action instead of a Complex Action."},{"id":"scorpion_the_pincers_hold_the_tail_strikes","nome":"The Pincers Hold, The Tail Strikes","rank":5,"descricao":"Striking an opponent's weakest point is the Scorpion's true path to victory. Once per encounter, you may spend a Void Point as a Complex Action to attack your opponent with a melee weapon. If the attack is successful, the target is Stunned. During the Reactions Stage, an affected opponent may attempt an Earth Ring roll against at TN equal to the amount of damage dealt to end the Stun effect. If he fails or does not attempt this roll, the Stun effect ends during the next Reactions Stage (the second Reaction Stage after he was struck)."}]},{"id":"scorpion_soshi_shugenja_school","clanId":"scorpion","nome":"Soshi Shugenja School","traco":"awareness","honra":"2.5","tags":["shugenja","scorpion_shugenja"],"pericias":[{"id":"calligraphy","rank":1,"enfase":"Cipher"},{"id":"courtier","rank":1,"enfase":""},{"id":"etiquette","rank":1,"enfase":""},{"id":"lore_theology","rank":1,"enfase":""},{"id":"spellcraft","rank":1,"enfase":""},{"id":"stealth","rank":1,"enfase":""}],"tecnicas":[{"id":"scorpion_the_kamis_whisper","nome":"The Kami's Whisper","rank":1,"descricao":"The Soshi cast their spells as quietly as the kami themselves. You may sacrifice an additional spell slot (of the same Element) when casting any spell with no potential to inflict damage in order to eliminate all visible signs of the spell having been cast. All spell effects take place normally; there is simply no outward sign of what has happened. You also gain a Free Raise on any spell with the Illusion keyword. Spells: Sense, Commune, Summon, 3 Air, 2 Fire, and 1 Water"}]},{"id":"scorpion_bayushi_courtier_school","clanId":"scorpion","nome":"Bayushi Courtier School","traco":"awareness","honra":"2.5","tags":["courtier","scorpion_courtier"],"pericias":[{"id":"calligraphy","rank":1,"enfase":""},{"id":"courtier","rank":1,"enfase":"Gossip"},{"id":"etiquette","rank":1,"enfase":""},{"id":"investigation","rank":1,"enfase":""},{"id":"sincerity","rank":1,"enfase":"Deceit"},{"id":"temptation","rank":1,"enfase":""}],"tecnicas":[{"id":"scorpion_weakness_is_my_strength","nome":"Weakness Is My Strength","rank":1,"descricao":"The Bayushi are masters of ferreting out and exploiting the weaknesses and failures of others. Even if they do not know the exact nature of a rival's secrets, there mere realization that he has some sort of secret is enough for them to work with. When you are making a Contested Social Roll against someoen else, you gain a Free Raise to your roll for every 3 points of Mental or Social Disadvantages (rounded off) he possesses. Disadvantages which did not award Experience Pionts still count for their normal point value for the purposes of this Technique. This technique cannot award more than 5 Free Raises. The Bayushi are also known as the masters of both truth and lies, speaking so smoothly that both are indistinguishable in their mouths. You gain a Free Raise when using the Courtier skill to spread gossip, and need not Raise in order to conceal that you are the source of that gossip."},{"id":"scorpion_shallow_waters","nome":"Shallow Waters","rank":2,"descricao":"The Scorpion know how to assess others, sensing their weaknesses so as to determine how best to bring them down. By conversing with someone for a few minutes, you can make a Contested Roll of your Investigation / Awareness against their Etiquette / Awareness. With a success, you learn the identity and rank of their lowerst Mental and their lowest social Skill that has at least one Rank (The GM chooses in the case of ties). You may spend a Void point to also learn their next lowest Mental Trait and next lowest Social Skill."},{"id":"scorpion_secrets_are_birthmarks","nome":"Secrets Are Birthmarks","rank":3,"descricao":"At this rank, the Scorpion has become so adept at ferreting out secrets that he can lure others in revealing them in casual conversation. By speaking with someone for a few minutes, you may make a Contested Roll of your Courtier (Manipulation) / Awareness against their Etiquette (Courtesy) / Awareness to force them into revealing one Mental or Social Disadvantage they possess. If they have no such Disadvantage, this will instead reveal one Mental or Social Advantage. (Note this will only reveal the rulebook title of the Advantage / Disadvantage, not the specific nature of it. For example, you might learn that the target has \"Dark Secret,\" but not the specific nature of the secret.) If the roll succeeded in revealing a Disadvantage, with the GM's permission you may take a 2-point Blackmail Advantage against this individual, for no cost in Experience Points."},{"id":"scorpion_scrutinys_sweet_sting","nome":"Scrutiny'S Sweet Sting","rank":4,"descricao":"At this rank, the Bayushi Courtier has learned to use all the information he has collected to subtly wreck his enemies, undermining their every word and deed. Any time you make a Contested Social Skill Roll against someone on whom you have Blackmail, his dice cannot explode. In addition, any time you make a Contested Social Skill Roll against someone, regardless of whether you have Blackmail on them or not, you may spend a Void Point to foce them to use a mental Trait of your choice (instead of the normal Trait used for the roll)."},{"id":"scorpion_no_more_masks","nome":"No More Masks","rank":5,"descricao":"The final lesson of the Bayushi School is to force the rest of the court to see the corrupt, dishonorable world he knows, shattering the reputations of those he speaks against. A number of times per session equal to your School Rank, you may make an Opposed Social Roll of Courtier (Gossip) / Awareness against an opponent's Etiquette (Courtesy) / Awareness. If you have Blackmail on the person you are targeting with his technique, you gain a bonus of +5k0 to the total of this roll. With a success, you may inflict one Social Disadvantage on the target: Bad Reputation, Sworn Enemy, or Obligation (to someone of your choice). The Disadvantage lasts for one month, unless the GM judges that the target has taken action which can expunge it sooner. (This Technique cannot be used on the same target until its effect expires.)"}]},{"id":"scorpion_shosuro_infiltrator_school","clanId":"scorpion","nome":"Shosuro Infiltrator School","traco":"reflexes","honra":"1.5","tags":["ninja","scorpion_ninja"],"pericias":[{"id":"acting","rank":1,"enfase":""},{"id":"athletics","rank":1,"enfase":""},{"id":"ninjutsu","rank":1,"enfase":""},{"id":"sincerity","rank":1,"enfase":""},{"id":"stealth","rank":2,"enfase":"Sneaking"}],"tecnicas":[{"id":"scorpion_the_path_of_shadows","nome":"The Path Of Shadows","rank":1,"descricao":"The first lesson of an infiltrator is to mask all signs of one's true nature. You lose no Honor for use of Low Skills or Ninjutsu Weapons in the service of the Scorpion Clan (subject to GM approval). You gain a bonus of +2k0 to the total of all Stealth Skill rolls."},{"id":"scorpion_strike_from_darkness","nome":"Strike From Darkness","rank":2,"descricao":"A student of the Shosuro Techniques never fails to exploit any advantage held over a foe. Whenever you declare an attack against an opponent who is unaware of your presence until the moment of the attack, your Raises are not limited to your Void and you roll additional dice equal to your School Rank on the attack roll. You also roll half this number of additional unkept dice on an attack roll made against an opponent who is suffering from a Condition effect (such as Stunned or Fatigued). These two effects are not cumulative, and if both could apply, you must choose one of them. (You do not add one and one half times your School Rank in dice to an attack roll against an opponent who is both Blinded and unaware of your presence, for example.)"},{"id":"scorpion_steel_within_silk","nome":"Steel Within Silk","rank":3,"descricao":"Striking quickly and effectively is the hallmark of a true shadow warrior. When attacking from ambush as described above, or when using ninjutsu weapons (including any weapons with the Ninja keyword), you may make a melee attack (or ranged attack, in the case of shuriken or tsubute) as a Simple Action rather than a Complex Action."},{"id":"scorpion_whisper_of_steel","nome":"Whisper Of Steel","rank":4,"descricao":"A master assassin strikes from shadow without ever revealing his presence. Even after attacking a target, your opponents and bystanders must succeed at a Contested Roll using Investigation (Notice) / Perception against Stealth / Agility to detect you. You may only use this Technique if you make a single attack per round. (The GM may rule that this technique does not work in situations where concealment is impossible.)"},{"id":"scorpion_the_final_silence","nome":"The Final Silence","rank":5,"descricao":"The true assassin requires but a single strike. After you make a damage roll as a result of a successful attack, you may spend a Void Point to increase any two dice to show 10s. These 10s do not explode. You may spend multiple Void Points in this manner, with each Void Point spent increasing the result of up to two damage dice."}]},{"id":"snake_chuda_shugenja_school","clanId":"snake","nome":"Chuda Shugenja School","traco":"willpower","honra":"4.5","tags":["shugenja","snake_shugenja"],"pericias":[{"id":"calligraphy","rank":1,"enfase":"Cipher"},{"id":"etiquette","rank":1,"enfase":""},{"id":"lore_maho","rank":1,"enfase":""},{"id":"lore_shadowlands","rank":1,"enfase":""},{"id":"spellcraft","rank":1,"enfase":""}],"tecnicas":[{"id":"snake_to_punish_the_wicked","nome":"To Punish The Wicked","rank":1,"descricao":"Isawa Chuda was a ruthless persecutor of the Shadowlands, and his techniques live on in those who bear his name. You may spend a Void Point as a Free Action to negate an amount of Reduction equal to your School Rank from one targeted opponent. You also add your School Rank to the total of any damage roll made by a spell you cast against a target who possesses the Shadowlands Taint."}]},{"id":"sparrow_suzume_bushi_school","clanId":"sparrow","nome":"Suzume Bushi School","traco":"willpower","honra":"6.5","tags":["bushi","sparrow_bushi"],"pericias":[{"id":"calligraphy","rank":1,"enfase":""},{"id":"kenjutsu","rank":1,"enfase":"Katana"},{"id":"lore_history","rank":1,"enfase":""},{"id":"lore_theology","rank":1,"enfase":""},{"id":"perform_storytelling","rank":1,"enfase":""}],"tecnicas":[{"id":"sparrow_all_things_in_time","nome":"All Things In Time","rank":1,"descricao":"The Suzume watches the flow of combat to discern the perfect time for assault. At the beginning of the Combat Round, before the first character has taken his Turn, you may reduce your Initiative by 5 to add +1k0 to all your attack and damage rolls for the Round."},{"id":"sparrow_purity_of_chi","nome":"Purity Of Chi","rank":2,"descricao":"The Suzume's body is filled with disdain for those who indulge in temptations away from the tenets of Bushido. You add +5 to your Armor TN against creatures and against human opponents with lower Honor."},{"id":"sparrow_wisdom_is_the_greatest_weapon","nome":"Wisdom Is The Greatest Weapon","rank":3,"descricao":"The Suzume is a masterful storyteller, captivating audiences with his words. You may spend a Void Point to add your Honor Rank to any Perform or Lore Skill Roll."},{"id":"sparrow_quiet_spirit_steady_blade","nome":"Quiet Spirit, Steady Blade","rank":4,"descricao":"The serenity of a Sparrow is often mistaken for complacency, but that is far from the case. You may make melee attacks as a Simple Action instead of a Complex Action while in the Attack Stance."},{"id":"sparrow_slow_and_deadly","nome":"Slow And Deadly","rank":5,"descricao":"The Suzume strikes when his foes least expect it, even if he must weather the worst of the opponents' attacks. During the Round following your adoption of the Center Stance, you add +10 to your attack and damage rolls. You do not gain this benefit during Iaijutsu duels."}]},{"id":"spider_daigotsu_bushi_school","clanId":"spider","nome":"Daigotsu Bushi School","traco":"strength","honra":"1.5","tags":["bushi","spider_bushi"],"pericias":[{"id":"hunting","rank":1,"enfase":""},{"id":"intimidation","rank":1,"enfase":""},{"id":"jiujutsu","rank":1,"enfase":""},{"id":"kenjutsu","rank":1,"enfase":"Katana"},{"id":"kyujutsu","rank":1,"enfase":""},{"id":"lore_shadowlands","rank":1,"enfase":""}],"tecnicas":[{"id":"spider_the_way_of_the_spider","nome":"The Way Of The Spider","rank":1,"descricao":"The Daigotsu Bushi must walk the fi ne line between using the Taint to power his body and hiding its effects in public. At the beginning of each Round, you may choose to either reduce TN penalties from Wound Ranks by your Strength Trait Rank plus your Taint Rank until the end of the Round, or increase your damage rolls by the same amount. Additionally, the TN on any roll made to detect the presence or effects of the Shadowlands Taint on you is increased by 10."},{"id":"spider_aura_of_blood","nome":"Aura Of Blood","rank":2,"descricao":"The presence of the Daigotsu Bushi can be unsettling to those who are unprepared to face it. You may spend a Void Point as a Simple Action to activate this Technique. While this Technique is active, you and all of your allies within 30’ add +2k0 to the total of all damage rolls. This lasts for a number of Rounds equal to your Taint Rank plus your Strength Trait Rank. This bonus is not cumulative with other applications of Aura of Blood. Using this Technique while under its effects refreshes its duration."},{"id":"spider_ashuras_wing","nome":"Ashura's Wing","rank":3,"descricao":"The Daigotsu Bushi moves and strikes as swiftly as ash borne away by the wind. You may make melee attacks as a Simple Action instead of a Complex Action."},{"id":"spider_devouring_wrath","nome":"Devouring Wrath","rank":4,"descricao":"By the power of Fu Leng, the Legionnaire feeds on the strength of his enemies. Any time you hit an opponent in melee, you immediately regain 5 Wounds. This can potentially grant additional Wounds beyond your normal maximum, but this bonus will not increase over 20 Wounds. Excess Wounds are lost at the end of the skirmish."},{"id":"spider_inhuman_assault","nome":"Inhuman Assault","rank":5,"descricao":"The wrath of a Daigotsu bushi is like that of a rampaging beast. Once per skirmish, you may launch into a series of bone-shattering blows by making a melee attack as a Complex Action. This attack ignores the bonuses and effects of armor (including Reduction from armor) and any Stance the target assumes. If the strike hits, the target cannot gain the bonuses of armor or Stance to his Armor TN for a number of Rounds equal to your Taint Rank plus your Strength Trait. If your opponent is in the Full Attack Posture, he still retains the -10 Armor TN penalty."}]},{"id":"spider_chuda_shugenja_school","clanId":"spider","nome":"Chuda Shugenja School","traco":"willpower","honra":"0.5","tags":["shugenja","spider_shugenja"],"pericias":[{"id":"calligraphy","rank":1,"enfase":"Cipher"},{"id":"hunting","rank":1,"enfase":""},{"id":"lore_maho","rank":1,"enfase":""},{"id":"lore_shadowlands","rank":1,"enfase":""},{"id":"spellcraft","rank":1,"enfase":""},{"id":"stealth","rank":1,"enfase":""}],"tecnicas":[{"id":"spider_blood_like_water","nome":"Blood Like Water","rank":1,"descricao":"The Chuda have existed for centuries, hidden among the people of Rokugan and concealing the true nature of their dark arts. When casting a maho spell, you may declare one Raise to conceal the corrupted nature of the magic. The spell functions exactly as normal, but there will be no outward sign that it is anything other than traditional elemental magic. You may declare a second Raise to reduce all Shadowlands Taint normally acquired by a maho spell to only one Point, regardless of the spell’s Mastery level. Alternatively, you may sacrifi ce one point of Honor to reduce all Taint normally acquired by the spell to one Point."}]},{"id":"spider_daigotsu_courtier_school","clanId":"spider","nome":"Daigotsu Courtier School","traco":"perception","honra":"1","tags":["courtier","spider_courtier"],"pericias":[{"id":"acting","rank":1,"enfase":""},{"id":"courtier","rank":1,"enfase":"Manipulation"},{"id":"etiquette","rank":1,"enfase":""},{"id":"meditation","rank":1,"enfase":""},{"id":"sincerity","rank":1,"enfase":"Deceit"},{"id":"temptation","rank":1,"enfase":""}],"tecnicas":[{"id":"spider_insidious_whispers","nome":"Insidious Whispers","rank":1,"descricao":"Every student of the Daigotsu Courtiers is accomplished at the art of masking his nature, preventing his true intentions and capabilities from being discovered by others. You are skilled at hiding your intentions and the symptoms of Taint. You gain a Free Raise when using Sincerity (Deceit). Any rolls made to detect your Taint (such as the techniques of the Kuni) have their TN increased by an amount equal to 5 x your School Rank. You add your School Rank to your Honor Rank whenever another is attempting to discern your Honor Rank."},{"id":"spider_cracks_in_the_wall","nome":"Cracks In The Wall","rank":2,"descricao":"The Daigotsu courtier is taught to drop subtle, seemingly innocuous conversational hints that disrupt the focus and attention of those around him. Any time you are engaged in conversation, you may spend a Void point and make a Courtier (Manipulation) / Awareness roll (as a Simple Action) at TN 25 to force everyone within 20 feet of you to suffer a penalty of –1k1 to all their Etiquette and Perform Skill rolls for the next hour. They are not aware of the source for their lack of focus. This effect cannot be stacked."},{"id":"spider_darkness_cannot_be_trapped","nome":"Darkness Cannot Be Trapped","rank":3,"descricao":"At this rank, the Spider courtier is taught to defl ect attention and blame from himself, spreading disharmony among his foes while avoiding the price of his own actions. Any time you are the focus of suspicion or accusation, you may spend a Void point as a Simple Action to try to shift the blame to someone else who is present at the moment of the accusation. You must make a Contested Roll of your Sincerity (Deceit) / Awareness versus the victim’s Sincerity (Honesty) / Awareness in order to make the shifting of blame stick. (If your attempt seems weak or poorly justifi ed, the GM can award bonuses to your victim’s attempt to defend himself.) With a success, everyone who heard you will believe your target is the real culprit, until presented with evidence to the contrary. This technique cannot be used to get out of situations in which you are clearly and inescapably guilty (e.g. standing over the dead magistrate with a bloody knife in your hand), nor can it shift blame to someone who is not present."},{"id":"spider_the_touch_of_sin","nome":"The Touch Of Sin","rank":4,"descricao":"At this level of training, the Spider’s mastery of manipulation and misdirection allows his words to twist the thoughts of others, temporarily leading them into weakness, aggression, and confusion. A number of times per session equal to your School Rank, you may speak with someone for a few minutes and then make a Contested Roll of your Courtier (Manipulation) / Willpower against their Etiquette (Courtesy) / Willpower. If you succeed, they acquire one of the seven Consumed by Shourido Disadvantages (your choice) for a number of hours equal to your School Rank. By calling two successful Raises on this roll, you can infl ict a second Consumed by Shourido Disadvantage of your choice on the same person for the same period of time. (You cannot use this technique on the same person twice in the same day.)"},{"id":"spider_the_embrace_of_darkness","nome":"The Embrace of Darkness","rank":5,"descricao":"The final lesson of the Daigotsu Courtier School teaches its students to lead their enemies into paths of aggression and violence. By speaking with someone for at least fi fteen minutes, you may make a Contested Roll of your Sincerity (Deceit) / Awareness against their Etiquette (Courtesy) / Perception. If your target currently has one of the Consumed by Shourido Disadvantages, you gain a +5k0 bonus to this roll. With a success, you may convince your target to treat some other person, group, institution, or clan as their enemy. This cannot be used to turn someone directly against his lord or the Emperor. Subject to that limitation, the target will continue to believe in this enmity until presented with evidence to the contrary. This technique cannot be used against the same person more than once per month."}]},{"id":"spider_order_of_the_spider_monk","clanId":"spider","nome":"Order of the Spider Monk","traco":"agility","honra":"1.5","tags":["monk","spider_monk"],"pericias":[{"id":"athletics","rank":1,"enfase":""},{"id":"jiujutsu","rank":2,"enfase":""},{"id":"lore_theology","rank":1,"enfase":""},{"id":"meditation","rank":1,"enfase":""},{"id":"polearms","rank":1,"enfase":""}],"tecnicas":[{"id":"spider_the_dark_path","nome":"The Dark Path","rank":1,"descricao":"The Order of the Spider teaches strength and mastery of oneself, even the darkness that hides within the soul. You gain a bonus of +1k0 to the total of all attack rolls made using unarmed strikes or with polearms. You also add twice your School Rank to your Armor TN against all melee attacks."},{"id":"spider_drawing_in_the_strike","nome":"Drawing In The Strike","rank":2,"descricao":"Mastery of the body is a step to the path of power, and this mastery affords tremendous endurance to those who reach it. You may select any non-Void Ring. You gain Reduction equal to this Ring, plus your Rank in the Shadowlands Taint, if you possess any."},{"id":"spider_speed_of_darkness","nome":"Speed Of Darkness","rank":3,"descricao":"The alignment of body and mind allow tremendous speed. When using a polearm or an unarmed attack, you may make melee attacks as Simple Actions rather than Complex Actions."},{"id":"spider_guarded_by_chi","nome":"Guarded By Chi","rank":4,"descricao":"Following mastery of the body comes mastery of the soul. When you learn this Technique, you may select any one non-Void Ring. You add twice your Rank in this Ring, plus your Shadowlands Taint Rank (if you possess any), to the TN of any spell being cast against you. You may choose to suppress this effect if you wish."},{"id":"spider_darkness_unleashed","nome":"Darkness Unleashed","rank":5,"descricao":"True mastery of the self requires drawing upon the darkness within. You gain an additional number of Void Points per day equal to your Shadowlands Taint rank or your Earth Ring, whichever is higher. These may be spent exactly like normal Void Points, except they may also be spent to add a bonus of +1k1 to the total of your damage rolls."}]},{"id":"tortoise_kasuga_smuggler_school","clanId":"tortoise","nome":"Kasuga Smuggler School","traco":"awareness","honra":"2","tags":["smuggler","tortoise_smuggler"],"pericias":[{"id":"commerce","rank":1,"enfase":""},{"id":"etiquette","rank":1,"enfase":""},{"id":"investigation","rank":1,"enfase":"Notice"},{"id":"lore_underworld","rank":1,"enfase":""},{"id":"sincerity","rank":1,"enfase":"Deceit"},{"id":"stealth","rank":1,"enfase":""}],"tecnicas":[{"id":"tortoise_way_of_the_tortoise","nome":"Way Of The Tortoise","rank":1,"descricao":"The Tortoise routinely consort with the lowest elements of Rokugani society, often spend time in foreign ports, dealing with gaijin, and other villains, and otherwise do things most samurai would find repugnant. They are also skilled merchants, an unavoidable side effect of being smugglers. At character creation, you may learn an additional gaijin language for free with every purchase of the Languages Advantage. You do not lose Honor for using Low Skills, or Glory for using the Commerce skill in public, so long as you are doing so as part of your duty to your clan. When dealing with heimin or hinin, such as peasants, merchants, and eta, you gain a +2k0 bonus to all Social Skill rolls."},{"id":"tortoise_the_shell_of_the_tortoise","nome":"The Shell Of The Tortoise","rank":2,"descricao":"Most samurai in Rokugan revile the Tortoise for their unusual behavior and their association with commoners and gaijin, but all samurai know the Tortoise Clan has the special permission and sponsorship of the Emperor. Any clan or Imperial samurai who physically attacks or openly slanders you without provocation on your part (GM's discretion) will immediately lose a number of points of Honor equal to twice your School Rank."},{"id":"tortoise_the_eyes_of_the_emperor","nome":"The Eyes Of The Emperor","rank":3,"descricao":"The Tortoise function as spies and agents of the Emperor, and are adept at the lowest of tactics and methods. When acting on behalf of your clan, you may roll additional unkept dice equal to your School Rank on all Low Skills in which you have at least one Skill Rank. This includes any School Skills which only function as Low Skills when used in certain ways (such as Sincerity with the Deceit Emphasis). This does not work with Advantages and Techniques which simulate Skill Ranks (such as the Crafty Advantage.)"},{"id":"tortoise_hand_in_hand","nome":"Hand In Hand","rank":4,"descricao":"The Tortoise work in close cooperation with the common folk of Rokugan, people who other samurai ignore as much as possible. This gives them access to information networks no other samurai can reach. Once per session, if you have access to the local heimin or hinin, you can roll Lore: Underworld / Awareness at TN 25 to learn one useful piece of information (chosen by the GM) that cannot be learned any other way."},{"id":"tortoise_the_tortoise_smiles","nome":"The Tortoise Smiles","rank":5,"descricao":"With his training completed, the Tortoise smuggler can transcend his own limits in the pursuit of his Clan's devious goals, serving the Emperor without constraint. When making a Skill Roll with any of your six specified School Skills, your maximum Raises are not limited by your Void. A number of times per session equal to your Void Ring, you may gain a +5k0 bonus when making a roll with any of your School Skills. This bonus can stack with the bonus from your Rank Three technique."}]},{"id":"unicorn_moto_bushi_school","clanId":"unicorn","nome":"Moto Bushi School","traco":"strength","honra":"3.5","tags":["bushi","unicorn_bushi"],"pericias":[{"id":"athletics","rank":1,"enfase":""},{"id":"defense","rank":1,"enfase":""},{"id":"horsemanship","rank":1,"enfase":""},{"id":"hunting","rank":1,"enfase":""},{"id":"kenjutsu","rank":1,"enfase":"Scimitar"}],"tecnicas":[{"id":"unicorn_the_way_of_the_unicorn","nome":"The Way Of The Unicorn","rank":1,"descricao":"The Moto combat style is a wild, unfettered fury that intimidates witnesses. You may wield any two-handed weapon with one hand (except for bows). You gain a bonus of +1k0 to damage rolls while mounted, using a scimitar, or while using a two-handed melee weapon (these bonuses do not stack). Scimitars have the Samurai keyword for you."},{"id":"unicorn_shinseis_smile","nome":"Shinsei's Smile","rank":2,"descricao":"The Moto are famed for slicing their enemies' throats from ear to ear, a gruesome display they proudly call Shinsei's Smile. You take advantage of your opponent's weakened state, gaining a bonus to your attack rolls equal to half of his Wound Rank TN penalties, rounded down. For example, if your opponent is unhurt and in the Healthy Wound Rank, you do not gain a bonus. If your opponent is in the Crippled Wound Rank, you gain a bonus of +10 to the total of attack rolls."},{"id":"unicorn_desert_wind_strike","nome":"Desert Wind Strike","rank":3,"descricao":"Power and precision are equally valuable to the Moto. You may make attacks as a Simple Action instead of a Complex Action when using a melee weapon."},{"id":"unicorn_the_charge_of_madness","nome":"The Charge Of Madness","rank":4,"descricao":"The Moto fighting style is utterly relentless, allowing him to move from one foe to another without ceasing. Once per skirmish, if you successfully bring a target down to the Out Wound Level, you may immediately make an additional attack as a Free Action. This attack may not target the same target as the attack that activated Technique. You may not make Raises on this attack."},{"id":"unicorn_moto_cannot_yield","nome":"Moto Cannot Yield","rank":5,"descricao":"A Moto never surrenders. While mounted or while assuming the Full Attack Stance you keep an additional number of damage dice equal to half your strength, rounded down. You only gain this bonus while wielding a two-handed weapon or a weapon with the Samurai keyword."}]},{"id":"unicorn_iuchi_shugenja_school","clanId":"unicorn","nome":"Iuchi Shugenja School","traco":"perception","honra":"5.5","tags":["shugenja","unicorn_shugenja"],"pericias":[{"id":"battle","rank":1,"enfase":""},{"id":"calligraphy","rank":1,"enfase":"Cipher"},{"id":"horsemanship","rank":1,"enfase":""},{"id":"lore_theology","rank":1,"enfase":""},{"id":"meditation","rank":1,"enfase":""},{"id":"spellcraft","rank":1,"enfase":""}],"tecnicas":[{"id":"unicorn_spirit_of_the_wind","nome":"Spirit of the Wind","rank":1,"descricao":"The Iuchi harness the power of the elements to grant the waves' speed to others. As a Complex Action, you may sacrifice one spell slot of any element to grant one target individual an additional Simple Move Action. This Simple Action is in addition to the target's normal Actions per Round. The Additional Action must be used on the target's next Turn or it is lost. You also gain a Free Raise on any spell with the Travel keyword. Spells: Sense, Commune, Summon, 3 Water, 2 Earth, and 1 Air"}]},{"id":"unicorn_ide_emissary_school","clanId":"unicorn","nome":"Ide Emissary School","traco":"awareness","honra":"5.5","tags":["courtier","unicorn_courtier"],"pericias":[{"id":"calligraphy","rank":1,"enfase":""},{"id":"commerce","rank":1,"enfase":""},{"id":"courtier","rank":1,"enfase":""},{"id":"etiquette","rank":1,"enfase":"Conversation"},{"id":"horsemanship","rank":1,"enfase":""},{"id":"sincerity","rank":1,"enfase":"Honesty"}],"tecnicas":[{"id":"unicorn_the_heart_speaks","nome":"The Heart Speaks","rank":1,"descricao":"The Ide are taught to adapt instantly to new customs and social nuances, allowing them to avoid giving offense in even the most dangerous and hostile of courts. Also, since they must often deal with foreigners who might react poorly to lies or manipulation, they are taught to employ honesty and direct speech whenever possible. In any situation in which you might inadvertently give offense, whether through accident or ignorance (such as being unware of a daimyo's hostility to a particular subject of conversation), you may roll Etiquette (Courtesy) / Awareness at TN 20 to avoid doing so. You gain a Free Raise when rolling Sincerity (Honest), but any time you roll Sincerity (Deceit), your TN is increased by +5."},{"id":"unicorn_piercing_the_veils","nome":"Piercing The Veils","rank":2,"descricao":"After centuries of dealing with unpredictable and sometimes violent folk in the Burning Sands, the Ide have learned an almost preternatural ability to read the emotions of others, recognizing their true feelings and, hopefully, steering away from trouble. You may attempt to read someone else's true emotions in a social situation by making a Contested Social Roll of Etiquette / Awareness against the target's Etiquette / Willpower. With a success, you gain a simple, general idea of their true feelings - which can be very useful when those feelings are not the same as their outward actions. You may Raise for better information, subject to GM's adjudication. (For example, two Raises might tell you, \"The Doji is actually hoping for your success against the Dragon.\")"},{"id":"unicorn_the_heart_listens","nome":"The Heart Listens","rank":3,"descricao":"The Ide family's training emphasizes friendship and good personal relations as the key to successful diplomacy. You may attempt to sway someone's attitude toward you in a positive direction. This requires spending at least 10 minutes in conversation, after which you may make a Contested Roll of your Sincerity (Honesty) / Awareness against their Etiquette (Courtesy) / Willpower. With a success, you shift their attitude toward you in a positive direction. (A hostile individual will become more neutral, an undecided individual will become friendly, etc.) If you make at least two successful Raises on this roll, the target will regard you as an Ally for the remainder of this day (subject to GM approval). This technique cannot be used on Sworn Enemies, and the GM is the final arbiter on whether it functions against unusual targets such as nonhuman creatures."},{"id":"unicorn_answering_the_heart","nome":"Answering The Heart","rank":4,"descricao":"At this level of training, the Ide have become true masters of mediation, able to see past all the deceptions and false fronts of diplomacy and discern the true solution to any problem. When using your Rank Two and Rank Three techniques, you may roll additional unkept dice equal to your School Rank."},{"id":"unicorn_the_immovable_hand_of_peace","nome":"The Immovable Hand Of Peace","rank":5,"descricao":"The final lesson the Ide school teaches its students is to be such perfect mediators that no honorable person can raise a hand against them in violence. You may spend a Void Point to make a Contested Roll of your Sincerity (Honesty) / Awareness against a target individual's Etiquette (Courtesy) / Awareness. If you win the roll, the target cannot take any hostile action against you (physical, social, or magical) for a number of hours equal to twice your School Rank, as long as your likewise refrain from hostility against that person. This Technique does not work agaisnt those with an Honor Rank less than 2.0 or who possess no Honor Rank (animals, oni, etc)."}]},{"id":"unicorn_utaku_battle_maiden","clanId":"unicorn","nome":"Utaku Battle Maiden","traco":"reflexes","honra":"6.5","tags":["bushi","unicorn_bushi"],"pericias":[{"id":"battle","rank":1,"enfase":""},{"id":"defense","rank":1,"enfase":""},{"id":"horsemanship","rank":2,"enfase":""},{"id":"kenjutsu","rank":1,"enfase":""},{"id":"sincerity","rank":1,"enfase":""}],"tecnicas":[{"id":"unicorn_riding_in_harmony","nome":"Riding In Harmony","rank":1,"descricao":"The Utaku Battle Maidens value honor above all. You gain a bonus equal to your Honor Rank to one attack per Round. While mounted, you may instead choose to apply to bonus to one damage roll if you choose. You gain a bonus equal to your Honor Rank to the total of all Horsemanship rolls."},{"id":"unicorn_the_void_of_war","nome":"The Void Of War","rank":2,"descricao":"An Utaku can sacrifice defense for speed if the flow of the battle calls for it. During Stage 1 of any Combat Round, you may add 5 to either your Initiative Score or your Armor TN. This bonus lasts until you use this Technique again or the skirmish ends."},{"id":"unicorn_sensing_the_breeze","nome":"Sensing The Breeze","rank":3,"descricao":"The natural feel of the saddle lends an Utaku unnatural freedom of movement. While mounted, you may make attacks as a Simple Action instead of a Complex Action."},{"id":"unicorn_wind_never_stops","nome":"Wind Never Stops","rank":4,"descricao":"Like the wind across the battlefield, the charge of an Utaku is unstoppable. While mounted, you may overrun the enemy spending a Void Point. You may take a Simple Action to charge the enemy and attack him at the end of your movement. (Both the movement and the attack take the same Simple Action. If you are mounted, this Action uses the movement rate of your steed.) If this attack succeeds, you gain a bonus of +2k1 to the total of all damage rolls this Turn."},{"id":"unicorn_otakus_blessing","nome":"Otaku's Blessing","rank":5,"descricao":"The Utaku carry the honor of their founder as their shield. At the beginning of your Turn, you may spend a Void Point as a Free Action to activate this Technique. You add your Honor Rank to all damage rolls and Bugei Skill Rolls this Turn. This bonus stacks with those from Riding in Harmony."}]}],"rings":[{"id":"air","nome":"Air"},{"id":"earth","nome":"Earth"},{"id":"fire","nome":"Fire"},{"id":"water","nome":"Water"},{"id":"void","nome":"Void"},{"id":"all","nome":"Universal"}],"traits":[{"id":"reflexes","nome":"Reflexes"},{"id":"awareness","nome":"Awareness"},{"id":"stamina","nome":"Stamina"},{"id":"willpower","nome":"Willpower"},{"id":"agility","nome":"Agility"},{"id":"intelligence","nome":"Intelligence"},{"id":"strength","nome":"Strength"},{"id":"perception","nome":"Perception"}],"skills":[{"id":"athletics","nome":"Athletics","traco":"strength","tipo":"bugei"},{"id":"battle","nome":"Battle","traco":"perception","tipo":"bugei"},{"id":"defense","nome":"Defense","traco":"reflexes","tipo":"bugei"},{"id":"horsemanship","nome":"Horsemanship","traco":"agility","tipo":"bugei"},{"id":"hunting","nome":"Hunting","traco":"perception","tipo":"bugei"},{"id":"iaijutsu","nome":"Iaijutsu","traco":"reflexes","tipo":"bugei"},{"id":"jiujutsu","nome":"Jiujutsu","traco":"agility","tipo":"bugei"},{"id":"chain_weapons","nome":"Chain Weapons","traco":"agility","tipo":"bugei"},{"id":"heavy_weapons","nome":"Heavy Weapons","traco":"agility","tipo":"bugei"},{"id":"kenjutsu","nome":"Kenjutsu","traco":"agility","tipo":"bugei"},{"id":"knives","nome":"Knives","traco":"agility","tipo":"bugei"},{"id":"kyujutsu","nome":"Kyujutsu","traco":"reflexes","tipo":"bugei"},{"id":"polearms","nome":"Polearms","traco":"agility","tipo":"bugei"},{"id":"spears","nome":"Spears","traco":"agility","tipo":"bugei"},{"id":"staves","nome":"Staves","traco":"agility","tipo":"bugei"},{"id":"war_fan","nome":"War Fan","traco":"agility","tipo":"bugei"},{"id":"acting","nome":"Acting","traco":"awareness","tipo":"high"},{"id":"artisan_bonsai","nome":"Artisan (Bonsai)","traco":"awareness","tipo":"high"},{"id":"artisan_gardening","nome":"Artisan (Gardening)","traco":"awareness","tipo":"high"},{"id":"artisan_ikebana","nome":"Artisan (Ikebana)","traco":"awareness","tipo":"high"},{"id":"artisan_origami","nome":"Artisan (Origami)","traco":"awareness","tipo":"high"},{"id":"artisan_painting","nome":"Artisan (Painting)","traco":"awareness","tipo":"high"},{"id":"artisan_poetry","nome":"Artisan (Poetry)","traco":"awareness","tipo":"high"},{"id":"artisan_sculpture","nome":"Artisan (Sculpture)","traco":"awareness","tipo":"high"},{"id":"artisan_tattoing","nome":"Artisan (Tattoing)","traco":"awareness","tipo":"high"},{"id":"calligraphy","nome":"Calligraphy","traco":"intelligence","tipo":"high"},{"id":"courtier","nome":"Courtier","traco":"awareness","tipo":"high"},{"id":"divination","nome":"Divination","traco":"intelligence","tipo":"high"},{"id":"etiquette","nome":"Etiquette","traco":"awareness","tipo":"high"},{"id":"games_fortunes_winds","nome":"Games (Fortunes & Winds)","traco":"awareness","tipo":"high"},{"id":"games_go","nome":"Games (Go)","traco":"intelligence","tipo":"high"},{"id":"games_kemari","nome":"Games (Kemari)","traco":"agility","tipo":"high"},{"id":"games_letters","nome":"Games (Letters)","traco":"awareness","tipo":"high"},{"id":"games_sadane","nome":"Games (Sadane)","traco":"awareness","tipo":"high"},{"id":"games_shogi","nome":"Games (Shogi)","traco":"intelligence","tipo":"high"},{"id":"investigation","nome":"Investigation","traco":"perception","tipo":"high"},{"id":"lore_architecture","nome":"Lore (Architecture)","traco":"intelligence","tipo":"high"},{"id":"lore_bushido","nome":"Lore (Bushido)","traco":"intelligence","tipo":"high"},{"id":"lore_crab","nome":"Lore (Crab)","traco":"intelligence","tipo":"high"},{"id":"lore_crane","nome":"Lore (Crane)","traco":"intelligence","tipo":"high"},{"id":"lore_dragon","nome":"Lore (Dragon)","traco":"intelligence","tipo":"high"},{"id":"lore_scorpion","nome":"Lore (Scorpion)","traco":"intelligence","tipo":"high"},{"id":"lore_phoenix","nome":"Lore (Phoenix)","traco":"intelligence","tipo":"high"},{"id":"lore_unicorn","nome":"Lore (Unicorn)","traco":"intelligence","tipo":"high"},{"id":"lore_lion","nome":"Lore (Lion)","traco":"intelligence","tipo":"high"},{"id":"lore_mantis","nome":"Lore (Mantis)","traco":"intelligence","tipo":"high"},{"id":"lore_elements","nome":"Lore (Elements)","traco":"intelligence","tipo":"high"},{"id":"lore_gaijin_culture","nome":"Lore (Gaijin Culture)","traco":"intelligence","tipo":"high"},{"id":"lore_ghosts","nome":"Lore (Ghosts)","traco":"intelligence","tipo":"high"},{"id":"lore_heraldry","nome":"Lore (Heraldry)","traco":"intelligence","tipo":"high"},{"id":"lore_history","nome":"Lore (History)","traco":"intelligence","tipo":"high"},{"id":"lore_nature","nome":"Lore (Nature)","traco":"intelligence","tipo":"high"},{"id":"lore_nonhuman_culture","nome":"Lore (Nonhuman Culture)","traco":"intelligence","tipo":"high"},{"id":"lore_omens","nome":"Lore (Omens)","traco":"intelligence","tipo":"high"},{"id":"lore_shugenja","nome":"Lore (Shugenja)","traco":"intelligence","tipo":"high"},{"id":"lore_spirit_realms","nome":"Lore (Spirit Realms)","traco":"intelligence","tipo":"high"},{"id":"lore_theology","nome":"Lore (Theology)","traco":"intelligence","tipo":"high"},{"id":"lore_war","nome":"Lore (War)","traco":"intelligence","tipo":"high"},{"id":"lore_the_sea","nome":"Lore (The Sea)","traco":"intelligence","tipo":"high"},{"id":"lore_law","nome":"Lore (Law)","traco":"intelligence","tipo":"high"},{"id":"medicine","nome":"Medicine","traco":"intelligence","tipo":"high"},{"id":"meditation","nome":"Meditation","traco":"void","tipo":"high"},{"id":"perform_biwa","nome":"Perform (Biwa)","traco":"agility","tipo":"high"},{"id":"perform_dance","nome":"Perform (Dance)","traco":"agility","tipo":"high"},{"id":"perform_drums","nome":"Perform (Drums)","traco":"agility","tipo":"high"},{"id":"perform_flute","nome":"Perform (Flute)","traco":"agility","tipo":"high"},{"id":"perform_oratory","nome":"Perform (Oratory)","traco":"awareness","tipo":"high"},{"id":"perform_puppeteer","nome":"Perform (Puppeteer)","traco":"agility","tipo":"high"},{"id":"perform_samisen","nome":"Perform (Samisen)","traco":"agility","tipo":"high"},{"id":"perform_song","nome":"Perform (Song)","traco":"awareness","tipo":"high"},{"id":"perform_storytelling","nome":"Perform (Storytelling)","traco":"awareness","tipo":"high"},{"id":"sincerity","nome":"Sincerity","traco":"awareness","tipo":"high"},{"id":"spellcraft","nome":"Spellcraft","traco":"intelligence","tipo":"high"},{"id":"tea_ceremony","nome":"Tea Ceremony","traco":"void","tipo":"high"},{"id":"craft_armorsmithing","nome":"Craft (Armorsmithing)","traco":"varies","tipo":"high"},{"id":"craft_bowyer","nome":"Craft (Bowyer)","traco":"varies","tipo":"high"},{"id":"craft_weaponsmithing","nome":"Craft (Weaponsmithing)","traco":"varies","tipo":"high"},{"id":"lore_anatomy","nome":"Lore (Anatomy)","traco":"intelligence","tipo":"low"},{"id":"lore_maho","nome":"Lore (Maho)","traco":"intelligence","tipo":"low"},{"id":"lore_kolat","nome":"Lore (Kolat)","traco":"intelligence","tipo":"low"},{"id":"lore_gozoku","nome":"Lore (Gozoku)","traco":"intelligence","tipo":"low"},{"id":"lore_lying_darkness","nome":"Lore (Lying Darkness)","traco":"intelligence","tipo":"low"},{"id":"lore_shadowlands","nome":"Lore (Shadowlands)","traco":"intelligence","tipo":"low"},{"id":"lore_underworld","nome":"Lore (Underworld)","traco":"intelligence","tipo":"low"},{"id":"ninjutsu","nome":"Ninjutsu","traco":"agility","tipo":"low"},{"id":"craft_poison","nome":"Craft (Poison)","traco":"varies","tipo":"low"},{"id":"craft_explosives","nome":"Craft (Explosives)","traco":"varies","tipo":"low"},{"id":"forgery","nome":"Forgery","traco":"agility","tipo":"low"},{"id":"intimidation","nome":"Intimidation","traco":"awareness","tipo":"low"},{"id":"sleight_of_hand","nome":"Sleight of Hand","traco":"agility","tipo":"low"},{"id":"stealth","nome":"Stealth","traco":"agility","tipo":"low"},{"id":"temptation","nome":"Temptation","traco":"awareness","tipo":"low"},{"id":"animal_handling","nome":"Animal Handling","traco":"awareness","tipo":"merchant"},{"id":"commerce","nome":"Commerce","traco":"intelligence","tipo":"merchant"},{"id":"craft_blacksmithing","nome":"Craft (Blacksmithing)","traco":"varies","tipo":"merchant"},{"id":"craft_brewing","nome":"Craft (Brewing)","traco":"varies","tipo":"merchant"},{"id":"craft_carpentry","nome":"Craft (Carpentry)","traco":"varies","tipo":"merchant"},{"id":"craft_cartography","nome":"Craft (Cartography)","traco":"varies","tipo":"merchant"},{"id":"craft_cobbling","nome":"Craft (Cobbling)","traco":"varies","tipo":"merchant"},{"id":"craft_farming","nome":"Craft (Farming)","traco":"varies","tipo":"merchant"},{"id":"craft_fishing","nome":"Craft (Fishing)","traco":"varies","tipo":"merchant"},{"id":"craft_masonry","nome":"Craft (Masonry)","traco":"varies","tipo":"merchant"},{"id":"craft_mining","nome":"Craft (Mining)","traco":"varies","tipo":"merchant"},{"id":"craft_pottery","nome":"Craft (Pottery)","traco":"varies","tipo":"merchant"},{"id":"craft_shipbuilding","nome":"Craft (Shipbuilding)","traco":"varies","tipo":"merchant"},{"id":"craft_tailoring","nome":"Craft (Tailoring)","traco":"varies","tipo":"merchant"},{"id":"craft_tattooing","nome":"Craft (Tattooing)","traco":"varies","tipo":"merchant"},{"id":"craft_weaving","nome":"Craft (Weaving)","traco":"varies","tipo":"merchant"},{"id":"engineering","nome":"Engineering","traco":"intelligence","tipo":"merchant"},{"id":"sailing","nome":"Sailing","traco":"agility","tipo":"merchant"}],"vantagens":[{"id":"gaijin_gear","nome":"Gaijin Gear","tipo":"material","custo":5,"descricao":"You possess a single piece of equipment that is gaijin in origin, constructed somewhere beyond the boundaries of the Emerald Empire. It may be a weapon from one of the many warrior cultures around Rokugan, such as the Senpet Empire, the overseas kingdoms of Merenae and Thrane, the barbarian Yobanjin tribes to the north, or even the distant Yodotai Empire far to the northwest. In this case simply establish a comparable weapon from Rokugan and use its mechanics, but the item will require its own u"},{"id":"gentry","nome":"Gentry","tipo":"material","custo":0,"descricao":"In the manner of all samurai, you have been given a duty to oversee that which ultimately belongs to the Emperor. In your case, however, your charge is signifi cantly larger than most ever achieve. The number of points assigned to this Advantage determines the size of the holding you have been assigned to oversee. Multiple characters can combine points in this Advantage in order to jointly oversee a larger holding. Characters assigned to oversee a holding are responsible for defending it, admini"},{"id":"inheritance","nome":"Inheritance","tipo":"material","custo":5,"descricao":"When you received your gempukku ceremony, your family honored you with an heirloom of your ancestors. It is among your most precious possessions, and you would die before you allowed it to be harmed or brought dishonor to it. You possess one item in addition to the normal starting equipment provided by your School. Whenever you make a Skill Roll using this item, such as a Perform: Biwa roll with a biwa, a Games: Go roll with a go set, or a Kenjutsu roll with a katana, you gain a bonus of +1k1 to"},{"id":"sacred_weapon_akodo_blade","nome":"Sacred Weapon (Akodo Blade)","tipo":"material","custo":6,"descricao":"You possess a special weapon created by the master weaponsmiths of your Clan, and considered to be an icon of all who bear the mon of your Clan. The cost of each individual weapon is denoted by the number after its name."},{"id":"sacred_weapon_black_steel_blade","nome":"Sacred Weapon (Black Steel Blade)","tipo":"material","custo":6,"descricao":"You possess a special weapon created by the master weaponsmiths of your Clan, and considered to be an icon of all who bear the mon of your Clan. The cost of each individual weapon is denoted by the number after its name."},{"id":"sacred_weapon_inquisitors_strike","nome":"Sacred Weapon (Inquisitor's Strike)","tipo":"material","custo":6,"descricao":"You possess a special weapon created by the master weaponsmiths of your Clan, and considered to be an icon of all who bear the mon of your Clan. The cost of each individual weapon is denoted by the number after its name."},{"id":"sacred_weapon_kaiu_blade","nome":"Sacred Weapon (Kaiu Blade)","tipo":"material","custo":6,"descricao":"You possess a special weapon created by the master weaponsmiths of your Clan, and considered to be an icon of all who bear the mon of your Clan. The cost of each individual weapon is denoted by the number after its name."},{"id":"sacred_weapon_kakita_blade","nome":"Sacred Weapon (Kakita Blade)","tipo":"material","custo":5,"descricao":"You possess a special weapon created by the master weaponsmiths of your Clan, and considered to be an icon of all who bear the mon of your Clan. The cost of each individual weapon is denoted by the number after its name."},{"id":"sacred_weapon_moto_scimitar","nome":"Sacred Weapon (Moto Scimitar)","tipo":"material","custo":6,"descricao":"You possess a special weapon created by the master weaponsmiths of your Clan, and considered to be an icon of all who bear the mon of your Clan. The cost of each individual weapon is denoted by the number after its name."},{"id":"sacred_weapon_shosuro_blade","nome":"Sacred Weapon (Shosuro Blade)","tipo":"material","custo":5,"descricao":"You possess a special weapon created by the master weaponsmiths of your Clan, and considered to be an icon of all who bear the mon of your Clan. The cost of each individual weapon is denoted by the number after its name."},{"id":"sacred_weapon_storm_kama_x2","nome":"Sacred Weapon (Storm Kama x2)","tipo":"material","custo":6,"descricao":"You possess a special weapon created by the master weaponsmiths of your Clan, and considered to be an icon of all who bear the mon of your Clan. The cost of each individual weapon is denoted by the number after its name."},{"id":"sacred_weapon_twin_sister_blades","nome":"Sacred Weapon (Twin Sister Blades)","tipo":"material","custo":3,"descricao":"You possess a special weapon created by the master weaponsmiths of your Clan, and considered to be an icon of all who bear the mon of your Clan. The cost of each individual weapon is denoted by the number after its name."},{"id":"servant","nome":"Servant","tipo":"material","custo":0,"descricao":"You possess a special weapon created by the master weaponsmiths of your Clan, and considered to be an icon of all who bear the mon of your Clan. The cost of each individual weapon is denoted by the number after its name."},{"id":"wealthy","nome":"Wealthy","tipo":"material","custo":1,"descricao":"Your branch of the family is particularly wealthy, and they have granted you additional resources in order to facilitate your fulfi llment of your duty. For each point spent on this Advantage, you gain two additional koku, to be added to the amount in your School outfi t. Crane, Unicorn, and Imperial characters may purchase this Advantage for 1 point less off its total cost."},{"id":"absolute_direction","nome":"Absolute Direction","tipo":"mental","custo":1,"descricao":"You possess an almost supernatural sense of direction, and you always know what direction is north, no matter the circumstances. This ability does not function if you are more than one day’s travel inside the Shadowlands."},{"id":"balance","nome":"Balance","tipo":"mental","custo":2,"descricao":"You possess an inherent calm and serenity that others have diffi culty overcoming when attempting to antagonize or taunt you, and that strengthens you when your honor is tested. When adding your Honor Rank to the total of any roll made to resist Intimidation or Temptation, you add an additional +1k0 to the roll as well."},{"id":"clear_thinker","nome":"Clear Thinker","tipo":"mental","custo":3,"descricao":"You possess a sharp mind and keen powers of perception, making it very diffi cult for others to deceive you. Whenever you make a Contested Roll against someone who is attempting to confuse or manipulate you in any way, you gain a bonus of +1k0 to the total of your roll. Dragon characters may purchase this Advantage for 2 points."},{"id":"crafty","nome":"Crafty","tipo":"mental","custo":3,"descricao":"You have a knack for instinctively knowing how to do things that most people prefer to avoid at all costs. Whenever you are in a situation where you would be forced to make an Unskilled Roll using a Low Skill, you are considered to have 1 rank in the Skill instead. Scorpion, Spider, and ninja characters may purchase this Advantage for 2 points."},{"id":"daredevil","nome":"Daredevil","tipo":"mental","custo":3,"descricao":"You have a natural fl air for athleticism and a complete lack of self-preservation when it comes to physical danger. Whenever you spend a Void Point to enhance an Athletics Skill Roll, you gain a bonus of +3k1 to the total of the roll instead of the normal +1k1. Mantis characters may purchase this Advantage for 2 points."},{"id":"dark_paragon_control","nome":"Dark Paragon (Control)","tipo":"mental","custo":5,"descricao":"You have mastered one of the precepts of Shourido, the dark code that forms an antithesis of Bushido. Once per session, you may voluntarily sacrifi ce 5 points of Honor as a Free Action in order to affect a particular type of roll as indicated below, and gain a bonus of +5 to the total of that roll. If you do not have 5 points of Honor to spend in this manner, you may spend a Void Point instead. Spider characters may purchase this Advantage for 4 points. Control: Re-roll any Social Skill Roll"},{"id":"dark_paragon_determination","nome":"Dark Paragon (Determination)","tipo":"mental","custo":5,"descricao":"You have mastered one of the precepts of Shourido, the dark code that forms an antithesis of Bushido. Once per session, you may voluntarily sacrifi ce 5 points of Honor as a Free Action in order to affect a particular type of roll as indicated below, and gain a bonus of +5 to the total of that roll. If you do not have 5 points of Honor to spend in this manner, you may spend a Void Point instead. Spider characters may purchase this Advantage for 4 points. Determination: Negate all TN/Wound penalt"},{"id":"dark_paragon_insight","nome":"Dark Paragon (Insight)","tipo":"mental","custo":5,"descricao":"You have mastered one of the precepts of Shourido, the dark code that forms an antithesis of Bushido. Once per session, you may voluntarily sacrifi ce 5 points of Honor as a Free Action in order to affect a particular type of roll as indicated below, and gain a bonus of +5 to the total of that roll. If you do not have 5 points of Honor to spend in this manner, you may spend a Void Point instead. Spider characters may purchase this Advantage for 4 points. Insight: Re-roll any roll that used the A"},{"id":"dark_paragon_knowledge","nome":"Dark Paragon (Knowledge)","tipo":"mental","custo":5,"descricao":"You have mastered one of the precepts of Shourido, the dark code that forms an antithesis of Bushido. Once per session, you may voluntarily sacrifi ce 5 points of Honor as a Free Action in order to affect a particular type of roll as indicated below, and gain a bonus of +5 to the total of that roll. If you do not have 5 points of Honor to spend in this manner, you may spend a Void Point instead. Spider characters may purchase this Advantage for 4 points. Knowledge: Re-roll any roll that used the"},{"id":"dark_paragon_perfection","nome":"Dark Paragon (Perfection)","tipo":"mental","custo":5,"descricao":"You have mastered one of the precepts of Shourido, the dark code that forms an antithesis of Bushido. Once per session, you may voluntarily sacrifi ce 5 points of Honor as a Free Action in order to affect a particular type of roll as indicated below, and gain a bonus of +5 to the total of that roll. If you do not have 5 points of Honor to spend in this manner, you may spend a Void Point instead. Spider characters may purchase this Advantage for 4 points. Perfection: Spending the Honor causes any"},{"id":"dark_paragon_strength","nome":"Dark Paragon (Strength)","tipo":"mental","custo":5,"descricao":"You have mastered one of the precepts of Shourido, the dark code that forms an antithesis of Bushido. Once per session, you may voluntarily sacrifi ce 5 points of Honor as a Free Action in order to affect a particular type of roll as indicated below, and gain a bonus of +5 to the total of that roll. If you do not have 5 points of Honor to spend in this manner, you may spend a Void Point instead. Spider characters may purchase this Advantage for 4 points. Strength: Re-roll any damage Roll"},{"id":"dark_paragon_will","nome":"Dark Paragon (Will)","tipo":"mental","custo":5,"descricao":"You have mastered one of the precepts of Shourido, the dark code that forms an antithesis of Bushido. Once per session, you may voluntarily sacrifi ce 5 points of Honor as a Free Action in order to affect a particular type of roll as indicated below, and gain a bonus of +5 to the total of that roll. If you do not have 5 points of Honor to spend in this manner, you may spend a Void Point instead. Spider characters may purchase this Advantage for 4 points. Will: Spending the Honor negates 10 Wound"},{"id":"forbidden_knowledge_gaijin_pepper","nome":"Forbidden Knowledge (Gaijin Pepper)","tipo":"mental","custo":5,"descricao":"There is a subject about which you possess considerable knowledge and insight. The problem is that this subject is forbidden, and considered grossly socially inappropriate if not outright illegal. Anyone who discovers your expertise in this area might rightly wonder how you came upon it. The benefi ts of the Advantage vary depending upon the nature of the information, and players should discuss with their GM how this Advantage will work. Gaijin Pepper: You possess fi rsthand knowledge of gunpowd"},{"id":"forbidden_knowledge_gozoku","nome":"Forbidden Knowledge (Gozoku)","tipo":"mental","custo":5,"descricao":"There is a subject about which you possess considerable knowledge and insight. The problem is that this subject is forbidden, and considered grossly socially inappropriate if not outright illegal. Anyone who discovers your expertise in this area might rightly wonder how you came upon it. The benefi ts of the Advantage vary depending upon the nature of the information, and players should discuss with their GM how this Advantage will work. Gozoku: You possess an intricate knowledge of the Gozoku c"},{"id":"forbidden_knowledge_kolat","nome":"Forbidden Knowledge (Kolat)","tipo":"mental","custo":5,"descricao":"There is a subject about which you possess considerable knowledge and insight. The problem is that this subject is forbidden, and considered grossly socially inappropriate if not outright illegal. Anyone who discovers your expertise in this area might rightly wonder how you came upon it. The benefi ts of the Advantage vary depending upon the nature of the information, and players should discuss with their GM how this Advantage will work. Kolat: You are intimately familiar with the nature and ope"},{"id":"forbidden_knowledge_lying_darkness","nome":"Forbidden Knowledge (Lying Darkness)","tipo":"mental","custo":5,"descricao":"There is a subject about which you possess considerable knowledge and insight. The problem is that this subject is forbidden, and considered grossly socially inappropriate if not outright illegal. Anyone who discovers your expertise in this area might rightly wonder how you came upon it. The benefi ts of the Advantage vary depending upon the nature of the information, and players should discuss with their GM how this Advantage will work. Lying Darkness: You are familiar with the entity known as "},{"id":"forbidden_knowledge_maho","nome":"Forbidden Knowledge (Maho)","tipo":"mental","custo":5,"descricao":"There is a subject about which you possess considerable knowledge and insight. The problem is that this subject is forbidden, and considered grossly socially inappropriate if not outright illegal. Anyone who discovers your expertise in this area might rightly wonder how you came upon it. The benefi ts of the Advantage vary depending upon the nature of the information, and players should discuss with their GM how this Advantage will work. Maho: You are familiar with the forbidden and blasphemous "},{"id":"higher_purpose","nome":"Higher Purpose","tipo":"mental","custo":3,"descricao":"There is some greater purpose to which you have devoted your life. This is not a simple matter, but some grand work that will take years or perhaps even the whole of your life to accomplish. Whatever this goal is, during any session in which you and the GM agree you have made demonstrable progress toward it, you gain one additional Experience Point."},{"id":"irreproachable","nome":"Irreproachable","tipo":"mental","custo":2,"descricao":"You have a soul of virtue that is beyond reproach, and others fi nd it diffi cult if not impossible to lead you into dishonorable behavior. When making a Contested Roll where the other party is using the Temptation Skill, you gain a bonus of +1k0 to your roll. Imperial characters may purchase this Advantage for 1 point."},{"id":"languages","nome":"Languages","tipo":"mental","custo":1,"descricao":"The Empire has only one language with two dialects. The world around Rokugan, however, has a wide variety of nations and cultures, each with their own language. For 1 point, you may learn one human language from any surrounding culture, including but not limited to: the Yobanjin dialect, Senpet, Yodotai, Mekham, Merenae, Rhuumal, Thrane, etc. A non-human language, such as the Nezumi or Naga languages, requires three points and confers only an ability to understand the language and a limited abil"},{"id":"paragon_compassion","nome":"Paragon (Compassion)","tipo":"mental","custo":7,"descricao":"You exemplify the code of Bushido, and have taken one particular tenet to heart and made it your way of life. In addition to the benefi t listed below, any time you gain Honor for exhibiting the virtue for which you have the Paragon Advantage, you gain an additional +1 Honor. Lion characters may purchase this Advantage for 6 points. Compassion: Any time you spend a Void Point to improve a roll made to directly help those lower than you in the Celestial Order, you gain +2k2 instead of +1k1."},{"id":"paragon_courage","nome":"Paragon (Courage)","tipo":"mental","custo":7,"descricao":"You exemplify the code of Bushido, and have taken one particular tenet to heart and made it your way of life. In addition to the benefi t listed below, any time you gain Honor for exhibiting the virtue for which you have the Paragon Advantage, you gain an additional +1 Honor. Lion characters may purchase this Advantage for 6 points. Courage: You add a bonus of +1k1 to the total of any roll made to resist Intimidation or to overcome Fear effects."},{"id":"paragon_courtesy","nome":"Paragon (Courtesy)","tipo":"mental","custo":7,"descricao":"You exemplify the code of Bushido, and have taken one particular tenet to heart and made it your way of life. In addition to the benefi t listed below, any time you gain Honor for exhibiting the virtue for which you have the Paragon Advantage, you gain an additional +1 Honor. Lion characters may purchase this Advantage for 6 points. Courtesy: Any time you make an Etiquette roll to avoid an embarrassment or breach of honor, you add +2k0 to the roll."},{"id":"paragon_duty","nome":"Paragon (Duty)","tipo":"mental","custo":7,"descricao":"You exemplify the code of Bushido, and have taken one particular tenet to heart and made it your way of life. In addition to the benefi t listed below, any time you gain Honor for exhibiting the virtue for which you have the Paragon Advantage, you gain an additional +1 Honor. Lion characters may purchase this Advantage for 6 points. Duty: You may spend a Void Point on any Skill Roll or Spell Casting Roll to negate all TN penalties for that roll, including Wound penalties."},{"id":"paragon_honesty","nome":"Paragon (Honesty)","tipo":"mental","custo":7,"descricao":"You exemplify the code of Bushido, and have taken one particular tenet to heart and made it your way of life. In addition to the benefi t listed below, any time you gain Honor for exhibiting the virtue for which you have the Paragon Advantage, you gain an additional +1 Honor. Lion characters may purchase this Advantage for 6 points. Honesty: On any Sincerity (Honesty) roll, you add a bonus of +1k1. You may add this bonus even if you do not possess the Emphasis, but it would apply in the situatio"},{"id":"paragon_honor","nome":"Paragon (Honor)","tipo":"mental","custo":7,"descricao":"You exemplify the code of Bushido, and have taken one particular tenet to heart and made it your way of life. In addition to the benefi t listed below, any time you gain Honor for exhibiting the virtue for which you have the Paragon Advantage, you gain an additional +1 Honor. Lion characters may purchase this Advantage for 6 points. Honor: You may add twice your Honor Rank to all rolls to resist Temptation or Intimidation rolls, instead of the normal bonus."},{"id":"paragon_sincerity","nome":"Paragon (Sincerity)","tipo":"mental","custo":7,"descricao":"You exemplify the code of Bushido, and have taken one particular tenet to heart and made it your way of life. In addition to the benefi t listed below, any time you gain Honor for exhibiting the virtue for which you have the Paragon Advantage, you gain an additional +1 Honor. Lion characters may purchase this Advantage for 6 points. Sincerity: You may add a bonus of +2k0 to all Contested Rolls using Sincerity."},{"id":"precise_memory","nome":"Precise Memory","tipo":"mental","custo":3,"descricao":"You have an incredible ability to recall exactly things you have seen or heard. In any situation where you need to remember something exactly the way it was, whether the wording of something you read or the details of a person’s physical appearance, you add a bonus of +1k1 to your Intelligence Trait Roll."},{"id":"read_lips","nome":"Read Lips","tipo":"mental","custo":4,"descricao":"Either through natural ability or incredible patience and practice, you have the ability to understand what others are saying even if you cannot hear them, simply by observing how their lips move. When you are in a situation where others are speaking and you cannot hear them, you can understand what they are saying by making a Perception Trait Roll against TN 15 + 5 for every twenty feet away from you the speakers are. Courtier characters may purchase this Advantage for 3 points."},{"id":"sage","nome":"Sage","tipo":"mental","custo":4,"descricao":"You have a love of learning, and have accumulated a staggering amount of information during the course of your lifetime. Whenever you would be forced to make an Unskilled Roll when using a Lore Skill, you instead are considered to have 1 rank in that Skill. Phoenix and shugenja characters may purchase this Advantage for 3 points."},{"id":"soul_of_artistry_artisan","nome":"Soul of Artistry (Artisan)","tipo":"mental","custo":4,"descricao":"Your soul soars with the spirit of creativity. Choose either Artisan Skills or Craft Skills when purchasing this Advantage. Any time that you would be required to make an Unskilled Roll using a Skill of the chosen type, you are considered to have 1 rank in that Skill. Crane and courtier characters may purchase this Advantage for 3 points."},{"id":"soul_of_artistry_craft","nome":"Soul of Artistry (Craft)","tipo":"mental","custo":4,"descricao":"Your soul soars with the spirit of creativity. Choose either Artisan Skills or Craft Skills when purchasing this Advantage. Any time that you would be required to make an Unskilled Roll using a Skill of the chosen type, you are considered to have 1 rank in that Skill. Crane and courtier characters may purchase this Advantage for 3 points."},{"id":"tactician","nome":"Tactician","tipo":"mental","custo":4,"descricao":"You have a mind well suited to the ebb and fl ow of battle. When making a roll on the Mass Battle Table, you may increase or decrease your result by 5. Lion and bushi characters may purchase this Advantage for 3 points."},{"id":"virtuous","nome":"Virtuous","tipo":"mental","custo":3,"descricao":"You embrace virtue in your every thought and action. You possess one additional rank of Honor above your normal starting value (as determined by your School)."},{"id":"wary","nome":"Wary","tipo":"mental","custo":3,"descricao":"You are constantly on alert, always looking out for the unexpected. When rolling Investigation (Notice) / Perception against Stealth (Ambush) / Agility to detect an ambush, you add +1k1 to your roll."},{"id":"way_of_the_land","nome":"Way of the Land","tipo":"mental","custo":2,"descricao":"You are intimately familiar with a particular region, having traveled it extensively to the point that you know it as well as the interior of your own house. Select the lands of one family, a major city, or some other reasonably sized region. While you are within that region, it is not possible for you to get lost, and you know the location of any available resources to be found there. Unicorn characters may purchase this Advantage for 1 point."},{"id":"bland","nome":"Bland","tipo":"physical","custo":2,"descricao":"You are extremely unremarkable in every regard, and others have a diffi cult time recognizing you unless you deliberately draw attention to your identity or affi liations. Whenever someone is making a Lore: Bushido / Awareness roll to determine your Honor Rank, or a Lore: Heraldry / Intelligence roll to determine your identity (based on your Glory Rank), you may voluntarily choose to increase the TN of that roll by 10."},{"id":"crab_hands","nome":"Crab Hands","tipo":"physical","custo":3,"descricao":"You possess a natural affi nity for weapons of all kinds, and can take up even an unfamiliar blade without diffi culty in times of stress. Any time that you would be forced to make an Unskilled Roll when using a Weapon Skill, you are instead considered to have 1 rank in that Weapon Skill. Crab and bushi characters may purchase this Advantage for 2 points."},{"id":"dangerous_beauty","nome":"Dangerous Beauty","tipo":"physical","custo":3,"descricao":"You possess a certain quality that makes you all but irresistible to members of the opposite sex, and they succumb easily to your manipulations. You gain a bonus of +1k0 to the total of all Temptation Skill Rolls made with members of the opposite sex. Scorpion characters may purchase this Advantage for 2 points."},{"id":"hands_of_stone","nome":"Hands of Stone","tipo":"physical","custo":6,"descricao":"Some have a natural talent for unarmed combat, and you are one such individual. The Damage Rolls for your unarmed attacks are increased by +0k1. Monk characters may purchase this Advantage for 5 points."},{"id":"large","nome":"Large","tipo":"physical","custo":4,"descricao":"You are signifi cantly larger than the average Rokugani, ranging in height from 6’0” to 6’3” in height. You gain a bonus of +1k0 to the total of all Damage Rolls for any large melee weapon. Crab characters may purchase this Advantage for 3 points."},{"id":"prodigy","nome":"Prodigy","tipo":"physical","custo":12,"descricao":"You are a marvel of the dojo, and your sensei believe that you will accomplish incredible things in your lifetime. Whenever you make a School Skill Roll, you gain a bonus of +1k0 to the roll."},{"id":"quick","nome":"Quick","tipo":"physical","custo":6,"descricao":"You can react quickly to others, seizing advantage where previously there had been none. If you did not act fi rst during a Combat Round, during the Reactions Stage of combat you may add your Refl exes Trait to the total of your Initiative Score for all subsequent rounds of this skirmish. This may done each Round that you did not act fi rst. Ninja characters may purchase this Advantage for 5 points."},{"id":"quick_healer","nome":"Quick Healer","tipo":"physical","custo":3,"descricao":"Your body mends incredibly quickly, allowing you to recover from even devastating wounds with amazing speed. For the purposes of recovering Wounds, your Stamina is considered to be two ranks higher."},{"id":"silent","nome":"Silent","tipo":"physical","custo":3,"descricao":"A servant has been assigned to assist you by your family, or possibly one whose help you purchased with your own resources in order to make life a little bit easier. You may have a maximum number of servants equal to twice your Status Rank. Different kinds of servants have different useful abilities and can more easily be supplied by different Clans. Typically, a servant has all Traits at rank 2 and a single Skill at rank 3. You may add additional Skill Ranks or Emphases to a servant at the time"},{"id":"strength_of_the_earth","nome":"Strength of the Earth","tipo":"physical","custo":3,"descricao":"In your soul can be found the spirit of the mountains and the strength of stone. You can overcome injuries that would cripple other men. The TN penalties you suffer from Wound Ranks are reduced by 3. Bushi characters may purchase this Advantage for 2 points."},{"id":"voice","nome":"Voice","tipo":"physical","custo":3,"descricao":"You have a voice that others fi nd pleasing in virtually every respect. You gain a bonus of +1k1 on any Perform Skill Roll that utilizes your voice, such as Perform: Singing or Perform: Oratory."},{"id":"allies","nome":"Allies","tipo":"social","custo":0,"descricao":"You have carefully nurtured social connections. Some of those in your web of connections would go to great lengths to protect you, while others have considerable resources. And some precious few are both. The total cost of this Advantage is determined by how many points you spend on your ally’s degree of influence and their devotion to you. Crane characters may purchase this Advantage for 1 point less than its normal cost."},{"id":"blackmail","nome":"Blackmail","tipo":"social","custo":1,"descricao":"You possess knowledge and proof of a dark secret held by another, and can use that secret to elicit their cooperation in a number of ways. The cost of the Advantage is equal to the Status Rank of the individual whom you are blackmailing. Using this Advantage too frequently or making grandiose demands on the person in question may result in them deciding your death is worth the risk of exposing their secret, no matter what the consequences might be. Scorpion characters may purchase this Advantage"},{"id":"blissful_betrothal","nome":"Blissful Betrothal","tipo":"social","custo":3,"descricao":"Your marriage has been arranged and, much to your delight, you have come to truly love your intended spouse. The social connections you have established as part of your enthusiastic marriage preparations allow you to purchase the following Advantages for two points less each (to a minimum of 1 point): Gentry, Kharmic Tie (with your betrothed only), Social Position, and Wealth."},{"id":"darling_of_the_court","nome":"Darling Of The Court","tipo":"social","custo":2,"descricao":"Your family sacrifi ced considerable resources and favors in order to sponsor your entrance into the School of another Clan. When creating your character, you may select a School of a different Clan to attend. You are still a member of your own Clan, however, creating a potential confl ict between your loyalty to your sensei and your loyalty to your lord and family."},{"id":"different_school","nome":"Different School","tipo":"social","custo":5,"descricao":"Your family sacrifi ced considerable resources and favors in order to sponsor your entrance into the School of another Clan. When creating your character, you may select a School of a different Clan to attend. You are still a member of your own Clan, however, creating a potential confl ict between your loyalty to your sensei and your loyalty to your lord and family."},{"id":"fame","nome":"Fame","tipo":"social","custo":3,"descricao":"As a result of your actions, there are many in the Empire who know your name. You gain +1 Glory Rank."},{"id":"heart_of_vengeance","nome":"Heart of Vengeance","tipo":"social","custo":5,"descricao":"One Clan has earned your eternal, undying hatred, and nothing will ever quench your rage. Select one Clan or other faction (such as the Brotherhood of Shinsei or one of the Imperial families) when purchasing this Advantage. You gain a bonus of +1k1 to the total of any Contested Roll made against a member of that Clan/faction. Spider characters may purchase this Advantage for 4 points."},{"id":"hero_of_the_people","nome":"Hero of the People","tipo":"social","custo":2,"descricao":"Although your reputation among your fellow samurai may not be any better than that of the next individual, your actions have garnered the adoration of the common folk. When meeting citizens of Rokugan who are not members of the samurai caste, the TN for them to recognize you, as determined by your Glory Rank, is lowered by 10."},{"id":"imperial_spouse","nome":"Imperial Spouse","tipo":"social","custo":5,"descricao":"Through a careful exchange of favors and resources, your family arranged for you to be married to a minor member of an Imperial family. Your spouse was not of high enough station to warrant you taking an Imperial name, but there are benefi ts all the same. You gain +0.5 Status Ranks, and gain a bonus of +1k1 to the total of all Social Skill rolls made with members of the Imperial families."},{"id":"leadership","nome":"Leadership","tipo":"social","custo":6,"descricao":"You have an innate knack for leading and inspiring others in battle. Once per Round during the Reactions stage, you may add your School Rank plus 1k1 to the Initiative Score of one ally in a skirmish. This bonus lasts until the Reactions stage of the following round. An individual may only benefi t from one use of this Advantage per Round. Lion characters may purchase this Advantage for 5 points."},{"id":"multiple_schools","nome":"Multiple Schools","tipo":"social","custo":10,"descricao":"You have been given an incredible opportunity to study at multiple dojo, each associated with a different major School. This is a rare opportunity indeed, as being released from one’s oaths to one sensei in order to study with another requires extraordinary circumstances. This Advantage may only be purchased during play, and once it is taken, the character stops progression in his current School. Upon reaching the next Insight Rank, he begins learning Techniques from the new School beginning at "},{"id":"perceived_honor","nome":"Perceived Honor","tipo":"social","custo":2,"descricao":"Others fi nd it diffi cult to perceive your true nature, a fact that benefi ts you in concealing your sometimes questionable actions. For each rank you possess in this Advantage, your Honor is considered one full rank higher for the purpose of all attempts to discern it. Anyone attempting to roll Lore: Bushido / Awareness to determine your Honor Rank will determine the false rank instead of your actual Honor."},{"id":"sacrosanct","nome":"Sacrosanct","tipo":"social","custo":4,"descricao":"Because of some great service you or perhaps your parents performed on behalf of the Emperor, the Son of Heaven has placed you under his protection. You may not purchase this Advantage unless you possess an Honor Rank of 6 or higher. So long as your Honor does not drop below 6.0, no one of Honor Rank 5 or higher may attack you unless you attack them fi rst; their rigid code of honor simply will not allow them to blatantly go against the Emperor’s wishes. Willingly entered duels ignore the effect"},{"id":"sensation","nome":"Sensation","tipo":"social","custo":3,"descricao":"You are capable of enrapturing the crowd, no matter the circumstances. Whenever you would be required to make a Skill Roll using a Perform Skill you do not possess, you are considered to have 1 rank in that skill."},{"id":"social_position","nome":"Social Position","tipo":"social","custo":6,"descricao":"You have received an illustrious social appointment, whether through your own accomplishments or purely because of political reasons. You gain +1 Status Rank."},{"id":"bentens_blessing","nome":"Benten's Blessing","tipo":"spiritual","custo":4,"descricao":"Benten’s Blessing (Crane): The Fortune of Romantic Love has showered you with her blessings. Whenever you are attempting to persuade someone, regardless of the circumstances, you gain a bonus of +0k1 to the total of the Social Skill Roll in question. This bonus only applies to persuasion, not coercion."},{"id":"bishamons_blessing","nome":"Bishamon's Blessing","tipo":"spiritual","custo":5,"descricao":"Bishamon’s Blessing (5 points) (Crab, Lion): The Fortune of Strength has taken notice of your might, and has favored you with his blessings. Whenever you declare and make three successful Raises on an attack roll for the purposes of the Increased Damage Maneuver, you gain one additional Raise. Free Raises do not count toward activating this effect. You also gain a bonus of +1k0 to the total of any Strength Trait Rolls."},{"id":"blood_of_osanowo","nome":"Blood of Osano-Wo","tipo":"spiritual","custo":4,"descricao":"You are descended from a bloodline of Hida Osano-Wo, the Fortune of Fire and Thunder, and his resilience lives on in you. You are immune to any penalties or damage from natural weather conditions, such as winter cold, summer heat, etc. If you suffer damage from a spell that employs natural forces (such as the mighty storm created by Hurricane, or the lightning bolt summoned by Fury of Osano-Wo), reduce the amount of damage you suffer by 1k1. Crab and Mantis characters may purchase this Advantage"},{"id":"chosen_by_the_oracles_air_","nome":"Chosen by the Oracles ( Air )","tipo":"spiritual","custo":6,"descricao":"For reasons beyond your understanding, you have caught the notice of one of the Oracles, humans suffused with the divine power of the Elemental Dragons. You must select one Ring when you take this Advantage. You gain a bonus of +1k1 to the total of all Ring Rolls using that Ring."},{"id":"chosen_by_the_oracles_earth_","nome":"Chosen by the Oracles ( Earth )","tipo":"spiritual","custo":6,"descricao":"For reasons beyond your understanding, you have caught the notice of one of the Oracles, humans suffused with the divine power of the Elemental Dragons. You must select one Ring when you take this Advantage. You gain a bonus of +1k1 to the total of all Ring Rolls using that Ring."},{"id":"chosen_by_the_oracles_fire_","nome":"Chosen by the Oracles ( Fire )","tipo":"spiritual","custo":6,"descricao":"For reasons beyond your understanding, you have caught the notice of one of the Oracles, humans suffused with the divine power of the Elemental Dragons. You must select one Ring when you take this Advantage. You gain a bonus of +1k1 to the total of all Ring Rolls using that Ring."},{"id":"chosen_by_the_oracles_void_","nome":"Chosen by the Oracles ( Void )","tipo":"spiritual","custo":6,"descricao":"For reasons beyond your understanding, you have caught the notice of one of the Oracles, humans suffused with the divine power of the Elemental Dragons. You must select one Ring when you take this Advantage. You gain a bonus of +1k1 to the total of all Ring Rolls using that Ring."},{"id":"chosen_by_the_oracles_water_","nome":"Chosen by the Oracles ( Water )","tipo":"spiritual","custo":6,"descricao":"For reasons beyond your understanding, you have caught the notice of one of the Oracles, humans suffused with the divine power of the Elemental Dragons. You must select one Ring when you take this Advantage. You gain a bonus of +1k1 to the total of all Ring Rolls using that Ring."},{"id":"daikokus_blessing","nome":"Daikoku's Blessing","tipo":"spiritual","custo":4,"descricao":"Daikoku’s Blessing (Mantis): The Fortune of Wealth has favored you with his patronage, and you excel in matters pertaining to wealth and mercantile pursuits. You gain a bonus of +1k1 to the total of all Commerce Skill Rolls."},{"id":"ebisus_blessing","nome":"Ebisu's Blessing","tipo":"spiritual","custo":4,"descricao":"Ebisu’s Blessing (Unicorn): You have captured the attention, if only briefl y, of the Fortune of Honest Work, and his favor is clear to those who serve him best. You gain a bonus of +1k1 to the total of all Social Skill Rolls made with citizens of Rokugan who are not members of the samurai caste."},{"id":"elemental_blessing_air","nome":"Elemental Blessing (Air)","tipo":"spiritual","custo":4,"descricao":"You are much beloved by the kami of a particular element, although you know not why that might be. As a result, the cost of increasing the Traits associated with one particular Ring, chosen when this Advantage is purchased, is decreased by 1. For example, if you choose Earth when you purchase this Advantage, the cost of increasing Stamina and Willpower is reduced by 1 Experience Point every time you increase them. Void may not be chosen for this Advantage. Phoenix characters may purchase this Ad"},{"id":"elemental_blessing_earth","nome":"Elemental Blessing (Earth)","tipo":"spiritual","custo":4,"descricao":"You are much beloved by the kami of a particular element, although you know not why that might be. As a result, the cost of increasing the Traits associated with one particular Ring, chosen when this Advantage is purchased, is decreased by 1. For example, if you choose Earth when you purchase this Advantage, the cost of increasing Stamina and Willpower is reduced by 1 Experience Point every time you increase them. Void may not be chosen for this Advantage. Phoenix characters may purchase this Ad"},{"id":"elemental_blessing_fire","nome":"Elemental Blessing (Fire)","tipo":"spiritual","custo":4,"descricao":"You are much beloved by the kami of a particular element, although you know not why that might be. As a result, the cost of increasing the Traits associated with one particular Ring, chosen when this Advantage is purchased, is decreased by 1. For example, if you choose Earth when you purchase this Advantage, the cost of increasing Stamina and Willpower is reduced by 1 Experience Point every time you increase them. Void may not be chosen for this Advantage. Phoenix characters may purchase this Ad"},{"id":"elemental_blessing_water","nome":"Elemental Blessing (Water)","tipo":"spiritual","custo":4,"descricao":"You are much beloved by the kami of a particular element, although you know not why that might be. As a result, the cost of increasing the Traits associated with one particular Ring, chosen when this Advantage is purchased, is decreased by 1. For example, if you choose Earth when you purchase this Advantage, the cost of increasing Stamina and Willpower is reduced by 1 Experience Point every time you increase them. Void may not be chosen for this Advantage. Phoenix characters may purchase this Ad"},{"id":"enlightened","nome":"Enlightened","tipo":"spiritual","custo":6,"descricao":"Your spiritual journey toward complete harmony with the universe as a whole has begun to reach its destination. In addition to whatever storyline effects your GM may choose to bestow on you, you also find it easier to enhance your connection to the Void. When you are using Experience Points to increase your Void Ring, the total cost is decreased by 2 points each time. Dragon and monk characters may purchase this Advantage for 5 points."},{"id":"friend_of_the_brotherhood","nome":"Friend of the Brotherhood","tipo":"spiritual","custo":5,"descricao":"You have studied among your allies at the Brotherhood of Shinsei, and as a result you understand your place in the universe slightly better than most. You may purchase Kiho (rules for Kiho are found in the Book of Water) as though you are a Monk of the Brotherhood of Shinsei, instead of paying a higher cost. You must still meet all other normal restrictions on learning Kiho. Only characters from Monk or Shugenja Schools (and not Monk characters from the Brotherhood of Shinsei) may purchase this "},{"id":"friend_of_the_elements_air","nome":"Friend of the Elements (Air)","tipo":"spiritual","custo":4,"descricao":"The spirits of a certain Element swirl about you at all times, lending their aid when possible even though you are likely unaware of their presence. Choose a Ring when this Advantage is purchased. Whenever you make a Trait Roll with either Trait associated with that Ring, you gain a Free Raise. Shugenja characters may purchase this Advantage for 3 points."},{"id":"friend_of_the_elements_earth","nome":"Friend of the Elements (Earth)","tipo":"spiritual","custo":4,"descricao":"The spirits of a certain Element swirl about you at all times, lending their aid when possible even though you are likely unaware of their presence. Choose a Ring when this Advantage is purchased. Whenever you make a Trait Roll with either Trait associated with that Ring, you gain a Free Raise. Shugenja characters may purchase this Advantage for 3 points."},{"id":"friend_of_the_elements_fire","nome":"Friend of the Elements (Fire)","tipo":"spiritual","custo":4,"descricao":"The spirits of a certain Element swirl about you at all times, lending their aid when possible even though you are likely unaware of their presence. Choose a Ring when this Advantage is purchased. Whenever you make a Trait Roll with either Trait associated with that Ring, you gain a Free Raise. Shugenja characters may purchase this Advantage for 3 points."},{"id":"friend_of_the_elements_void","nome":"Friend of the Elements (Void)","tipo":"spiritual","custo":4,"descricao":"The spirits of a certain Element swirl about you at all times, lending their aid when possible even though you are likely unaware of their presence. Choose a Ring when this Advantage is purchased. Whenever you make a Trait Roll with either Trait associated with that Ring, you gain a Free Raise. Shugenja characters may purchase this Advantage for 3 points."},{"id":"friend_of_the_elements_water","nome":"Friend of the Elements (Water)","tipo":"spiritual","custo":4,"descricao":"The spirits of a certain Element swirl about you at all times, lending their aid when possible even though you are likely unaware of their presence. Choose a Ring when this Advantage is purchased. Whenever you make a Trait Roll with either Trait associated with that Ring, you gain a Free Raise. Shugenja characters may purchase this Advantage for 3 points."},{"id":"friendly_kami_air","nome":"Friendly Kami (Air)","tipo":"spiritual","custo":5,"descricao":"A particular kami has befriended you, and stays in your vicinity at all times. Choose one element when this Advantage is purchased. You gain a bonus of +1k1 to the total of all Spell Casting Rolls made to cast Sense, Commune, or Summon with regard to that Element only. Only shugenja may purchase this Advantage. You may not select this Advantage for an Element in which you are Defi cient."},{"id":"friendly_kami_earth","nome":"Friendly Kami (Earth)","tipo":"spiritual","custo":5,"descricao":"A particular kami has befriended you, and stays in your vicinity at all times. Choose one element when this Advantage is purchased. You gain a bonus of +1k1 to the total of all Spell Casting Rolls made to cast Sense, Commune, or Summon with regard to that Element only. Only shugenja may purchase this Advantage. You may not select this Advantage for an Element in which you are Defi cient."},{"id":"friendly_kami_fire","nome":"Friendly Kami (Fire)","tipo":"spiritual","custo":5,"descricao":"A particular kami has befriended you, and stays in your vicinity at all times. Choose one element when this Advantage is purchased. You gain a bonus of +1k1 to the total of all Spell Casting Rolls made to cast Sense, Commune, or Summon with regard to that Element only. Only shugenja may purchase this Advantage. You may not select this Advantage for an Element in which you are Defi cient."},{"id":"friendly_kami_void","nome":"Friendly Kami (Void)","tipo":"spiritual","custo":5,"descricao":"A particular kami has befriended you, and stays in your vicinity at all times. Choose one element when this Advantage is purchased. You gain a bonus of +1k1 to the total of all Spell Casting Rolls made to cast Sense, Commune, or Summon with regard to that Element only. Only shugenja may purchase this Advantage. You may not select this Advantage for an Element in which you are Defi cient."},{"id":"friendly_kami_water","nome":"Friendly Kami (Water)","tipo":"spiritual","custo":5,"descricao":"A particular kami has befriended you, and stays in your vicinity at all times. Choose one element when this Advantage is purchased. You gain a bonus of +1k1 to the total of all Spell Casting Rolls made to cast Sense, Commune, or Summon with regard to that Element only. Only shugenja may purchase this Advantage. You may not select this Advantage for an Element in which you are Defi cient."},{"id":"fukurokujins_blessing","nome":"Fukurokujin's Blessing","tipo":"spiritual","custo":4,"descricao":"Fukurokujin’s Blessing (Dragon, Phoenix): The Fortune of Wisdom favors you above all others, and you reap the benefi ts of his patronage. Select one Lore Skill when you purchase this Advantage. Whenever you make a Skill Roll using that Skill, you gain a bonus of +1k1 to the total of that roll."},{"id":"great_destiny","nome":"Great Destiny","tipo":"spiritual","custo":5,"descricao":"The kharmic cycle has some great purpose in store for you, and the Celestial Order will conspire to keep you alive, no matter what, until your destiny can be fulfi lled. Once per session, when you suffer Wounds that would kill you, you are reduced to a single Wound remaining instead. This will only happen once per session, as there are limits to the extent that the Heavens will intervene in mortal affairs."},{"id":"hoteis_blessing","nome":"Hotei's Blessing","tipo":"spiritual","custo":4,"descricao":"Hotei’s Blessing: The Fortune of Contentment fi nds you a pleasing tribute to his works, and favors you with his sense of serenity and his jovial nature. Whenever an effect of any sort, either a spell, Advantage, Technique, or other effect, would cause you to lose Void Points, the instigator of the effect must fi rst defeat you in a Contested Void Roll. If the effect already calls for a Contested Roll of some kind, your roll is instead increased by +10."},{"id":"inaris_blessing","nome":"Inari's Blessing","tipo":"spiritual","custo":3,"descricao":"The Fortune of Rice is a lesser Fortune, but nevertheless is among the most revered entities throughout the whole of Rokugan, particularly by the common people of the Empire. When fasting or deprived of food, you do not suffer from the normal inability to regain Void Points, although other penalties apply as normal."},{"id":"inner_gift","nome":"Inner Gift","tipo":"spiritual","custo":7,"descricao":"You possess a mysterious gift that even shugenja cannot fully understand. Monks describe individuals such as yourself as existing in a unique state of harmony with the universe, but then they say that sort of thing a lot. Your gift may be a manifestation of the kami, perhaps an indicator of spirit ancestry, or any of a number of different theories. The exact nature of an Inner Gift should be discussed with the GM before taking this Advantage."},{"id":"ishikendo","nome":"Ishiken-do","tipo":"spiritual","custo":8,"descricao":"You have that rarest of gifts, the ability to commune with the Void itself. This gift is similar in many respects to the ability to speak to the kami, save that there are no naturally occurring kami of the Void; the Void itself is a living thing, both everything and nothing all at once. You may cast Void spells as described later in this chapter. Only shugenja may take this Advantage, and without this Advantage a character cannot cast Void spells. Phoenix characters may purchase this Advantage f"},{"id":"jurojins_blessing","nome":"Jurojin's Blessing","tipo":"spiritual","custo":4,"descricao":"Jurojin’s Blessing (Scorpion): The Fortune of Longevity favors you, and as a result you can expect a long and healthy life. Whenever you are rolling to resist the effects of a disease or poison, you gain a bonus of +2k0 to the total of the roll."},{"id":"kharmic_tie_1","nome":"Kharmic Tie 1","tipo":"spiritual","custo":1,"descricao":"Your destiny is not yours alone, but is bonded to that of another in some fundamental way. You may have been close to this other person during a previous life, or perhaps your destiny in this life will yet be entwined in theirs in some essential manner. Select one person when purchasing this Advantage. For each point spent on this Advantage, once per session you gain a bonus of +1k1 to the total of all attack rolls made when fighting for or protecting the person to whom you are bonded."},{"id":"luck","nome":"Luck","tipo":"spiritual","custo":3,"descricao":"Fortune favors the mortal man. A number of times per session equal to your rank in this Advantage, you may choose to immediately re-roll any one roll you make, keeping the higher of the two results."},{"id":"magic_resistance","nome":"Magic Resistance","tipo":"spiritual","custo":2,"descricao":"For reasons beyond your understanding, the kami are reluctant to involve themselves with you in any way. For each rank you possess in this Advantage, all elemental spells targeting you have the TN of the Spell Casting Roll made to enact it increased by +3. Maho, gaijin, and non-human forms of magic are not affected by this Advantage."},{"id":"touch_of_the_spirit_realms_chikushudo","nome":"Touch of the Spirit Realms (Chikushudo)","tipo":"spiritual","custo":5,"descricao":"Somehow, a fragment of the essence of a spirit realm is present in your soul, and suffuses everything you do. Shugenja characters may purchase this Advantage for 4 points. Chikushudo: You gain a bonus of +1k1 on all Animal Handling rolls."},{"id":"touch_of_the_spirit_realms_gakido","nome":"Touch of the Spirit Realms (Gaki-do)","tipo":"spiritual","custo":5,"descricao":"Somehow, a fragment of the essence of a spirit realm is present in your soul, and suffuses everything you do. Shugenja characters may purchase this Advantage for 4 points. Gaki-do: When you resolve an attack that kills an opponent, you immediately regain 5 Wounds."},{"id":"touch_of_the_spirit_realms_jigoku","nome":"Touch of the Spirit Realms (Jigoku)","tipo":"spiritual","custo":5,"descricao":"Somehow, a fragment of the essence of a spirit realm is present in your soul, and suffuses everything you do. Shugenja characters may purchase this Advantage for 4 points. Jigoku: You may add your Taint Rank to any attack roll and any Skill roll or Trait roll that uses a Physical Trait. If you are Lost, you add twice your Taint Rank rather than your normal bonus. You may not take this Advantage unless you possess the Shadowlands Taint."},{"id":"touch_of_the_spirit_realms_maigo_no_musha","nome":"Touch of the Spirit Realms (Maigo no Musha)","tipo":"spiritual","custo":5,"descricao":"Somehow, a fragment of the essence of a spirit realm is present in your soul, and suffuses everything you do. Shugenja characters may purchase this Advantage for 4 points. Maigo no Musha: When you are awarded Glory in an amount greater than 3 points, you receive one additional point."},{"id":"touch_of_the_spirit_realms_meido","nome":"Touch of the Spirit Realms (Meido)","tipo":"spiritual","custo":5,"descricao":"Somehow, a fragment of the essence of a spirit realm is present in your soul, and suffuses everything you do. Shugenja characters may purchase this Advantage for 4 points. Meido: You gain a bonus of +2k0 to Contested Rolls versus attempts to manipulate you in social interactions, such as use of the Courtier Skill."},{"id":"touch_of_the_spirit_realms_sakkaku","nome":"Touch of the Spirit Realms (Sakkaku)","tipo":"spiritual","custo":5,"descricao":"Somehow, a fragment of the essence of a spirit realm is present in your soul, and suffuses everything you do. Shugenja characters may purchase this Advantage for 4 points. Sakkaku: You gain a bonus of +1k1 on Sincerity (Deceit) rolls."},{"id":"touch_of_the_spirit_realms_tengoku","nome":"Touch of the Spirit Realms (Tengoku)","tipo":"spiritual","custo":5,"descricao":"Somehow, a fragment of the essence of a spirit realm is present in your soul, and suffuses everything you do. Shugenja characters may purchase this Advantage for 4 points. Tengoku: You gain a bonus of +2k0 on Earth Ring Rolls made to resist the Shadowlands Taint."},{"id":"touch_of_the_spirit_realms_toshigoku","nome":"Touch of the Spirit Realms (Toshigoku)","tipo":"spiritual","custo":8,"descricao":"Somehow, a fragment of the essence of a spirit realm is present in your soul, and suffuses everything you do. Shugenja characters may purchase this Advantage for 4 points. Toshigoku: When making a Move Action to get into range to attack an opponent, the distance of your move is increased by 5 feet. (This costs 8 points instead of 5.)"},{"id":"touch_of_the_spirit_realms_yomi","nome":"Touch of the Spirit Realms (Yomi)","tipo":"spiritual","custo":7,"descricao":"Somehow, a fragment of the essence of a spirit realm is present in your soul, and suffuses everything you do. Shugenja characters may purchase this Advantage for 4 points. Yomi: Select one School Skill. You gain a bonus of +1k0 on all Skill Rolls made using that Skill. (This costs 7 points instead of 5.)"},{"id":"touch_of_the_spirit_realms_yumedo","nome":"Touch of the Spirit Realms (Yume-do)","tipo":"spiritual","custo":5,"descricao":"Somehow, a fragment of the essence of a spirit realm is present in your soul, and suffuses everything you do. Shugenja characters may purchase this Advantage for 4 points. Yume-do: You can recover all expended Void Points with only four hours of rest, rather than the normal full night of eight hours of rest."},{"id":"great_potential","nome":"Great Potential","tipo":"varies","custo":5,"descricao":"Within you lies the potential to excel at one particular endeavor, perhaps more so than any other living soul in the Empire. Select any one Skill when you purchase this Advantage. When you make Raises on a Skill Roll using that Skill, your Raises are limited by your rank in that Skill instead of your Void Ring. If your Void Ring is higher, however, you may use that as a measure for your Raises if you so choose."}],"desvantagens":[{"id":"ascetic","nome":"Ascetic","tipo":"mental","custo":2,"descricao":"You have no taste for or interest in material things, and this minimalist attitude has impacted how others view you. Your School Outfi t includes only weapons, armor, clothing, necessary tools of the trade for your profession (such as a scroll satchel for shugenja), and nothing else. Any time you would be awarded Glory as a result of your actions, you receive only half the normal amount. Coupled with the normal restriction for Monks in gaining Glory, ascetic monk characters would only gain one q"},{"id":"brash","nome":"Brash","tipo":"mental","custo":3,"descricao":"You have a notoriously short temper and are likely to answer anything you perceive as a threat with steel. If you are threatened or insulted, you must make a Willpower Trait roll (adding your Honor Rank to the total) at a TN of 25, or you will attack immediately. This Disadvantage is worth 4 points to Lion characters."},{"id":"cant_lie","nome":"Can't Lie","tipo":"mental","custo":2,"descricao":"You are psychologically incapable of telling a lie, perhaps because it has been so thoroughly drilled into your nature by your honorable family. Not only can you not tell a lie, but if someone in your presence tells a lie and you know that it is untrue, you must succeed at a Willpower Trait Roll (TN 20) or immediately correct them. This can cause untold diffi culty in court settings and can lead to complete disgrace if you are not careful."},{"id":"compulsion","nome":"Compulsion","tipo":"mental","custo":2,"descricao":"There is some activity in which you are hopelessly compelled to partake. It is a ritual that is so ingrained in your behavior that it requires a feat of will to forsake it, even in dire circumstances. This may be something illicit and addictive, such as sake or gambling, or it may be as innocuous as visiting every major temple you pass. The basic Disadvantage requires a Willpower Trait Roll of TN 15 to overcome. The TN of the roll increases by 5 for every additional point gained by the Disadvant"},{"id":"consumed_control","nome":"Consumed (Control)","tipo":"mental","custo":4,"descricao":"You have walked the path of Shourido, and it has consumed you utterly. One of the tenets has become your existence, and you live only to enact it. These Disadvantages are worth one additional point to Spider characters. Control (4 Points): You are determined to control and dominate others, no matter what the cost, and can never admit that you are wrong or might have made a mistake. You suffer a –1k1 penalty on all Etiquette and Sincerity rolls."},{"id":"consumed_determination","nome":"Consumed (Determination)","tipo":"mental","custo":6,"descricao":"You have walked the path of Shourido, and it has consumed you utterly. One of the tenets has become your existence, and you live only to enact it. These Disadvantages are worth one additional point to Spider characters. Determination (6 Points): You believe you can do anything on your own, without the need for any outside help or agency, or even any inner strength. You cannot spend Void Points to enhance die-rolls. (You can still spend Void Points for other purposes and enhancements.)"},{"id":"consumed_insight","nome":"Consumed (Insight)","tipo":"mental","custo":4,"descricao":"You have walked the path of Shourido, and it has consumed you utterly. One of the tenets has become your existence, and you live only to enact it. These Disadvantages are worth one additional point to Spider characters. Insight (4 Points): You seek profound insight in even the most trivial things, to the exclusion of normal activity. Choose one of your School Skills. Any time you use this Skill, you must make a Willpower Trait Roll at TN 20 or become lost in reverie as you seek a deeper understa"},{"id":"consumed_knowledge","nome":"Consumed (Knowledge)","tipo":"mental","custo":4,"descricao":"You have walked the path of Shourido, and it has consumed you utterly. One of the tenets has become your existence, and you live only to enact it. These Disadvantages are worth one additional point to Spider characters. Knowledge (4 Points): You are obsessed with gaining more knowledge and understanding of all things, no matter what the cost. Any time you encounter some topic, area of research, or new idea, no matter how trivial, scandalous, or blasphemous it might be, you must make a Willpower "},{"id":"consumed_perfection","nome":"Consumed (Perfection)","tipo":"mental","custo":5,"descricao":"You have walked the path of Shourido, and it has consumed you utterly. One of the tenets has become your existence, and you live only to enact it. These Disadvantages are worth one additional point to Spider characters. Perfection (5 Points): You must do everything perfectly, even when there is no need to do so in order to succeed. Any time you make a Skill or Spell Casting Roll, you must call one extra Raise for no effect, or the roll will automatically fail. This Disadvantage is worth 6 points"},{"id":"consumed_strength","nome":"Consumed (Strength)","tipo":"mental","custo":5,"descricao":"You have walked the path of Shourido, and it has consumed you utterly. One of the tenets has become your existence, and you live only to enact it. These Disadvantages are worth one additional point to Spider characters. Strength (5 Points): Raw physical power is the only way to defeat your foes. Finesse and negotiation are for fools. You must call one extra Raise (for no effect) in order to use the Called Shot, Feint, or Disarm Maneuvers in combat, and you suffer a -1k0 penalty to any Etiquette "},{"id":"consumed_will","nome":"Consumed (Will)","tipo":"mental","custo":4,"descricao":"You have walked the path of Shourido, and it has consumed you utterly. One of the tenets has become your existence, and you live only to enact it. These Disadvantages are worth one additional point to Spider characters. Will (4 Points): You must get your way, and others must give way to your wishes. You have no respect for the opinions or desires of others. You suffer a –1k1 penalty to all Courtier and Temptation Skill Rolls, as your refusal to compromise or respect others makes you socially int"},{"id":"contrary","nome":"Contrary","tipo":"mental","custo":3,"descricao":"Your strong will and rigid view of the world insists not only that you develop an opinion on everything, but that you must share it at every opportunity. During any debate or dispute, or even casual discussion, you feel compelled to weigh in and attempt to persuade others to see the matter from your point of view. In any tense situation, you must succeed at a Willpower Trait Roll to avoid taking action, whether to resolve a confl ict physically or simply to interject into an argument. The TN for"},{"id":"disbeliever","nome":"Disbeliever","tipo":"mental","custo":3,"descricao":"You have experienced a dramatic revelation that has shattered your faith in Rokugani theology. Perhaps you believe that the Fortunes have no interest in mankind, or perhaps you have come to believe that the Tao of Shinsei holds nothing but empty promises. If your disbelief were made public knowledge, you would be shunned by all properly pious individuals everywhere, and any memberships you possess in temples or monastic orders would be instantly revoked. Your lack of piety makes you uncomfortabl"},{"id":"doubt","nome":"Doubt","tipo":"mental","custo":4,"descricao":"Something has happened to cause you to question your training, so much so that it interferes with your ability to perform properly. Select one of your School Skills. Every time you use this Skill, you must declare one Raise that confers no benefit."},{"id":"driven","nome":"Driven","tipo":"mental","custo":2,"descricao":"You are possessed by some goal, and will sacrifice almost anything to accomplish it, even your honor. Family, friends, material possessions, and even Bushido mean nothing compared to the potential completion of this goal, whatever it may be."},{"id":"failure_of_bushido_compassion","nome":"Failure of Bushido (Compassion)","tipo":"mental","custo":3,"descricao":"Try though you might to adhere to the code of bushido, one tenet in particular is simply foreign to you, and you have no concept of how to exemplify it through your actions. This Disadvantage is worth 1 additional point to ninja characters. Compassion (3 Points): You must spend a Void point before you are able to act on behalf of someone of lower Status or social caste."},{"id":"failure_of_bushido_courage","nome":"Failure of Bushido (Courage)","tipo":"mental","custo":4,"descricao":"Try though you might to adhere to the code of bushido, one tenet in particular is simply foreign to you, and you have no concept of how to exemplify it through your actions. This Disadvantage is worth 1 additional point to ninja characters. Courage (4 Points): When facing an opponent of higher Glory or Status, or when facing a Shadowlands opponent, the TN of all rolls you make is increased by +5."},{"id":"failure_of_bushido_courtesy","nome":"Failure of Bushido (Courtesy)","tipo":"mental","custo":4,"descricao":"Try though you might to adhere to the code of bushido, one tenet in particular is simply foreign to you, and you have no concept of how to exemplify it through your actions. This Disadvantage is worth 1 additional point to ninja characters. Courtesy (4 Points): Any time you make a Social Skill Roll to apologize or avoid giving offense, you must call a Raise for no effect, or the roll will automatically fail."},{"id":"failure_of_bushido_duty","nome":"Failure of Bushido (Duty)","tipo":"mental","custo":6,"descricao":"Try though you might to adhere to the code of bushido, one tenet in particular is simply foreign to you, and you have no concept of how to exemplify it through your actions. This Disadvantage is worth 1 additional point to ninja characters. Duty (6 Points): You cannot spend Void Points to negate Wounds."},{"id":"failure_of_bushido_honesty","nome":"Failure of Bushido (Honesty)","tipo":"mental","custo":3,"descricao":"Try though you might to adhere to the code of bushido, one tenet in particular is simply foreign to you, and you have no concept of how to exemplify it through your actions. This Disadvantage is worth 1 additional point to ninja characters. Honor (3 Points): You cannot add your Honor Rank to any roll to resist Intimidation or Temptation."},{"id":"failure_of_bushido_honor","nome":"Failure of Bushido (Honor)","tipo":"mental","custo":3,"descricao":"Try though you might to adhere to the code of bushido, one tenet in particular is simply foreign to you, and you have no concept of how to exemplify it through your actions. This Disadvantage is worth 1 additional point to ninja characters. Honor (3 Points): You cannot add your Honor Rank to any roll to resist Intimidation or Temptation. c Sincerity (4 Points): Any time you are rolling the Sincerity Skill to convince someone of what you are saying, you must call an extra Raise for no effect, or "},{"id":"failure_of_bushido_sincerity","nome":"Failure of Bushido (Sincerity)","tipo":"mental","custo":4,"descricao":"Try though you might to adhere to the code of bushido, one tenet in particular is simply foreign to you, and you have no concept of how to exemplify it through your actions. This Disadvantage is worth 1 additional point to ninja characters. Sincerity (4 Points): Any time you are rolling the Sincerity Skill to convince someone of what you are saying, you must call an extra Raise for no effect, or the roll automatically fails."},{"id":"fascination","nome":"Fascination","tipo":"mental","custo":1,"descricao":"You are completely fascinated by some subject, and will go to great lengths to learn more about it or to experience it in new ways. Typical subjects of a samurai’s fascination include music, horses, poetry, and history. This fascination badly impedes your judgment, and you will take even dishonorable actions to learn more, which could end in absolute disgrace if your actions are discovered."},{"id":"frail_mind","nome":"Frail Mind","tipo":"mental","custo":3,"descricao":"You have difficulty concentrating, even when focusing your attention on an opponent. Whenever you make a Contested Roll using Willpower, your opponent gains a bonus of +2k0."},{"id":"greedy","nome":"Greedy","tipo":"mental","custo":3,"descricao":"Material wealth is more important to you than anything else, even though samurai are not meant to be sullied with commercial interests. Opponents attempting to use Temptation (Bribery) rolls against you gain a bonus of +1k1 to the total of the roll. This Disadvantage is worth 4 points to Mantis characters."},{"id":"gullible","nome":"Gullible","tipo":"mental","custo":4,"descricao":"Your trust is given easily and you place tremendous faith in those whom you trust, unfortunately making it very simple for others to take advantage of your naïve nature. Opponents attempting to use Sincerity (Deceit) against you gain a bonus of +1k1 to the total of their rolls."},{"id":"idealistic","nome":"Idealistic","tipo":"mental","custo":2,"descricao":"You adhere closely to the code of Bushido, perhaps too closely, and you have a hopelessly naïve view of the world and how things work. You have impossible standards that not even the most heroic individual could hope to meet, much less you. Whenever you lose Honor, the loss is increased by 1 point. This Disadvantage is worth 3 points to Lion characters."},{"id":"insensitive","nome":"Insensitive","tipo":"mental","custo":2,"descricao":"Your primary interest is in yourself and things that you care about. The plight of others simply does not interest you, and you fi nd it diffi cult to pretend otherwise. With the exception of those who contribute directly to your well being, such as your lord, you must spend a Void Point to place yourself at risk for the welfare of any other person unless there is an immediate benefi t for you personally. This Disadvantage is worth 3 points to Scorpion characters."},{"id":"jealousy","nome":"Jealousy","tipo":"mental","custo":3,"descricao":"You are obsessed with outperforming another individual in order to prove that you deserve all the things he has, things you perceive as superior to your own. Choose one other PC or a major NPC in your campaign. You are obsessed with overcoming them at all costs, and will go to any lengths to do so. Once you have bested the target of your jealousy, your nature will cause you to become jealous of someone else."},{"id":"lost_love","nome":"Lost Love","tipo":"mental","custo":3,"descricao":"You shared a bond of true love with someone once, and have since lost it. This need not be romantic love, as familial or brotherly love lost is equally tragic. You tend to suffer bouts of melancholy when reminded of your lost love. When you are reminded of your loss, all your TNs are increased by 5 until you spend a Void Point to regain your focus. This disruption of your concentration cannot happen more than twice per day, and at least one hour must pass between instances."},{"id":"obtuse","nome":"Obtuse","tipo":"mental","custo":3,"descricao":"The point of many fi ne things simply escapes you. Poetry, art, music… it all seems meaningless to you. The Experience Point cost for increasing any High Skill other than Investigation or Medicine is doubled. This Disadvantage is worth 4 points to Crab and bushi characters."},{"id":"overconfident","nome":"Overconfident","tipo":"mental","custo":3,"descricao":"You possess a grossly inflated view of your own prowess, and are often incapable of recognizing when a situation is beyond your ability to handle. When outnumbered or facing a clearly superior enemy (whether in court or in battle), you must succeed at a Perception Trait Roll (TN 20) in order to recognize the situation for what it is and leave instead of engaging. This Disadvantage is worth 4 points to Lion and Mantis characters."},{"id":"phobia","nome":"Phobia","tipo":"mental","custo":1,"descricao":"You possess an irrational fear that you cannot overcome, no matter how much you struggle to convince yourself that there is no reason behind it. When confronted with the object of your phobia, all of your TNs are increased by +5 for every point you possess in this Disadvantage."},{"id":"softhearted","nome":"Soft-Hearted","tipo":"mental","custo":2,"descricao":"Human life is precious to you, so much so that you have difficulty executing the basic duty of the samurai caste: to kill. When faced with the opportunity to kill another human being, you must succeed at a Willpower Trait Roll (TN 20), or you are unable to do so. If you do kill another, the TNs of all your rolls are increased by +10 for one day as you are wracked with guilt. This penalty is not cumulative with multiple deaths. This Disadvantage could potentially also apply to killing nonhuman cr"},{"id":"true_love","nome":"True Love","tipo":"mental","custo":3,"descricao":"True love in Rokugan can be a wonderful experience, but more often than not it is a disaster, for it is rare for samurai to be allowed to marry for love. Whenever you are in a position where you must choose between love and duty, you must spend a Void Point before you can choose your duty over your lover."},{"id":"bad_eyesight","nome":"Bad Eyesight","tipo":"physical","custo":3,"descricao":"Your eyesight is exceptionally poor, whether as a result of some medical condition or even from a missing eye. You suffer a penalty of -1k1 to all ranged attack rolls and to any Perception-based rolls."},{"id":"bad_health","nome":"Bad Health","tipo":"physical","custo":4,"descricao":"You suffer from a chronic medical condition that constantly renders you weak and susceptible to both illness and injury. Your Earth Ring is considered one rank lower for the purposes of determining Wound Ranks and for resisting diseases."},{"id":"blind","nome":"Blind","tipo":"physical","custo":6,"descricao":"You possess no natural eyesight whatsoever save for a slight ability to determine light and dark. You suffer a penalty of -3k3 to all ranged attack rolls and -1k1 to melee attack rolls. Your base Armor TN is equal to your Refl exes Trait plus 5 (armor adds bonuses as normal). Your Water Ring is considered two ranks lower for the purposes of determining how far you may move as part of a Move Action. Any attempt at a Simple Move Action requires an Athletics/Agility roll (TN 20) or you are knocked "},{"id":"disturbing_countenance","nome":"Disturbing Countenance","tipo":"physical","custo":3,"descricao":"Something about your appearance causes others to respond to you with concern and caution. You are not necessarily unattractive, merely disturbing in some way. The TN of all your Social Skill Rolls is increased by +5. This Disadvantage is worth 4 points to Spider characters."},{"id":"epilepsy","nome":"Epilepsy","tipo":"physical","custo":4,"descricao":"You possess a rare and poorly understood condition that causes you to experience seizures from time to time, consisting of a trance-like state, rigid muscle spasms, and frothing at the mouth. These are brought on by high stress or fl ashing lights, such as fi reworks displays. Under such circumstances, you must succeed at a Willpower Trait Roll at TN 15 to avoid the seizure. If you fail, you experience a seizure and may roll a second Willpower Trait Roll (TN 10) each minute to end it. This Disad"},{"id":"lame","nome":"Lame","tipo":"physical","custo":4,"descricao":"One of your legs is withered or perhaps even near-useless, either due to a birth defect, a crippling injury, or a ravaging disease. Your Water Ring is considered 1 for the purposes of determining Move Actions, and any Agility Trait Rolls or Agility-based Skill Rolls that require any sort of activity in your lower limbs suffer a penalty of +10 to the TN."},{"id":"low_pain_threshold","nome":"Low Pain Threshold","tipo":"physical","custo":4,"descricao":"Your ability to focus in the face of pain is less than that of others. The TN penalties you suffer due to Wound Ranks are increased by +5 each rank."},{"id":"missing_limb","nome":"Missing Limb","tipo":"physical","custo":6,"descricao":"One of your limbs is missing, either through catastrophic injury or due to an unfortunate defect of your birth. You suffer a penalty of +10 to all TNs involving the use of the limb missing. For example, wielding a two-handed weapon with only one arm would have a +10 to all TNs, but an Athletics (Running) Skill Roll would not."},{"id":"permanent_wound","nome":"Permanent Wound","tipo":"physical","custo":4,"descricao":"Some wounds will not heal, not matter how often they are treated or by what means. Your first Wound Rank is always considered full. This Disadvantage is worth 5 points to bushi characters."},{"id":"small","nome":"Small","tipo":"physical","custo":3,"descricao":"You are noticeably smaller than average for a denizen of the Emerald Empire. As a result, your Water Ring is considered one rank lower for determining the distance of your Move Actions, and you suffer a penalty of -1k0 on the Damage Rolls of all your melee attacks. You may not take the Large Advantage."},{"id":"weakness_agility","nome":"Weakness (Agility)","tipo":"physical","custo":6,"descricao":"You have a significant weakness of some sort, either physical or mental, that is diffi cult to overcome even under ideal circumstances. Select one Trait. That Trait is treated as if it were one rank lower for the purposes of all rolls and Trait-based mechanical effects."},{"id":"weakness_awareness","nome":"Weakness (Awareness)","tipo":"physical","custo":6,"descricao":"You have a significant weakness of some sort, either physical or mental, that is diffi cult to overcome even under ideal circumstances. Select one Trait. That Trait is treated as if it were one rank lower for the purposes of all rolls and Trait-based mechanical effects."},{"id":"weakness_intelligence","nome":"Weakness (Intelligence)","tipo":"physical","custo":6,"descricao":"You have a significant weakness of some sort, either physical or mental, that is diffi cult to overcome even under ideal circumstances. Select one Trait. That Trait is treated as if it were one rank lower for the purposes of all rolls and Trait-based mechanical effects."},{"id":"weakness_perception","nome":"Weakness (Perception)","tipo":"physical","custo":6,"descricao":"You have a significant weakness of some sort, either physical or mental, that is diffi cult to overcome even under ideal circumstances. Select one Trait. That Trait is treated as if it were one rank lower for the purposes of all rolls and Trait-based mechanical effects."},{"id":"weakness_reflexes","nome":"Weakness (Reflexes)","tipo":"physical","custo":6,"descricao":"You have a significant weakness of some sort, either physical or mental, that is diffi cult to overcome even under ideal circumstances. Select one Trait. That Trait is treated as if it were one rank lower for the purposes of all rolls and Trait-based mechanical effects."},{"id":"weakness_stamina","nome":"Weakness (Stamina)","tipo":"physical","custo":6,"descricao":"You have a significant weakness of some sort, either physical or mental, that is diffi cult to overcome even under ideal circumstances. Select one Trait. That Trait is treated as if it were one rank lower for the purposes of all rolls and Trait-based mechanical effects."},{"id":"weakness_strength","nome":"Weakness (Strength)","tipo":"physical","custo":6,"descricao":"You have a significant weakness of some sort, either physical or mental, that is diffi cult to overcome even under ideal circumstances. Select one Trait. That Trait is treated as if it were one rank lower for the purposes of all rolls and Trait-based mechanical effects."},{"id":"weakness_willpower","nome":"Weakness (Willpower)","tipo":"physical","custo":6,"descricao":"You have a significant weakness of some sort, either physical or mental, that is diffi cult to overcome even under ideal circumstances. Select one Trait. That Trait is treated as if it were one rank lower for the purposes of all rolls and Trait-based mechanical effects."},{"id":"antisocial","nome":"Antisocial","tipo":"social","custo":2,"descricao":"You find the presence of others uncomfortable, so much so that it is immediately obvious to those around you. Your preference for solitude causes you to behave in a manner that might best be described as rude. If you take the 2 point version of this Disadvantage, you suffer a penalty of -1k0 to all Social Skill Rolls. For 4 points, the penalty is -1k1. This Disadvantage is worth 1 additional point to Crab characters."},{"id":"bitter_betrothal","nome":"Bitter Betrothal","tipo":"social","custo":2,"descricao":"You have been promised to another, or perhaps are already married, and neither of you are at all pleased with the situation. Your spouse despises you, but he or she at least has the decorum to manage your estate properly… for the most part. Your mutual dislike, however, can result in tremendous diffi culty with even simple domestic or bureaucratic tasks. This Disadvantage is worth 3 points to Imperial characters."},{"id":"black_sheep","nome":"Black Sheep","tipo":"social","custo":3,"descricao":"For whatever reason, your family is completely disgusted with you and your actions. You have not been cast out and made ronin, but you are no longer welcome in your own household. You may only maintain proper relations with any member of your family via the Allies Advantage, and if you attend one of your own family’s Schools, you may not advance in School Rank without going to great lengths to fi nd a willing teacher."},{"id":"blackmailed","nome":"Blackmailed","tipo":"social","custo":0,"descricao":"Someone out there knows of some dark secret of yours, or some horrible indiscretion you committed in a moment of weakness. What’s worse, they intend to make you pay for it. The cost of this Disadvantage is equal to your Status Rank. The person blackmailing you will contact you periodically and require certain things of you. You must weigh these actions against the potential disgrace if your secret is discovered, and act accordingly."},{"id":"cast_out","nome":"Cast Out","tipo":"social","custo":1,"descricao":"You, or perhaps your entire line, were at some point denounced by an order of monks, an act that can bring shame to even the least pious samurai. One point in this Disadvantage indicates the disapproval of a single temple, while three points represents a major sect within the Brotherhood of Shinsei. Monks of this sect treat you as if your Glory Rank were in fact Infamy (see the Infamous Disadvantage)."},{"id":"dark_secret","nome":"Dark Secret","tipo":"social","custo":4,"descricao":"You possess some horrifi c secret that could lead not only to your ruination, but perhaps others in your family as well. It may be something terrible you have learned about your family that you alone know (if a venerated ancestor was secretly a dishonorable buffoon), or something you personally have done (you may be a member of the Kolat or Gozoku). If your secret is exposed, you may be required to commit seppuku or possibly even be executed. This Disadvantage is worth 5 points to ninja characte"},{"id":"dependant","nome":"Dependant","tipo":"social","custo":0,"descricao":"Someone who is largely incapable of defending himself or herself requires you to look after them. This may be an elderly relative, a naïve spouse, or a small child. The point value of this Disadvantage varies depending upon how helpless the individual is and how frequently they appear in the campaign. A small child completely dependant upon you for everything might cost 5 or 6 points, while a spouse who is independent but whom you must consider before all major decisions might be worth 2 or 3 po"},{"id":"dishonored","nome":"Dishonored","tipo":"social","custo":5,"descricao":"You have been dishonored so spectacularly that your name has been removed from your family’s records, and most within the family act as if you were dead. However, the Clan has granted you the opportunity to wash away your dishonor if you perish in battle. This custom, which started with the Lion Clan, is known as the Deathseeker tradition. You possess Status Rank 1 and may not gain Status so long as you possess this Disadvantage."},{"id":"forced_retirement","nome":"Forced Retirement","tipo":"social","custo":4,"descricao":"You have been forced into early retirement by entering a monastery, perhaps due to political reasons or because of some public disgrace. You may not advance any further in your School. When you gain a new Insight Rank, you must instead begin taking ranks of an unaligned Monk School (see the Book of Water). You need not purchase the Multiple Schools Advantage for this. You are no longer considered a member of your Clan. This Disadvantage is worth 5 points to monk characters."},{"id":"gaijin_name","nome":"Gaijin Name","tipo":"social","custo":1,"descricao":"Either due to your lineage or your parents’ fascination with another culture, you possess a name that is clearly not of Rokugani origin. Although there is no honor loss for such a thing, others regard you questionably as a result. Your individual dice may only explode once on a Social Skill Roll (that is, each die has a maximum possible result of 20). This Disadvantage is worth 2 points to Unicorn characters."},{"id":"hostage","nome":"Hostage","tipo":"social","custo":3,"descricao":"In the resolution of a dispute between Clans, it is not uncommon for hostages to be exchanged as “guests” of one another’s Clans for a specifi ed amount of time. This ensures that the treaty in question is not broken. Although you are treated respectfully and as a guest in the lands of another Clan, you are not permitted to leave without escort and, should war break out between your Clan and your hosts, your life will be forfeit."},{"id":"infamous","nome":"Infamous","tipo":"social","custo":2,"descricao":"You are well known among some circles, but not in the manner you might wish. Rather than being known for your valor and your courage, you are known for being ruthless, cruel, and dangerous. This reputation may not be deserved, but it is widespread enough that it no longer matters if it is true. Your starting Glory Rank is replaced with an Infamy Rank, which serves in exactly the same capacity, save for the reaction of those who recognize you."},{"id":"lechery","nome":"Lechery","tipo":"social","custo":2,"descricao":"Physical pleasure is a weakness of yours, and you spend considerable time pursuing it. When an opponent makes a Temptation (Seduction) roll against you, he gains a bonus of +1k1 to the total of his roll."},{"id":"obligation","nome":"Obligation","tipo":"social","custo":3,"descricao":"There is someone to whom you are indebted or for whom you must fulfill some significant duty. The nature of this debt can vary considerably, but when it comes due, nothing else matters. You must honor it, even if it leads to your ruination. The fi rst level of this Disadvantage is a relatively minor matter that nevertheless demands your full attention. The second level represents a major, signifi cant obligation that could potentially damage your family’s standing if you do not devote considerab"},{"id":"rumormonger","nome":"Rumormonger","tipo":"social","custo":4,"descricao":"You cannot resist the temptation to spread rumors and gossip, no matter how ridiculous or outlandish they might seem. When presented with an opportunity to spread rumors, to resist doing so you must succeed at a Willpower Trait Roll with a TN equal to 5x the Glory Rank of the highest-Glory individual involved in the rumor. This Disadvantage is worth 5 points to courtier characters."},{"id":"social_disadvantage","nome":"Social Disadvantage","tipo":"social","custo":3,"descricao":"You have slipped from your position within the Celestial Order, and your place in society refl ects that. You begin with Status Rank 0."},{"id":"sworn_enemy","nome":"Sworn Enemy","tipo":"social","custo":3,"descricao":"You have earned an enemy, one who will stop at nothing to see you defeated or even killed. The basic version of this Advantage assumes that your enemy is of equal Insight Rank. For each Insight Rank above yours your enemy possesses, increase the value of this Disadvantage by 1. For 2 additional points, the enemy becomes your kharmic nemesis, and you may not spend Void Points when opposing him or her in any situation."},{"id":"sworn_enemy_kharmic","nome":"Sworn Enemy (Kharmic)","tipo":"social","custo":5,"descricao":"You have earned an enemy, one who will stop at nothing to see you defeated or even killed. The basic version of this Advantage assumes that your enemy is of equal Insight Rank. For each Insight Rank above yours your enemy possesses, increase the value of this Disadvantage by 1. For 2 additional points, the enemy becomes your kharmic nemesis, and you may not spend Void Points when opposing him or her in any situation."},{"id":"bad_fortune","nome":"Bad Fortune","tipo":"spiritual","custo":3,"descricao":"Kharma is a powerful force, and sometimes it is a destructive one as well. There is something unpleasant in store for you, and you may have no idea what it is until it is far too late. Bad fortunes take an almost infi nite variety of forms, all worth the same number of points, and players and GMs should discuss the form of a Bad Fortune during character creation. Some of the more common versions include: * Secret Love: Somewhere, someone is madly in love with you, and will go to any lengths to s"},{"id":"bentens_curse","nome":"Benten's Curse","tipo":"spiritual","custo":3,"descricao":"The Fortune of Romantic Love has forsaken you utterly, and others fi nd your company unpleasant as a result. The TN of any Etiquette roll you make is increased by +10."},{"id":"bishamons_curse","nome":"Bishamon's Curse","tipo":"spiritual","custo":3,"descricao":"The Fortune of Strength fi nds you offensive to his divine essence, and has denied you his domain. Your Strength is considered one rank lower for determining the Damage Roll of any weapon you wield."},{"id":"cursed_by_the_realm_chikushudo","nome":"Cursed by the Realm (Chikushudo)","tipo":"spiritual","custo":4,"descricao":"The influence of the spirit realms can be felt throughout the mortal realm of Ningen-do, and for whatever reason, the essence of one realm in particular has marked you as a foe of all that emanate from that realm. This Disadvantage is worth 5 points to shugenja characters. Chikushudo: You suffer a penalty of -1k1 to all Animal Handling rolls."},{"id":"cursed_by_the_realm_gakido","nome":"Cursed by the Realm (Gaki-do)","tipo":"spiritual","custo":4,"descricao":"The influence of the spirit realms can be felt throughout the mortal realm of Ningen-do, and for whatever reason, the essence of one realm in particular has marked you as a foe of all that emanate from that realm. This Disadvantage is worth 5 points to shugenja characters. Gaki-do: The hungry dead crave your life essence above all others. All gaki and other hungry dead will attack you before any other available target, no matter the cost."},{"id":"cursed_by_the_realm_jigoku","nome":"Cursed by the Realm (Jigoku)","tipo":"spiritual","custo":4,"descricao":"The influence of the spirit realms can be felt throughout the mortal realm of Ningen-do, and for whatever reason, the essence of one realm in particular has marked you as a foe of all that emanate from that realm. This Disadvantage is worth 5 points to shugenja characters. Jigoku: The Realm of Evil thirsts for your soul. Any roll you make to resist the Shadowlands Taint suffers a penalty of -1k1."},{"id":"cursed_by_the_realm_maigo_no_musha","nome":"Cursed by the Realm (Maigo no Musha)","tipo":"spiritual","custo":4,"descricao":"The influence of the spirit realms can be felt throughout the mortal realm of Ningen-do, and for whatever reason, the essence of one realm in particular has marked you as a foe of all that emanate from that realm. This Disadvantage is worth 5 points to shugenja characters. Maigo no Musha: Your existence thwarts destiny in some manner. Any roll you make against a spirit of any kind suffers a penalty of -1k1."},{"id":"cursed_by_the_realm_meido","nome":"Cursed by the Realm (Meido)","tipo":"spiritual","custo":4,"descricao":"The influence of the spirit realms can be felt throughout the mortal realm of Ningen-do, and for whatever reason, the essence of one realm in particular has marked you as a foe of all that emanate from that realm. This Disadvantage is worth 5 points to shugenja characters. Meido: The ennui of the Realm of Waiting fi lls your soul. When unoccupied by physical activity or social interaction, you tend to lapse into a trance-like state that causes you to suffer a penalty of -1k0 to all Perception- b"},{"id":"cursed_by_the_realm_sakkaku","nome":"Cursed by the Realm (Sakkaku)","tipo":"spiritual","custo":4,"descricao":"The influence of the spirit realms can be felt throughout the mortal realm of Ningen-do, and for whatever reason, the essence of one realm in particular has marked you as a foe of all that emanate from that realm. This Disadvantage is worth 5 points to shugenja characters. Sakkaku: Trickster spirits plague you, and at least once a month you are the victim of some elaborate, cruel prank by some malicious spirit."},{"id":"cursed_by_the_realm_tengoku","nome":"Cursed by the Realm (Tengoku)","tipo":"spiritual","custo":4,"descricao":"The influence of the spirit realms can be felt throughout the mortal realm of Ningen-do, and for whatever reason, the essence of one realm in particular has marked you as a foe of all that emanate from that realm. This Disadvantage is worth 5 points to shugenja characters. Tengoku: The Celestial Heavens reject you as unclean. While within a temple devoted to the Heavens (any Fortune, the Kami, the Elemental Dragons, or the Sun or Moon), the TNs of all your rolls is increased by +10."},{"id":"cursed_by_the_realm_toshigoku","nome":"Cursed by the Realm (Toshigoku)","tipo":"spiritual","custo":4,"descricao":"The influence of the spirit realms can be felt throughout the mortal realm of Ningen-do, and for whatever reason, the essence of one realm in particular has marked you as a foe of all that emanate from that realm. This Disadvantage is worth 5 points to shugenja characters. Toshigoku: At the sight of a wounded opponent, you are overcome with bloodlust and must succeed at a Willpower Trait Roll (TN 15) or immediately attack the wounded party."},{"id":"cursed_by_the_realm_yomi","nome":"Cursed by the Realm (Yomi)","tipo":"spiritual","custo":4,"descricao":"The influence of the spirit realms can be felt throughout the mortal realm of Ningen-do, and for whatever reason, the essence of one realm in particular has marked you as a foe of all that emanate from that realm. This Disadvantage is worth 5 points to shugenja characters. Yomi: You may not possess any Advantages or abilities that specifi cally reference ancestral links (Inheritance, for example)."},{"id":"cursed_by_the_realm_yumedo","nome":"Cursed by the Realm (Yume-do)","tipo":"spiritual","custo":4,"descricao":"The influence of the spirit realms can be felt throughout the mortal realm of Ningen-do, and for whatever reason, the essence of one realm in particular has marked you as a foe of all that emanate from that realm. This Disadvantage is worth 5 points to shugenja characters. Yume-do: You are plagued with horrifi c nightmares, making sleep diffi cult. You require 10 hours of sleep to regain Void Points, rather than the normal 8."},{"id":"daikokus_curse","nome":"Daikoku's Curse","tipo":"spiritual","custo":3,"descricao":"The Fortune of Wealth fi nds you unpleasant, and as a result all your mercantile interests come to very little. You suffer a penalty of -1k1 to all Commerce rolls, and the koku of your School’s starting outfit is reduced by 1."},{"id":"dark_fate","nome":"Dark Fate","tipo":"spiritual","custo":3,"descricao":"There is a destiny of tremendous signifi cance in store for you, and sadly it is not an illustrious one. Before your death, you will usher tremendous darkness into the world in some way. Perhaps you will allow family secrets to fall into the hands of enemies, or perhaps you will allow the Great Kaiu Wall to fall to the Shadowlands. Destiny protects those for whom it has great plans, even if they do not desire it. Once per session, when you suffer Wounds that would kill you, you are instead reduc"},{"id":"ebisus_curse","nome":"Ebisu's Curse","tipo":"spiritual","custo":3,"descricao":"The Fortune of Honest Work fi nds you a distrustful soul, and others can instinctively sense the aura of mistrust surrounding you. You suffer a penalty of -1k1 on all Social Skill rolls made with non-samurai citizens of Rokugan."},{"id":"elemental_imbalance","nome":"Elemental Imbalance","tipo":"spiritual","custo":2,"descricao":"The kami of one element favor you, but so much so that their voices sometimes overpower your will and cause your invocations to achieve results other than what you intended. Only shugenja may take this Disadvantage. Choose an element in which you do not possess a Defi ciency. Whenever you cast a spell of this element, you must make a Willpower Trait Roll at TN 15 + 5 per rank of this Disadvantage. If you fail the roll, something disastrous happens. The spell may fail outright, it may target some"},{"id":"fukurokujins_curse","nome":"Fukurokujin's Curse","tipo":"spiritual","custo":3,"descricao":"The Fortune of Wisdom has denied you his blessings, and you fi nd yourself none the wiser for it. When making a Lore Skill Roll, your TN is increased by +5."},{"id":"haunted","nome":"Haunted","tipo":"spiritual","custo":3,"descricao":"One of your ancestors has chosen to bestow personal attention on you, constantly offering you advice and making demands. Perhaps the ancestor merely wishes you to live up to the ideals of your Clan and family, or perhaps he has some unfi nished task or duty which he wishes you to complete. You must show all due deference and respect to your ancestor, and do your best to live up to his (or her) expectations. If you fail to do so, your ancestor’s disapproval will bring bad fortune upon you: so lon"},{"id":"hoteis_curse","nome":"Hotei's Curse","tipo":"spiritual","custo":6,"descricao":"The Fortune of Happiness has denied you his blessings, and you are poorer for it. Any Technique or Advantage that requires you to spend a Void Point to activate instead requires two Void Points."},{"id":"jurojins_curse","nome":"Jurojin's Curse","tipo":"spiritual","custo":3,"descricao":"The Fortune of Longevity has turned his back on you. You suffer a penalty of -2k0 to resist all poisons and diseases."},{"id":"lord_moons_curse","nome":"Lord Moon's Curse","tipo":"spiritual","custo":3,"descricao":"The madness of Lord Moon, Onnotangu, lingers in your soul, driving you to fi ts of madness despite your increased understanding of the universe. You gain an additional Void Point at sunset on any night of the full moon. If you do not use this Void Point, it is lost with the sunrise. However, when the full moon rises, you must make a Willpower Trait Roll against TN 15 +5 for each level in this Disadvantage after the fi rst. If you fail the roll, you lose control of your character for the evening."},{"id":"momoku","nome":"Momoku","tipo":"spiritual","custo":8,"descricao":"There is a fundamental spiritual imbalance present in your soul that no one can explain or rectify, but it has a dramatic impact on your place within the universe, and harmony is a state virtually unknown to you. You possess Void Points, but you may not spend them on anything except School Techniques which specifi cally require Void Points. The basic uses of Void Points listed in the Book of Earth are unavailable to you."},{"id":"shadowlands_taint","nome":"Shadowlands Taint","tipo":"spiritual","custo":4,"descricao":"You have felt the touch of darkness, and it has not left you unscathed. You possess the Shadowlands Taint, a condition that makes you hopelessly spiritually lost in the eyes of virtually the entire Empire, and which is essentially incurable. You have 0.5 ranks of Shadowlands Taint. It is up to you whether you are actually aware of your Taint, since it is not detectable at this level."},{"id":"touch_of_the_void","nome":"Touch of the Void","tipo":"spiritual","custo":3,"descricao":"You have been touched by the essence of the Void, and it has forever damaged your mind. Whenever you draw upon the Void, the effect is powerful, but can overwhelm you. When you spend a Void Point to augment a roll, you gain a bonus of +2k1 instead of +1k1. Every time you spend a Void Point, however, you must succeed at a Willpower Trait Roll (TN 30) or be Dazed for one Round. This Disadvantage is worth 4 points to Phoenix characters."},{"id":"unlucky","nome":"Unlucky","tipo":"spiritual","custo":2,"descricao":"Fortune favors the mortal man… just not in your case. A number of times per session equal to your rank in this Disadvantage, the GM may force you to immediately re-roll one roll, keeping the second roll in all cases."},{"id":"wrath_of_the_kami","nome":"Wrath of the Kami","tipo":"spiritual","custo":3,"descricao":"The spirits of a particular element have a vehement dislike for you, and when invoked to smite you, they gleefully and enthusiastically comply. This may be the result of a shugenja’s curse, an offense you offered to the Fortunes, or a variety of other spiritual causes. Select one element when you purchase this Disadvantage. Spells of this element cast against you confer one Free Raise on the Spell Casting Roll. This Disadvantage is worth 4 points to shugenja characters."}],"katas":[{"id":"breath_of_wind_style","nome":"Breath of Wind Style","mastery":"3","elemento":"air","descricao":"Your initiative Score increases by 2 during the Reactions Stage of each Combat Round. This effect stacks but disappears immediately if the kata is no longer in effect","requisitos":[{"campo":"crane_kakita_bushi_school","tipo":"tag","texto":"Kakita Bushi School"},{"campo":"scorpion_bayushi_bushi_school","tipo":"tag","texto":"Bayushi Bushi School"}]},{"id":"striking_as_air","nome":"Striking as Air","mastery":"3","elemento":"air","descricao":"When in the Defense Stance your Armor TN is increased by your Air Ring","requisitos":[]},{"id":"hidden_blade_style","nome":"Hidden Blade Style","mastery":"4","elemento":"air","descricao":"Your Disarm attacks deal normal damage rather than 2k1. You may not increase your damage on these attacks via Raises (including from use of the Feint Maneuver)","requisitos":[{"campo":"scorpion_bayushi_bushi_school","tipo":"tag","texto":"Bayushi Bushi School"},{"campo":"mantis_yoritomo_bushi_school","tipo":"tag","texto":"Yoritomo Bushi School"}]},{"id":"iron_forest_style","nome":"Iron Forest Style","mastery":"4","elemento":"air","descricao":"While using a spear or polearm, you may use your Air Ring instead of Agility for attack rolls","requisitos":[{"campo":"daidoji_iron_warrior","tipo":"tag","texto":"Daidoji Iron Warrior"},{"campo":"boar_heichi_bushi_school","tipo":"tag","texto":"Heichi Bushi School"},{"campo":"phoenix_shiba_bushi_school","tipo":"tag","texto":"Shiba Bushi School"}]},{"id":"veiled_menace_style","nome":"Veiled Menace Style","mastery":"4","elemento":"air","descricao":"Once per turn, you may add your Stealth Skill Rank to your Armor TN for a single attack","requisitos":[{"campo":"scorpion_bayushi_bushi_school","tipo":"tag","texto":"Bayushi Bushi School"},{"campo":"crab_hiruma_bushi_school","tipo":"tag","texto":"Hiruma Bushi School"},{"campo":"mantis_tsuruchi_archer_school","tipo":"tag","texto":"Tsuruchi Archer School"},{"campo":"mantis_yoritomo_bushi_school","tipo":"tag","texto":"Yoritomo Bushi School"}]},{"id":"iron_in_the_mountains_style","nome":"Iron in the Mountains Style","mastery":"3","elemento":"earth","descricao":"You may use your Earth Ring in place of your Air Ring for the Defense Stance","requisitos":[{"campo":"daidoji_iron_warrior","tipo":"tag","texto":"Daidoji Iron Warrior"},{"campo":"crab_hida_bushi_school","tipo":"tag","texto":"Hida Bushi School"}]},{"id":"striking_as_earth","nome":"Striking as Earth","mastery":"3","elemento":"earth","descricao":"When in the Full Defense Stance you gain Reduction equal to your Earth Ring. This is cumulative with other forms of Reduction","requisitos":[]},{"id":"indomitable_warrior_style","nome":"Indomitable Warrior Style","mastery":"4","elemento":"earth","descricao":"Reduce your TN penalties from Wound Ranks by your Earth Ring","requisitos":[{"campo":"spider_daigotsu_bushi_school","tipo":"tag","texto":"Daigotsu Bushi School"},{"campo":"crab_hida_bushi_school","tipo":"tag","texto":"Hida Bushi School"},{"campo":"badger_ichiro_bushi_school","tipo":"tag","texto":"Ichiro Bushi School"},{"campo":"unicorn_moto_bushi_school","tipo":"tag","texto":"Moto Bushi School"}]},{"id":"striking_as_fire","nome":"Striking as Fire","mastery":"3","elemento":"fire","descricao":"When in the Full Attack Stance you may add your Fire Ring to the total of one attack roll made per round","requisitos":[]},{"id":"disappearing_world_style","nome":"Disappearing World Style","mastery":"4","elemento":"fire","descricao":"Choose one opponent. Once per turn against that opponent, you may use your Agility trait instead of your Strength Trait for damage rolls.","requisitos":[{"campo":"lion_akodo_bushi_school","tipo":"tag","texto":"Akodo Bushi School"},{"campo":"crane_kakita_bushi_school","tipo":"tag","texto":"Kakita Bushi School"}]},{"id":"reckless_abandon_style","nome":"Reckless Abandon Style","mastery":"4","elemento":"fire","descricao":"You may add your Fire Ring to your Armor TN while in the Full Attack Stance","requisitos":[{"campo":"spider_daigotsu_bushi_school","tipo":"tag","texto":"Daigotsu Bushi School"},{"campo":"lion_matsu_berserker_school","tipo":"tag","texto":"Matsu Berserker School"}]},{"id":"spinning_blades_style","nome":"Spinning Blades Style","mastery":"5","elemento":"fire","descricao":"Once per turn while wielding a weapon in each hand, you may make the Extra Attack Maneuver for 3 Raises instead of 5. The second attack comes from your off-hand weapon, dealing weapon damage as appropriate. You may not increase your damage on either attack via Raises","requisitos":[{"campo":"dragon_mirumoto_bushi_school","tipo":"tag","texto":"Mirumoto Bushi School"},{"campo":"mantis_yoritomo_bushi_school","tipo":"tag","texto":"Yoritomo Bushi School"}]},{"id":"balance_the_elements_style","nome":"Balance The Elements Style","mastery":"3","elemento":"void","descricao":"You may use your Void Ring in place of your Reflexes for your Initiative roll","requisitos":[{"campo":"dragon_mirumoto_bushi_school","tipo":"tag","texto":"Mirumoto Bushi School"},{"campo":"phoenix_shiba_bushi_school","tipo":"tag","texto":"Shiba Bushi School"}]},{"id":"striking_as_void","nome":"Striking as Void","mastery":"3","elemento":"void","descricao":"When in the Center Stance your Armor TN is increased by your Void Ring","requisitos":[]},{"id":"strength_of_purity_style","nome":"Strength Of Purity Style","mastery":"4","elemento":"void","descricao":"Once per turn while rolling damage, you may roll your Honor Rank instead of the normal Strength + DF of the weapon. You keep dice equal to the DR of the weapon as usual.","requisitos":[{"campo":"lion_akodo_bushi_school","tipo":"tag","texto":"Akodo Bushi School"},{"campo":"crane_kakita_bushi_school","tipo":"tag","texto":"Kakita Bushi School"},{"campo":"lion_matsu_berserker_school","tipo":"tag","texto":"Matsu Berserker School"},{"campo":"unicorn_utaku_battle_maiden","tipo":"tag","texto":"Utaku Battle Maiden School"}]},{"id":"strength_in_arms_style","nome":"Strength In Arms Style","mastery":"4","elemento":"water","descricao":"Once per Turn while wielding a Heavy Weapon, you may use your Strength Trait instead of your Agility for an attack roll","requisitos":[{"campo":"crab_hida_bushi_school","tipo":"tag","texto":"Hida Bushi School"},{"campo":"badger_ichiro_bushi_school","tipo":"tag","texto":"Ichiro Bushi School"},{"campo":"unicorn_moto_bushi_school","tipo":"tag","texto":"Moto Bushi School"}]},{"id":"striking_as_water","nome":"Striking as Water","mastery":"4","elemento":"water","descricao":"When in the Attack Stance you may move 5 additional feet as a Free Action","requisitos":[]}],"kihos":[{"id":"air_fist","nome":"Air Fist","mastery":"3","elemento":"air","tipo":"internal","descricao":"Perhaps the most basic of all Kiho, Air Fist allows a monk to channel the energy of the wind an lend its speed to his stries. While this Kiho is active, as long as the only attacks you make are unarmed attacks, your Initiative Score is increased by +5. If you make any other type of attack, the effect is immediately canceled. The damage of all unarmed strikes made while this Kiho is active is reduced by an amount equal to your Air Ring. This effect ends after a maximum of one day."},{"id":"flee_the_darkness","nome":"Flee the Darkness","mastery":"6","elemento":"air","tipo":"kharmic","descricao":"A member of the Brotherhood is taught the fundamental lesson of keeping his spirit free from the darkness that can envelop all men. When this Kiho is activated, you become immune to the influence of the Shadowlands Taint (or other supernatural ailments, such as the influence of the Lying Darkness) for a number of rounds equal to your Air Ring. This immunity both prevents you from acquiring the Taint while the Kiho is active, and allows you to ignore all penalties (and benefits) associated with any Taint you already possess while the Kiho is active. If you take any deliberate action that would normally result in the acquisition of the Taint, such as casting a maho spell, the effect ends immediately and you gain the Taint as normal."},{"id":"the_great_silence","nome":"The Great Silence","mastery":"4","elemento":"air","tipo":"mystical","descricao":"This peculiar technique allows a monk to use a precise attack to disrupt the flow of an individual's chi in such a way that they are unable to speak. This Kiho must be delivered by an atemi attack. If successful, the target of this attack is unable to speak for a number of rounds equal to your Air Ring."},{"id":"harmony_of_the_mind","nome":"Harmony of the Mind","mastery":"5","elemento":"air","tipo":"mystical","descricao":"A gift often possessed by members of the Brotherhood is the ability to quickly and accurately gauge the strength of others. a useful ability both in assessing new applicants to the order and in determining how best to overcome obstacles. By making a Contested Air Roll against a target within your line of sight, you may learn one of the following pieces of information: their highest or lowest Ring, their highest Skill Rank. or their highest cost Spiritual Advantage or Disadvantage. For every successful Raise made on this roll, you can gain one additional piece of information. You may use this Kiho a number of times per day equal to your Air Ring."},{"id":"riding_the_clouds","nome":"Riding the Clouds","mastery":"3","elemento":"air","tipo":"mystical","descricao":"By aligning his chi with that of the wind, a monk can make his body light and buoyant, dramatically increasing the distance he can leap. While this Kiho is active, you may make a Simple Move Action to leap a maximum distance equal to your Air Ring x10. This effect lasts until you have made such a leap once, and then is expended."},{"id":"soul_of_the_four_winds","nome":"Soul of the Four Winds","mastery":"4","elemento":"air","tipo":"internal","descricao":"By bringing their chi in alignment with that of the wind. monks may dramatically increase their reaction time and ability to evade the blows of others. While this Kiho is active, your Armor TN is increased by an amount equal to your Insight Rank plus your Air Ring."},{"id":"stain_upon_the_soul","nome":"Stain Upon the Soul","mastery":"3","elemento":"air","tipo":"martial","descricao":"This is a basic martial technique known to many sects of the Brotherhood, but one that is decried by several orders as impure and wicked. Its ease of use and its terrible effect on others are the reasons most often cited for this. You must make a successful atemi attack against a target. This disrupts the flow of the target's chi and causes crippling pain throughout the body, distracting them from everything else. The target suffers a penalty to all TNs as if he suffered from a number of Wound Ranks equal to your Air Ring. This lasts for a number of rounds equal to your Insight Rank plus your Air Ring. This effect cannot afflict a target multiple times, and is superceded by actual Wounds, not cumulative with them."},{"id":"steal_the_air_dragon","nome":"Steal the Air Dragon","mastery":"7","elemento":"air","tipo":"kharmic","descricao":"This Kiho borders upon the Mystical, but is not quite as overt as those slivers of enlightenment. By drawing his chi inward, a monk can make himself less noticeable and more prone to being easily overlooked. While this Kiho is active, you gain additional rolled and kept dice equal to your Air Ring on all Stealth Skill Rolls. This effect lasts a number of minutes equal to your Insight Rank."},{"id":"way_of_the_willow","nome":"Way of the Willow","mastery":"5","elemento":"air","tipo":"internal","descricao":"The wind is all around us, and by focusing his chi, a monk may see as the wind does, dramatically increasing his ability to perceive threats and preemptively counteract them. While this Kiho is active, if you have not yet taken your Turn during the current combat Round, you may spend a Void Point to immediately interrupt any opponent who declares a melee attack against you. As part of this interruption, you may either make a Move Action away from the opponent, or you may instead make an unarmed attack against them. Once you have done so, the effect of this Kiho ends. This Kiho is rendered inactive if not used within one day of its activation."},{"id":"cleansing_spirit","nome":"Cleansing Spirit","mastery":"4","elemento":"earth","tipo":"internal","descricao":"Rain and time wash the mountain, leaving it free from impurities. While this Kiho is active, you roll a number of additional dice equal to half your Earth Ring (rounded down) on any roll made to resist the effects of poison or disease."},{"id":"earthen_fist","nome":"Earthen Fist","mastery":"3","elemento":"earth","tipo":"internal","descricao":"Although part of the elemental fist set of Kiho, this particular technique is more defensive than offensive. While Earthen Fist is active, you may only adopt the Defense or Full Defense Stances. If an opponent makes a melee attack against you and misses, on your next Turn you may attempt the Disarm Maneuver against that opponent (assuming they are within range) for no Raises and regardless of the normal restrictions of your stance, ending the Kiho's effect. This Kiho is rendered inactive if not used within one day of its activation."},{"id":"earth_needs_no_eyes","nome":"Earth Needs No Eyes","mastery":"3","elemento":"earth","tipo":"internal","descricao":"You can attune yourself to minute vibrations in the earth and use them to detect the movement of others. While this Kiho is active you can detect the approach of any creature or individual that moves across the ground within a distance equal to your Insight Rank x50 in feet. You only know the location of moving things in contact with the ground. If this Kiho is active when a skirmish begins, you cannot be ambushed or surprised by any land-bound opponent. This effect lasts a number of minutes equal to your Earth Ring."},{"id":"embrace_the_stone","nome":"Embrace the Stone","mastery":"5","elemento":"earth","tipo":"mystical","descricao":"By focusing their chi like that of the mountain, monks may become like stone themselves, turning aside blows and ignoring damage. When you activate this Kiho, you gain a Reduction Rating equal to twice your Earth Ring. This stacks with any other Reduction you have from other sources (such as spells or armor). This effect lasts for a number of rounds equal to your Earth Ring."},{"id":"grasp_of_the_earth_dragon","nome":"Grasp of the Earth Dragon","mastery":"5","elemento":"earth","tipo":"internal","descricao":"Embracing the essence of stone grants a monk incredible powers of resilience. When this Kiho is active, your TN penalties at all Wound Ranks are reduced by an amount equal to your Earth Ring. You may also continue to take Simple Actions when at the Down Wound Rank. This effect lasts a number of rounds equal to your Earth Ring."},{"id":"rest_my_brother","nome":"Rest, My Brother","mastery":"5","elemento":"earth","tipo":"martial","descricao":"Easily among the most difficult and most sacred of all Kiho, this technique is restricted to a handful of orders within the Brotherhood. It functions by reversing the chi flow of a Tainted individual, causing them excruciating pain and temporarily restoring clarity of thought. This Kiho requires an atemi attack to be activated. The attack deals normal unarmed damage (despite being an atemi attack), plus an additional number of unkept damage dice equal to the opponent's Shadowlands Taint Rank. If the target is a human or other formerly uncorrupted creature (as opposed to an oni or other inherently Tainted creature), he loses all benefits of the Shadowlands Taint for a number of Rounds equal to your Earth Ring. During this time, he is free from the madness and mental instability normally brought on by the Taint."},{"id":"root_the_mountain","nome":"Root the Mountain","mastery":"5","elemento":"earth","tipo":"internal","descricao":"As the Crab say, the mountain does not move, and neither does one who shares its strength. While this Kiho is active, attempts to use the Knockdown Maneuver against you require two extra Raises to he successful. Any attempt to force you to move against your will, including Knockdown Maneuvers, requires a Contested Earth Roll in addition to any other costs or Contested Rolls. You may not make Move Actions without dispelling this effect."},{"id":"speed_of_the_mountains","nome":"Speed of the Mountains","mastery":"4","elemento":"earth","tipo":"kharmic","descricao":"Earth is many things, but fleet is not among them. By delivering an atemi attack against an opponent and activating this Kiho, you cause their earthen chi to become ascendant. The opponent's Water Ring is considered to be two ranks lower for the purposes of determining how far they can move as part of a Move Action. This effect lasts for a number of rounds equal to twice your Earth Ring."},{"id":"way_of_the_earth","nome":"Way of the Earth","mastery":"4","elemento":"earth","tipo":"martial","descricao":"The grip of a monk can be like stone, crushing those who find themselves trapped in his grasp. Opponents engaged in a Grapple with you while this Kiho is active suffer a number of additional Wounds per Round equal to your Earth Ring, regardless of who is winning the Grapple. This damage is inflicted during the Reactions Stage. This effect lasts a number of minutes equal to your Earth Ring."},{"id":"the_body_is_an_anvil","nome":"The Body is an Anvil","mastery":"4","elemento":"fire","tipo":"mystical","descricao":"A master of the ways of Fire can channel his chi outward, granting him a measure of protection and repelling attackers. While this Kiho is active, your skin becomes extremely hot to the touch, and anyone who touches you, including those who target you with unarmed attacks or those you strike with an unarmed attack, suffer Wounds equal to your Fire Ring. This effect lasts a number of rounds equal to twice your Fire Ring."},{"id":"breaking_flow","nome":"Breaking Flow","mastery":"3","elemento":"fire","tipo":"martial","descricao":"Fire destroys all it touches, and a monk harnessing his Fire chi can achieve similar effects. While this Kiho is active, your unarmed strikes inflict full damage to all non-metal substances, including wood and stone, without inflicting any ill effects on you as a result of punching such objects. This effect lasts a number of minutes equal to your Fire Ring. The GM is the ultimate judge of how much damage a particular inanimate object can withstand before being destroyed."},{"id":"channel_the_fire_dragon","nome":"Channel the Fire Dragon","mastery":"6","elemento":"fire","tipo":"internal","descricao":"Fire cannot be extinguished by more fire, nor can it be quelled with cold. While this Kiho is active, any damage you suffer as a result of heat or cold is reduced by -2k2. This includes effects that generate fire, such as spells and other Kiho. This effect lasts for one day."},{"id":"dance_of_the_flames","nome":"Dance of the Flames","mastery":"6","elemento":"fire","tipo":"martial","descricao":"Filling one's chi with the power of Fire has considerable effects on one's speed as well as ones temperament. While this Kiho is in effect, you may make unarmed attacks as a Simple Action rather than a Complex Action. You must make an unarmed attack against an opponent (rather than an ally or inanimate object) every Round while this Kiho is active, or its effects end immediately."},{"id":"destinys_strike","nome":"Destiny's Strike","mastery":"4","elemento":"fire","tipo":"martial","descricao":"The force of destiny is powerful, and can be harnessed by those who truly understand their place in the universe. While this Kiho is active, whenever you are struck by a melee attack from an opponent, you may immediately make a counterattack in the form of a single unarmed attack. If you have not taken your Turn yet this round, this counts as your Turn. If you have taken your Turn, this is a Free Action instead. This counterattack ignores any Wound Penalties suffered as a resuIt of the attack to which it is responding. This Kiho lasts until the end of the skirmish."},{"id":"falling_star_strike","nome":"Falling Star Strike","mastery":"7","elemento":"fire","tipo":"martial","descricao":"One of the most blatant and powerful of all Kiho, the Falling Star Strike is a devastating martial attack that can cripple opponents permanently if not used with restraint. When employed, the fists of the monk using it arc wreathed in flame, and his eyes burn like fiery embers. This Kiho may only be activated by spending a Void Point, and may not he activated by making a Void / Meditation Skill Roll. It also requires two Raises on an unarmed attack to activate. The unarmed attack inflicts normal damage, plus an additional amount of damage with a DR equal to your Fire Ring in rolled and kept dice. Additionally, you and the target must make a Contested Fire Roll. If you are successful, the target is struck Blind for a number of hours equal to your Fire Ring."},{"id":"fires_fleeting_speed","nome":"Fire's Fleeting Speed","mastery":"4","elemento":"fire","tipo":"kharmic","descricao":"Fire darts and surges, as do those who carry it in their souls. While this Kiho is active, increase the distance you may move when using any Move Action by +5'. This effect lasts a number of Rounds equal to your Fire Ring."},{"id":"flame_fist","nome":"Flame Fist","mastery":"3","elemento":"fire","tipo":"martial","descricao":"By mingling your chi with another's while Fire is ascendant within your body, you can disonent and confuse an opponent, inhibiting their actions. An opponent struck by this Kiho's activating atemi strike suffers a TN penalty to all actions equal to three times your Fire Ring. This effect lasts a number of rounds equal to your Fire Ring."},{"id":"unbalance_the_mind","nome":"Unbalance the Mind","mastery":"5","elemento":"fire","tipo":"mystical","descricao":"A momentary disruption of the Fire chi within a target can leave them addled and confused. The target of this Kiho's activating afen;i strike is Dazed."},{"id":"as_the_breakers","nome":"As the Breakers","mastery":"5","elemento":"water","tipo":"kharmic","descricao":"By disrupting the flow of chi through others, you can inhibit them without harm. With a successful atemi strike, the target of your strike loses one Simple Action this Round. You may only target opponents who have not yet acted in the present Round, and an opponent may not be affected by this Kiho more than once per skirmish."},{"id":"buoyed_by_the_kami","nome":"Buoyed by the Kami","mastery":"3","elemento":"water","tipo":"mystical","descricao":"A monk whose Water chi is ascendant can resist the siren call of the depths. While this Kiho is active, you may move across the surface of water as if it were basic terrain. This effect only continues as long as you are taking Simple Move Actions each round, and lasts for a maximum of fIve minutes. at which time you may reactivate this Kiho if necessary."},{"id":"chi_protection","nome":"Chi Protection","mastery":"4","elemento":"water","tipo":"martial","descricao":"Perhaps the strangest application of the atemi technique, this Kiho permits a monk to restore or enhance the flow of chi through another's body, hastening the healing of wounds or other ailments. You must spend a Void Point to activate this Kiho (as opposed to the normal allowance to activate by a Void / Meditation Skill Roll), which is done immediately after successfully striking a target (either an opponent or a willing ally) with an alemi strike. The individual targeted by the strike regains a number of Wounds equal to your Water Ring, immediately and then at the start of your Turn every subsequent Round for a number of Rounds equal to your Insight Rank, You may not use this Kiho on yourself."},{"id":"freezing_the_lifeblood","nome":"Freezing the Lifeblood","mastery":"7","elemento":"water","tipo":"martial","descricao":"This attack disrupts the flow of chi through an opponent's body, paralyzing them for a short time. The individual struck by the atemi attack is paralyzed, effectively Stunned and unable to take Move Actions, and may not move tinder his own power for a number of Rounds equal to your lnsigh Rank."},{"id":"partaking_the_waves","nome":"Partaking the Waves","mastery":"6","elemento":"water","tipo":"internal","descricao":"Certain monks may channel the power of the ocean into their bodies, moving and Ilowing away from attacks like the sea itself. While this Kiho is active, you gain Reduction equal to your Water Ring. This stacks with Reduction from other sources such as spells and armor. This effect lasts a number of Rounds equal to twice your Water Ring."},{"id":"ride_the_water_dragon","nome":"Ride the Water Dragon","mastery":"3","elemento":"water","tipo":"kharmic","descricao":"To walk with the Water Dragon's power is to harness the incredible restorative abilities of the ocean. While this Kiho is active, for a number of Rounds equal to your Insight Rank, you recover Wounds equal to your Water Ring during the Reactions Stage of the Round."},{"id":"slap_the_wave","nome":"Slap the Wave","mastery":"7","elemento":"water","tipo":"mystical","descricao":"A powerful expression of inner strength, this Kiho channels the monk's chi outward in an explosive wave that carries the power of a tsunami. You must spend a Void point to activate this Kiho (Void / Meditation Skill Rolls are not possible). You must strike your hands together and release a powerful kiai shout. Everyone in your forward facing arc and within a (Itstance of your Water Ring x5 feet must succeed at a Contested Water Roll against you, or become Dazed."},{"id":"waves_in_all_things","nome":"Waves in All Things","mastery":"4","elemento":"water","tipo":"mystical","descricao":"Water flows through all things. including the earth. You may make an unarmed attack by striking a body of standing water or the earth. The effects of this strike are felt by one opponent who is in contact with either the water or earth (whichever one was struck) and who is within a number of feet equal to your Water Ring x10. The effect of the strike is quite obvious, and may not be performed discreetly. If you are concealed at the time this Kiho is activated, your position is immediately revealed to the target and those in his immediate vicinity."},{"id":"banish_all_shadows","nome":"Banish All Shadows","mastery":"4","elemento":"void","tipo":"kharmich","descricao":"One of the most powerful effects of ones chi upon another is the clarity it brings, which can allow one to overcome shortcomings for a short time. The target of this Kiho's activating strike may, for a number of Rounds equal to your Void Ring, ignore the effects of his highest-point Disadvantage. This effect does not target Spiritual or Social Disadvantages."},{"id":"death_touch","nome":"Death Touch","mastery":"7","elemento":"void","tipo":"mystical","descricao":"The death touch, also known as dim mak, is perhaps the rarest and most reviled use of a monk's understanding of the flow of chi. It involves a series of aremi strikes that disrupt and corrupt the flow of chi through an opponent's body, leading to debilitating pain and possibly death. You must successfully strike an opponent with three atemi strikes on three consecutive Rounds immediately after activating this Kiho, and you must spend an additional Void Point after the third and final strike (in addition to any Void Points spent to activate the Kiho). Your opponent suffers increasing weakness broken up by bouts of agonizing pain. All of the target's Rings are reduced by 1 each hour. The maximum penalty is an amount equal to your insight Rank. If any Ring reaches 0 due to these penalties, the target falls into a catatonic state and must make three Contested Void Rolls against you (these rolls use the target's full Void, without penalties). If the target loses all three rolls by at least 5 or more, he dies. (This Kiho does not automatically kill the victim if his Earth is reduced to 0.) Use of this technique can be grounds for excommunication from the Brotherhood of Shinsei."},{"id":"eight_directions_awareness","nome":"Eight Directions Awareness","mastery":"5","elemento":"void","tipo":"mystical","descricao":"Some monks are at a state of harmony with the world to such extent that they are aware of everything around them. While this Kiho is active, you become aware of all living things within a distance equal to your Void Ring x 10 feet. You are also aware of any object or individual within that range that has been deliberately concealed, including secret doors, hidden compartments, buried objects, etc."},{"id":"silent_solace","nome":"Silent Solace","mastery":"5","elemento":"void","tipo":"kharmic","descricao":"Proper use of nerve strikes can impede not only the physical. but the spiritual as well. An opponent struck by this Kiho's activating strike must expend two spell slots to cast a single spell. This effect lasts a number of Rounds equal to your Void Ring."},{"id":"song_of_the_world","nome":"Song of the World","mastery":"3","elemento":"void","tipo":"kharmic","descricao":"By listening to the song of the elements around him, a monk may perceive the universe slightly ahead of all others. You must target an opponent within fifty feet when activating this Kiho, and succeed at a Contested Void Roll against him. If successful, his Initiative Score is reduced by 5 and yours is increased by the same amount."},{"id":"spin_the_kharmic_wheel","nome":"Spin the Kharmic Wheel","mastery":"8","elemento":"void","tipo":"kharmic","descricao":"Theoretically one of the most powerful Kiho known to exist, Spin the Kharmic Wheel is known only to a handful of reclusive masters within the Brotherhood, and discovered by a new soul perhaps once in a generation. You must deliver this Kiho via an unarmed attack in order to properly harness the forces of destiny that it unleashes. You expend all remaining Void Points when this Kiho is activated. The target of your attack loses one randomly determined Social, Spiritual, or Mental Disadvantage and gains a new randomly determined Social, Spiritual, or Mental Disadvantage of equal value. The GM may opt to choose the Disadvantages instead of selecting randomly, if that seems to produce a more interesting (or believeable) result."},{"id":"touch_the_void_dragon","nome":"Touch the Void Dragon","mastery":"4","elemento":"void","tipo":"internal","descricao":"Certain orders of the Brotherhood are adept at aligning their chi with the dominant Element in the environment around them, drawing strength from the world. While this Kiho is active, one of your Rings and its associated Traits are considered one Rank higher. Which Ring is affected depends upon the environment. Mountains increase Earth, the seashore increases Water, the plains increase Air, the desert or volcanic areas increase Fire, etc."},{"id":"to_the_last_breath","nome":"To the Last Breath","mastery":"3","elemento":"void","tipo":"kharmic","descricao":"With a simple exhalation, a monk can expend his energy into the universe around him, allowing others to partake of it as they wish. Any one selected individual within twenty feet when this Kiho is activated gains a Void Point on their next Turn. No target may benefit from this Kiho more than twice per day."},{"id":"void_fist","nome":"Void Fist","mastery":"4","elemento":"void","tipo":"martial","descricao":"Unlike other atemi attacks, the Void Fist is a normal unarmed strike that would appear, if observed, to be damaging to its target. This is an illusion, however, as its true purpose is to use the target as a conduit with the great Void. You must make a successful Raise to strike an opponent with Void Fist. A successful strike inflicts no damage. but you immediately regain two Void Points. This Kiho can only be used on enemies, and has no effect on allies. It has no effect on targets who do not have Void Points."}],"feiticos":[{"id":"blessed_wind","nome":"Blessed Wind","elemento":"air","mastery":"1","area":"10' radius around the caster","alcance":"Personal","duracao":"Concentration","descricao":"You summon a swirling aura of winds to protect you from ranged attacks. The buffeting winds deflect arrows and other projectiles. While you maintain your concentration, this spell adds + 15 to your Armor TN versus all non-magical ranged attacks."},{"id":"by_the_light_of_the_moon","nome":"By the Light of the Moon","elemento":"air","mastery":"1","area":"20' radius around the caster","alcance":"Personal","duracao":"1 minute","descricao":"You call upon the kami to reveal that which has been hidden. All concealed objects within the area of effect appear as slightly luminous outlines to you. Any non-magical concealment is revealed, including secret compartments, trap doors, concealed weapons, etc. Only you can see the presence of these objects."},{"id":"cloak_of_night","nome":"Cloak of Night","elemento":"air","mastery":"1","area":"One object","alcance":"Touch","duracao":"1 hour","descricao":"You can call upon the kami trap an object in their embrace, hiding it from the sight of mortal beings. You may target anyone non-living object smaller than you. This object becomes invisible the naked eye. Attempts perceive it magically will automatically succeed if the Mastery level of the spell used is higher than that of this spell. Spells of equal Mastery Level require a Contested Air Roll to detect the hidden object. The object is still physically present and can be touched, smelled, or sensed with any normal sense other than vision."},{"id":"legacy_of_kazenokami","nome":"Legacy of Kaze-no-Kami","elemento":"air","mastery":"1","area":"One known individual within range","alcance":"School Rank x 10 miles","duracao":"Special","descricao":"You are able call upon the spirits of the wind to take form as a bird and carry a message for you. The bird that is created by this spell appears perfectly normal in all regards, but if it takes any damage it dissipates into wind immediately, ending the spell. Upon creating the bird, you may speak tit, giving it a spoken message of up tone minute in length. The bird will then fly away to deliver the message the person (or persons) specified when the spell is cast. The bird will fly to their location, deliver the message via a whisper (it can be overheard by others, but not easily), and then disappear. If the bird is unable to reach the individual, but they are within range (if they are within a building with no windows, for instance will remain outside waiting for up tone week before disappearing). If the person specified by the spell is not within range, the bird will fly away in a random direction and disappear when it is out of your line of sight."},{"id":"natures_touch","nome":"Nature's Touch","elemento":"air","mastery":"1","area":"One Creature","alcance":"10'","duracao":"Special","descricao":"You are able to use the spirits of the wind to speak to an animal and ensure that it understands what you are saying. This spell works only on natural animals, and will not work with Shadowlands creatures or creatures from other realms. It does not guarantee that the animal will regard you positively or that it will fulfill requests made of it, but the creature will understand anything you tell it (within its ability (naturally - political relationships will have no meaning ta horse. no matter how many times you explain them). This spell lasts as long as you maintain your full and undivided attention on the animal and continue speaking to it."},{"id":"tempest_of_air","nome":"Tempest of Air","elemento":"air","mastery":"1","area":"A cone 75' long and 15' wide at its end","alcance":"Personal","duracao":"Instantaneous","descricao":"You summon a powerful gust of air emanating from your position that crashes into all in its path, knocking them the ground. All targets within the area of effect suffer 1k1 Wounds and must make a Contested Roll using their Earth against your Air. Every target that fails suffers Knock down."},{"id":"to_seek_the_truth","nome":"To Seek the Truth","elemento":"air","mastery":"1","area":"One individual touched (may be the caster)","alcance":"Personal / Touch","duracao":"5 minutes","descricao":"You call upon the wind to purge the mind of your target, granting him clarity. This spell may negate temporary mental or social penalties suffered as a result of a mechanical effect, including Techniques, Wound Ranks, or other spells. The TN of the Spell Casting Roll made to cast this spell is increased by an amount equal the Technique Rank, Wound Rank, or spell Mastery Level used create the penalty in the first place. Disadvantages permanently possessed by an individual may not be countered using this spell."},{"id":"token_of_memory","nome":"Token of Memory","elemento":"air","mastery":"1","area":"One small (1 cubic foot or smaller) illusory object","alcance":"10'","duracao":"1 hour","descricao":"You can create a flawless illusion of one object. The item appears real in every way up until the spell expires, at which point it disappears. If you are attempting create a specific, familiar object. Such as another samurai's katana, you must declare one Raise, and (hat individual may make a Contested Roll using his Perception against the total of your Spell Casting Roll to detect the forgery. Images created by this spell are completely stationary, and if placed in a situation where they must move (such as floating in water), disappear instantly. An image of a katana could be created sitting on a rack, for example, but not in a samurai's obi because it would not be able to move with the samurai. Objects created with this spell have no true physical substance and cannot bear weight or inflict damage."},{"id":"way_of_deception","nome":"Way of Deception","elemento":"air","mastery":"1","area":"One illusory duplicate of the caster","alcance":"20'","duracao":"Concentration plus 5 minutes","descricao":"You can entreat the capricious spirits of the wind create a perfect duplicate image of you a short distance away. The illusion exactly reflects your appearance at the time the spell is cast, including your clothing and any equipment. The illusion may appear anywhere within the spells range, and will perform whatever actions you perform while it is in effect. (If you sit down, for instance, your duplicate will sit down as well, even if there is nothing so sit on.) Once you leave the normal range of the spell, the duplicate disappears. If you make two Raises on the Spell Casting Roll, you may leave the area of effect and the illusion will remain in whatever position it was in when you left for as long as you continue concentrating on maintaining the spell."},{"id":"yari_of_air","nome":"Yari of Air","elemento":"air","mastery":"1","area":"One created weapon","alcance":"Personal or 20'","duracao":"5 minutes","descricao":"You summon a swirling weapon of pure air, only visible as a foggy outline. The weapon's default form is a yari, but one Raise can change its form to any other spear of your choosing. The weapon has DR 1k1. If you do not possess the Spears Skill, you may instead use your School Rank in its place. If you do possess the Spears Skill, using this weapon grants you one Free Raise that can only be used on the Feint or Increased Damage Maneuvers. This weapon disappears if is lost from your hand. Instead of summoning the yari for yourself, you may cause it to appear in the hands of an ally within 20 feet. He is treated as the caster for all purposes of the spell, but he does not gain the Free Raise bonus."},{"id":"commune","nome":"Commune","elemento":"all","mastery":"1","area":"Self","alcance":"20'","duracao":"Concentration","descricao":"This spell can be cast in any element save Void. It allows the caller to speak with one of the local elemental kami, asking it a few questions, which it will answer honestly to the best of its ability. Typically this spell will invoke the most active and energetic spirit of the chosen element in the area of effect; if all of the local spirits are quiescent. The GM may require the caster call 1 or 2 Raises to wake up a local spirit enough answer questions. A spirit reached with Commune will answer questions. The caster may Raise to get more questions (one per Raise). The caster may also Raise for clarity, get a more accurate and informative answer the questions. (Kami are notorious for their inability Tully comprehend human behavior, and asking questions without Raises for clarity can often result in confusing, enigmatic, or incomplete answers.) Spirits snot forget anything. So theoretically a shugenja can ask a spirit about something that happened decades ago; however, they do not experience time in the same way as mortals. Straying task about something from long agile usually require Raises in order make the caster's wishes clear the spirit. The nature of the information which spirits can impart varies by element: Air spirits tend to be playful and easily distracted, conveying information as emotions or as riddles and jokes. Since they are more interested in feelings than in facts, and enjoy playing games with those speak with them, communing with an Air spirit can sometimes be very frustrating. Earth spirits are straightforward and matter-of-fact, often blunt, but are rather uninterested in the behavior of mortals, have a poor understanding of human emotion, and tend to be overly focused on obscure details such as the color of a piece of clothing or the weight of a horse. Fire spirits are irritable and temperamental, and are often angry at being summoned unless they are propitiated with an offering of something burn. On the other hand, if a shugenja can please them they tend to offer the clearest and most accurate information. Water spirits communicate their knowledge through soundless visual images. This can be very helpful ta shugenja trying investigate a past incident, but since the spirits cannot convey scent, sound, or emotion, the information they provide can often be incomplete or misleading."},{"id":"sense","nome":"Sense","elemento":"all","mastery":"1","area":"50' radius from the caster","alcance":"Personal","duracao":"Instantaneous","descricao":"This spell can be cast in any of the four standard elements. It allows the caster sense the presence, quantity, and rough location of elemental spirits (not the evil spirits known as kansen) of that element within the range of the spell. This is most frequently applied when looking for spirits with which commune (see below), but can also be useful as a crude, basic location device. For example, a caster lost in the wilderness could cast Sense (Water) in hopes of locating a source of drinking water."},{"id":"summon","nome":"Summon","elemento":"all","mastery":"1","area":"1 cubic foot of summoned material","alcance":"30'","duracao":"Permanent","descricao":"This spell can be cast in any of the four standard elements. It allows the caster to summon a modest quantity (one cubic foot) of the chosen element. The summoned matter appears (usually in a rough hall shape) in any open space within the spells range. This cannot place the summoned material inside another physical object or living creature. The summoned element will behave in a normal and mundane matter - Earth falls the ground, water soaks anything it lands on, air blows away, and fire winks out unless there is something present for it burn. In general it is impossible to use this spell effectively in combat, although clever shugenja may find a few modest combat uses, such as using Summon Fire to ignite a foe soaked in cooking oil. More commonly, the spells value is in simpler functions, such as summoning Water while in a desert, or summoning Fire to light a campfire without flint and tinder. Raises may be used with this spell summon a more specific type of the appropriate element, such as wood or iron with Earth, or tea with Water. The GM should choose how many Raises (generally anywhere from 1 to 4) this requires. However, these Raises cannot be used create rare/precious materials (such as gold) or spiritually powerful substances (such as jade or crystal)."},{"id":"armor_of_earth","nome":"Armor Of Earth","elemento":"earth","mastery":"1","area":"Self","alcance":"Personal","duracao":"10 rounds","descricao":"This spell infuses the caster's body with the strength of Earth, weakening the force of any physical or magical attack which strikes him. For the duration of the spell, you gain Reduction in an amount equal to your Earth Ring + School Rank. However, this infusion of Earth slows your movements. Your Water is considered 1 Rank lower for purposes of movement while you are under the effects of this spell."},{"id":"courage_of_the_seven_thunders","nome":"Courage Of The Seven Thunders","elemento":"earth","mastery":"1","area":"Targets up to caster's Shugenja School Rank","alcance":"30'","duracao":"10 minutes","descricao":"This spell infuses the targets (who may include the caster) with firm and unyielding courage, bolstered by the eternal power of the Earth. For the duration of the spell, all the targets gain +5k to resist any kind of Fear effect, whether magical or natural. However, this spell is associated with the memory of the legendary Seven Thunders, and those whose connection the Thunders is tenuous do not receive the same degree of blessing from the Earth kami. Samurai who are not of the original Seven Great Clans receive only + 3k to their rolls to resist Fear. Anyone who has at least a full Rank of Shadowlands Taint cannot benefit from this spell, although this will not actually reveal that they are tainted. This spell may be cast as a combined ritual by two or more shugenja who know the spell, in which case they may add their highest single Earth Rank to their combined total School Ranks to determine how many targets the spell can affect."},{"id":"earths_stagnation","nome":"Earth's Stagnation","elemento":"earth","mastery":"1","area":"One target","alcance":"50'","duracao":"6 rounds","descricao":"This spell calls on the Earth in the target's body to weigh him down, impeding his movements. The target suffers a -2k penalty to all rolls using the Agility trait, and his Water Ring is considered 1 Rank lower for the purpose of how far he can move."},{"id":"earths_touch","nome":"Earth's Touch","elemento":"earth","mastery":"1","area":"One target","alcance":"Touch","duracao":"1 hour","descricao":"With this spell, the shugenja calls forth the Earth of the target (which may be himself), invoking the kami to strengthen his health and mental fortitude. For the duration of the spell, one of the target's Earth Traits (chosen by the caster) is increased by 1. This does not increase the Ring itself, but it can enhance the target's ability to withstand temptation, resist poisons, or dominate others."},{"id":"elemental_ward","nome":"Elemental Ward","elemento":"earth","mastery":"1","area":"One target","alcance":"Touch","duracao":"1 hour","descricao":"This spell uses the power of Earth to enhance resistance to hostile magic. The spirits of Earth armor the target's body and soul, rejecting other kami when they try to affect the target. When the shugenja casts this spell, he chooses one Element (which cannot be Void or Maho). Spells of that element suffer a TN penalty equal the caster's School Rank x 5 when they are cast on anyone under the protection of this spell. (Unfortunately, this includes \"friendly\" magic, such as healing.)"},{"id":"jade_strike","nome":"Jade Strike","elemento":"earth","mastery":"1","area":"One target","alcance":"100'","duracao":"Instantaneous","descricao":"This spell summons forth the purest of Earth kami, those of jade, in the form of a blast of iridescent green energy. The jade power flies out and unerringly strikes the chosen target. It cannot be intercepted or deflected, although Magic Resistance or other forms of magical Defense can thwart it. If the target has at least one Rank of Taint, the Jade Strike will inflict damage with a DR of 3k3, burning and blackening the Tainted flesh. However, a target who does not have at least a full Rank of Taint will not suffer any damage from the spell. Casting Jade Strike on a non-Tainted target is generally regarded as a grave insult - except perhaps among the more paranoid ranks of the Kuni family, where it is seen as merely a sensible precaution."},{"id":"jurojins_balm","nome":"Jurojin's Balm","elemento":"earth","mastery":"1","area":"One target","alcance":"Touch","duracao":"1 hour","descricao":"This spell fills the target's body with the purity and vigor of Earth, driving out poisons and impurities. If the target suffers the effects of any poison or toxin within the duration of the spell, or is already under the effects of a poison when the spell targets him, he may re-roll any failed Stamina roll to resist the poison, with a bonus of +2k the second roll. (However, if the second roll is also failed, the poison has full effect.) An interesting side-effect of this spell is that it also cures drunkenness and other such effects, and it is impossible for the target to become intoxicated during the spells duration."},{"id":"minor_binding","nome":"Minor Binding","elemento":"earth","mastery":"1","area":"One target","alcance":"60'","duracao":"2 hours","descricao":"This spell was pioneered by the Kuni family but has come into use among other shugenja who Battle the forces of the Shadowlands, such as the Scorpion and the Phoenix. It is used to safely imprison minor Shadowlands creatures, typically for purposes of interrogation. Any Shadowlands creature with an Earth of 3 or less can be targeted with this spell. It cannot affect the Lost, Oni Lords or their spawn, or creatures with an Earth of 4 or higher, nor can it affect creatures who are not tainted. If the spell is cast successfully, it calls forth manacles of iron, formed from pure Earth spirits, which trap and bind the target creature, rendering it physically helpless for the duration of the spell. When the spell expires, the manacles instantly crumble away into dust."},{"id":"soul_of_stone","nome":"Soul Of Stone","elemento":"earth","mastery":"1","area":"One target","alcance":"Touch","duracao":"1 hour","descricao":"This spell fills the targets soul with the firm and unyielding strength of stone. For the duration of the spell, the target's feelings are immovable, and any attempt to divert or distract him will be resisted with supernatural determination. He gains a +3k bonus to any rolls made to resist emotional manipulation or the distractions of desire, including Courtier (Manipulation) rolls, Temptation rolls, Compulsions, and any similar effects which the GM judges to be appropriate. However, this stony self-control also makes it difficult for the target to read and affect the emotions of others, and for the duration of the spell he suffers a -1k penalty to all Awareness Trait rolls and Awareness-related Skill Rolls made for the purpose of influencing others."},{"id":"tetsubo_of_earth","nome":"Tetsubo Of Earth","elemento":"earth","mastery":"1","area":"One created weapon","alcance":"Personal or 20'","duracao":"5 minutes","descricao":"You summon a tetsubo of pure earth, studded with all manner of stones. The weapon's default form is a tetsubo, but one Raise can change its form to any other heavy weapon of your choosing. The tetsubo has a DR of 2k2. When wielding this weapon, you may use your School Rank in place of your Heavy Weapons Skill if you wish. If you do have the Heavy Weapon skill, the tetsubo grants you a Free Raise for the Knockdown maneuver (this bonus does not apply if you grant the tetsubo to another person instead of wielding it yourself). The tetsubo disappears if it is lost from your hand. Instead of summoning the tetsubo for yourself, you may cause it to appear in the hands of an ally within 20 feet. He is treated as the caster for all purposes of the spell, but does not gain the Free Raise bonus."},{"id":"biting_steel","nome":"Biting Steel","elemento":"fire","mastery":"1","area":"1 bladed weapon","alcance":"Touch","duracao":"1 minute","descricao":"Fire spirits can infuse metal with their own fury, turning a sharp edge into a supremely perfect one. This spell enhances the damage of steel bladed weapons, such as swords, knives, naginata, etc. Biting Steel cannot affect weapons which are not metal blades, which are Nemuranai, or which have already been enhanced by magical effects. The weapon's DR is increased by 1k1 for the duration of the spell."},{"id":"burning_kiss_of_steel","nome":"Burning Kiss Of Steel","elemento":"fire","mastery":"1","area":"One melee weapon in caster's hand","alcance":"Touch","duracao":"5 minutes","descricao":"This spell embraces a weapon with fire, causing it to be larger and more effective. When the spell is cast, a tendril of fire extends from your hands to engulf your weapon. (If you drop or lose the weapon, the spell effect ends.) This weapon gains a + 1k1 bonus to melee attack rolls. The bonus is +2k2 when making attacks against mounted opponents or opponents of larger than human size."},{"id":"envious_flames","nome":"Envious Flames","elemento":"fire","mastery":"1","area":"One target","alcance":"30'","duracao":"Instantaneous","descricao":"Fire's most basic power is destruction, and summoned Fire spirits can easily be unleashed on one's enemies. This spell invokes a single Fire kami, which lances toward the target, hitting unerringly so long as the target is within range. The spell deals 2k2 Wounds. The burns this spell inflicts are quite painful, and if the spell targets a shugenja who is casting a spell, his Willpower roll has a TN of 20 plus the damage dealt, instead of the normal 10 plus damage dealt."},{"id":"extinguish","nome":"Extinguish","elemento":"fire","mastery":"1","area":"100' radius","alcance":"Personal","duracao":"Instantaneous","descricao":"Fire spirits can be driven away by the proper invocation, a very useful ability in Rokugani towns and cities where the construction is all wood and paper. This spell dismisses the active Fire kami in the area. All non-magical fire in the area of effect is immediately snuffed out, and any damage dealt by fire (magical or not) reduces its DR by 1k1 until the start of the next Round."},{"id":"fires_of_purity","nome":"Fires Of Purity","elemento":"fire","mastery":"1","area":"One target","alcance":"25'","duracao":"1 minute","descricao":"This spell, one of to the few directly protective prayers involving the Fire kami, asks the kami to protect one person, enveloping the target in a shroud of bright flames. Neither the caster nor anything he carries takes damage from the spell, but anyone who comes into contact with him or strikes him with a melee attack takes 2k2 Wounds. Anyone the target strikes in melee with an unarmed attack or a weapon he carried when the spell was cast also rakes an extra 2k2 Wounds. Anything the target puts down, however, cannot be picked back up without subjecting it to the damage from the spell. Ranged weapons such as arrows bypass this barrier of fire, dealing Wounds as normal."},{"id":"fury_of_osanowo","nome":"Fury Of Osano-wo","elemento":"fire","mastery":"1","area":"One target","alcance":"300'","duracao":"Instantaneous","descricao":"This spell is actually a prayer to the Fortune of Fire and Thunder, inviting his wrath upon your enemy. It can only be cast outdoors, and summons a bolt of lightning from the sky, striking the target for 5k2 Wounds. Everyone within 10' of the target must make a Stamina roll versus a TN of 15 to avoid being deafened for 2 Rounds. If this spell is cast during a thunderstorm, the damage is increased to 6k2 for a moderate storm and 6k3 for a disastrous storm or hurricane."},{"id":"katana_of_fire","nome":"Katana Of Fire","elemento":"fire","mastery":"1","area":"One created weapon","alcance":"Personal or 20' (see script description)","duracao":"5 minutes","descricao":"You summon a blade of pure fire, blazing like the soul of an honorable warrior. The weapon's default form is a katana, but one Raise can change its form to any other sword of your choosing. The katana has a DR of 2k2. When wielding this weapon, you may use your School Rank in place of your Kenjutsu Skill if you wish. If you do possess the Kenjutsu Skill, you add your Honor Rank to all damage rolls made with this weapon. The katana of fire disappears if it is lost from your hand. Instead of summoning the katana for yourself, you may cause it to appear in the hands of an ally within 20 feet. He is treated as the caster for all purposes of the spell, but does not gain the Honor boost to damage."},{"id":"never_alone","nome":"Never Alone","elemento":"fire","mastery":"1","area":"One target","alcance":"Touch","duracao":"5 Rounds (see script description)","descricao":"This spell invokes Fire's element of knowledge and understanding, strengthening the spirit of one of your allies by opening his eyes to the courage of his ancestors. The target of the spell receives a bonus to all attack rolls, Skill rolls, and Trait Rolls equal to your Fire Ring. This effect lasts until either the spell expires, or until the target fails an attack roll or Skill Roll, or until the target suffers Wounds from any source, whichever comes first."},{"id":"the_fires_that_cleanse","nome":"The Fires That Cleanse","elemento":"fire","mastery":"1","area":"c Area: 30' radius","alcance":"Self","duracao":"Instantaneous","descricao":"Destruction is one of the basic impulses of Fire, and this spell calls on that urge to spread destruction in the caster's surroundings. The spell whips the kami into a frenetic chaos, destroying everything around you. Everyone in the area of effect, including you, suffers damage with DR equal to your Fire Ring. This result is rolled once and applied to everyone within the area. However, you take only half damage (rounded up), since the kami makes some effort to avoid you."},{"id":"the_raging_forge","nome":"The Raging Forge","elemento":"fire","mastery":"1","area":"One weapon or armor","alcance":"Touch","duracao":"Instantaneous","descricao":"Fire is the element of creation as well as destruction, and a skilled shugenja can use this to great effect. This spell invokes the powers of the forge, mighty and merciless, to remake a material item, such as a weapon or suit of armor, into its perfect form. The target item loses all blemishes, including cracks or nicks. This spell cannot repair an item which has actually been broken or destroyed, however, and it can only affect items that are of ordinary quality."},{"id":"boundless_sight","nome":"Boundless Sight","elemento":"void","mastery":"1","area":"Self","alcance":"50 miles","duracao":"4 rounds","descricao":"The most essential lesson of the ishiken is that all is linked through the Void, and through the Void all can be perceived. By focusing your energy, you can look through the veil and see another location as if you were standing there. This location must be familiar to you, and you must have been there at least once before. For the duration of the spell, you can see and hear all that transpires in the other location, but you may not be detected and you may not interact with things or individuals there in any way. During this spell, your body is in a trance-like state that leaves you highly vulnerable to attack (your Armor TN is reduced to 5)."},{"id":"drawing_the_void","nome":"Drawing The Void","elemento":"void","mastery":"1","area":"Self","alcance":"Personal","duracao":"Instantaneous","descricao":"The ability to reach into the Void itself and gain strength from it is a vital lesson in the training of all ishiken. Upon completion of this spell, you gain a number of additional Void Points equal to your School Rank plus one. If these Void Points take you above the number you may normally possess, then you lose one of the extra Void Points every Round that you do not spend one."},{"id":"flow_through_the_void","nome":"Flow Through The Void","elemento":"void","mastery":"1","area":"Up to one cubic foot of pure elemental matter","alcance":"Touch","duracao":"Permanent","descricao":"In the Void, all things are equal, all one and none. By tapping into this connection, you may transform a small amount of pure elemental matter(water, fire, air, or Earth in the form of dirt or soil) into anyone other element."},{"id":"see_through_lies","nome":"See Through Lies","elemento":"void","mastery":"1","area":"Target individual","alcance":"25'","duracao":"Instantaneous","descricao":"The patterns that comprise all things in the Void exist in individuals as well, and with training, ishiken can recognize them. You learn the highest point Advantage or highest point Disadvantage (your choice) possessed by the target of this spell."},{"id":"sense_void","nome":"Sense Void","elemento":"void","mastery":"1","area":"25' radius around the caster","alcance":"Personal","duracao":"Concentration","descricao":"Life is evident in the Void like the stars in the night sky. This spell causes you to enter a trance during which you become aware of the existence and location of all living creatures within the radius of the spell. Although you are aware of their location, you cannot see them or any details. You would know if there were the three humans waiting outside the castle wall, for instance, but you would not recognize them other than to know that they were present. This also gives you information regarding non-sentient, natural living creatures. Spirits and Shadowlands creatures are recognizable as a gap in your awareness, although this spell cannot recognize Tainted humans as anything other than humans."},{"id":"the_voids_caress","nome":"The Void's Caress","elemento":"void","mastery":"1","area":"One target individual","alcance":"Touch","duracao":"1 minute","descricao":"Although beginning students of ishiken-do cannot affect the pattern of the Void, they can make very short-term alterations to it. You may negate any one Mental or Spiritual Disadvantage of the target of this spell posseses, up to a maximum of 5 points in value. The Shadowlands Taint may not be removed via this spell, although the mental disorders that can be caused by it can be temporarily alleviated."},{"id":"touch_the_emptiness","nome":"Touch The Emptiness","elemento":"void","mastery":"1","area":"One target individual","alcance":"30'","duracao":"Instantaneous","descricao":"The sensation of experiencing the Void firsthand can be extremely disturbing for those unaccustomed to it. The target of this spell suffers 1k1 damage and is dazed."},{"id":"witness_the_untold","nome":"Witness The Untold","elemento":"void","mastery":"1","area":"One target individual","alcance":"15'","duracao":"3 rounds","descricao":"It is possible to gain fleeting glimpses of things that have not yet happened by peering through the Void. If you are delaying your action, you may interrupt the target of the spell after he has declared his action but before he has taken his action when his turn comes up. This may be done during each Round for the duration of the spell. (Normally someone delaying their Action cannot interrupt the Action of another participant.)"},{"id":"bo_of_water","nome":"Bo Of Water","elemento":"water","mastery":"1","area":"One created weapon","alcance":"Personal or 20' (see spell description)","duracao":"5 minutes","descricao":"You summon a staff of pure water, as rigid as the real thing despite its fluid nature. The weapon's default form is a Bo, but one Raise can change its form to any other staff of your choosing. The weapon has DR 1k2. If you do not possess the Staves Skill, you may instead use your School Rank in its place. If you do possess the Staves Skill, using this weapon grants you one Free Raise that can only he used on the Knockdown Maneuver. This weapon disappears if it is lost from your hand. Instead of summoning the Bo for yourself, you may cause it to appear in the hands of an ally within 20 feet. He is treated as the caster for all purposes of the spell, but he does not gain the Free Raise bonus."},{"id":"clarity_of_purpose","nome":"Clarity Of Purpose","elemento":"water","mastery":"1","area":"10' radius around caster","alcance":"Personal","duracao":"2 rounds","descricao":"One of the many strengths of Water is in its speed. All allies within the area of effect of this spell gain a bonus of +5 to their Initiative Scores for the duration of the spell."},{"id":"ebbing_strength","nome":"Ebbing Strength","elemento":"water","mastery":"1","area":"One target creature","alcance":"20'","duracao":"3 rounds","descricao":"Energy flows through the universe just as water flows through the mortal shell. You may send your energy to another, weakening yourself and strengthening them in the process. You may reduce anyone of your Physical Traits by an amount up to your School Rank. The target of this spell increases the same Physical Trait by the same amount. If your Trait is reduced to 0 as a result of this spell, you immediately fall unconscious and the spells duration is reduced to 1 round. No trait may be enhanced above double its normal rank by this spell."},{"id":"path_to_inner_peace","nome":"Path To Inner Peace","elemento":"water","mastery":"1","area":"One target individual","alcance":"Touch","duracao":"Instantaneous","descricao":"The water kami can influence the flow of water through the body, dramatically hastening the natural healing process. You can use this spell to heal Wounds that another individual has suffered. This spell restores a number of Wounds to the target equal to the amount by which the Spell Casting Roll exceeded the spells TN to cast."},{"id":"reflections_of_pan_ku","nome":"Reflections Of Pan Ku","elemento":"water","mastery":"1","area":"One object","alcance":"Touch","duracao":"Instantaneous","descricao":"Divining the abilities of an object is among the simplest lessons a student of water learns in the temple. If this spell is successfully cast on an object, you automatically learn all powers and abilities that object possesses. This is most frequently used to identify any supernatural qualities an item possesses, such as a Nemuranai or a cursed weapon, but it can also identify the spell contained within a shugenja's prayer scroll. This spell will not allow a shugenja to read a scroll if it is written in a cipher he does not understand, but he can at least identify the spell in question. This spell will also grant the caster knowledge of the item's origin in very broad strokes, such as where it was forged, the Clan of the individual who has carried it the longest, or something similar at the GM's discretion."},{"id":"reversal_of_fortunes","nome":"Reversal Of Fortunes","elemento":"water","mastery":"1","area":"One target individual","alcance":"10'","duracao":"3 rounds","descricao":"Versatility is the domain of water, and those who carry its blessing reap the rewards. For the duration of this spell, the target may immediately re-roll anyone roll per round. This must be done immediately after the first roll is completed, and the target may keep either result."},{"id":"speed_of_the_waterfall","nome":"Speed Of The Waterfall","elemento":"water","mastery":"1","area":"One target individual or creature","alcance":"Touch","duracao":"1 hour","descricao":"Those filled with the essence of water find their movement far faster than ever before. The target of this spell may move a total distance per round equal to their Water x 20' plus an amount equal to twice your Water Ring, This spell does not grant the target additional movement, it simply increases the maximum possible amount they can move during a Round for the duration of the spell."},{"id":"spirit_of_the_water","nome":"Spirit Of The Water","elemento":"water","mastery":"1","area":"One target individual","alcance":"20'","duracao":"Instantaneous","descricao":"The spirit of Water is both fluid and rapid. The target gains one additional Simple Action during the Reactions Stage of the Round in which this spell is completed. This Action cannot be used to make an attack."},{"id":"sympathetic_energies","nome":"Sympathetic Energies","elemento":"water","mastery":"1","area":"One target individual","alcance":"25'","duracao":"Instantaneous","descricao":"Energy flows between all living things as water flows through the Earth, You may transfer any one existing spell effect from you to the willing target of this spell. With three Raises, you may transfer one spell effect from one willing target to another willing target. You cannot transfer spells between unwilling targets."},{"id":"the_rushing_wave","nome":"The Rushing Wave","elemento":"water","mastery":"1","area":"One target individual","alcance":"10'","duracao":"1 round","descricao":"You can temporarily increase the speed of your target. This spell allows the target to make a Free Move Action of up to his Water Ring x 10' (instead of the normal x 5'). Without Raises for Duration, this benefit must be used on the target's next Turn or it is lost."},{"id":"bentens_touch","nome":"Benten's Touch","elemento":"air","mastery":"2","area":"Target individual (may be the caster)","alcance":"Personal / Touch","duracao":"1 hour","descricao":"By calling upon the air kami to whisper suggestions to others, you may cause them perceive the target of this spell more positively than they otherwise might. The target of this spell gains a bonus of + 1k1, plus your Air Ring, the total of all Social Skill rolls made for the duration of the spell."},{"id":"call_upon_the_wind","nome":"Call Upon the Wind","elemento":"air","mastery":"2","area":"Target individual (may be the caster)","alcance":"Personal or 20'","duracao":"1 minute","descricao":"The winds can lift and buoy, carrying even the heaviest burden into the skies for short periods. The target of this spell gains a limited form of flight, allowing him to move through the air unimpeded. The target of the spell may make Free Move Actions, but not Simple Move Actions, and may never move more than 10' per round. Heavy winds can interfere with this movement or prevent it altogether. At the end of the spells duration, the target drifts harmlessly the ground, no matter how high he might be."},{"id":"hidden_visage","nome":"Hidden Visage","elemento":"air","mastery":"2","area":"Self","alcance":"Personal","duracao":"5 minutes","descricao":"Air kami are mischievous and capricious, and enjoy anything they perceive as a joke. You may call upon them create a subtle illusion, altering your facial features just enough that you appear to be a different person. This spell does not allow you to impersonate specific individuals, or even people radically different from you, you appear as a person of the same age, build, race, and gender. The differences are subtle, enough so that you could be mistaken for your own brother or cousin."},{"id":"mist_of_illusion","nome":"Mist of Illusion","elemento":"air","mastery":"2","area":"10' radius","alcance":"20'","duracao":"1 minute","descricao":"With greater fluency with the kami comes the ability to craft increasingly convincing images from the stuff of the wind itself. You may create illusions of any object, individual, or image that you can imagine. These images are stationary, and they must fit within the spells area of effect, but they can be as simple or complex as desired. These illusions are visual only, with no auditory component, odors, etc."},{"id":"secrets_on_the_wind","nome":"Secrets on the Wind","elemento":"air","mastery":"2","area":"20' radius","alcance":"10 miles","duracao":"Concentration","descricao":"The kami can carry whispers across an Empire, if properly entreated to do so. This spell requires you to perform a preparation ritual in order to cast it effectively. The ritual requires ten minutes of uninterrupted meditation in the area designated as the spells area of effect. Any time within the 48 hours immediately following this ritual, you may cast this spell, and overhear anything being said in the prepared area. If your concentration is disrupted, the effect ends and may not be renewed without an additional preparation ritual. Only one area may be prepared via this ritual at one time."},{"id":"the_kamis_whisper","nome":"The Kami's Whisper","elemento":"air","mastery":"2","area":"10' radius","alcance":"50'","duracao":"1 round","descricao":"The kami of the wind can carry whispers for great distances, and can even create them if properly entreated. You can petition the kami create a false sound, either a voice or a natural sound such as an animal's growl or running water, for example. The sound can be no louder than a normal speaking voice, and cannot impersonate a specific person's voice. If used create the sound of a voice, the spell is limited to twenty words."},{"id":"whispering_wind","nome":"Whispering Wind","elemento":"air","mastery":"2","area":"Target individual","alcance":"20'","duracao":"Instantaneous","descricao":"The air kami see very little difference between speech and thought, and can perceive both with relative ease. By comparing the two, the kami can determine if what has been spoken is true, or a lie. Unfortunately, they have notoriously short attention spans, and thus can only assess extremely recent conversations. By invoking this spell, you may determine if the last thing said by the target was true or false. The kami have no concept of personal opinion, however, and if the target truly believes what he said was true, the kami will believe it as well."},{"id":"wolfs_proposal","nome":"Wolf's Proposal","elemento":"air","mastery":"2","area":"Self","alcance":"Personal","duracao":"10 minutes","descricao":"This spell, crafted to initiate relations between groups, is easily twisted to nefarious purposes. It calls the kami create a subtle aura of suggestion around the caster, one that does not disguise the caster but rather causes others perceive him as slightly more benevolent than perhaps he truly is. For the duration of this spell, your Honor Rank is considered three ranks higher for the purposes of any Lore:Bushido rolls made to determine your Honor Rank."},{"id":"be_the_mountain","nome":"Be The Mountain","elemento":"earth","mastery":"2","area":"One target creature","alcance":"30'","duracao":"4 rounds","descricao":"A variant of the spell Armor of Earth, designed to protect allies, this prayer causes the Earth kami to envelop the target with their embrace, covering his skin with a stony barrier that repels physical blows. The target gains Reduction of a value equal to 5x the caster's School Rank to a maximum of 20, but cannot take Simple Move Actions for the duration of the spell (Free Move Actions are still allowed). Only a willing ally can be targeted with this spell."},{"id":"earth_becomes_sky","nome":"Earth Becomes Sky","elemento":"earth","mastery":"2","area":"One target creature","alcance":"100'","duracao":"Instantaneous","descricao":"This spell summons up several huge boulders from the earth, and hurls them through the air to unerringly strike one (or more) target creatures. The target struck by these boulders suffers damage with a DR equal the caster's Earth rank. If the caster strikes multiple targets, the DR is reduced by 1k1 for each additional target, to a minimum of 1k1 damage per target. These boulders are made of normal, mundane stone, and thus cannot normally bypass Reduction or Invulnerability, but a powerful caster can infuse the boulders with the power of Jade."},{"id":"embrace_of_kenrojijin","nome":"Embrace Of Kenro-ji-jin","elemento":"earth","mastery":"2","area":"One target creature","alcance":"Personal or Touch","duracao":"1 hour","descricao":"This spell allows the target (who can be the caster or one other person) to literally dive into the ground, which becomes as clear and easy to traverse as water for him. He can see for a distance of 100 yards through the Earth, and can move through it in any direction as easily as though he were in normal air. The target can see through the edge of the Earth into the normal world, but he cannot attack, cast spells, speak, hear, or otherwise interact with those outside the Earth unless he emerges from the ground (at which point the spell immediately ends). If the spell ends while the target is still underground, the Earth spirits are offended by the Target's continued presence, and immediately expel him into the nearest open air, wherever that might be."},{"id":"force_of_will","nome":"Force Of Will","elemento":"earth","mastery":"2","area":"One target","alcance":"50'","duracao":"2 rounds","descricao":"This spell infuses the target with an intense resistance to pain and death, as the Earth kami bolster his will to live to superhuman levels. He is able to shrug off the pain and shock of his wounds, even continuing in the face of lethal injuries for a short time. For the duration of this spell, the target is immune to all Wound Rank penalties and effects - including the effect of being dead if the Out rank is completely filled. When the spell expires, however, the full effects of any Wounds apply immediately - thus, this spell typically affords either a brief chance to be healed before it is too late, or the chance to wage a final battle in the face of certain death."},{"id":"grasp_of_earth","nome":"Grasp Of Earth","elemento":"earth","mastery":"2","area":"One target","alcance":"50'","duracao":"5 rounds","descricao":"This spell causes the Earth kami to reach up and seize hold of the target, often taking the form of a massive hand or claw which grips the unfortunate creature in stony digits. The target is rendered near-immobile, able to move only 3' per round as a Simple Move Action, and unable to move at all with a Free Move Action. The target may break free by spending a Complex Action and rolling Raw Strength at a TN equal to 5x the caster's Earth."},{"id":"hands_of_clay","nome":"Hands Of Clay","elemento":"earth","mastery":"2","area":"Self","alcance":"Personal","duracao":"10 minutes","descricao":"This spell infuses Earth spirits into the hands and feet of the caster, allowing them to merge with the Earth found in wood, earth, and stone. This allows the caster to walk and climb along sheer surfaces, including walls and cliffs, at half his normal movement speed (rounded up). He can even hang from ceilings and move along them, although in that case he can only move 3' with a Simple Action. When the spell ends, the effect concludes without warning, possibly leading to a painful fall."},{"id":"the_mountains_feet","nome":"The Mountain's Feet","elemento":"earth","mastery":"2","area":"One target","alcance":"Personal or 20'","duracao":"1 hour","descricao":"This spell fortifies the target by rooting his feet the stone and soil beneath, allowing him to shrug off anything that might separate him from the much of Earth. The target gains +3k0 to resist all Knockdown maneuvers, and any spell which seeks to knock down the target, lift him into the air, or otherwise break his connection the Earth must win a Contested roll of the spells Element against the caster's Earth."},{"id":"wholeness_of_the_world","nome":"Wholeness Of The World","elemento":"earth","mastery":"2","area":"One target creature","alcance":"Personal or 20'","duracao":"10 minutes","descricao":"This spell infuses the target with the strength of Earth to such a degree that his Rings and Traits become wholly resistant to any effort to change them. Any physical or magical effect which would raise or lower his Traits or Rings is completely ineffective for the duration of those spell, as the Earth kami normally rebuff any such efforts to alter the target's Elemental balance."},{"id":"disrupt_the_aura","nome":"Disrupt The Aura","elemento":"fire","mastery":"2","area":"Target person or creature","alcance":"50'","duracao":"24 hours","descricao":"Anyone whose elements are out of balance will feel the effects, and this spell creates this condition deliberately by aggravating the Fire present in the target's body. While the spell is in effect, the target cannot be healed by magical means. Magical spells, items, or Techniques that attempt to restore Wounds to the target automatically fail. (Mundane wound treatment with the Medicine skill will still be effective.) The target may realize something is physically wrong with him but cannot find out what is happening without the help of a shugenja - casting Sense (Fire will show the presence of many excited Fire spirits within the target."},{"id":"enticing_dance_of_the_flame","nome":"Enticing Dance Of The Flame","elemento":"fire","mastery":"2","area":"20' radius","alcance":"50'","duracao":"2 rounds","descricao":"A more potent version of The Fires That Cleanse, this spell keeps the Fire kami under tighter control and persuades them to remain present for longer. If the spell is cast successfully, Fire kami erupt into a violent, ferocious dance at a location of your choice, igniting that area into flames. Every target in the area takes 3k2 Wounds on the Round the spell takes effect. At the beginning of each subsequent Round, if the spell is still active, every target still in the affected area takes an additional 2k1 Wounds."},{"id":"hurried_steps","nome":"Hurried Steps","elemento":"fire","mastery":"2","area":"Self","alcance":"Personal","duracao":"2 rounds (see script description)","descricao":"Fire is the element of thought, and thought is swift indeed. You draw upon the speed of the Fire kami to aid you in the next spell you cast. The casting time of the next Fire spell you cast is reduced by 4 Rounds. If the next spell is Mastery Level 3 or lower, it casts instantaneously as a Simple Action. If you do not begin casting the new spell within the next 2 Rounds, however, the benefit of Hurried Steps elapses."},{"id":"mental_quickness","nome":"Mental Quickness","elemento":"fire","mastery":"2","area":"One item","alcance":"Touch","duracao":"10 minutes","descricao":"Fire kami can be imbued into physical objects, allowing them to remain present for longer periods of time. Shugenja have devised many ways to use this technique to aid themselves and others. This spell, one of the most basic of this kind, imbues a material item with the cleverness and wit of fire. Anyone who carries that item has their Intelligence Trait increased by 3 for the duration of the spell."},{"id":"relentless_heat","nome":"Relentless Heat","elemento":"fire","mastery":"2","area":"One armor","alcance":"Touch","duracao":"10 Rounds","descricao":"This spell is designed to protect bushi by infusing a Fire kami into their armor. The spell targets one suit of armor, which glows with the strength of the merciless desert sun. Any opponent who attempts to strike the person wearing the armor, whether or not the attack hits, is immediately considered to be Fatigued until the beginning of their next Tum. The penalties apply to the attack roll that triggered the spell, and any attackers in the Full Attack Posture immediately assume the Attack Posture instead. This spell has no effect on ranged attacks or spells that target the wearer of the armor."},{"id":"tail_of_the_fire_dragon","nome":"Tail Of The Fire Dragon","elemento":"fire","mastery":"2","area":"Self","alcance":"Personal","duracao":"4 rounds","descricao":"This spell invokes several Fire kami to form a whip-like tendril that extends from the caster's hand. The tendril of flame will not burn you, since the kami are grateful for the opportunity to burn others at your command. You may use this tendril to strike enemies as far as 30' away, extending it out and back with blinding speed. Your attack roll with the tendril is equal to your Agility + (twice your School Rank), keeping your Agility. The tendril has a DR equal to your Fire Ring."},{"id":"the_fires_from_within","nome":"The Fires From Within","elemento":"fire","mastery":"2","area":"One target","alcance":"100'","duracao":"Instantaneous","descricao":"Probably the most widely known and recognized offensive spell in the element of Fire. This prayer has been in use by Rokugani shugenja since the very earliest days of the Empire. You summon Fire kami to form an orb of flame that hovers in your palm for a moment before streaking toward the target. The sphere gains momentum and size until it hits its target, making it quite spectacular visually. The spell has a DR equal to your Fire Ring."},{"id":"ward_of_purity","nome":"Ward Of Purity","elemento":"fire","mastery":"2","area":"15' radius from the object touched","alcance":"Touch","duracao":"1 day","descricao":"Although Earth is the traditional method of opposing evil forces like the Shadowlands Taint, the spirits of Fire can also be invoked to purge and destroy such spiritual abominations. This spell binds a Fire kami into a specific location which it protects against the forces of evil. Casting the spell requires inscribing elaborate kanji on a flat surface in chalk or ink, and takes one minute of concentrated effort, after which the Spell Casting Roll must be made. Once the Ward of Purity is activated and the power of the kami is fully engaged, however, the kami within the inscription protects the area against the influence of the Shadowlands or the Lying Darkness. Persons or creatures with at least 1 Shadowlands Taint Rank, or who are under the control of the Lying Darkness, must make a successful Contested Willpower Roll against you in order to enter the Ward's area of effect; you gain a +5 bonus to this roll. In addition, those creatures who successfully enter the area suffer extreme pain, as the power of the ward burns their very essence. Their bodies ignite and they suffer Wounds equal to the total of your Fire Ring + insight Rank each Round they remain within the area of effect. Spells and missiles are unaffected by Ward of Purity. The object upon which the ward is inscribed must remain immobile and the inscription must remain dearly visible at all times, or else the Ward is dispelled. If overlapping Wards of Purity are present, their effects do not stack."},{"id":"altering_the_course","nome":"Altering The Course","elemento":"void","mastery":"2","area":"Self","alcance":"Personal","duracao":"1 minute","descricao":"Ishiken have a much greater capacity to draw upon the Void than others, and may do it consciously rather than unconsciously. You may spend multiple Void Points on any roll made within the duration of this spell. It still must be a roll on which the expenditure of Void Points is allowable (no damage rolls may be augmented via this spell, for example."},{"id":"drink_of_your_essence","nome":"Drink Of Your Essence","elemento":"void","mastery":"2","area":"One target individual","alcance":"30'","duracao":"Instantaneous","descricao":"As an ishiken grows more powerful, he can gain more information from examining an individual's pattern within the Void. You learn a great deal of information about the target of this spell, including his individual Rings (but not Traits), his current Wound penalties, and a one word summation of his present mood (\"hostile, \"sorrowful,\" \"confused,\" etc.)."},{"id":"false_whispers","nome":"False Whispers","elemento":"void","mastery":"2","area":"One target individual","alcance":"30'","duracao":"1 minute","descricao":"Mingling the Void of two beings, even for just a moment, can lead to one of the two being manipulated if he is not prepared for it. The target of this spell will repeat the next sentence you say, verbatim, without any foreknowledge of what he is doing. They speak the words in their own normal voice, regardless of how you speak it. This effect will not allow others to cast spells, even if you have them recite a portion of a spell. This spell only allows the effect once, the first time you speak a single sentence during the duration of the spell."},{"id":"reach_through_the_void","nome":"Reach Through The Void","elemento":"void","mastery":"2","area":"Target object, up to five pounds in weight","alcance":"50'","duracao":"Instantaneous","descricao":"All things, both living and un-living, exist within the Void, and can be touched through it. You can manipulate items through the Void, moving them without touching them. These items are small, usually only up to only five pounds, although a powerful shugenja can raise enough to move somewhat heavier items."},{"id":"severed_from_the_stream","nome":"Severed From The Stream","elemento":"void","mastery":"2","area":"One target individual","alcance":"25'","duracao":"5 rounds","descricao":"Talented ishiken can rob others of their ability to tap into the Void, if only temporarily. If this spell is successful, the target must succeed at a Contested Void Roll against you before they are able to spend any Void Points. This roll does not count as an action for the target, and they must succeed at only one Contested Roll per turn, even if they are spending multiple Void Points per turn as a result of a Technique or other ability."},{"id":"the_empty_voice","nome":"The Empty Voice","elemento":"void","mastery":"2","area":"Self","alcance":"Personal","duracao":"5 minutes","descricao":"Drawing on the essence of everything allows an ishiken to invoke the kami with far greater ease than normal. For the duration of this spell, you may cast spells of other elements without speaking your prayers aloud. This applies only to spells of equal or lower Mastery Level (any spell of Mastery Level l or 2)."},{"id":"cloak_of_the_miya","nome":"Cloak Of The Miya","elemento":"water","mastery":"2","area":"Self","alcance":"Personal","duracao":"5 rounds","descricao":"You wrap yourself in the protective embrace of the wave. Your Armor TN is increased by an amount equal to your Water Ring plus your School Rank for the duration of this spell."},{"id":"inaris_blessing","nome":"Inari's Blessing","elemento":"water","mastery":"2","area":"Created sustenance","alcance":"Personal","duracao":"Instantaneous","descricao":"Inari is the Fortune of Rice, and one of the most beloved of all divine entities throughout the Empire. This spell invokes Inari's blessing, and creates nourishing food and drink at your command. This spell generates enough food and drink to sustain a number of individuals equal to your School Rank + 1 for one day. Without Raises, this food is bland but sustaining, such as unflavored rice and water, but with Raises, you can increase the quality of the food to seafood or tea at the GM's discretion. The TN to cast this spell is doubled when in the Shadow lands."},{"id":"reflective_pool","nome":"Reflective Pool","elemento":"water","mastery":"2","area":"Body of water / target location","alcance":"10 miles","duracao":"5 minutes","descricao":"The inscrutable knowledge of Water is a great boon to those who know the means by which it can be invoked. You may stare into a body of water, which may be as small as a puddle, and through it view a familiar location as if you were present, although you can only see what is taking place, not hear it. In order for a location to be familiar to you, you must either have spent a great deal of time there (your home, the dojo, a preferred temple, etc.), or have spent a minimum of ten minutes in meditation at the location. Any body of water can be used for this spell, but since the visions imparted are visual images depicted will be clearer with larger bodies."},{"id":"rejuvenating_vapors","nome":"Rejuvenating Vapors","elemento":"water","mastery":"2","area":"One target individual","alcance":"Touch","duracao":"Instantaneous","descricao":"Water washes away all that is impure, refreshing and reinvigorating all it touches. The target of this spell is instantly refreshed as if he had just arisen from a full night's sleep. This does not restore spent Void Points, but can eliminate fatigue and exhaustion. When used on a shugenja, this spell does restore the spell slots associated with the Void Ring (which can be used for any elements), but not the spell slots associated with other Rings. Abilities that characters may use a limited number of times per day are not refreshed by this spell. No Individual can benefit from Rejuvenating Vapors more than once within a 24-hour period."},{"id":"stand_against_the_waves","nome":"Stand Against The Waves","elemento":"water","mastery":"2","area":"One target individual","alcance":"10'","duracao":"Instantaneous","descricao":"A samurai who possesses the speed and strength of the mighty river is a dangerous foe indeed. The target of this spell gains a Simple Action during the Reaction Stage of the current Combat Round. This action may only be used to make an attack. If the target is incapable of making an attack as a Simple Action, this spell grants him a Complex Action instead. This spell cannot award a shugenja the ability to cast a second spell in the same Round."},{"id":"the_ties_that_bind","nome":"The Ties That Bind","elemento":"water","mastery":"2","area":"Self","alcance":"10 miles","duracao":"Instantaneous","descricao":"Even the lightest touch forges a connection, and through the spirits of water that connection may be explored. This spell allows you to seek out the spirits of Water within a single, specific object. You must be familiar with the object in question, either having spent a great deal of time around it or handled it personally. If the object is within the range of this spell, you will know the direction and relative distance it is from your current position."},{"id":"waveborne_speed","nome":"Wave-borne Speed","elemento":"water","mastery":"2","area":"Self","alcance":"Personal","duracao":"2 Rounds","descricao":"The speed of the river can be imparted by knowledgeable shugenja. Your Water Ring is increased by 2 for the purposes of determining how far you may move as part of any Move Actions made during the present Round or the following Round."},{"id":"essence_of_air","nome":"Essence Of Air","elemento":"air","mastery":"3","area":"Self","alcance":"Personal","duracao":"5 rounds","descricao":"Air can be merged with the essence of a mortal, and doing so can impart tremendous abilities, albeit at great risk the caster. You mix with the wind itself and become insubstantial. You may not interact with any physical objects while insubstantial, although you remain on the ground, and you may pass through solid objects at a rate of one foot per round. Your Water Ring is considered halved (rounded down) while you remain insubstantial, and you may not cast any other spells until you return to solidity."},{"id":"mask_of_wind","nome":"Mask Of Wind","elemento":"air","mastery":"3","area":"Self","alcance":"Personal","duracao":"1 hour","descricao":"A skilled shugenja can petition the kami to create incredibly elaborate illusions to obscure ones identity and appearance. You may use this spell to adopt the appearance of any humanoid creature of approximately the same size, up to one foot taller or shorter than you. You could use this spell to assume the guise of a kenku, for example, because they are roughly the same size as humans. A goblin or an ogre would be impossible, however, because they are to short and to large, respectively."},{"id":"striking_the_storm","nome":"Striking The Storm","elemento":"air","mastery":"3","area":"Self","alcance":"Personal","duracao":"3 rounds","descricao":"The most powerful winds can turn aside not only arrows, but steel as well. You may summon a buffet of winds that surrounds you in an unrelenting cocoon of swirling air. Your Armor TN is increased by +20 against both melee and ranged attacks. The force of the winds surrounding you prevents you from hearing others if they speak to you, however."},{"id":"summon_fog","nome":"Summon Fog","elemento":"air","mastery":"3","area":"50' radius","alcance":"100'","duracao":"1 minute","descricao":"The kami can be petitioned to coalesce in an area as they do in the coast, creating a thick, obscuring fog. Within the area affected by your spell, the visibility is decreased to a meager five feet. Fabrics and other absorbent materials within the spells area of effect will become damp or even wet if they remain within it long enough. Small sources of open flame such as candles, might be extinguished as well, at the GM's discretion. The moistness of fog is extremely damaging to rice paper."},{"id":"summoning_the_gale","nome":"Summoning The Gale","elemento":"air","mastery":"3","area":"Target individual (may be the caster)","alcance":"50'","duracao":"Concentration","descricao":"Swirling winds can be commanded to circle a designated target, preventing ranged attacks being made in either direction. This spell affects an area thirty feet around the target in all directions. Everyone within the affected area gains a + 15 bonus to their Armor TN against ranged attacks. However, everyone within the area also suffers a penalty of -3k3 to all ranged attack rolls."},{"id":"the_eye_shall_not_see","nome":"The Eye Shall Not See","elemento":"air","mastery":"3","area":"Self or target individual","alcance":"Personal or Touch","duracao":"Concentration","descricao":"You call upon the kami to create an area of distraction surrounding you, drawing all attention away from you and your actions. The kami whisper in the ears of those within 20' of you (or of the target if you cast the spell on someone else), causing them to be conveniently distracted from your presence. You are not invisible, but those within 20' of you will not see you as long as you do not make any loud noises or otherwise draw attention to yourself. Those outside that distance are not distracted, however, and will see you perfectly well regardless of your action or inaction."},{"id":"your_hearts_enemy","nome":"Your Heart's Enemy","elemento":"air","mastery":"3","area":"One target individual","alcance":"25'","duracao":"5 rounds","descricao":"The kami can see into the hearts of mortals, and can use that information at a shugenja's request. You manifest the Kami as an illusion of the thing your target fears most in the world. It may be an individual (the man who killed his father), or an item (a cursed blade that brought ruin this family), or even a vista of some sort (an image of an enemy slaying his family). This effectively generates Fear 4 that the target must overcome (see the Book of Earth for rules regarding Fear). Only the target can see the specifics of the illusion, others see only a hazy outline that appears to be a small fog cloud."},{"id":"bonds_of_ningendo","nome":"Bonds Of Ningen-do","elemento":"earth","mastery":"3","area":"One target spirit creature","alcance":"500'","duracao":"30 days","descricao":"This spell is a more powerful and specialized form of Minor Binding. It is a ritual designed to bind or dispel troublesome creatures from the various spirit realms. Any creature from the realms of Sakkaku, Chikushudo, Gaki-Do, Toshigoku, or Yume-Dan be affected by this spell. Casting it requires 10 minutes, although if additional shugenja who know the spell assist in the ritual, the time is reduced by 1 minute per additional shugenja, to a minimum of 1 minute. If the targeted creature is within range of the caster(s) when the spell is successfully completed, the creature can be either bound or dispelled. If it is bound, it must obey the caster's commands for the duration of the spell, although suicidal commands will break the spell - this is how the Kuni have forced mujina spirits to labor for them in their iron mines. (It should be noted that this use of the spell is considered controversial and even blasphemous by many in Rokugan.) If the creature is dispelled, it immediately leaves Ningen-Do its native spirit realm, and cannot return until the spells duration ends. Either way, the spirit creature will regard the caster as an enemy thereafter, and is likely to seek vengeance if it can."},{"id":"earth_kamis_blessing","nome":"Earth Kami's Blessing","elemento":"earth","mastery":"3","area":"Caster or one target creature","alcance":"Personal or 20'","duracao":"10 minutes","descricao":"This spell infuses the target (which may be the caster or one of his allies) with the strength and resilience of the Earth, making him rougher and more firm-minded. For the duration of the spell, the target gains +2 Wounds per Wound Rank, and gains + 1k1 on all rolls involving the Earth Ring and its associated Traits. When the spell expires, any Wounds the target has suffered still remain, and this may drive him into a lower Wound Rank or even kill him."},{"id":"earths_protection","nome":"Earth's Protection","elemento":"earth","mastery":"3","area":"10' radius from caster","alcance":"Personal","duracao":"Concentration","descricao":"This spell calls on the spirits of Earth to protect the area around the caster from the effects of the other three Elements (Air, Fire, and Water) for a short time. While the caster concentrates on maintaining the favour of the Earth spirits, the effects of spells which call on those other three elements are mitigated. Any hostile Air, Fire, or Water spell cast within the area of Earth's Protection, or extending its effects into that area, will suffer a + 10 TN penalty to the Spell Casting roll. In addition, any damage which those spells inflict on creatures within Earth's Protection will be reduced by 1k1 (to a minimum of 1k1)."},{"id":"purge_the_taint","nome":"Purge The Taint","elemento":"earth","mastery":"3","area":"50' radius around caster","alcance":"Personal","duracao":"Permanent","descricao":"This spell was originally created by the Kuni family and is still primarily practised by them, although knowledge of its prayers has spread to other Clans. It is an elaborate ritual spell, requiring an hour to cast, that calls on the powers of Earth to purge the land of the Shadowlands Taint, driving out all the evil kansen in the area. The spell will remove all the Taint from the land, plant life, and inanimate objects within the area of effect. It will not remove Taint from living creatures, nor will it affect powerful Tainted artifacts or objects made of obsidian. The removal of the Taint, however, is not without price. The elemental kami in the area of effect are also weakened and purged by the spell, especially the Earth spirits whose efforts are called upon to power it. In the aftermath of casting this spell, the local spirits will be scattered and weakened, inflicting a + 15 TN penalty on all Spell Casting rolls within the area. This negative effect will sometimes fade with time, especially if it was cast in a single location surrounded by normal lands. But if the spell is cast over a wide area, such as the Kuni Wastes, the elemental kami will usually permanently leave the area, reducing it to a gray, lifeless wasteland."},{"id":"sharing_the_strength_of_many","nome":"Sharing The Strength Of Many","elemento":"earth","mastery":"3","area":"One to six target persons within range","alcance":"30'","duracao":"5 rounds","descricao":"This spell infuses its targets, up to six people (who can include the caster), with the power of Earth, allowing them each call upon the Earth of their comrades to bolster their efforts. For the duration of the spell, the lowest Earth Ring Rank among all the targets is added the total of all Ring, Trait, and Skill rolls (but not Spell Casting rolls) they make."},{"id":"strength_of_the_crow","nome":"Strength Of The Crow","elemento":"earth","mastery":"3","area":"One target","alcance":"Touch","duracao":"Hours equal to caster's Shugenja School Rank","descricao":"This spell infuses the target (who can be the caster) with a powerful resistance the Shadowlands Taint, repelling the dark kansen of the Taint with the pure power of Earth. For the duration of the spell, the target(s) gain a +5K5 bonus to all rolls made to resist gaining the Shadow lands Taint, and any Maho spells suffer a + 10 TN penalty to affect them. This bonus does not apply to any rolls made to resist an increase in Taint the target already possesses - it only applies to new Taint gained from outside sources. Likewise it cannot protect the target from gaining Taint by casting Maho."},{"id":"the_wolfs_mercy","nome":"The Wolf's Mercy","elemento":"earth","mastery":"3","area":"One target creature","alcance":"50'","duracao":"10 rounds","descricao":"This spell has existed in Rokugan for centuries, but is best known for its extensive use by Toturi Sezaru, \"the Wolf,\" who employed it during his hunts for Bloodspeakers. It calls on the power of the Earth to afflict the target, weighing down his body and impeding his muscles, leaving him weak and vulnerable. The target's Earth Ring is lowered by 1 Rank, and his Wound Ranks are reduced correspondingly for the duration of the spell. (This can potentially kill him immediately if he has already suffered Wounds.) In addition, his Strength Rank is also lowered by 1 for the same duration. If the target has at least one full Rank of Shadow lands Taint, the Earth spirits will be filled with wrath, and punish him more severely, lowering his Earth Ring by 2 Ranks (to a minimum of 1)."},{"id":"breath_of_the_fire_dragon","nome":"Breath Of The Fire Dragon","elemento":"fire","mastery":"3","area":"15' long, 5' wide blast","alcance":"Personal","duracao":"4 rounds","descricao":"This spell is a prayer to the Dragon of Fire, one of the mightiest of celestial beings, entreating him for a bit of his power. If the spell is successful, you gain the ability to breathe a bolt of flames from your open mouth once per Round as a Simple Action. The bolt has a DR equal to your Fire Ring and strikes every target in front of you within the area of effect. You may choose to take actions other than breathing fire while under the effects of this spell, but you cannot speak or cast spells. The spell expires after four Rounds, but you may choose to end this spell during the Reactions Stage of any earlier Round."},{"id":"fiery_wrath","nome":"Fiery Wrath","elemento":"fire","mastery":"3","area":"One free-standing structure, or 50' x 50' area","alcance":"100'","duracao":"Instantaneous","descricao":"Fiery Wrath was originally created to clear brush for farming and to demolish wooden structures with a minimum of work and no hazard. It is also used to start bonfires for rituals and celebrations. The spell allows you to destroy a building or other structure by appealing to the excitable Fire kami with in the target's materials. All flammable materials within the area of effect immediately catch fire and burn until nothing but ash is left. The fire cannot be extinguished except by magical means; mundane water, sand, and other retardants would have no effect. Only one structure may be targeted by the spell, and the fire will not spread out to adjoining structures, as your prayers keep the Fire kami under tight control. Living beings and materials that are not flammable are not affected. In fact, while clothes worn by people caught within the area of effect will burn, their flesh will not so much as singe."},{"id":"haze_of_battle","nome":"Haze Of Battle","elemento":"fire","mastery":"3","area":"One target","alcance":"10'","duracao":"5 Rounds, or 1 hour out of combat","descricao":"Fire spirits are known for their erratic and temperamental nature, and shugenja can badly disrupt their foes in battle by imbuing them with this aspect of the element. The target of this spell is filled with the unfocused fury of Fire, enraging him and forcing him to lose perspective. The target immediately assumes the Full Attack Stance and cannot switch from that Stance for the duration of the spell. If the spell is cast out of Battle, the target gains the Brash and Contrary Disadvantages for the duration of the spell. This spells effects can be overcome by those of strong will. The target can attempt to resist with an opposed Willpower roll, but you add you’re Fire to the total of your roll. If the spell is cast in battle, this roll occurs during the Reactions Stage of Battle. The roll occurs once every 10 minutes."},{"id":"hungry_blade","nome":"Hungry Blade","elemento":"fire","mastery":"3","area":"One weapon","alcance":"50'","duracao":"5 Rounds","descricao":"This spell is a more potent version of Biting Steel, designed to enhance any weapon rather than merely a sword. The spell strengthens the Fire spirits in a single target weapon, causing them to come forth and form a faint sheath of fire around it. The weapon's wielder adds +1k to all attack rolls, and all of his damage dice explode on a result of 8 or better. Each die can explode on an 8 or 9 only once per roll, however, even if the wielder has other effects that allow the die to explode on 9s."},{"id":"ravenous_swarms","nome":"Ravenous Swarms","elemento":"fire","mastery":"3","area":"One target person","alcance":"30'","duracao":"5 Rounds","descricao":"A more powerful and sophisticated form of the prayer which invokes the Fires From Within. This spell not only damages the target but also disrupts his own attempts to invoke the Fire kami, making it a very effective weapon against a rival Fire shugenja. You summon forth a bolt of flames that streaks toward the target with wild abandon. The flames deal 4k3 Wounds on impact and then encircle the opponent for the duration of the spell, waiting for him to make a mistake. If the target casts any Fire spell during that time, the Fire kami instantly strike, dealing 3k3 extra Wounds and causing the Spell Casting Roll to automatically fail. (The target loses the appropriate spell slot as usual.)"},{"id":"shining_light","nome":"Shining Light","elemento":"fire","mastery":"3","area":"One target armor","alcance":"30'","duracao":"10 rounds","descricao":"Another example of spells which can imbue Fire kami into items, this spell temporarily binds a Fire kami into a piece of armor (such as a helmet or chest plate). The armor emits a bright light that becomes blinding whenever the wearer is attacked. Any time the armor's wearer is attacked in melee, immediately afterward the opponent takes 2k2 Wounds and is Blinded until the Reactions Stage of the same Round. The spell has no effect on ranged attacks."},{"id":"the_fist_of_osanowo","nome":"The Fist Of Osano-wo","elemento":"fire","mastery":"3","area":"20' radius","alcance":"50'","duracao":"1 round","descricao":"A more powerful prayer to the Fortune of Thunder, this spell invokes his anger to devastate a targeted area. Massive lightning strikes and vaguely fist-shaped bolts of flame streak from the skies, smiting the area of effect. Weak structures and those easily set on fire (such as most Rokugani homes) are destroyed by the spells fury, or catch fire and are consumed. The spell has a DR equal to your Fire Ring, inflicting this damage on anyone caught within the area of effect Using this spell in populated areas is generally considered a criminal act, unless the shugenja can cite extreme circumstances, since fires are terribly dangerous to Rokugani cities."},{"id":"echoes_in_the_void","nome":"Echoes In The Void","elemento":"void","mastery":"3","area":"One target individual","alcance":"25'","duracao":"Concentration","descricao":"Thoughts are as whispers in the Void, if one knows how to listen. As long as this spell is in effect and you maintain concentration on one target within the area of effect, you can hear what that person is thinking. How this manifests may vary depending upon the individual. Stalwart warriors may have short, curt statements summarizing their thoughts, while artisans may think in terms of poetry."},{"id":"kharmic_intent","nome":"Kharmic Intent","elemento":"void","mastery":"3","area":"One target individual","alcance":"20'","duracao":"10 minutes","descricao":"Links forged of the Void allow the passage of enormous energy, the substance of the universe itself, between those who share it. You may target anyone willing individual with this spell. All remaining Void Points either of you possess are placed in a Single pool, which either of you may draw upon as normal. Essentially, this spell allows two individuals to share Void Points back and forth as they see fit. This also allows ishiken to share the additional Void Points they gain from other Void spells, At the end of the spells Duration, all remaining Void Points are divided between the participants, up to their normal maximum number."},{"id":"moment_of_clarity","nome":"Moment Of Clarity","elemento":"void","mastery":"3","area":"Self","alcance":"Personal","duracao":"2 rounds","descricao":"The entirety of human achievement is reflected in the Void. You may select any one Skill. You gain temporary ranks in this Skill equal to your Void Ring. If you already possess ranks in this Skill, the new level of Skill replaces your old one; the two are not cumulative."},{"id":"read_the_essence","nome":"Read The Essence","elemento":"void","mastery":"3","area":"One target object","alcance":"Personal","duracao":"Instantaneous (but see spell description)","descricao":"Even objects have resonance, and retain some memory of those who hold them, and events that take place involving them. By meditating upon an object, you can gain a vision of the individual who held it last, or of a major event that might have involved it in some manner. Using this spell on a calligraphy brush, for example, might show the last person who used it to write a letter. Using it on a weapon might instead show the last death it was used to inflict. The GM has ultimate authority over what vision the spell imparts. Extremely important objects, such as ancestral weapons or standards, may have powerful visions that grip the caster for longer periods of time, rather than imparting simple instantaneous visions."},{"id":"void_release","nome":"Void Release","elemento":"void","mastery":"3","area":"One target individual","alcance":"25'","duracao":"Instantaneous","descricao":"Most are ignorant of the Void coursing within them, and do not realize that it can be stolen away. You must make a Contested Void Roll against the target of this spell. If successful, the target loses one Void Point, and you gain one Void Point. An additional point is exchanged for every increment of 5 by which you exceed the target's roll. These temporary Void Points may take you above the maximum number of Void Points you may have, but they expire within one hour if not used. This spell cannot be used on a creature who does not have Void Points, or which has some other mechanical effect that substitutes for Void (such as Naga Akasha or Ratling Name)."},{"id":"near_to_ice","nome":"Near To Ice","elemento":"water","mastery":"3","area":"One target individual","alcance":"Touch","duracao":"5 rounds","descricao":"As water grows durable and resistant with the coming winter, so too can the water within the human form become sterner and more durable. The target of this spell has all current Wound Penalties negated for the duration of the spell. Any additional penalties incurred take full effect, using the difference between the negated penalty and the new penalty as the effective penalty incurred. Wounds are not healed by this effect, they simply cease to inhibit those suffering from them."},{"id":"regrow_the_wound","nome":"Regrow The Wound","elemento":"water","mastery":"3","area":"One target individual","alcance":"Touch","duracao":"Concentration","descricao":"Water flows into all things, and flows out. In flowing out, it can carry away that which is undesirable. The pain and suffering inflicted by injuries can be channeled away from an individual, and cast into the infinite ocean where they are lost forever. The target of this spell recovers a number of Wounds equal to your Water Ring plus your School Rank each round the spell is in effect. You must touch the target when the spell is cast, but after that it may be maintained without physical contact."},{"id":"silent_waters","nome":"Silent Waters","elemento":"water","mastery":"3","area":"Self","alcance":"Personal","duracao":"Variable","descricao":"The memory of the ocean is infinite, and its vast power call lay in wait for a very long time indeed. Upon completion of a successful casting of this spell, you may immediately cast a second spell of any element. This second spell must be a spell you can normally cast, and it must be of Mastery Level 3 or lower. If the second Spell Casting Roll is successful, the second spell is stored within you, and will not activate until a specific physical effect takes place, which you specify at the time of the casting. The spells trigger could be that you speak a certain word, draw a blade, or fall in Battle, for example. Whatever the trigger, when it occurs, the second spell immediately takes effect as if you had just finished casting the spell. A character may never benefit from multiple uses of Silent Waters at one time. If a second use of the spell is cast on the same individual, the currently stored spell is immediately dispelled and replaced with the new one."},{"id":"strike_of_the_tsunami","nome":"Strike Of The Tsunami","elemento":"water","mastery":"3","area":"A cone originating from the caster, ten feet wide at the end","alcance":"25'","duracao":"Instantaneous","descricao":"Water is everywhere, and obeys the commands of its favored shugenja. You summon a crushing wave of water that overruns everything in its path. The wave inflicts 3k3 Wounds on everything within the affected area, and all opponents within the area of effect must make an Earth Roll (TN 15) or suffer Knockdown. Obviously, everything within the area of effect is saturated with water."},{"id":"visions_of_the_future","nome":"Visions Of The Future","elemento":"water","mastery":"3","area":"Self","alcance":"Personal","duracao":"1 minute","descricao":"Although not as reliable as the natural,if extremely rare gift of foresight or the equally rare Void spells that enable divination, this spell still allows powerful visions of the future. It was first developed by the Tonbo Family of the Dragonfly Clan, and is found infrequently outside their ranks. The spell requires use of a large pool of still Water into which you must gaze. Upon completion of the spell, you enter a brief trance, and see images of things that have not yet come to pass. These Images are rarely direct, and tend to be symbolic (violence is depicted as a scene of battle, for instance) but the events foreseen are completely accurate, and will come to pass unless prevented by your direct intervention. Only the shugenja casting this spell may see the events depicted in the vision. Many shugenja believe that use of this spell is a means of thwarting the natural order, and regard both it and those who make use of it negatively."},{"id":"walking_upon_the_waves","nome":"Walking Upon The Waves","elemento":"water","mastery":"3","area":"One target individual (may be the caster)","alcance":"Touch","duracao":"10 minutes","descricao":"The Water kami buoy those who carry their favor and grant them passage. The target of this spell may move across the surface of water as if it were slid ground (Basic Terrain). If the surface of the Water is disturbed, as by a storm, rolling waves, or any other similar event, it counts as Difficult Terrain."},{"id":"water_kamis_blessing","nome":"Water Kami's Blessing","elemento":"water","mastery":"3","area":"One target individual (may be the caster)","alcance":"Touch","duracao":"5 rounds","descricao":"By calling upon the clarity of water, you can receive tremendous insight into the world around you. The target of this spell receives a bonus to all his Perception based rolls, whether Trait Rolls, Skill Rolls, or anything else, consisting of additional rolled dice equal to your Water Ring."},{"id":"call_the_spirit","nome":"Call The Spirit","elemento":"air","mastery":"4","area":"Target spirit","alcance":"Special","duracao":"5 minutes","descricao":"Essentially an extremely powerful specific form of the basic spell Summon. Call the Spirit allows a shugenja summon any particular spirit, regardless of its realm, to have a discussion. You may use this spell to summon any spirit from any of the spirit realms, although realm denizens that are not spirits (such as Fortunes) are immune. If you know something specific about the spirit, either having seen it before or having intimate knowledge of its actions (for example, \"the spirit that killed my father\"), you may summon that spirit in particular. The nature of the spell prevents the spirit from attacking you unless you attack first, but it will not necessarily be friendly. The spirit disappears as soon as the spells duration expires. This spell can potentially summon extremely dangerous creatures, such as oni, and should be used with caution."},{"id":"false_realm","nome":"False Realm","elemento":"air","mastery":"4","area":"100' radius","alcance":"250'","duracao":"1 hour","descricao":"The greatest masters of the wind can create illusions of such beauty and clarity that those affected by them might truly believe they were somewhere else. You can completely alter the appearance of the terrain within the area of effect of this spell. You can make a miserable swamp look, sound, and smell like a beautiful garden, or vice versa. Although these illusions can be extraordinarily intricate and completely convincing to all other senses, they still have no substance and cannot be touched."},{"id":"gift_of_wind","nome":"Gift Of Wind","elemento":"air","mastery":"4","area":"Self","alcance":"Personal","duracao":"5 minutes","descricao":"The ultimate gift of the wind spirits is to become like the wind itself, unseen. The wind kami surround you and render you completely invisible. Non-magical vision can detect your presence. You can still be touched, heard, and smelled, hut unless you attack someone else, you remain invisible for the duration of the spell. The kami consider attacking someone to be ruining the joke, and immediately end the spells effect if you do so."},{"id":"know_the_mind","nome":"Know The Mind","elemento":"air","mastery":"4","area":"Target individual","alcance":"10'","duracao":"3 rounds","descricao":"Although the ultimate secrets of the human mind and hidden even the winds, air kami can pluck the most intimate thoughts from the minds of others and whisper them to those who carry their favor. For the duration of this spell, you essentially hear the surface thoughts of the spells target. You only learn things they are actively thinking about. For example, if you asked the name of the Target's daughter, that name would appear in their mind instantly even if they had no intention of speaking it aloud. A Contested Roll using your Perception against the target's Awareness will also allow you to assess their true emotional state, regardless of how they appear physically."},{"id":"netsuke_of_wind","nome":"Netsuke Of Wind","elemento":"air","mastery":"4","area":"One hand-held object","alcance":"Touch","duracao":"1 hour","descricao":"Although it requires great favor, the air kami are willing to coalesce into a solid form for a short period of time if they are fond enough of the priest asking them. You may create a small object out of the Air itself, something that can be held in one or both hands and that does not weigh more than twenty pounds at the most. This creation is an illusion, but it can be used functionally, including inflicting damage if it is a weapon. The object disappears completely at the end of the spells duration."},{"id":"symbol_of_air","nome":"Symbol Of Air","elemento":"air","mastery":"4","area":"Special","alcance":"Touch","duracao":"Permanent","descricao":"Priests of the kami are capable of inscribing powerful wards that invoke the power of the elements against all who attempts to pass them. A Symbol of Air must be inscribed on a solid object, most often a door, window, gate, or other passageway. Anyone attempting to pass through this passageway or otherwise pass by the area protected by the Symbol is affected by the protective ward. Such persons must succeed at a Contested Roll using their Earth against the caster's Air. Those who fail are affected by a powerful drowsiness, and must succeed at a Willpower Roll against the total of the Spell Casting Roll used create the ward or fall into a deep sleep for one hour. Those affected by the spell cannot be woken by normal means, but will awaken instantly if subjected to any attack or form of harm, as the kami will not be party to such humorless tricks. You may only have one Symbol of Air in existence at any time, and Symbol spells of different elements may never affect the same area. This spell may be dispelled by another casting of Symbol of Air from any shugenja, or by destroying the surface where the Symbol was etched."},{"id":"armor_of_the_emperor","nome":"Armor Of The Emperor","elemento":"earth","mastery":"4","area":"Self","alcance":"Personal","duracao":"5 Rounds","descricao":"This spell covers the caster in a thick layer of tough, resilient Earth spirits who repel all damage, whether physical blows or magical effects. Any time the caster suffers damage from an enemy physical or magical attack, each individual damage die has its total Reduced by the caster's Shugenja School Rank. This cannot reduce a die's total below O."},{"id":"essence_of_earth","nome":"Essence Of Earth","elemento":"earth","mastery":"4","area":"One target creature (self or another)","alcance":"Personal or 20'","duracao":"10 rounds","descricao":"This spell infuses the target with the true strength of Earth, allowing him to shrug off blows which might otherwise take his life. For the duration of the spell, the target's Earth Ring is considered to be 1 Rank higher, and his Wounds are increased correspondingly. However, when the spell ends, the Earth spirits immediately depart and the target's Wounds return to normal - possibly resulting in death, if he has suffered sufficient injury."},{"id":"symbol_of_earth","nome":"Symbol Of Earth","elemento":"earth","mastery":"4","area":"Special","alcance":"Touch","duracao":"Permanent","descricao":"Priests of the kami are capable of inscribing powerful wards that invoke the power of the elements against all who attempt to pass them. A symbol of Earth can be inscribed on a solid object, most often a door, window, gate, or any other passageway. Anyone attempting to pass through this passageway or otherwise pass by the ward is affected by its power, and must succeed at a Contested Roll using their Air against the caster's Earth. Those who fail are struck with a powerful shockwave, and must succeed at a Strength roll against the Total of The Spell Casting Roll used to create the ward or be knocked Prone and Stunned. If they have at least one Rank of Taint, they also suffer 2k2 Wounds. You may only have one Symbol of Earth in existence at any time, and Symbol spells of different elements may never affect the same area. This spell may be dispelled by another casting of Symbol of Earth from any shugenja, or by destroying the surface where the Symbol was etched."},{"id":"tomb_of_jade","nome":"Tomb Of Jade","elemento":"earth","mastery":"4","area":"One target creature","alcance":"50'","duracao":"Concentration","descricao":"Considered by many shugenja to be the ultimate spell for opposing the creatures of the Shadowlands, this spell calls on the purest of Earth spirits, those of jade, to consume the very Taint within the target. The spell can only affect a target who has at least one full Rank of Shadowlands Taint, but if the spell fails, the caster will not automatically know that the target is Taint-free - there is always the possibility that the target was able to resist the spell l. When Tomb of Jade is cast, the target is momentarily immobilized as the Earth spirits enter his body. Each round, starting with the first round, the caster must make a Contested Earth roll against the target. If Rhea target wins, the spell ends. If the caster wins, the target takes 2k2 Wounds as the spirits begin transform his body into jade. This continues each round until the target successfully resists, the caster stops concentrating, or the target dies. Those killed by this spell are transformed into statues of pure jade, which crumbles away into mundane dust in 24 hours."},{"id":"wall_of_earth","nome":"Wall Of Earth","elemento":"earth","mastery":"4","area":"Wall measuring a maximum of 10' high and 100' wide","alcance":"100'","duracao":"10 minutes","descricao":"This spell coaxes the spirits of Earth into rising up and forming a thick, powerful barrier to protect the caster. The wall of rock-hard earth which this spell creates can be shaped as the caster desires, and can be curved, placed on the side of a hill, or even formed in a circle. It is extremely tough, requiring a Strength roll against a TN of the caster's (Earth + School Rank) x 5 in order to break through. It is strong enough to hold back a raging flood, a lava flow, or hurricane winds, at least as long as the spell lasts. When the spell expires, however, the earthen barrier crumbles away in moments."},{"id":"death_of_flame","nome":"Death Of Flame","elemento":"fire","mastery":"4","area":"One target","alcance":"100'","duracao":"5 Rounds","descricao":"This spell brings the anger of Fire on the target, suppressing his elemental Fire and lowering both his Agility and his Intelligence Ranks by an amount equal to your Fire Ring, to a minimum of one. If you maintain Concentration for the duration of the spells effect, the target cannot escape its effects. If you don't maintain Concentration, each Round at the start of his Turn the target may make a contested Fire roll against you (using his original, unmodified Fire Ring) to end the spells effect."},{"id":"defense_of_the_firestorm","nome":"Defense Of The Firestorm","elemento":"fire","mastery":"4","area":"One target armor","alcance":"Touch","duracao":"5 Rounds","descricao":"A more potent form of spells like Shining Light, this prayer summons forth an aura of magical flames from a suit of armor, surrounding and protecting: the armor's wearer. These flames do not harm the armor's bearer and do not harm living things, However, all wooden weapons (including arrows and many pole arms) burn instantly before they reach the target, doing no damage. The flames also impede sight to the target, increasing his Armor TN by 20."},{"id":"symbol_of_fire","nome":"Symbol Of Fire","elemento":"fire","mastery":"4","area":"10' radius","alcance":"100'","duracao":"Permanent","descricao":"Priests of the kami are capable of inscribing powerful wards that invoke the power of the elements against all who attempt to pass them. A symbol of Fire can be inscribed on a solid object, most often a door, window, gate, or any other passageway, anyone attempting to pass through this passageway or otherwise pass by the ward is affected by its power, and must succeed at a Contested Roll using their Water against the castor's Fire. Those who fail are Dazed, Blinded for one Round, and take 3k3 Wounds. This spell may be dispelled by another casting of Symbol of Fire from any shugenja, or by destroying the surface where the Symbol was etched. You may only have one Symbol of Fire in existence at any time, and Symbol spells of different elements may never affect the same area."},{"id":"the_mending_forge","nome":"The Mending Forge","elemento":"fire","mastery":"4","area":"One target item","alcance":"Touch","duracao":"Instantaneous","descricao":"This simple and powerful spell has only one function: to call on the creative power of Fire to bring back what has been destroyed. Any damaged or destroyed material item can be restored with this spell, provided all of its pieces are gathered in front of the caster, (if some pieces are missing, the spell will automatically fail.) The spell takes 1 minute to cast, and you must concentrate during that minute. If successful, the spell restores the item to a whole and undamaged state. It should be noted that the Fire kami must work harder to repair items of unusual quality - if you use this spell to repair a Nemuranai or an item of Fine quality or better, you must offer the Fire kami a gift of another item for them to burn and destroy - appropriate to the worth of the item."},{"id":"wall_of_fire","nome":"Wall Of Fire","elemento":"fire","mastery":"4","area":"Special","alcance":"100'","duracao":"1 hour","descricao":"You invoke the Fire kami to spring up and form a wall of flames, barring passage to all. The wall 1s a 10' tall, l' wide, and 25' long, and causes 6k6 Wounds to anyone who touches it. This wall may be made shorter or thinner as desired, within the total specifications, but all of the mass of flames must be used somehow. The wall may be created in an area where people or creatures are standing, forcing them to make a Reflexes Trait Roll against a TN of 20 to avoid taking Wounds from the fire. You may Raise to increase one of the specifications (height, width, or length) by its base increment 10', 1', or 25' respectively)."},{"id":"ward_of_thunder","nome":"Ward Of Thunder","elemento":"fire","mastery":"4","area":"15' radius from the armor","alcance":"Touch","duracao":"1 hour","descricao":"Osano-Wo's protection can be temporarily invoked for a suit of armor by casting this spell and inscribing the kanji for thunder on the armor. Those within 15' of the armor are under Osano-Wo's care, and are completely protected from non-magical fire and thunder for the duration of the spell. Additionally, any Fire spell cast by a shugenja other than yourself which targets something within the area of effect has its Spell Casting TN increased by 20."},{"id":"balance_of_elements","nome":"Balance Of Elements","elemento":"void","mastery":"4","area":"One target individual (may be the caster)","alcance":"Touch","duracao":"5 rounds / 5 minutes (see spell description)","descricao":"Flaws in the great pattern of the Void can be overcome, no matter how severe. You may negate all Disadvantages of the target for the duration of the spell. Negative effects inflicted from spells (such as TN penalties, Armor TN reduction, or Trait/Ring reduction) are negated as well, as long as the Mastery Level of the spell causing the penalty is 3 or less. If used during the taxing environment of combat, the duration of this spell is extremely limited (5 rounds). In non-combat situations, however, the effects of the spell can last significantly longer (5 minutes). This temporary replenishing of the target's pattern also heals 3k3 Wounds."},{"id":"draw_closed_the_veil","nome":"Draw Closed The Veil","elemento":"void","mastery":"4","area":"One target spirit","alcance":"50'","duracao":"Instantaneous","descricao":"The emptiness that is the Void is part and parcel of what separates the various spirit realms from one another, and it is possible to strengthen it in certain areas. You may target any one spirit not native to the mortal realm of Ningen-do. That spirit is banished to its home realm for a minimum amount of time equal to your Void Ring in months. Spirits that possess a physical body in the mortal realm, such as oni or certain shape shifter spirits, require a Contested Willpower Roll for this spell to affect them. Spirits that are significantly more powerful than you are (GM's discretion) may prove immune to the effects of this spell."},{"id":"fill_with_emptiness","nome":"Fill With Emptiness","elemento":"void","mastery":"4","area":"One target individual","alcance":"Touch","duracao":"Instantaneous","descricao":"Strengthening an individual's connection to the Void can replenish their reserves of inner energy. The target of this spell regains all lost Void Points, up to their normal maximum number."},{"id":"void_strike","nome":"Void Strike","elemento":"void","mastery":"4","area":"One target individual","alcance":"50'","duracao":"Instantaneous","descricao":"The mortal shell can endure only so much direct contact with the Void, too much, and the flesh can be destroyed by the exposure. This spell inflicts damage with a DR equal to your Void Ring."},{"id":"dominion_of_suitengu","nome":"Dominion Of Suitengu","elemento":"water","mastery":"4","area":"Two bodies of water","alcance":"100 miles","duracao":"Concentration","descricao":"The Fortune of the Sea is a wrathful entity, but one who nevertheless blesses those who entreat him properly. This spell, created by the Mantis clan, allows you to peer into a body of water, which must be at least one foot across and one inch deep, and see out of any other body of water anywhere in the Empire, so long as it is within range of the spell. This can be at any point along the seacoast, a lake, river, stream, or even a puddle, but you must know the location of the body of water you are targeting. You can see everything around that body of water as if you were submerged within it. You cannot hear what is taking place, only see it."},{"id":"heart_of_the_water_dragon","nome":"Heart Of The Water Dragon","elemento":"water","mastery":"4","area":"Target individuals equal to caster's School Rank (may include the caster)","alcance":"25'","duracao":"1 round per School Rank","descricao":"The Water Dragon is a benevolent entity, and his blessings are powerful. Any time that a target of this spell suffers damage during the duration, he instantly regains 1k1 Wounds."},{"id":"strike_of_the_flowing_waters","nome":"Strike Of The Flowing Waters","elemento":"water","mastery":"4","area":"One target individual (may be the caster)","alcance":"10'","duracao":"1 round","descricao":"Water flows over and through obstacles, and so too can those infused with its energy. The target of this spell may ignore bonuses this opponents' Armor TN conferred by worn armor, spell effects of Mastery Level 3 and below, and other non-Technique mechanical effects. Against non-human creatures who do not wear armor, this allows the target to treat their armor as Slower. This spell does not negate the Reduction awarded by armor, nor does it ignore the increase to armor TN conferred as a result of an individual adopting the Defense or Full Defense Stances."},{"id":"symbol_of_water","nome":"Symbol Of Water","elemento":"water","mastery":"4","area":"Special","alcance":"Touch","duracao":"Permanent","descricao":"Priests of the kami are capable of inscribing powerful Wards that invoke the power of the elements against all who attempt to pass them. A symbol of water can be inscribed on a solid object most often a door, window, gate, or any other passageway. Anyone attempting to pass through this passageway or otherwise pass through the area is affected by the protective Ward, and must succeed at a Contested Roll using their Fire against the caster's Water. Those who fail arc affected by a crippling terror, and must immediately roll against a Fear 7 effect. You may only have one Symbol of Water in existence at any time, and Symbol spells of different elements may never affect the same area. This spell may be dispelled by another casting of Symbol of Water from any shugenja, or by destroying the surface where the Symbol was etched."},{"id":"the_path_not_taken","nome":"The Path Not Taken","elemento":"water","mastery":"4","area":"Self","alcance":"Personal","duracao":"1 day","descricao":"No element can match the sheer versatility and adaptability of Water. Prior to casting this spell, you must select one Ring in which you will be temporarily weakened, and one in which you will be temporarily strengthened. Upon the successful conclusion of this spell, you may transfer a number of unused daily spell slots from the weakened Ring to the strengthened Ring. This spell lasts exactly one day, and then the effects are lost."},{"id":"cloud_the_mind","nome":"Cloud The Mind","elemento":"air","mastery":"5","area":"One target individual","alcance":"Touch","duracao":"Permanent","descricao":"This extremely invasive spell is considered blasphemous by most honorable shugenja, and many respectable shugenja orders would deem its use reason for excommunication if not outright execution. This spell calls upon the air kami befuddle and dismay a target, invading their mind and influencing their ability to recall exactly what happened to them over a certain length of time. When this spell is successfully cast against a target, you must succeed at a Contested Roll using your Air versus the target’s Earth. If successful, the target's memories are disrupted, and they forget what has happened to them over the course of the past week (five days). This information is completely lost the target. What's more, the spell renders them extremely susceptible to suggestion, and you can tell them what happened to them over the course of the missing time. This allows unscrupulous shugenja to exploit others and essentially give them false memories, although certain individuals are highly resistant to this manner of manipulation. It is possible to determine that an individual was the target of this spell through use of the Commune spell, but it requires that the kami be specifically asked if they can detect any such manipulation."},{"id":"draw_back_the_shadow","nome":"Draw Back The Shadow","elemento":"air","mastery":"5","area":"30' radius","alcance":"100'","duracao":"Instantaneous","descricao":"Just as the kami craft illusions, they can cast them aside. Within the area affected by this spell, any illusions created by spells of Mastery Level 4 or lower are automatically dispelled. Spells of Mastery Level 5 or 6 require a Contested Air Roll between you and the shugenja who created those spells; if you are successful, those illusions are dispelled as well. Ongoing magical effects that are not illusions may also be dispelled by this spell, but require a Contested Ring Roll between you and their creator, using your Air versus his appropriate Ring."},{"id":"echoes_on_the_breeze","nome":"Echoes On The Breeze","elemento":"air","mastery":"5","area":"One target individual","alcance":"Personal","duracao":"Concentration","descricao":"No destination is beyond the reach of the wind. With a simple prayer the kami, you can send your words across the span of the Empire, whispering into the ear of anyone you need to send a message. The person must be someone you know, and the spell will establish a link between the two of you only as long as you concentrate. You may communicate with one another, although you only hear each other’s voices as whispers. Both participants are instantly aware when the connection is forged, and either can end it at any point."},{"id":"legion_of_the_moon","nome":"Legion Of The Moon","elemento":"air","mastery":"5","area":"10' radius from the caster","alcance":"Personal","duracao":"5 minutes","descricao":"The Moon can reveal what is hidden, but also conceal those who receive its blessings. You may summon the greater blessing of the Moon and envelop a large group of people within it, completely obscuring them from sight. Every individual you choose within the area of effect of this spell is rendered invisible to all normal senses for the duration of the spell. Those within the area that you choose to exclude are not affected. Anyone affected by the spell who performs any action that physically interacts with an unaffected individual is immediately excluded from the spell effect."},{"id":"slayers_knives","nome":"Slayer's Knives","elemento":"air","mastery":"5","area":"Corridor of air 10' wide","alcance":"30'","duracao":"Instantaneous","descricao":"The wind can be deadly to those unprepared for its fury. You summon a powerful wind that tears through anything in its path. At your behest, the kami create a corridor of air filled with a cutting wind that inflicts damage with a DR equal tour Air Ring +2k to everything in its path. (For example, a shugenja with Air 4 would inflict 6k4 damage with this spell). Paper and light cloth are destroyed instantly, although heavier cloth may only be damaged. Anyone damaged by these winds must succeed at an Earth Ring Roll (TN 20) or be Knocked Down."},{"id":"earthquake","nome":"Earthquake","elemento":"earth","mastery":"5","area":"1 mile radius","alcance":"Personal","duracao":"1 minute","descricao":"This spell unleashes a terrible, ground-wracking earthquake, centered on the caster, who alone is unaffected. The earthquake utterly destroys all wooden buildings within the radius of effect, and inflicts severe damage on stone structures. All persons with in the area of the earthquake are thrown the ground, and remain Prone and Stunned for the duration of the spell, as well as suffering 2k1 Wounds. Individuals who are inside buildings (including the caster) will suffer 6k6 damage from falling debris, collapsing roofs, etc. Casting this spell within range of a major inhabited area is generally considered an act of war."},{"id":"major_binding","nome":"Major Binding","elemento":"earth","mastery":"5","area":"One target Shadowlands creature","alcance":"100'","duracao":"12 hours","descricao":"The more powerful counterpart the Kuni family's Minor Binding spell, this spell has also been employed by other clan shugenja, especially those of the Phoenix Clan. It is used to imprison more powerful Shadowlands creatures and members of the Lost, typically for purposes of interrogation. Any Lost and any Shadow lands creature can be targeted with this spell. It can also target other spirit creatures who are tainted. It cannot affect any other creatures. The spell is a ritual, and requires ten minutes to cast (making it quite hazardous when dealing with a rampaging oni), but if additional shugenja join in casting the spell the casting time is reduced by 1 minute per shugenja, to a minimum of 1 minute. If it is cast successfully, the casters make a Contested Roll of their combined Earth Rings against to be Earth of the target. If the casters win, the spell calls forth manacles of pure elemental jade, which imprison the creature and render it helpless with the pain of its searing bonds for the duration of the spell. When the spell expires, however, the manacles instantly crumble into dust, and the creature is liable to seek immediate and bloody vengeance on its captors."},{"id":"strike_at_the_roots","nome":"Strike At The Roots","elemento":"earth","mastery":"5","area":"One target creature","alcance":"50'","duracao":"3 rounds","descricao":"A more powerful and devastating form of The Wolfs Mercy, this spell brings the true wrath of the Earth onto the target, draining all favor of the Earth from his body and leaving him a weak, trembling, helpless victim. After casting this spell, the caster must succeed in a Contested Earth roll against the targets of the spell (rolling separately if he is targeting multiple people). If the target loses the roll, his Earth Ring is immediately reduced to 1 for the duration of the spell. This also reduce his Wound Ranks and may result in his immediate death if he has already suffered injuries."},{"id":"the_kamis_strength","nome":"The Kami's Strength","elemento":"earth","mastery":"5","area":"One target creature","alcance":"30'","duracao":"5 rounds","descricao":"This spell allows the caster to fortify one person with the power of Earth, greatly enhancing their physical capabilities and their resistance to damage. The target of this spell gains Reduction of 20 and increases his Strength and one other physical Trait by an amount equal the caster’s Earth Ring. In return, however, the target is weighed down by the burden of Earth and cannot take Simple Move Actions (he can still take a Free Move Action)."},{"id":"the_kamis_will","nome":"The Kami's Will","elemento":"earth","mastery":"5","area":"One target creature","alcance":"30'","duracao":"10 rounds","descricao":"The counterpoint to the Kami's Strength, this spell infuses one person with the stubbornness and determination of Earth, greatly enhancing their willpower and making them all but immune the effects of elemental magic. The target of this spell increases his Willpower by an amount equal the caster's Earth Ring, and any spells (friendly or hostile, but not including Maho spells) which target him suffer a penalty of -XkX to their Spell Casting roll, where X is the caster's Earth Ring. In return, however, the target is made so stubborn and willful that he cannot function properly in a social environment, and suffers a penalty to all Social Skill rolls of –Xk0, where X is the Earth Ring of the caster."},{"id":"destructive_wave","nome":"Destructive Wave","elemento":"fire","mastery":"5","area":"25' radius","alcance":"Personal","duracao":"Instantaneous","descricao":"A highly potent offensive spell, originally devised by the Isa-wa Elemental Masters. This prayer summons up a great mass of Fire kami, which roll outward from the caster in a wave of searing flames. Every target within the area of effect, whether friendly or hostile, takes 7k7 Wounds, for the raging flames make no distinction between ally and enemy. You alone do not take damage from the spell."},{"id":"everburning_rage","nome":"Everburning Rage","elemento":"fire","mastery":"5","area":"One target","alcance":"25'","duracao":"1 Round","descricao":"A powerful curse that infuses the target's body with angry Fire spirits, wracking him with pain as the kami sear his nerves and ligaments. For the duration of the spell, the victim is considered to be at the Down Wound Level and suffers all associated penalties and conditions, although he takes no actual Wounds from the spell. When the spell expires, the pain instantly ceases and the target may stand up as if nothing had happened. This spell is somewhat controversial with some shugenja schools, particularly the more peaceful ones, since it amounts to little more than the deliberate infliction of pain. A few shugenja have even noted certain disturbing similarities between this spell's effects and those of certain maho curses."},{"id":"follow_the_flame","nome":"Follow The Flame","elemento":"fire","mastery":"5","area":"See below","alcance":"Personal","duracao":"5 Rounds","descricao":"This spell grants you exceptional control of the nearby Fire kami, allowing you to coax them into a very unusual and terrifying attack. On the Round this spell is cast and every Round thereafter, you may declare a line of sight target within 300' and send a stream of fire toward it that snakes along the ground. (On later Rounds, designating a target in this manner is a Simple Action.) The stream of fire moves at a rate of 75' each Round and moves around impassable (or inflammable barriers) in order to reach its target. Once the fire reaches its destination, the target bursts into flames, suffering 6k5 Wounds. The subject catches fire and takes half that many Wounds (rounded down) every subsequent Round until the Fire is doused normally or the spells duration expires."},{"id":"light_of_the_sun","nome":"Light Of The Sun","elemento":"fire","mastery":"5","area":"30' radius","alcance":"100'","duracao":"10 rounds","descricao":"This prayer invokes the power of the Sun, worshipped and venerated throughout Rokugan, and is a special favorite among the Moshi family, although shugenja all across the Empire have learned it. The spell calls down a concentrated beam of pure sunlight to punish the unworthy. Everyone caught in the area of effect hikes 2k2 Wounds per Round from the intense heat. Human targets (only) take an additional 2kl Wounds for every Honor Rank they are below 4, and an additional 2k2 Wounds if they possess at least 1 Rank of the Shadowlands Taint or are controlled by the Lying Darkness. Human targets who have an Honor Rank of 0 are Blinded for a number of Rounds equal to your Fire Ring."},{"id":"wings_of_the_phoenix","nome":"Wings Of The Phoenix","elemento":"fire","mastery":"5","area":"Self","alcance":"Personal","duracao":"10 Rounds","descricao":"The Phoenix is one of the most powerful symbols of Fire known to the Rokugani, and this spell calls on the essence of that being to grant its caster the power of flight. When this spell is cast, you summon clouds of Fire kami who take the form of giant wings sprouting from your back. You gain the ability to fly for the duration of the spell, moving at a speed of Water x 10 for a Free Action or Water x 20 for a Simple Action. If you are airborne when the spell expires, the Fire kami will bear you down to earth before departing."},{"id":"divide_the_soul","nome":"Divide The Soul","elemento":"void","mastery":"5","area":"Self","alcance":"Personal","duracao":"1 minute","descricao":"The true mysteries of the Void are beyond the comprehension of non-ishiken. Using this spell, you may divide your soul across the Void, and exist in who places in the mortal realm simultaneously. The second \"you\" appears anywhere you might wish within your sight when you cast the spell. You have full knowledge of all that happens in both locations, and may take any normal actions in either place (both manifestations may take actions simultaneously as if they were two separate individuals). Only one manifestation may make a Spell Casting Roll per round. Any Wounds suffered by either manifestation are combined when the spell ends, and if either of your selves dies, both die."},{"id":"reforge","nome":"Reforge","elemento":"void","mastery":"5","area":"One object","alcance":"Touch","duracao":"Permanent","descricao":"All is one and one is all. You may take any single object and transform it into any other object of comparable size. This will only work on an object that is uniform in its construction, rather than assembled from multiple pieces. This spell will not affect living material. Although the effect of this spell is permanent, it can be reversed by a second casting on the same object, even by a different ishiken."},{"id":"unbound_essence","nome":"Unbound Essence","elemento":"void","mastery":"5","area":"One target individual","alcance":"25'","duracao":"1 hour","descricao":"Tampering with the pattern of another being's Void can result in catastrophic changes to their abilities. The target's Rings are reordered at random, along with their Traits. For instance, a target might exchange his Air Ring for his Fire Ring, and his Water Ring for his Earth Ring for the duration of this spell. Mental and Physical Traits exchange their values if those values are greater than the Ring. In the above example, if your target has Air 3 and Reflexes 4, he would instead have Fire 3 and Agility 4, with his values for those Traits reassigned this Air and Reflexes."},{"id":"everchanging_waves","nome":"Ever-changing Waves","elemento":"water","mastery":"5","area":"Self","alcance":"Personal","duracao":"1 hour","descricao":"Ultimate command over Water can allow flesh to flow like liquid. This spell allows you to physically alter your mortal body, changing your shape to match that of another natural creature (see the Book of tile Void for a list of the more common natural creatures found in Rokugan). While in this form, you keep your Mental Traits. For Physical Traits, you keep whichever is higher, yours or those of the animal into which you have transformed. Other natural abilities are gained as well, including natural weapons or sensory abilities. Some traditionalist shugenja sects look down upon this spell as unclean."},{"id":"hands_of_the_tides","nome":"Hands Of The Tides","elemento":"water","mastery":"5","area":"Targets up to caster's Water Ring","alcance":"100' radius centered on the caster","duracao":"Instantaneous","descricao":"The exchange of energy via Water is a simple matter that can ultimately lead to the exchange of flesh as well. Within the area of effect of this spell, you may choose a number of willing targets up to your Water Ring. You may switch the positions among those targets as you see fit, exchanging one for another. At the end of the spell, there must be a person in every position that was occupied when the spell began, but who is located where can vary depending upon the number of people affected."},{"id":"power_of_the_ocean","nome":"Power Of The Ocean","elemento":"water","mastery":"5","area":"One target individual","alcance":"Touch","duracao":"A number of days equal to your School Rank","descricao":"Perhaps the greatest gift Water can bestow requires a powerful shugenja to impart it to others. This spell is a complex ritual that requires an hour to cast, and can only be cast upon a willing target. For the duration of the spell, the target requires no food, drink, or sleep. A number of times during the duration equal to your School Rank, the target may replenish his Void Points as a Simple Action; this is the equivalent of recovering Void Points via a full night of rest. The target also recovers a number of Wounds per hour equal to twice your Water Ring. If the target of this spell is a shugenja, he regains all expended spell slots at sunrise, regardless of whether he has had any rest. After the spell expires, the target lapses into a state of complete exhaustion. This lasts for exactly half the duration of the spell effect. During this time, the target cannot take any significant physical action, and can only move about sluggishly. Travel is completely impossible."},{"id":"suitengus_embrace","nome":"Suitengu's Embrace","elemento":"water","mastery":"5","area":"One target individual","alcance":"25'","duracao":"Instantaneous","descricao":"The Fortune of the Sea is wrathful, and requires little prompting by his loyal adherents to smite another. By invoking the Water kami, you can fill a target's lungs with seawater, crippling and potentially killing them. If the spell is cast successfully, the target can take no actions other than to attempt to resist the spell. For All intents and purposes, the target is reduced to the Down Wound Level in terms of his ability to take actions. Each round he must make a Stamina Roll (TN 15) to resist. If the target makes three total successes, he spends one additional round vomiting up seawater, and then is fully recovered. However, if the target suffers two consecutive failures, he has fallen unconscious and will die within 1 minute unless some form of magical or medical intervention is made. Although means of combating drowning are not well known in Rokugan, it is possible to save an individual incapacitated by this spell by making a successful Medicine / Intelligence roll at TN 5O."},{"id":"the_final_bond","nome":"The Final Bond","elemento":"water","mastery":"5","area":"One target object or individual","alcance":"Special","duracao":"Instantaneous","descricao":"The greatest bonds can never be broken. This spell allows you to detect the location of one object or individual well known to you, regardless of their location. The object must be one you have spent a tremendous amount of time around, or have handled frequently in the past. If the target of the spell is an individual, it must be someone well known to you, such as a member of your immediate family or a close friend. You instantly know their approximate location anywhere in the Empire. This is not a exact location, but sufficient to tremendously narrow any search (for example. \"The City of Ryo Owari Toshi,\" or 'the northern reaches of the Shinomen Mori\"). If the target is outside the Empire of Rokugan, the spell automatically fails."},{"id":"rise_air","nome":"Rise, Air","elemento":"air","mastery":"6","area":"One summoned spirit","alcance":"30'","duracao":"Concentration","descricao":"The wind itself will take form to defend you. The ultimate actualization of the Summon spell, this spell summons a massive kami of pure air to serve you. It takes the form of a vaguely humanoid shape, roughly ten feet in height, with an indistinct outline visible only because of small debris caught up in its body. The kami may move up to 10' x your Air per round, and generates powerful winds in a twenty foot radius around it that hinder movement, preventing anyone from making Simple Move Actions within its area of effect. The manifest kami is treated as if it has all Physical Traits equal to your Air Ring, and attacks with a Jujitsu Skill Rank equal to half your Air Ring. Damage from these attacks has a DR equal to your Air Ring (for example, a spirit summoned by a shugenja with Air 6 would inflict 6k6 damage with its attacks). For purposes of taking damage, the spirit is considered to have Wounds as though it were a human with Earth equal tour Air Ring, but suffers no Wound penalties. It is Invulnerable (see the creature rules in the Book of Void for details of this ability). If it is successfully reduced to zero Wounds, it is dispelled."},{"id":"the_false_legion","nome":"The False Legion","elemento":"air","mastery":"6","area":"Within 100' of the caster","alcance":"Personal","duracao":"Concentration","descricao":"The greatest illusory gift of the wind is legion. Within the area of effect of this spell, you can create a number of illusory figures up to your Air Ring x 10. These figures may be as detailed or as vague as you prefer (such as \"Crane bushi\" versus \"heavy infantry of the fourth Daidoji legion\"), although you must be familiar with their appearance in order for this spell to take effect (you could not, for example, replicate a family man you have never seen). The figures are fully mobile and will take whatever actions you desire as long as they do not leave the spells area of effect. They can be seen, heard, or even smelled, but as with most illusions, they cannot physically interact with objects or individuals in any way."},{"id":"wrath_of_kazenokami_hurricane","nome":"Wrath Of Kaze-no-kami (hurricane)","elemento":"air","mastery":"6","area":"1 mile radius, centered on the caster","alcance":"Personal","duracao":"Concentration (special)","descricao":"The wrath of the air kami, and of the Fortune of the Wind, is truly dreadful to behold. In casting this spell, you unleash the full force of a hurricane upon your enemies. When the spell takes effect, you are standing in the eye of the storm, a zone radiating twenty feet in every direction from you, and in which no ill effects of the spell are suffered. Outside the eye, however, the brutal effects of the storm tear at everything in its path. Objects weighing less than five hundred pounds are lifted by the wind and tossed into the storm. Individuals in this area must hold on to something immobile or be cast into the winds to their certain death. Everyone within the affected region who does not have sturdy shelter suffers 1k1 Wounds per minute from the winds and minor debris. There is a one in ten chance each minute that an exposed individual will instead suffer 5k5 Wounds due to being struck by a wind-borne object. This spell lasts for a maximum of one hour, although it can last far shorter times if you are disrupted while maintaining the spell. This spell may not be cast in a given area more than once per month, as it completely exhausts the favors of the air Kami to perform it."},{"id":"essence_of_jade","nome":"Essence Of Jade","elemento":"earth","mastery":"6","area":"One target creature","alcance":"30'","duracao":"10 rounds","descricao":"This spell calls on the purity of jade to protect its targets against the power of Jigoku, whether manifested as Taint or as the dreaded magic known as Maho. The target radiates the sacred green light of jade, and while the spell lasts, he cannot gain the Shadowlands Taint and is completely immune to the effects of all Maho spells. This spell cannot be cast on anyone who possesses at least one full Rank of Taint, for the pure jade spirits will recoil from such a corrupt individual, immediately alerting the caster to this individuals Tainted nature."},{"id":"power_of_the_earth_dragon","nome":"Power Of The Earth Dragon","elemento":"earth","mastery":"6","area":"One target creature","alcance":"50'","duracao":"10 minutes","descricao":"This spell is the most powerful of the physically protective Earth spells, calling on the favor of the Dragon of Earth to enshroud the targets with protection against all forms of harm. The Earth spirits absorb all damage which the targets suffer while the spell lasts. However, there are limits to even Earth's endurance. Nemuranai can bypass the protection. Further, if the Earth spirits protecting a specific target absorb a total of 100 Wounds of damage, they will be exhausted and the spells effects on that target come to an end."},{"id":"prison_of_earth","nome":"Prison Of Earth","elemento":"earth","mastery":"6","area":"One target creature","alcance":"30'","duracao":"Permanent","descricao":"The most powerful of the binding spells which Earth shugenja use to deal with dangerous creatures, this spell can literally imprison the essence of such a creature for as long as the caster desires. Casting this spell requires that the caster possess a gem or pearl in which to imprison the creature (the GM may, discretionally, allow other rare or precious items to be used, such as a beautifully inlaid puzzle-box or a crystal pendant). The spell can target any creature native the realms of Jigoku, Gaki-Do, or Toshigoku, and any other non-human creature with at least 1 full Rank of Taint. After casting the spell, the caster must make a Contested Willpower roll against the target. If the caster wins, the creature's physical body vanishes and its essence is imprisoned within the item. It will remain there indefinitely unless the item is physically destroyed. If that happens, the released creature immediately resumes its physical form, and will most likely seek vengeance against the caster or his descendants."},{"id":"rise_earth","nome":"Rise, Earth","elemento":"earth","mastery":"6","area":"One summoned spirit","alcance":"30'","duracao":"Concentration","descricao":"The Earth itself arises and takes form to defend you. The ultimate realization of the Summon spell, this prayer summons a massive kami of pure Earth to serve you. It takes the form of a vaguely humanoid shape, roughly ten feet in height, with a broad body and thick limbs all formed from earth and stone. This mighty Earth kami may move up to 5x your Earth per round, and its footsteps shake the Earth 1n a twenty foot radius around it, preventing anyone from making Simple Move Actions within its area of effect. This Earth spirit is treated as if it has all Physical Traits equal to your Earth Ring, and attacks with a Jujitsu Skill Rank equal that of your Earth Rank. The DR from these attacks is equal to your Earth Ring. The kami can carry up to 1,000 pounds of weight if so commanded, and its blows are strong enough to destroy any wooden structure and to shatter stone walls of one-foot thickness. For purposes of taking damage, the spirit is considered to have Wounds as though it were a human with Earth equal to your Earth Ring, but suffers no Wound penalties. It is Invulnerable (see the creature rules in the Book of Void for details of this ability). If it is successfully reduced to zero Wounds, it is dispelled."},{"id":"beam_of_the_inferno","nome":"Beam Of The Inferno","elemento":"fire","mastery":"6","area":"One Target","alcance":"200'","duracao":"Instantaneous","descricao":"This is perhaps the deadliest single spell available ta shugenja, and one of the most fearsome spells ever developed in the Empire. The prayer invokes a tremendous blast of fire against the chosen target, who takes l0k10 Wounds. The spell puts all the Fire kami in the area into a state of agitation, and normal fires within range will burn hotter and more violently for many minutes after the spell is cast."},{"id":"globe_of_the_everlasting_sun","nome":"Globe Of The Everlasting Sun","elemento":"fire","mastery":"6","area":"1 mile","alcance":"500'","duracao":"1 day","descricao":"This mighty prayer calls on all the Fire kami in the area to remain quiet and calm, soothing the agitation which often afflicts them. It is often invoked during major festivals, such as the crowning of a new Emperor. For the duration of the spell, all buildings within the area of effect are immune to the effects of magical fire, and all Fire spells cast within that area have the TN of their Spell Casting Rolls increased by 15. Normal fires will still ignite and burn, but they do so sluggishly, and do not spread easily."},{"id":"the_souls_blade","nome":"The Soul's Blade","elemento":"fire","mastery":"6","area":"One target weapon","alcance":"Touch","duracao":"5 Rounds","descricao":"This spell imbues incredibly powerful Fire kami into a weapon, granting it the full fury of a raging firestorm. A bushi armed with this weapon is a terrible opponent, for the Fire spirits shock and daze his enemies with every blow. For the duration of the spell, the weapon will overcome invulnerability and every target hit with it is automatically Stunned."},{"id":"ring_of_the_void","nome":"Ring Of The Void","elemento":"void","mastery":"6","area":"Self","alcance":"Personal","duracao":"Concentration (requires one hour to cast)","descricao":"Rare and extraordinarily powerful, even by shugenja standards, this prayer calls on the unique favor of the dragon whose domain the ishiken tread: the Void Dragon. Unlike most spells, this is not something that is taught by others, but rather is simply learned through insight by those capable of casting it (and as such it has no scroll associated with it). This spell, more of a meditation ritual, actually allows you to commune with the Void Dragon itself, a feat few mortals have ever managed to perform successfully. During your brief moments of contact with this divine entity, you may ask it questions as you see fit. The Void Dragon knows all that can be known, although it is under no particular compulsion to answer you directly, or even at all. Respect must be maintained at all times, for those who have attempted this feat in the past and failed to pay homage to their patron have ceased to exist altogether."},{"id":"rise_from_the_ashes","nome":"Rise From The Ashes","elemento":"void","mastery":"6","area":"One target individual","alcance":"Touch","duracao":"Instantaneous (requires one hour to cast)","descricao":"Everything that exists has a pattern in the Void, a thread woven in the tapestry that is existence. By recalling the memory of that pattern, you can reverse recent effects that have happened to a living creature. When you cast this spell on an individual, you are essentially restoring their existence within the Void in accordance with their previous self. Upon completion of the spell, the person is immediately restored to the state they were in eight hours prior to when the spell was begun. Any injuries suffered during this time, the effects of diseases or poisons, even the acquisition of supernatural conditions such as the Shadowlands Taint or corruption by the Lying Darkness, can be undone in this manner. Upon the completion of this spell, you lose all Void Points, and you may not regain Void Points for a period of three days, after which they will begin to recover at one Void Point per day until you have your maximum normal amount again. This spell cannot be used to restore someone who has died."},{"id":"unmake_the_world","nome":"Unmake The World","elemento":"void","mastery":"6","area":"One target creature, individual, or object","alcance":"50'","duracao":"Instantaneous","descricao":"The most powerful and terrifying ability of those who command the Void is the ability to destroy the bonds that exist between the five elements. By eradicating the bonds between existing elements, you can effectively cause one object or creature to cease to exist. When you cast this spell on a living creature, you must succeed at a Contested Roll using your Void against the target's Earth. If you are successful, they are instantly killed, and their remains disappear into the Void. Success is automatic against a non-magical object, but attempting to destroy an awakened object, such as a Nemuranai, may have dire ramifications at the GM's discretion. The kami contained within an awakened object frequently respond very poorly to this manner of attack, for instance."},{"id":"peace_of_the_kami","nome":"Peace Of The Kami","elemento":"water","mastery":"6","area":"One target individual","alcance":"Touch","duracao":"Instantaneous","descricao":"The ultimate benevolence of the Water Dragon is without measure. The target is instantly cured of all diseases, his system purged of any and all poisons, and all Wounds are completely healed."},{"id":"rise_water","nome":"Rise, Water","elemento":"water","mastery":"6","area":"One summoned spirit","alcance":"30'","duracao":"Concentration","descricao":"The sea itself will take form to defend you. The ultimate actualization of the Summon spell, this spell summons a massive kami of pure water to serve you. It takes the form of a vaguely humanoid shape, roughly ten feet in height, with an outline that constantly shifts and changes due tits fluid construction. The kami may move up to 15' x your Water per round, and saturates the ground in a 20' radius around it, ensuring that all terrain in that area is at least Moderate Terrain (unless it was already Difficult). The manifest kami is treated as if it has all Physical Traits equal to your Water Ring, and attacks with a jiujutsu Skill Rank equal to half your Water Rank. Damage from these attacks has a DR equal to your Water Ring. For purposes of taking damage, the spirit is considered to have Wounds as though it were a human with Earth equal to your Water Ring, but suffers no Wound penalties. It is Invulnerable (see the creature rules in the Book of Void for details of this ability). If it is successfully reduced to zero Wounds, it is dispelled."},{"id":"waters_sweet_clarity","nome":"Water's Sweet Clarity","elemento":"water","mastery":"6","area":"Target body of water","alcance":"Personal","duracao":"3 rounds","descricao":"The greatest form of augury is one that speaks directly and allows others to witness it. By focusing your energy on a still body of water, you can invoke powerful visions of the future based upon your questions. You may ask one question, and the waters will reveal the answer. The answer takes the form of three separate images, which may be connected in any number of ways, including events occurring over time, or perhaps three facets of a single event. Unlike other forms of augury, others may witness these visions as well."},{"id":"wisdom_and_clarity","nome":"Wisdom and Clarity","elemento":"water","mastery":"2","area":"self","alcance":"Personal","duracao":"1 hour","descricao":"By entreating the insight of the Water kami, a shugenja may dramatically increase his ability to perceive the world around him. For the duration of this spell, your reading speed doubles, and you will have perfect recall of everything you read while under the influence of this spell. This spell does not enhance comprehension, however, so any language or cipher you are not familiar with is still completely indecipherable."},{"id":"ebb_and_flow_of_battle","nome":"Ebb and Flow of Battle","elemento":"water","mastery":"4","area":"All selected allies within 50' radius of the caster","alcance":"Personal","duracao":"5 rounds","descricao":"Mobility is one of the greatest strengths of Water. In a skirmish or a Battle, mobility is key to survival. This spell increases the movement speed of all allies within range. You may choose to exclude specific allies from its effects if you choose. All those affected by the spell may move a distance equal to their Water Ring x 10 in feet as a Free Action (this is normally a Simple Action)."},{"id":"maho_blood_and_darkness","nome":"[MAHO] Blood And Darkness","elemento":"air","mastery":"1","area":"30 foot radius","alcance":"Centered on caster","duracao":"10 rounds","descricao":"This spell plunges the air around the caster into an unnatural visual obscurement, either pitch black or dark blood red as the caster desires, as the kansen literally block the vision of everyone in the area of effect. Everyone who enters or remains within the spell's area of effect, except for the caster, is considered to be Blind until they move out of the area of effect. The caster can see normally - the kansen recognize their master and do not block his vision. The zone of obscurement does not move once it is created. Magical effects or Shadowlands powers that overcome blindness can see through the obfuscation, but otherwise there is no way to overcome tbe effect until the spell expires."},{"id":"maho_inspire_fear","nome":"[MAHO] Inspire Fear","elemento":"air","mastery":"1","area":"One Target person","alcance":"50 feet","duracao":"1 hour","descricao":"This maho spell causes the target person to gain a Phobia of the caster's choice. For the duration of the spell, the victim is considered to have a 3-Point Phobia (as per the Disadvantage in the Book of Fire) of a nature chosen by the caster. Mahotsukai frequently use this spell to make their victims afraid of their weapons or allies, to make shugenja afraid of their spell scrolls, and other cruel tricks."},{"id":"maho_legacy_of_the_dark_one","nome":"[MAHO] Legacy Of The Dark One","elemento":"air","mastery":"1","area":"One target person/creature","alcance":"100 feet","duracao":"5 rounds","descricao":"This subtle maho spell causes distracting kansen to cluster around the target, disrupting his connection to the true Void. Tbe target immediately loses one Void point, and cannot regain it for the duration of the spell."},{"id":"maho_sinful_dreams","nome":"[MAHO] Sinful Dreams","elemento":"air","mastery":"1","area":"One target intelligent creature","alcance":"300 feet","duracao":"1 hour","descricao":"This subtle and sinister spell causes the target to experience dreams of committing dark, sinful, and dishonorable acts. It can only be cast on a person who is either sleeping or in a situation where they could easily fall asleep (resting, meditating, etc). The caster need not know exactly where the target is located. So long as the target is within the spell's range, the spell will succeed. Due to the impact of these disturbing and distracting dreams, the victim of this spell becomes vulnerable to future manipulation by the caster. For the next 24 hours after the spell concludes, the caster gains a Free Raise on all Temptation and Intimidation rolls against the victim. The caster may Raise on the spell to increase the number of Free Raises awarded."},{"id":"maho_blood_rite","nome":"[MAHO] Blood Rite","elemento":"earth","mastery":"1","area":"One Target person/creature","alcance":"Touch","duracao":"10 minutes","descricao":"A deceptive spell which allows many maho-tsukai to masquerade as noble priests, healing the injured. This spell convinces the kansen to flow into the target, stimulating his flesh to heal and knit itself closed, and stimulating his body to feats of physical prowess. The target immediately heals 1k1 Wounds, and for the duration of the spell one of his physical Traits (chosen by the caster) is treated as one Rank higher. (This can award a temporary increase in Wounds if it causes the target's Earth Ring to increase, but the Wounds will drop back to normal when the spell expires, and this may result in the death of the target if he has taken sufficient injury.) However, there is a cruel price for this assistance from the kansen: the target of spell immediately gains 1k1 points of Shadowlands Taint."},{"id":"maho_summon_undead_champion","nome":"[MAHO] Summon Undead Champion","elemento":"earth","mastery":"1","area":"One humanoid corpse","alcance":"100 feet","duracao":"1 hour","descricao":"This spell is used by maho-tsukai to quickly bring forth undead warriors to protect themselves or slaughter their enemies. It must be cast on a corpse which is within the spells range - it cannot target a living creature. The corpse will be animated by a kansen, rising up and serving the caster as best it can. Mechanically, the animated corpse is considered a zombie (as per the Book of Void, page 331). It obeys any simple commands (such as \"kill them\" or \"wait here\") from the maho-tsukai who summoned it. Complex or conditional orders cannot be understood, and the zombie will simply stand and wait until it is given an order simple enough to understand. Once created, it can move freely beyond the spell's initial range. If the zombie is beheaded or destroyed, it will not re-animate unless the spell is cast again. At the end of the spell's duration, the kansen will depart and the undead creature will collapse to the ground, becoming nothing more than a corpse."},{"id":"maho_bleeding","nome":"[MAHO] Bleeding","elemento":"fire","mastery":"1","area":"One Target person/creature","alcance":"50 feet","duracao":"Indefinite","descricao":"This spell inflicts a malignant kansen on a wounded person. The target of the spell must be already injured (suffering from at least 1 Wound) in order for this spell to be effective. The spell causes the injury to begin bleeding, inflicting 1 Wound per Round at the start of the victim's Turn. This effect continues every Round indefinitely, unless the injury is bandaged with a successful Medicine (Wound Treatment) / Intelligence roll at TN 20. Magically healing the target to full Wounds will also end the bleeding."},{"id":"maho_written_in_blood","nome":"[MAHO] Written In Blood","elemento":"fire","mastery":"1","area":"One message (up to ten words)","alcance":"Touch","duracao":"1 week","descricao":"Maho-tsukai use this spell to leave hidden messages, either to communicate with each other or to intimidate others. The message is written in blood onto any flat surface, and may be up to ten words long (Raises can be taken ro lengthen the message). When the message is completed, the blood will sink into the surface and disappear, reappearing later when a condition set by the caster is fulfIlled. Conditions for the message's reappearance can be as simple or as complex as the caster might desire, so long as they are conditions the kansen can reasonably perceive (GM's judgment). Until the message reappears, it is physically undetectable, although spells such as Sense or By the Light of the Moon will detect something magically concealed in the surface. If the spell's duration expires without the trigger-event taking place, the hidden blood will reappear without forming the message."},{"id":"maho_disrupt_the_limb","nome":"[MAHO] Disrupt The Limb","elemento":"water","mastery":"1","area":"One Target person's limb","alcance":"50 feet","duracao":"10 rounds","descricao":"This curse causes the muscles of a target limb - an arm or leg of the caster's choice - to be afflicted with pain, weakness, and tremors for the duration of the spell. All rolls for physical actions taken with that limb for the duration of the spell suffer a +15 TN penalty. In addition, if the target limb is a leg, the victim is considered to be under the effects of the Lame Disadvantage for the duration of the spell."},{"id":"maho_curse_of_the_unblinking_eye","nome":"[MAHO] Curse Of The Unblinking Eye","elemento":"air","mastery":"2","area":"One target creature","alcance":"100 feet","duracao":"2 days","descricao":"This spell curses the target with the attentions of malignant Air kansen who prevent him from sleeping. For the duration of the spell, the victim cannot sleep, and thus cannot recover Void points or spell slots from rest. Further, for each day the victim goes without sleep, he must make a Raw Stamina roll at a TN equal to 5 + (5x number of nights without sleep) or suffer the effects of being Fatigued."},{"id":"maho_caress_of_fu_leng","nome":"[MAHO] Caress Of Fu Leng","elemento":"earth","mastery":"2","area":"One target object","alcance":"50 feet","duracao":"Instantaneous","descricao":"This spell summons dark kansen to consume and destroy the substance most inimical to them - jade. The caster may target any one jade item, weapon, or object within the spell's range (he must be able to see it). The jade is instantly corrupted, its blessed properties annihilated by an overwhelming saturation of Taint. Only a foul black slime is left behind. This spell cannot affect an awakened nemuranai (magical relic) that contains jade."},{"id":"maho_drain_the_soul","nome":"[MAHO] Drain The Soul","elemento":"earth","mastery":"2","area":"One target person/creature","alcance":"50 feet","duracao":"10 minutes","descricao":"This spell causes malignant Earth kansen to afflict the target, draining away his natural Earth and leaving him weak and sickly. For the duration of the spell, the victim's Stamina rank is reduced by 1 (to a minimum of 1). This can cause the victim's Earth Ring to temporarily drop, reducing his Wound Ranks and making him more vulnerable to injury."},{"id":"maho_pain","nome":"[MAHO] Pain","elemento":"earth","mastery":"2","area":"One target creature","alcance":"10 feet","duracao":"1 round","descricao":"This spell wracks the target with intense physical pain shooting up and down the limbs and through the torso. The target falls Prone, helpless with pain, and cannot act on his next Turn. In addition, the target must make a Willpower Trait Roll at TN 20 to avoid crying aloud in pain, which could cause a loss of Honor and/or Glory."},{"id":"maho_spreading_the_darkness","nome":"[MAHO] Spreading The Darkness","elemento":"earth","mastery":"2","area":"Two target persons","alcance":"30 feet","duracao":"Permanent","descricao":"This sinister curse is employed by maho-tsukai both to control their own Taint and to spread the gift of Jigoku to others. The spell targets two people, at least one of which must have the Shadowlands Taint. The spell causes some of this Taint to leave that creature and transfer to the other, the kansen gleefully carrying the gift of Jigoku from one creature to the other. The maximum number of Taint points which can be moved in this manner is equal to The caster's Earth + Insight Rank - however, it can never remove the last point of Taint from the target. (Once the Taint has its grip on someone, it is supremely unwilling to let go.) If the person receiving the Taint is an unwilling target, the caster must succeed in a Contested Willpower roll against the target, or the spell fails."},{"id":"maho_puppet_master","nome":"[MAHO] Puppet Master","elemento":"fire","mastery":"2","area":"One target undead creature","alcance":"100 feet","duracao":"4 hours","descricao":"This spell allows a maho-tsukai to exert his will against any undead creatures in the area, taking control of them and forcing them to obey his will. If the spell targets a mindless uncontrolled creature such as a zombie, the caster takes control of it automatically. If the spell targets a free-willed undead creature such as a pennaggalon, the caster must succeed in a Contested Willpower roll against the creature. Likewise, if the spell targets an undead creature controlled by someone else (another maho-tsukai, oni lord, etc), the caster must succeed in a Contested Willpower roll against the controller. Once controlled, the undead will obey the caster's commands for the duration of the spell, subject to the limits of the creature's intelligence. Zombies will typically only be able to comprehend the most basic of orders (\"kill him,\" etc). At the end of the spell's duration, the undead either revert to the control of their previous master (if they had one) or become free-willed once more."},{"id":"maho_curse_of_weakness","nome":"[MAHO] Curse Of Weakness","elemento":"water","mastery":"2","area":"One target person or creature","alcance":"50 feet","duracao":"10 rounds","descricao":"A more powerful form of the spell Disrupt Limb, this spell inflicts an overwhelming barrage of angry Water kansen on the target. The kansen flow through his body, inflicting headache, weakness. fatigue, and muscle tremors. For the duration of the spell, he is at a +10 TN penalty to all physical and mental activities that require Skill or Trait rolls. (This includes Spell Casting rolls.) He also suffers a -10 penalty to his Armor TN, as the debilitation makes it difficult for him to dodge blows."},{"id":"maho_hates_heart","nome":"[MAHO] Hate's Heart","elemento":"air","mastery":"3","area":"One target creature","alcance":"50 feet","duracao":"3 rounds","descricao":"The target of this spell is infused with Air kansen which cause him to suffer a sudden, violent, murderous rage against whoever he is looking at or speaking with when the spell takes effect. (Cunning maho-tsukai usually cast this spell from concealment, to avoid the risk that the rage might he directed against them.) For the duration of the spell, the victim will be consumed with murderous, uncontrollable rage, unable to think of anything but killing this person. He will immediately attack the object of his hatred to the very best of his ability. At the start of each Turn, the victim may roll his Honor at TN 30 to control the rage for that Round. The victim will only be able to take Free and Simple Actions during that Round, since so much of his energy is dedicated to conrrolling the anger."},{"id":"maho_death_beyond_life","nome":"[MAHO] Death Beyond Life","elemento":"earth","mastery":"3","area":"One target person","alcance":"Touch","duracao":"24 hours","descricao":"This spell is among the most secret spells employed by the leaders of the Bloodspeaker cult, and is quite rare among maho-tsukai outside of that elite group. It allows the caster to literally cheat death, for himself or another person. The spell must be cast on its target while still alive, and its protective effect normally lasts 24 hours, although skilled spell casters can extend it. If the target dies within the duration of the spell, powerful kansen will cany his soul away, preventing it from passing on to Meido for judgment. Exactly eight hours after death, they will bring hack the soul and re-infuse it into the body, and the target rises from the dead at the Down Wound Rank. Returning from the dead in this way inflicts a full Rank of Taint on the target, due to his soul having been in the care of kansen for eight hours. This blasphemous resurrection will work as long as the target's corpse is still intact - even if limbs have been lost or the head severed, the body will reassemble itself when the kansen return. The only way to prevent the resurrection is to scatter the body parts or burn the corpse to ashes."},{"id":"maho_essence_of_undeath","nome":"[MAHO] Essence Of Undeath","elemento":"earth","mastery":"3","area":"One humanoid corpse","alcance":"50 feet","duracao":"Indefinite","descricao":"A more powerful form of undead summoning, this spell animates a dead corpse into an undead warrior. Unlike the minor, temporary zombies created by \"Summon Undead Champion,\" this spell binds a kansen into a dead body, creating a powerful Tainted revenant which serves the caster to the best of its ability. The resulting creature is described as \"Undead Revenant\" in the Book of Void, page 330. The revenant will last indefinitely (until destroyed), and the Taint infusing its body prevents it from decaying further. It cannot speak, but can understand and obey any verbal command. It will serve the maho-tsukai who summoned it until it is physically destroyed."},{"id":"maho_summon_oni","nome":"[MAHO] Summon Oni","elemento":"earth","mastery":"3","area":"One summoned oni","alcance":"50 feet","duracao":"Indefinite","descricao":"Among the most hazardous spells in the maho-tsukai's repertoire, this spell summons forth an oni from Jigoku. The oni appears anywhere the caster desires within the range of the spell, and must immediately be given a name - either the caster's own name or the name of another person closely connected to the caster (a close friend, immediate blood relative, or someone who owes the caster their life) - or it will simply depart back to Jigoku. A name, however, anchors the oni into Ningen-do and allows it to remain within the mortal realm. Once the caster has given the oni a name he must engage in a Contested Willpower roll against it. If the caster gave the oni his own name, he gains a +3k2 bonus to this roll. The caster may also Raise when casting Summon Oni to gain additional unkept dice on this roll. The GM should determine the Willpower of the oni - the more powerful the oni, the higher its Willpower. If the caster wins the roll, the oni will obey his commands (at least for now). If the oni wins the roll however, it is free of control and typically runs amok until it is destroyed. Naming an oni is a perilous business, for the oni will try to steal the name away and thereby gain full autonomy and the ability to remain in the mortal realm. Such creatures become Oni Lords, monstrously powerful, able to spawn lesser but still potent copies of themselves. Thus summoned oni will typically not immediately attack the persons who gave them names, seeking instead to leave them alive until they can steal the names completely. Any person who shares their name with an oni will acquire an Oni Mark, a small discoloration on the skin. Every day the bearer of an Oni Mark must make an Earth roll to resist gaining the Shadowlands taint as the connection to the oni corrupts them {see the Taint rules for more details}. Each week they must make another Contested Willpower Roll, similar to the first, against the oni in order to avoid surrendering their name to it. The oni gains +1k1 to this roll for each Rank of Shadowlands Taint the Mark has inflicted on its bearer. If the name-bearer is the same person who summoned the oni, he continues to gain the +3k2 bonus to the roll, plus any bonuses from Raises on the original spell. If the oni ever wins this roll it steals the victim's name and becomes an Oni Lord, freeing itself from any control by its summoner (even if that person is different from the one with the Oni Mark). The now-nameless victim of the Oni Mark becomes a slave of the oni and must obey its commands. If the oni is destroyed or otherwise banished back to Jigoku, it loses its connection to the person with its name and the Oni Mark disappears."},{"id":"maho_armour_of_obsidian","nome":"[MAHO] Armour Of Obsidian","elemento":"fire","mastery":"3","area":"One target person or creature (can be caster)","alcance":"Touch","duracao":"10 minutes or until used","descricao":"This spell wreaths the target in an invisible shield of kansen. If the target is struck or affected by a spell with the Jade keyword, the kansen intercede and negate the spell's effect. This is quite spectacular, as the target is briefly wreathed in a cloud of black, soundless fire which visibly absorbs and consumes the spell. The magical armor normally only works once, although a skilled maho-tsukai can make it strong enough to withstand multiple spells."},{"id":"maho_truth_is_a_scourge","nome":"[MAHO] Truth Is A Scourge","elemento":"air","mastery":"4","area":"One target person","alcance":"50 feet","duracao":"10 minutes","descricao":"One of the more subtle and psychologically destructive spells in the maho-tsukai's arsenal, this spell causes a kansen to distort the target's thoughts, making it impossible for him to lie. Regardless of what he might intend to say, the target of this spell will find himself telling the truth, no matter how damaging that truth might be to himself, his family and lord, or his Clan. In fact, he will find himself blurting out any dangerous or damaging secrets he possesses. In order to conceal the truth while under the effects of this spell, the target must make a Willpower roll at TN 30."},{"id":"maho_chains_of_jigoku","nome":"[MAHO] Chains Of Jigoku","elemento":"earth","mastery":"4","area":"One creature or person","alcance":"50 feet","duracao":"10 minutes","descricao":"A dark counterpoint to the binding spells practiced by Earth shugenja, this spell summons the kansen to bind and trap living creatures (it cannot affect the undead). When the spell is cast, manacles of dark, rusty iron burst from the ground and ensnare the target, trapping him and holding him in place. The target is rendered immobile and helpless, unable to take any physical actions other than to try to break free (although he can still speak). The victim can only break free by making a Contested Roll of his Strength against the Earth of the maho-mahotsukai who cast the spell. (The caster may take Raises to gain additional unkept dice on this roll) When the spell expires, the manacles melt away into a disgusting black ooze."},{"id":"maho_possession","nome":"[MAHO] Possession","elemento":"air","mastery":"5","area":"One target person","alcance":"100 feet","duracao":"1 day","descricao":"This fearsome spell allows the maho-tsukai to take direct possession of another person, forcing his soul into the victim's body and controlling it like a puppet. The caster must know the name of his chosen victim and must also have either a drop of blood or a piece of hair from the target. Once the spell is cast, the maho-tsukai must make a Contested Willpower Roll against the target. (The caster may take Raises to gain unkept dice on this roll.) If the target wins the roll, the possession fails, and the caster suffers 2k1 Wounds as the angry kansen lash back at the one who summoned them. If the caster wins the roil, he takes complete possession of the victim's body and may use it as he sees fit. He does not, however, gain any of the possessed body's memories, knowledge, or instincts. In mechanical terms, the possessed body has its own physical Traits and Advantages but has the mental Traits,mental/spiritual Advantages, School Techniques, and Skills of the possessing maho-tsuka. The spell's victim experiences what is happening to him in an eerie, dream-like manner. When the spell's duration ends, the caster's soul returns to his own body, and the victim regains control of himself - and must face the consequences of what he did while possessed. While the possession lasts, the caster's body is in a comatose state. He can end the possession early and return to his own body at will. If the possessed body is killed, he will immediately return to his own body. If his own body is killed while he possesses another, he will have no place to return when the spell expires and will thus die the moment the spell's duration ends."},{"id":"maho_touch_of_death","nome":"[MAHO] Touch Of Death","elemento":"earth","mastery":"5","area":"One target creature","alcance":"50 feet","duracao":"Instantaneous","descricao":"The most dreaded of all maho spells, the Touch of Death ages, blackens, and blights the target. Skin and flesh shrivel and blacken, hair turns gray and falls out, and shattering pains wrack the body. The victim physically ages by 10 years, and suffers 7k7 Wounds. The wounds can be healed normally, but the aging cannot be reversed. A character unfortunate enough to be hit by this spell multiple times (and survive) will be left elderly and decrepit."},{"id":"maho_strength_of_darkness","nome":"[MAHO] Strength Of Darkness","elemento":"fire","mastery":"5","area":"One target person","alcance":"Personal / Touch","duracao":"10 rounds","descricao":"This spell infuses me body of the target with the power of the Taint, unnaturally enhancing his physical prowess for a short time, allowing him to perform superhuman feats of speed, strength, and stamina. The recipient of the spell gains + 1 Rank to his Earth Ring and his other three physical Traits for the duration of the spell. (The caster may Raise to increase the Traits, but the Earth Ring cannot be increased further.) He also gains the ability to see through any sort of visual impairment - fog, smoke, or even complete darkness. The physical evidence of this magical enhancement is obvious and grotesque - the target's flesh swells and bulges unnaturally and his eyes turn blood-red. This spell increases the target's Wounds per Rank to match his enhanced Earth Rank. When the spell expires and the Earth Ring drops back to normal, the target's Wounds also return to normal levels. This can result in death if he has suffered serious damage while under the spell's effects."},{"id":"maho_no_pure_breaths","nome":"[MAHO] No Pure Breaths","elemento":"air","mastery":"4","area":"One target creature","alcance":"100 feet","duracao":"Instantaneous (but see below)","descricao":"No Pure Breaths was a Mastery 4 maho air spell which allowed the maho-tsukai to summon the Air within a target and force it out. The target literally exploded or more often the spell simply ruptured lungs and stomachs, causing internal bleeding."},{"id":"maho_stealing_the_soul","nome":"[MAHO] Stealing The Soul","elemento":"earth","mastery":"4","area":"One target person","alcance":"1 mile","duracao":"1 day","descricao":"Stealing the Soul was a Mastery 4 maho fire spell which allowed the caster to weaken another person's physical and mental abilities. This spell was most notoriously used in the assassination of the legendary Crab Clan Champion Hida Shonojo, weakening him enough to ensure the success of the attack."}],"caminhos":[{"id":"amethyst_champion_path","nome":"The Amethyst Champion","clanId":"imperial","tecnicas":[{"id":"the_emperors_voice","nome":"The Emperor's Voice","rank":0,"descricao":"The Amethyst Champion brings the voice of the Emperor and the Imperial Court to those who cannot attend the Imperial Court. As such, the Champion is a master at dealing with any threats to the sanctity of the Emperor’s court. As a Free Action, you may spend a Void Point to temporarily gain the ability to use any courtier Technique that has been used against you in the past seven days’ time."}],"requisitos":[{"campo":"courtier","tipo":"tag","min":null,"texto":"Courtier only"}]},{"id":"emerald_champion_path","nome":"The Emerald Champion","clanId":"imperial","tecnicas":[{"id":"the_emperors_hand","nome":"The Emperor's Hand","rank":0,"descricao":"The Emerald Champion is the hand of the Emperor, and the champion of his laws. You gain a bonus of +1k1 on all High and Bugei Skill Rolls, and an additional +1k0 on all your School Skills. You also gain a number of bonus Void Points per day equal to your highest Ring. These Void Points may be granted to any one subordinate or ally in your line of sight for use on any appropriate roll. Granting these bonus Void Points in this manner is a Free Action, but may only be done once per Round. You may not use these bonus Void Points yourself."}],"requisitos":[{"campo":"bushi","tipo":"tag","min":null,"texto":"Bushi only"}]},{"id":"jade_champion_path","nome":"The Jade Champion","clanId":"imperial","tecnicas":[{"id":"the_emperors_will","nome":"The Emperor's Will","rank":0,"descricao":"The Jade Champion is the enforcer of the Emperor’s laws related to magic and religion. You gain a Free Raise on all Spell Casting Rolls. When confronting an opponent who practices any form of outlawed magic (maho, yobanjin shamanism, any form of gaijin sorcery, etc.) or who possesses corrupt supernatural abilities (the Shadowlands Taint or corruption by the Lying Darkness), you gain an additional Free Raise on your Spell Casting Roll."}],"requisitos":[{"campo":"shugenja","tipo":"tag","min":null,"texto":"Shugenja only"}]},{"id":"ruby_champion_path","nome":"The Ruby Champion","clanId":"imperial","tecnicas":[{"id":"master_of_the_dojo","nome":"Master of the Dojo","rank":0,"descricao":"The Ruby Champion is among the greatest sensei in the Empire, and can inspire those under his command to almost unparalleled heights. When fighting alongside allies under your command, you may spend a Void Point as a Complex Action to allow any one ally within line of sight to use one of your Techniques as if that ally were a member of your School of equivalent rank. This effect lasts until the start of your next Turn."}],"requisitos":[{"campo":"bushi","tipo":"tag","min":null,"texto":"Bushi only"}]},{"id":"topaz_champion_path","nome":"The Topaz Champion","clanId":"imperial","tecnicas":[{"id":"soul_of_promise","nome":"Soul of Promise","rank":0,"descricao":"The Topaz Champion is among the best and brightest of each generation. When you advance in Insight Rank and into this Path, you gain the Technique it would normally replace. You also gain a number of bonus Void Points per day equal to your highest Ring. You may spend these just like normal Void Points (with all the normal restrictions), but they may only be used to enhance your School Skill Rolls."}],"requisitos":[]},{"id":"emerald_magistrate_path","nome":"The Emerald Magistrate","clanId":"imperial","tecnicas":[{"id":"honor_is_my_shield","nome":"Honor Is My Shield","rank":0,"descricao":"Those who enforce the Emperor’s laws are among the most virtuous souls, and that is their protection. You gain Reduction equal to half your Honor Rank, rounded up. This effect is cumulative with Reduction you may have from other sources, including armor."}],"requisitos":[{"campo":"investigation","tipo":"skill","min":"3","texto":"Investigation 3"},{"campo":"lore_law","tipo":"skill","min":"3","texto":"Lore: Law 3"},{"campo":"more","tipo":"rpg","min":null,"texto":"Must receive an appointment as an Emerald Magistrate"}]},{"id":"jade_magistrate_path","nome":"The Jade Magistrate","clanId":"imperial","tecnicas":[{"id":"scent_of_the_kami","nome":"Scent of the Kami","rank":0,"descricao":"A servant of the Jade Champion is a master at deciphering the mysteries of the kami. You may make a Perception / Spellcraft Skill Roll to identify any spells cast in an area during the past forty-eight hours. The TN for this roll is equal to the basic TN to cast the spell in question (which is to say its Mastery Level x 5, plus 5)."}],"requisitos":[{"campo":"lore_law","tipo":"skill","min":"3","texto":"Lore: Law 3"},{"campo":"spellcraft","tipo":"skill","min":"3","texto":"Spellcraft 3"},{"campo":"more","tipo":"rpg","min":null,"texto":"Must receive an appointment as an Jade Magistrate"}]},{"id":"imperial_legionnaire_path","nome":"The Imperial Legionnaire","clanId":"imperial","tecnicas":[{"id":"strength_of_the_empire","nome":"Strength of the Empire","rank":0,"descricao":"The strength of the Emperor is exerted via the actions of his loyal legions. When fighting alongside other members of the Imperial legions, or alongside Emerald or Jade Magistrates, when you spend a Void Point to enhance a roll you also gain a bonus to the roll equal to the number of allied legionnaires and/or magistrates within 25 feet."}],"requisitos":[{"campo":"glory","tipo":"trait","min":"2","texto":"Glory 2+"},{"campo":"more","tipo":"rpg","min":null,"texto":"Must receive an appointment to the Imperial Legions"}]},{"id":"jade_legionnaire_path","nome":"The Jade Legionnaire","clanId":"imperial","tecnicas":[{"id":"purity_in_purpose_and_deed","nome":"Purity in Purpose & Deed","rank":0,"descricao":"The Jade Legionnaires accompany the Jade Magistrates against the most dangerous, most insidious, and most numerous of the Empire’s magical threats. If your Honor Rank is higher than that of your opponent, you may add the difference between the two to the total of all your attack and damage rolls made against that opponent. For the purposes of this Technique, all creatures and other opponents who do not possess an Honor Rank are assumed to have an Honor Rank of 0."}],"requisitos":[{"campo":"glory","tipo":"trait","min":"2","texto":"Glory 2+"},{"campo":"more","tipo":"rpg","min":null,"texto":"Must receive an appointment to the Jade Legion"}]},{"id":"crab_berserker","nome":"Crab Berserker","clanId":"crab","tecnicas":[{"id":"crab_berserkers_rage","nome":"Berserker's Rage","rank":2,"descricao":"The Crab berserkers manifest their unique and dangerous gifts after spending some time – often months, sometimes even years – on the Kaiu Wall. Some berserkers call on ma- niacal fury to power their rages, while others enter the notorious “dead eye” trance, but the result is the same: superhuman strength and a near-immunity to pain. Once per skirmish, you may enter your rage dur- ing the Reactions Stage. Once begun, the rage lasts for a number of Combat Rounds equal to double your Earth Ring. (You may end it during an earlier round by spending a Void point during the Reactions Stage.) While in your rage, you cannot take the Center, De- fense, or Full Defense stances, and cannot use any non-Bugei skills. While in the raging state, you ig- nore all penalties and effects of Wound Ranks. You also gain a +2k1 bonus to all attack and damage rolls. If you are killed while raging, you remain alive and can continue to attack until the rage ends, but you cannot be healed (unless you are first targeted with the Force of Will spell) – you are dead, your body simply does not know it yet. The rage ends if you sustain Wounds equal to twice the amount that would normally kill you"}],"requisitos":[{"campo":"earth","tipo":"ring","min":"4","texto":"Earth Ring: 4"},{"campo":"*crab_bushi","tipo":"school","min":"1","texto":"Replaces Any Crab Bushi School Rank 2"}]},{"id":"crab_oni_slayer","nome":"Oni Slayer","clanId":"crab","tecnicas":[{"id":"crab_bound_by_the_world","nome":"Bound by the World","rank":3,"descricao":"The Kuni study the poorly understood art of binding, of using ritual circles and symbols to trap demons so they can be destroyed forever. You may expend an Earth spell slot and make a Spell Casting roll (without TN, see below) in order to ritually prepare a binding circle, a process which takes one hour. This circle may encompass a maximum area equal to your School Rank x 5 in square feet, although you may combine efforts with other Kuni to encompass larger areas by adding your School Ranks together (only one of you may make the Spell Casting Roll). Once an oni enters the circle, it becomes active. The oni may not leave the circle without first succeeding at a Willpower Trait Roll against a TN equal to the total of your Spell Casting roll. While the circle is active, you gain one less Earth spell slot per day."}],"requisitos":[{"campo":"lore_shadowlands","tipo":"skill","min":"3","texto":"Lore: Shadowlands 3"},{"campo":"crab_kuni_shugenja_school","tipo":"school","min":"2","texto":"Replaces Kuni Shugenja 3"}]},{"id":"crane_empress_guard_rank3","nome":"Empress Guard (Rank 3)","clanId":"crane","tecnicas":[{"id":"crane_to_defend_unto_death_rank3","nome":"To Defend Unto Death","rank":3,"descricao":"The Empress Guard hold the honor of their duties seriously. Only the pure of soul and sharp of eye meet the Crane Clan's exacting standards. You may add half your Honor Rank to all attack and Perception rolls. Also, while defending the Imperial family, you may add +10 to your Armor TN."}],"requisitos":[{"campo":"perception","tipo":"trait","min":"3","texto":"Perception: 3"}]},{"id":"crane_empress_guard_rank4","nome":"Empress Guard (Rank 4)","clanId":"crane","tecnicas":[{"id":"crane_to_defend_unto_death_rank4","nome":"To Defend Unto Death","rank":4,"descricao":"The Empress Guard hold the honor of their duties seriously. Only the pure of soul and sharp of eye meet the Crane Clan's exacting standards. You may add half your Honor Rank to all attack and Perception rolls. Also, while defending the Imperial family, you may add +10 to your Armor TN."}],"requisitos":[{"campo":"perception","tipo":"trait","min":"3","texto":"Perception: 3"}]},{"id":"crane_asahina_fetishist","nome":"Asahina Fetishist","clanId":"crane","tecnicas":[{"id":"crane_the_world_in_the_palm_of_the_hand","nome":"The World in the Palm of the Hand","rank":2,"descricao":"The Asahina are the fi nest crafters of tsangusuri (fetishes) in the whole of Rokugan, and their treasures are highly prized. When using an Artisan Skill or a Craft Skill to create a small token of some kind, you may spend a Void Point to confer a one-time blessing into the token. Whoever is in possession of the token may activate this blessing at any time. When activated, the token grants a bonus of +2k0 to one High Skill Roll. No more than one token may be used per day per individual."}],"requisitos":[]},{"id":"dragon_mirumoto_mountaineer","nome":"Mirumoto Mountaineer","clanId":"dragon","tecnicas":[{"id":"dragon_heart_of_the_mountain","nome":"Heart of the Mountain","rank":2,"descricao":"The Mountaineer is a rugged warrior whose constant dealings with the unpredictability of nature makes him ready for anything that may await him in battle. When you are surprised during a skirmish due to failing your Investigation (Notice) / Perception Contested Roll, you may immediately make a second roll using Athletics / Agility. If you are successful, you are not surprised. You may also add half your Athletics Skill Rank (rounded up) to the total of all your ranged attack rolls."}],"requisitos":[{"campo":"athletics","tipo":"skill","min":"2","texto":"Athletics (Climbing) 3"}]},{"id":"dragon_tamori_warrior_priest","nome":"Tamori Warrior Priest","clanId":"dragon","tecnicas":[{"id":"dragon_strength_of_the_soul","nome":"Strength of the Soul","rank":4,"descricao":"The Tamori are the most martially inclined of all Rokugan's shugenja families, often training alongside their clan’s bushi. You can expend a spell slot as a Free Action to gain a bonus of +1k0 on any Bugei Skill roll. You may not expend more spell slots per round in this manner than your School Rank. You may make melee attacks as a Simple Action when using a weapon created by one of the following spells: Bo of Water, Tetsubo of Earth, Katana of Fire, or Yari of Air."}],"requisitos":[{"campo":"*weapon","tipo":"skill","min":"3","texto":"One Weapon Skill at rank 3"},{"campo":"dragon_tamori_shugenja_school","tipo":"school","min":"3","texto":"Replaces Tamori Shugenja 4"}]},{"id":"lion_deathseeker","nome":"Deathseeker","clanId":"lion","tecnicas":[{"id":"lion_heart_of_the_lion","nome":"Honor of the Lion","rank":1,"descricao":"Deathseekers redeem their dishonored names by falling in the thick of battle. You gain the Benefit, Skills, Honor, and Outfit of a Rank 1 Lion bushi (any Lion bushi school). You may add your Honor Rank to the total of one damage roll during your Turn. If you do, your Armor TN is reduced by 5 until the Reactions Stage of the following Combat Round. Addition- ally, you add +1k0 to attack rolls while in the Full Attack Stance."}],"requisitos":[{"campo":"honor","tipo":"trait","min":"5","texto":"Honor Rank 5"},{"campo":"dishonored","tipo":"rule","min":null,"texto":"Dishonored disadvantage"}]},{"id":"lion_bishamon_chosen","nome":"Bishamon's Chosen","clanId":"lion","tecnicas":[{"id":"lion_scion_of_strength","nome":"Scion of Strength","rank":3,"descricao":"The Fortune of Strength shows obvious favor to those who follow his teachings without question or reservation. You may expend a spell slot as a Free Action to gain a bonus of +1k0 to any Strength-based roll, including the dam- age roll of a melee weapon. You may also expend a spell slot in this manner to gain a bonus of +1k0 to the Spell Casting roll made for any spell with the Battle descriptor."}],"requisitos":[{"campo":"battle","tipo":"skill","min":"3","texto":"Battle 3"},{"campo":"lion_kitsu_shugenja_school","tipo":"school","min":"2","texto":"Replaces Kitsu Shugenja 3"}]},{"id":"mantis_yoritomo_scoundrel","nome":"Yoritomo Scoundrel","clanId":"mantis","tecnicas":[{"id":"mantis_revel_in_villany","nome":"Revel in Villainy","rank":2,"descricao":"The Scoundrel will do what he must, despite what society may say about his activities. Whenever you spent a Void Point to enhance an Athletics, Commerce, Sailing, Sincerity, or Low Skill Roll, you gain an additional bonus to the total of the roll equal to twice your School Rank."}],"requisitos":[{"campo":"commerce","tipo":"skill","min":"2","texto":"Commerce 2"},{"campo":"sailing","tipo":"skill","min":"2","texto":"Sailing 2"},{"campo":"yoritomo_bushi_school","tipo":"school","min":"1","texto":"Replaces Yoritomo Bushi 2"}]},{"id":"mantis_navigator","nome":"Mantis Navigator","clanId":"mantis","tecnicas":[{"id":"mantis_the_fortunes_guidance","nome":"The Fortunes' Guidance","rank":3,"descricao":"The shugenja who serve the Mantis are taught many techniques that allow them to placate the elements, even under extreme circumstances. When confronted with difficult weather conditions, you may negate them by spending a Void Point as a Simple Action. This affects an area equal to your School Rank x 20 feet in all directions from you. In a skirmish, this effect lasts a number of Rounds equal to your School Rank. Outside of combat, this effect lasts a number of hours equal to your School Rank. If the weather effect being negated is the result of a spell, you may only negate spells with a Mastery Level equal or less than your School Rank, and then only by spending a number of spell slots equal to the Mastery Level in addition to the Void Point."}],"requisitos":[{"campo":"sailing","tipo":"skill","min":"3","texto":"Sailing (Navigation) 3"},{"campo":"*mantis_shugenja","tipo":"school","min":"2","texto":"Any Mantis Shugenja School, Rank 3"}]},{"id":"phoenix_shiba_yojimbo","nome":"Shiba Yojimbo","clanId":"phoenix","tecnicas":[{"id":"phoenix_shibas_sacrifice","nome":"Shiba's Sacrifice","rank":3,"descricao":"The Shiba yojimho are an elite cadre of personal guards, trained to give their lives for their charges at a moment's notice. Only the most honorable and selfless of the Shiha are selected fOr this training, since it requires a willingness to throw one's life away without hesitation. At the start of any skirmish, you may designate one ally as your charge for that skirmish. Any time your charge is hit by a physical attack or a targeted (non-area-affect) damage-causing spell, if you are within 10', you may make a Defense/ Reflexes roll at TN 25. With a success, you take the damage instead of your charge. If you spend a Void Point to reduce this damage, it is reduced by 20 instead of the normal 10."}],"requisitos":[{"campo":"honor","tipo":"trait","min":"5","texto":"Honor 5"},{"campo":"phoenix_shiba_bushi_school","tipo":"school","min":"2","texto":"Replaces Shiba Bushi 3"}]},{"id":"phoenix_isawa_tensai","nome":"Isawa Tensai","clanId":"phoenix","tecnicas":[{"id":"phoenix_embrace_the_elements","nome":"Embrace the Elements","rank":2,"descricao":"There are those among the Phoenix whose chi is so strongly attuned to the essence of a single Element that they are able to accomplish incredible things by studying that Element to the exclusion of others. You gain an additional Affinity in any one Element for which you already possess an Affinity. You gain a Deficiency in all otber Elements. For example, if you are a Rank 1 lsawa Shugenja with an Affinity for Fire, when you advance to this Technique. you will be a Rank 2 shugenja capable of casting Mastery Level 4 Fire spells, but only Mastery Level 1 spells of all other Elements."}],"requisitos":[{"campo":"lore_elements","tipo":"skill","min":"3","texto":"Lore (Elements) 3"},{"campo":"spellcraft","tipo":"skill","min":"3","texto":"Spellcraft 3"},{"campo":"phoenix_isawa_shugenja_school","tipo":"school","min":"1","texto":"Isawa Shugenja School, Rank 2"}]},{"id":"scorpion_bitter_lies_swordsman","nome":"Bitter Lies Swordsman","clanId":"scorpion","tecnicas":[{"id":"scorpion_dark_sword_bitter_lies","nome":"The Dark Sword of Bitter Lies","rank":3,"descricao":"The Bitter Lies Swordsman charges into battle with no regard for his own safety. You may spend a Void Point to immediately re-roll any one roll. This re-roll suffers no penalty to the TN, even if you failed the original roll. You may keep either result that you prefer. However, you may not re-roll the same roll another time through any means."}],"requisitos":[{"campo":"kenjutsu","tipo":"skill","min":"3","texto":"Kenjutsu 3"},{"campo":"scorpion_bayushi_bushi_school","tipo":"school","min":"2","texto":"Replaces Bayushi Bushi 3"}]},{"id":"scorpion_shadow_hunter","nome":"Shadow Hunter","clanId":"scorpion","tecnicas":[{"id":"scorpion_scourge_in_shadow","nome":"Scourge in Shadow","rank":3,"descricao":"There are some targets the Shosuro ninja are unable to eliminate, either because of their protection or simply because they are too difficult to kill. For such targets, the Soshi send in their Shadow Hunters. When casting a damaging spell targeting an opponent who is unaware of your presence, you gain a bonus of +2kO on the Spell Casting Roll. You may also expend a single spell slot as a Free Action to gain a bonus of +1k1 on a Knives or Stealth Skill Roll."}],"requisitos":[{"campo":"stealth","tipo":"skill","min":"3","texto":"Stealth 3"},{"campo":"*scorpion_shugenja","tipo":"school","min":"2","texto":"Any Scorpion Shugenja School, Rank 3"}]},{"id":"spider_obsidian_magistrate","nome":"Obsidian Magistrate","clanId":"spider","tecnicas":[{"id":"spider_strength_in_terror","nome":"Strength in Terror","rank":1,"descricao":"The Obsidian Magistrate is the bastion of Shourido and enforcer of Daigotsu's will. You gain the BeneFit, Skills, Honor, and Outfit of a Rank 1 Daigotsu Bushi. You may add your Perception Trait plus your Taint Rank to the total of all High and Bugei Skill Rolls. This bonus does not apply to Weapon Skills. You may also add the difference between your Honor and that of your opponent to the total of attack rolls made against that opponent."}],"requisitos":[{"campo":"investigation","tipo":"trait","min":"2","texto":"Investigation 2"},{"campo":"spider_daigotsu_bushi_school","tipo":"school","min":"0","texto":"Replaces Daigotsu Bushi 1"}]},{"id":"spider_chuda_subversive","nome":"Chuda Subversive","clanId":"spider","tecnicas":[{"id":"spider_dark_kamis_descretion","nome":"The Dark Kami's Discretion","rank":4,"descricao":"Certain sects of the Chuda have extensively studied means by which the influence of Jigoku in the mortal realm can be concealed from others. By expending three spell slots, you may completely suppress your own Taint, or that of a willing target you touch, for a number of hours equal to your School Rank. In the case of a human who possesses the Taint, this will render them temporarily immune to damage from jade or other effects that target the Taint, but will deny them access to any Taint-based abilities, such as maho or Shadowlands powers. In the case of inherently Tainted creatures targeted by this effect, such as oni or goblins, the effect only renders them immune to Taint-detection abilities. They gain no immunities and lose no abilities. This Technique in no way disguises physical mutations."}],"requisitos":[{"campo":"lore","tipo":"skill","min":"4","texto":"Lore (Shadowlands) 4"},{"campo":"spider_chuda_shugenja_school","tipo":"school","min":"3","texto":"Chuda Shugenja School, Rank 4"}]},{"id":"unicorn_shinjo_scout_moto_bushi","nome":"Shinjo Scout (Moto Bushi)","clanId":"unicorn","tecnicas":[{"id":"unicorn_swift_soul","nome":"The Swift Soul","rank":2,"descricao":"The Shinjo Scout learns to slip by unnoticed, even deep in enemy territory. You may use the Stealth Skill while on horseback. You are considered to have the Way of the Land Advantage no matter where you are. Finally, you gain +1k0 to all attack rolls while Mounted."}],"requisitos":[{"campo":"stealth","tipo":"skill","min":"3","texto":"Stealth 3"}]},{"id":"unicorn_shinjo_scout_shinjo_bushi","nome":"Shinjo Scout (Shinjo Bushi)","clanId":"unicorn","tecnicas":[{"id":"unicorn_swift_soul","nome":"The Swift Soul","rank":2,"descricao":"The Shinjo Scout learns to slip by unnoticed, even deep in enemy territory. You may use the Stealth Skill while on horseback. You are considered to have the Way of the Land Advantage no matter where you are. Finally, you gain +1k0 to all attack rolls while Mounted."}],"requisitos":[{"campo":"stealth","tipo":"skill","min":"3","texto":"Stealth 3"}]},{"id":"unicorn_iuchi_traveler_iuchi_shugenja","nome":"Iuchi Traveler","clanId":"unicorn","tecnicas":[{"id":"unicorn_where_the_wind_wills","nome":"Where the Wind Wills","rank":3,"descricao":"You possess knowledge of the most sacred Unicorn magic: the art of moving from one point to another without crossing the space in between. You may spend one Void Point and expend one spell slot of either Air or Water (Void may not be used) as a Simple Action to instantly teleport a maximum distance equal to your School Rank x 100 feet. This affects only you and the material you are carrying, but by expending a second Void Point you may also teleport any horse-sized mount on which you are sitting at the time of the effect."}],"requisitos":[{"campo":"athletics","tipo":"skill","min":"2","texto":"Athletics 2"},{"campo":"horsemanship","tipo":"skill","min":"2","texto":"Horsemanship 2"}]},{"id":"unicorn_iuchi_traveler_horiuchi_shugenja","nome":"Iuchi Traveler","clanId":"unicorn","tecnicas":[{"id":"unicorn_where_the_wind_wills","nome":"Where the Wind Wills","rank":3,"descricao":"You possess knowledge of the most sacred Unicorn magic: the art of moving from one point to another without crossing the space in between. You may spend one Void Point and expend one spell slot of either Air or Water (Void may not be used) as a Simple Action to instantly teleport a maximum distance equal to your School Rank x 100 feet. This affects only you and the material you are carrying, but by expending a second Void Point you may also teleport any horse-sized mount on which you are sitting at the time of the effect."}],"requisitos":[{"campo":"athletics","tipo":"skill","min":"2","texto":"Athletics 2"},{"campo":"horsemanship","tipo":"skill","min":"2","texto":"Horsemanship 2"}]}]}
;